  \node [draw,circle,fill=red!50,"$i$" below] (1) at (7,0) {};
  \node [draw,circle,fill=blue!50,"$k$"below ] (2)[right=of 1] {};
   \node [draw,circle,fill=red!50,"$j$" below] (3) [right=of 2] {};

  \begin{scope}[>=Latex]

    \draw[-> , thick,]  (1) edge["r"] (2);
    \draw[->, thick]  (2) edge["s"] (3);    
