    \draw[-> , thick]  (1) edge (2);
 \end{scope}



\end{tikzpicture}
}
\end{center}
%
The corresponding matrix is known as \textit{exchange matrix}. The quiver mutation  $\mu_{k}$ at the node $k$, can be formulated by using the entries of the exchange matrix $B$ as shown below. 
%

\textit{Matrix mutation} $\mu_{k}(B)$: The new exchange matrix $B' = \mu_{k}(B)$  is given by 

  \begin{equation}\label{matrixmu}
       (\mu_{k}(B))_{ij} = (B')_{ij}= b'_{ij} =
        \begin{cases}
            -b_{ij} & \text{if} \ i= k \ \text{or} \ j=k  \\ 
            b_{ij} + \frac{1}{2} \qty(\abs{b_{ik}}b_{kj} + b_{ik}\abs{b_{kj}})& \text{otherwise}  \\ 
        \end{cases}
    \end{equation} 

Together with quiver (or matrix mutation), cluster variable $x_{k}$ in the cluster $\vb{x}$ is updated to new variable which is given by the equation below. 

 \textit{Cluster mutation} $\mu_{k}(\vb{x})$: The \textit{cluster mutation} of $\vb{x}$ in direction $k$, $\mu_{k}(\vb{x}) = \qty(x_{1},\dots,x_{k-1},x'_{k},\dots x_{n})$, give rises to new cluster variable $x'_{k}$ which is given by following expression,
    %
    \begin{equation}\label{mu1}
    \mu_{k}(x_{k}) =x'_{k} =  \dfrac{1}{x_{k}}\qty( \prod^{n}\limits_{\substack{j=1 \\ b_{jk} > 0}}x^{b_{jk}}  + \prod^{n}\limits_{\substack{j=1 \\ b_{jk} < 0}}x^{-b_{jk}} )  
\end{equation}
This expression is known as a (coefficient free) \textit{exchange relation}. Note that the mutation is an involution such that the quiver remains unchanged when the same mutation is applied twice in the same direction i.e. $\mu_{k}\cdot \mu_{k} (\vb{x},Q)= \mu^{2}_{k}(\vb{x},Q) = (\vb{x},Q)$. The sequence of mutations starting from the initial seed $(\vb{x}_{0},B_{0})$,
\begin{align*}
(\vb{x}_{0},B_{0}) \xmapsto{\mu_{i_{1}}} (\vb{x}_{1},B_{1}) \xmapsto{\mu_{i_{2}}} (\vb{x}_{2},B_{2}) \xmapsto{\mu_{i_{3}}} \cdots \xmapsto{\mu_{i_{m}}}(\vb{x}_{m},B_{m})
\end{align*}
%
produces new cluster variables and quiver, resulting in construction of the cluster algebra.
%
%
\begin{defn}[Cluster algebra] Let $\mathcal{F}$ be the field of rational functions in $n$ independent variables $x_{1},\dots,x_{n}$ over $\mathbb{C}$ and set $\vb{x} = (x_{1},\dots,x_{n}) \in \mathcal{F}^{n}$. Let $B$ be $n\times n$ skew-symmetrizable matrix. Then cluster algebra of rank $n$,  $\mathcal{A}(\vb{x},B)$, is set of distinguished cluster variables in all of seeds that are reachable by sequence of mutations starting from the initial seed.
\end{defn}
%


One can extend the notion of cluster algebra by  incorporating non-mutable variables, \textit{frozen variables}, in cluster, together with their corresponding \textit{frozen nodes} in the quiver. As the name suggests, they never mutate. For the precise detail,let us consider cluster algebra of rank $n$ with initial cluster $\vb{x}= (x_1,x_2,\dots, x_n)$ and initial quiver $Q$ with $n$ mutable nodes. To generalise the structure, we introduce the $m$ frozen variables $\tilde{x}={n+1},\tilde{x}={n+2},\cdots ,\tilde{x}={n+m}$ and corresponding $m$ frozen nodes. These variables are added to cluster forming  extended cluster \textit{extended cluster}  $\tilde{\vb{x}}=(x_{1},x_{2},\dots,x_{n},x_{n+1},\dots,x_{n+m})$ and the quiver is extended to $\tilde{Q}$ with $n+m$ nodes, where $m$ nodes are designated as frozen. Then the extended cluster algebra can be built from the extended initial seed $(\tilde{\vb{x}},\tilde{Q})$  by applying sequence of mutations 
%
\begin{equation}
    x_{k}'x_{k} = \alpha_{k}\prod^{n}\limits_{\substack{j=1 \\ b_{jk} > 0}}x_{j}^{b_{jk}}  + \beta_{k}\prod^{n}\limits_{\substack{j=1 \\ b_{jk} < 0}}x_{j}^{-b_{jk}} 
\end{equation}
where the coefficients are 
\begin{equation}\label{coeffvar}
    \alpha_{k} = \prod^{n+m}\limits_{\substack{j=n+1 \\ b_{j,k} > 0}}x_{j}^{b_{j,k}}, \quad \beta_{k} = \prod^{n+m}\limits_{\substack{j=n+1 \\ b_{j,k} < 0}}x_{j}^{-b_{j,k}}.
\end{equation}
%
Note that mutation rule for the extended quiver is same as previously given. We refer to these more general cluster algebras as \textit{cluster algebras of geometric type}.




Let us consider the example of coefficient free cluster algebra. 

\begin{exmp}\label{TypeA2ex} Begin with the initial seed $(\vb{x},B)$, where $\vb{x} = (x_{1},x_{2})$ and the exchange matrix  
