%\end{rem}

\subsection{Deformed map of type $D_{4}$}\label{DefmapD4}
%
We make a minor modification of the cluster mutations in the cluster map $\varphi_{D_{4}}$ in a way that an arbitrary coefficient is attached to each monomials of right hand side of expressions in \eqref{typeD4:clmu} as shown below. 
%
\begin{equation}\label{typeD4:dclmu}
\begin{split}
\tilde{\mu}_{1}: (x_{1},x_{2},x_{3},x_{4}) \mapsto (x_{1}',x_{2},x_{3},x_{4}): & \quad x_{1}'x_{1} = b_{1} + a_{1}x_{2} \\ 
\tilde{\mu}_{2}: (x_{1}',x_{2},x_{3},x_{4}) \mapsto (x_{1}',x_{2}',x_{3},x_{4}): & \quad x_{2}'x_{2} = b_{2} + a_{2}x_{1}' x_{3}x_{4} \\ 
\tilde{\mu}_{3}: (x_{1}',x_{2}',x_{3},x_{4}) \mapsto (x_{1}',x_{2}',x_{3}',x_{4}): & \quad x_{3}'x_{3} = b_{3} + a_{3}x_{2}' \\ 
\tilde{\mu}_{4}: (x_{1}',x_{2}',x_{3}',x_{4}) \mapsto (x_{1}',x_{2}',x_{3}',x_{4}'): & \quad x_{4}'x_{4} = b_{4} + a_{4}x_{2} '\\ 
\end{split}
\end{equation}
%
which we refer this as deformed map of type $D_{4}$, $\phi_{D_{4}} = \tilde{\mu}_{4}\tilde{\mu}_{3}\tilde{\mu}_{2}\tilde{\mu}_{1}$. We can reduce the number of parameters by scaling each cluster variables $ x_{i} \to \lambda_{i} x_{i}$ with appropriate choice of parameters $(\lambda_{1},\lambda_{2},\lambda_{3},\lambda_{4}) \in (\mathbb{C}^{*})^4$.  which simplifies the process of the calculations in the later stage. Therefore the iteration of the deformed map can be written as  
%
\begin{equation}\label{typeD4:dclmu1}
\begin{split}
 x_{1,n+1}x_{1,n}& = b_{1} + x_{2,n} \\ 
x_{2,n+1}x_{2,n} &= b_{2} + x_{1,n+1} x_{3,n}x_{4,n} \\ 
 x_{3,n+1}x_{3,n} &= b_{3} + x_{2,n+1}\\ 
 x_{4,n+1}x_{4,n} &= b_{4} + x_{2,n+1} '\\ 
\end{split}
\end{equation}
%
where $n$ denotes the number of iterates $\tilde{\phi}^{n}(\vb{x})$. By the theorem 1.3 in \cite{hk}. Following the same step as previously, we can project this map to 2D parameteric birational map via the rational map $\pi:\mathbb{C}^{4} \to \mathbb{C}^{2}$ as
%
\begin{equation}
 \begin{array}{lcrcl}
    \hat{\phi}_{D_{4}}&:&\C^2&\to&\C^2\\
    & &\vb{u}=(u_1,u_2)&\mapsto&\left(\dfrac{(b_1 + u_1)u_2 + b_2}{u_1}, \dfrac{(b_4 + u_2)u_1 + b_1u_2 + b_2)((b_3 + u_2)y_1 + b_1u_2 + b_2)}{u_2u_1^2(b_1 + u_1)}\right) \;, 
  \end{array}
\end{equation}
%
which is intertwined with $\hat{\phi}_{D_{4}} \cdot \pi = \pi \cdot \phi$ and preserves the symplectic form \eqref{sympformD4}. In order to verify the Liouville integrability of the map, we first assume that corresponding first integral takes analogous form of the \eqref{firstintD4} such that  
%
\begin{equation}
\tilde{I}(\vb{u})=   \alpha_{0} u_1 + \alpha_1 u_2 + \frac{\alpha_2 u_1}{u_2} + \frac{\alpha_3 u_2}{u_1} + \frac{\alpha_4}{u_2} + \frac{\alpha_5}{u_1} + \frac{\alpha_6 u_2}{u_1^2} + \frac{\alpha_7}{u_2u_1} + \frac{\alpha_8}{u_1^2} + \frac{\alpha_9}{u_2u_1^2}
\end{equation} 
%
where we adjusted each monomial in the first integral \eqref{firstintD4} by attaching an arbitrary parameter $\alpha_{i}$. Without loss of generality, we can set $\alpha_{0} = 1$.  Imposing that $\tilde{I}$ is invariant under the action of $\hat{\phi}_{D_{4}}$ i.e. (i.e.$\hat{\phi}_{D_{4}}^{*}(\tilde{I}(\vb{u})) = \tilde{I}(\vb{u})$), constrains parameters such that 
%
\begin{equation} 
\tilde{I}(\vb{u}) =  u_1 + u_2 + \frac{u_1}{u_2} + \frac{(b_1 + 1)u_2}{u_1} + \frac{b_3 + b_4 + 1}{u_2} + \frac{b_1 + b_2 + b_3 + b_4 + 1}{u_1} + \frac{b_1u_2}{u_1^2} + \frac{b_3b_4 + b_3 + b_4}{u_1u_2} + \frac{2b_2}{u_1^2} + \frac{b_3b_4}{u_1^2u_2}
\end{equation}
if one of the following set of conditions satisfies, 
%
\begin{align*}
(1) &\quad b_{2} = b_{4} = b_{1}b_{3} \\ 
(2) &\quad b_{1} = b_{2} = b_{3}b_{4} \\
(3) &\quad b_{2} = b_{3} = b_{1}b_{4} \\
\end{align*}
%
This result implies that the cluster map $\varphi_{D_{4}}$ is deformed into integrable map in more than one distinct way. Notice that the first integral and the deformed map are invariant under the exchange of parameters $b_{3} \leftrightarrow b_{4}$. Thus,  integrable maps corresponding to cases (1) and (3) are the distinct cases among the three.  	
%
\begin{equation}\label{D41map}
\hat{\phi}_{1}: \quad  \mqty(u_{1} \\ u_{2}) \mapsto \qty(\frac{(b_1+u_{1})u_{2} + b_1b_3}{u_{1}}, \quad  
\frac{\qty[(b_1 + u_1)u_2 + b_1b_3(u_1+1)]\cdot \qty[u_2 + b_{3}]}{u_1^2u_2})
\end{equation}
%
\begin{equation}\label{D42map}
    \hat{\phi}_{2}: \quad  \mqty(u_{1} \\ u_{2}) \mapsto 
\qty(\frac{(b_3b_4+u_{1})u_{2} + b_3b_4}{u_{1}}, \quad  \frac{\qty[(b_{4} + u_{2})u_{1} + b_3b_4(u_{2} + 1)]\cdot \qty[(b_{3} + u_{2})u_{1} + 
b_3b_4 (u_{2}+1)]}{u_{1}^2u_{2}(b_3b_4+u_{1})})
\end{equation}
%
By the Theorem in \cite{hk}, we know that they preserve the symplectic form. So the deformed map retains both integrability and symplectic, but no longer possess  Laurent property.  In our previous work \cite{hkm24}, we have shown that each map admit \textit{Laurentification} that lifts each deformed map to cluster algebra of rank 8 including 2 frozen variables, $\mathcal{A}(\tilde{\vb{x}}, Q_{D_{4}}^{(l)})$ endowed with cluster $\tilde{\vb{x}} = (\tx_{1}, \tx_{2},\dots, \tx_{10} )$ and the extended quiver $Q_{D_{4}}^{(l)}$, for $l= \qty{1,2}$  (shown in Figure \ref{Q}).
