This is established by defining the rational map $\pi_{1} : (\tx_{1}, \tx_{2},\dots, \tx_{8} ) \to (u_{1},u_{2})$, which is equivalent to
 \begin{equation}\label{vartransD4i}
    u_{1} =\frac{\tx_3}{\tx_{5}\tx_6}, \qquad 
u_2 = \frac{\tx_2\tx_4\tx_8}{\tx_1\tx_6\tx_{7}},
\end{equation}
and whose structure is obtained by analysing singularity confinement pattern via empirical version of $p$-adic analysis (see further details in \cite{hkm24}). The quivers $ Q_{D_{4}}^{(l)}$ are constructed via pull back of the symplectic form by the rational map $\pi_{1}$, 
%
\begin{equation}
 \tilde{\om} = \pi_{1}^{*}(\hat{\om}) = \sum_{i<j}\frac{\tilde{b}_{ij}}{\tilde{x}_{i}\tilde{x}_{j}} \dd \tilde{x}_{i} \w \dd \tilde{x}_{j}
\end{equation}
%
where the coefficient $\tilde{b}_{ij}$ denotes the number of edges between mutable (non frozen) nodes in $ Q_{D_{4}}^{(l)}$, directed from node $i$ to node $j$. Thus each deformed map is lifted via the $\pi_{1}$ to a distinguished cluster map,  defined by the cluster mutations in $\mathcal{A}(\tilde{\vb{x}}, Q_{D_{4}}^{(l)})$.
 The cluster map, obtained  via Laurentification from $\hat{\phi}_{1}$ is given as
%
\begin{equation}
\psi^{(1)}_{D_{4}} = \pi_{1}^{*}\hat{\phi}_{D_{4}}^{(1)}  = \hat{\rho}_{1}^{-1}\hat{\mu}_{1} \hat{\mu}_{3}\hat{\mu}_{8}, \qquad \rho_{1} = (3,2,8)(1,5,6,7,4)
\end{equation}
%
whose mutations are defined in cluster algebra  $\mathcal{A}(\tilde{\vb{x}}, Q_{D_{4}}^{(1)})$. Note that here we denote the mutations in this cluster algbra  $\hat{\mu}$ to distinguish them from the mutations in the cluster algebra of type $D_{4}$.
By setting the initial cluster $\tilde{\vb{x}}$ as 
$$(\tx_{1}, \tx_{2},\tx_{3}, \tx_{4},\tx_{5},\tx_{6},\tx_{7},\tx_{8},\tx_{9},\tx_{10} ) = (\tau_{0},\sigma_{1},\sigma_{0},\tau_{4}, \tau_{1},\tau_{2},\tau_{3},r_{0}, b_3, b_4)$$
the action of the map $\psi^{(1)}_{D_{4}}$ induces 
\begin{equation}\label{LaurentphihatmapD4i} 
 \begin{array}{lcrcl}
   \psi^{(1)}_{D_{4}}  &:&(\tx_{1}, \tx_{2},\tx_{3}, \tx_{4},\tx_{5},\tx_{6},\tx_{7},\tx_{8},\tx_{9},\tx_{10} )&\to& (\tx_{5}, \tx_{8}',\tx_{2},\tx_{1}',\tx_{6},\tx_{7},\tx_{4}, \tx_{3}' ,\tx_{9},\tx_{10})\\
    & &(\tau_{0},\sigma_{1},\sigma_{0},\tau_{4}, \tau_{1},\tau_{2},\tau_{3},r_{0}, b_3, b_4)&\mapsto& (\tau_{1},\sigma_{2},\sigma_{1},\tau_{5}, \tau_{2},\tau_{3},\tau_{4},r_{1},b_{3},b_{4}), 
  \end{array}
\end{equation}
Discrete evolution induced by map is described by the following system of recurrence relations, 
%
\begin{equation}\label{systmtauD4i}
    \begin{split}
        & \sigma_{n+2}r_{n} =b_{3}\sigma_{n}\tau_{n+2}\tau_{n+3} + \sigma_{n+1}\tau_{n}\tau_{n+4} \\ 
        &  r_{n+1}\sigma_{n} = \sigma_{n + 1}\tau_{n+4}\tau_{n} + b_{1}\sigma_{n+2}\tau_{n+2}\tau_{n} \\ 
        &\tau_{n+5}\tau_{n} = b_1b_3 \tau_{n+2}\tau_{n+3} + r_{n+1} . 
    \end{split}
\end{equation}
%
Laurentification of the second deformed map $\hat{\phi}_{2}$ gives rises to following cluster map, 
%
\begin{equation}
\psi^{(2)}_{D_{4}} = \pi_{2}^{*}\hat{\phi}_{D_{4}}^{(2)}  = \hat{\rho}_{2}^{-1}\hat{\mu}_{2}\hat{\mu}_{1}\hat{\mu}_{8}\hat{\mu}_{3} ,\qquad \hat{\rho}_{2} = (1,2)(3,4,5,6,7)
\end{equation}
%
Now if we identify the cluster variables in the initial cluster $\tilde{\vb{x}}$ as 
%
\begin{equation} 
(\tx_{1}, \tx_{2},\tx_{3}, \tx_{4},\tx_{5},\tx_{6},\tx_{7},\tx_{8},\tx_{9},\tx_{10} ) = (\hat{s}_{0},\hat{r}_{0},\hat{\tau}_{0}, \htau_{1},\htau_{2},\htau_{3},\htau_{4},\hat{\eta}_{0}, b_3, b_4)
\end{equation}
then we see that the iteration of the map, 
%
\begin{equation}\label{LaurentphihatmapD4ii} 
 \begin{array}{lcrcl}
   \psi^{(1)}_{D_{4}}  &:&(\tx_{1}, \tx_{2},\tx_{3}, \tx_{4},\tx_{5},\tx_{6},\tx_{7},\tx_{8},\tx_{9},\tx_{10} )&\to& (\tx_{2}',\tx_{1}', \tx_{3}',\tx_{4},\tx_{5},\tx_{6},\tx_{7},\tx_{3}, \tx_{8}' ,\tx_{9},\tx_{10})\\
    & &(\hat{s}_{0},\hat{r}_{0},\hat{\tau}_{0}, \htau_{1},\htau_{2},\htau_{3},\htau_{4},\hat{\eta}_{0}, b_3, b_4)&\mapsto& (\hat{s}_{1},\hat{r}_{1},\hat{\tau}_{1}, \htau_{2},\htau_{3},\htau_{4},\htau_{5},\hat{\eta}_{1}, b_{3},b_{4}), 
  \end{array}
\end{equation}
%
is equivalent to the following recursion relations,
\begin{equation}
\begin{split}
 &\htau_{n+5}\htau_{n} = b_3b_4  \htau_{n+3}\htau_{n+2} + \hat{\eta}_{n}, \\ 
    &\hat{\eta}_{n+1}\hat{\eta}_{n} = \hat{r}_{n}\hat{\sigma}_{n}\htau_{n+1}\htau_{n+5} + b_3b_4 \htau_{n+4}\htau_{n+3}^2\htau_{n+2}, \\ 
    &\hat{r}_{n+1}\hat{s}_{n} = b_{3}\htau_{n+3}\htau_{n+4} +\hat{\eta}_{n+1}, \\
    & \hat{s}_{n+1}\hat{r}_{n} = b_{4} \htau_{n+3}\htau_{n+4} + \hat{\eta}_{n+1}. 
\end{split}
\end{equation}

In summary, the deformation approach introduced by \cite{hk} generalizes Liouville integrable type $D_{4}$ cluster map in two distinct ways. Moreover, this approach yields new cluster algebras via Laurentification, whose quivers induce cluster maps, $\psi^{(1)}$ and $\psi^{(2)}$, corresponding to each deformed map, $\hat{\varphi}_{1}$ and $\hat{\varphi}_{2}$ respectively. 




