    \end{split}
\end{equation}
which reduces the deformed map into the 4D symplectic map i.e. 
%
\begin{equation}
\hat{\varphi}: (y_{1},y_{2},y_{3},y_{4}) \to (y_{1}',y_{2}',y_{3}',y_{4}') 
\end{equation}
