\subsection{Tropicalization and degree growth for deformed $\rD_{6}$ map} 


In the previous work \cite{hkm24}, we showed that the degree growth of iteration of cluster maps $\psi_{D_{4}}^{(1)}$ and $\psi_{D_{4}}^{(2)}$,  (induced from deformed type $D_{4}$ map in the section \ref{DefmapD4} ) is quadratic with a (max,+) relation analogous to the exchange relations. This results in vanishing algebraic entropy, indicating that the maps possess integrability, which is consistent with the integrability of the deformed map $\tilde{\varphi}_{D_{4}}$. Here, we find the degree growth of cluster map $\psi_{D_{6}}$ and then determine associated algebraic entropy by following the same steps taken in the type $D_4$ case \cite{hkm24}. 


As the Laurent property of the cluster map $\psi_{\rD_{6}}$ holds, we can write the sequence of tau-functions $\tau_{n}$, $\chi_{n}$, $\eta_{1,n}$, $\xi_{1,n}$, $r_{n}$ and $s_{n}$ as Laurent polynomial in initial cluster $\hat{\vb{x}}$  \eqref{D6initialvar}, shown below
%
\begin{equation}\label{eq:LaurentD6m}
\begin{split}
&\tau_{n} = \frac{N^{(1)}_{n}(\hat{\vb{x}})}{\hat{\vb{x}}^{\vb{d}_{n}}}, \quad \chi_{n} = \frac{N^{(2)}_{n}(\hat{\vb{x}})}{\hat{\vb{x}}^{\vb{p}_{n}}}, \quad \eta_{1,n} = \frac{N^{(3)}_{n}(\hat{\vb{x}})}{\hat{\vb{x}}^{\vb{q}_{n}}}, \\
&\xi_{1,n} = \frac{N^{(4)}_{n}(\hat{\vb{x}})}{\hat{\vb{x}}^{\vb{r}_{n}}}, \quad  r_{n} = \frac{N^{(4)}_{n}(\hat{\vb{x}})}{\hat{\vb{x}}^{\vb{v}_{n}}},\quad s_{n} = \frac{N^{(4)}_{n}(\hat{\vb{x}})}{\hat{\vb{x}}^{\vb{j}_{n}}} \\
\end{split}
\end{equation}
where d-vectors $\vb{d}_{n}, \vb{d}_{n}, \vb{d}_{n},\vb{d}_{n} $ is associated with the tau-functions assoicated with unfrozen variables $
(\xi_{1,0},r_{0},s_{0},\tau_{0}, \tau_{1}, \tau_{2},\tau_{3},\tau_{4}, \tau_{5} ,\tau_{6},\chi_{0},\eta_{1,0}, b_{5},b_{6})  $ 
and  have initial data given by a $12 \times 12$ identity matrix.
%
\begin{equation}\label{initialdvD6}
\qty( \vb{q}_{0} \ \vb{r}_{0} \ \vb{v}_{0} \ \vb{j}_{0} \ \vb{d}_{0} \ \vb{d}_{1} \ \vb{d}_{2} \ \vb{d}_{3} \ \vb{d}_{4} \ \vb{d}_{5} \  \vb{d}_{6} \  \vb{p}_{0}  ) = -I
\end{equation}
%
Direct substitution \eqref{eq:LaurentD6m} into \eqref{eq:deformD6} yields the (max,+) relations for the d-vectors,
%
\begin{equation}\label{bilinearD6deg}
\begin{array}{rcl}
\vb{d}_{n+7} + \vb{d}_{n} & = & \max(\vb{d}_{n+5} + \vb{d}_{n+2}, \vb{p}_{n} ), \\
 \vb{p}_{n+1} + \vb{p}_{n} & = & \max(\vb{d}_{n+2} + \vb{d}_{n+3} +\vb{d}_{n+5} + \vb{d}_{n+6}, \vb{q}_{n} + \vb{d}_{n+1} + \vb{d}_{n+7} ), \\
  \vb{q}_{n+1} + \vb{q}_{n} & = & \max(\vb{d}_{n+3} + \vb{d}_{n+4} +\vb{d}_{n+5} +\vb{d}_{n+6}, \vb{r}_{n}+\vb{p}_{n+1} ), \\
 \vb{r}_{n+1} + \vb{r}_{n} & = & \max(\vb{d}_{n+4} + 2\vb{d}_{n+5}+ \vb{d}_{n+6}, \vb{v}_{n} +  \vb{j}_{n}+  \vb{q}_{n+1}), \\
  \vb{v}_{n+1} + \vb{j}_{n} & = & \max(\vb{d}_{n+5} + \vb{d}_{n+6}, \vb{r}_{n+1}), \\
   \vb{j}_{n+1} + \vb{v}_{n} & = & \max(\vb{d}_{n+5} + \vb{d}_{n+6}, \vb{r}_{n+1}), \\
\end{array}  
\end{equation}
%

Next we introduce quantities which is analogous to the tropical version of \eqref{vartransformD6} as following,
%
\begin{equation}\label{eq:tropvarD6x}
\begin{split}
\vb{X}_{1,n} = \vb{d}_{n} + \vb{d}_{n+6} - \vb{d}_{n+1} - \vb{d}_{n+5}, & \quad \vb{X}_{2,n} = \vb{p}_{n} - \vb{d}_{n+2} - \vb{d}_{n+5},\\
\vb{X}_{3,n} = \vb{q}_{n} - \vb{d}_{n+3} - \vb{d}_{n+5}, &  \quad  \vb{X}_{4,n} = \vb{r}_{n} - \vb{d}_{n+4} - \vb{d}_{n+5}, \\ 
\vb{X}_{5,n} = \vb{v}_{n} + \vb{s}_{n}  - \vb{d}_{n+5}, & \quad \vb{X}_{6,n} = \vb{j}_{n} - \vb{d}_{n+5} - \vb{s}_{n},
\end{split}
\end{equation}
%
along with quantities corresponding to symplectic coordinates   $y_{j}$ \eqref{vartransformD6y}, shown below. 
%
\begin{equation}\label{eq:tropvarD6y}
\begin{array}{rcl}
\vb{Y}_{1,n} = \vb{p}_{n} - \vb{d}_{n+2} - \vb{d}_{n+5},& \quad &\vb{Y}_{2,n} = \vb{d}_{n+1} + \vb{q}_{n} - \vb{d}_{n} - \vb{d}_{n+3} - \vb{d}_{n+6},\\
  \vb{Y}_{3,n} = \vb{d}_{n+2} + \vb{r}_{n} - \vb{d}_{n+4} - \vb{p}_{n}, & \quad &\vb{Y}_{4,n} = \vb{d}_{n+3} +  \vb{v}_{n} + \vb{j}_{n} - \vb{d}_{n+5} - \vb{q}_{n} \\ 
\end{array}
\end{equation}
%
Then we can see that $\vb{X}_{i,n}$ satisfies ultradiscretized expression of original type $\rD_{6}$ (\eqref{D6recs} with all $b_{i}=1$) from the (max,+) equations \eqref{bilinearD6deg} as stated in below, 
%
\begin{lm}\label{periodtropD6}
The quantities $\vb{X}_{j,n}$ in \eqref{eq:tropvarD6x} satisfy following system of (max,+) equations: 
\begin{equation} \label{maxD6}
\begin{array}{rcl}
\vb{X}_{1,n+1} + \vb{X}_{1,n} & = & \qty[\vb{X}_{2,n}]_{+}, \\
\vb{X}_{2,n+1} + \vb{X}_{2,n} & = & \qty[\vb{X}_{1,n+1} +\vb{X}_{3,n} ]_{+} ,\\
\vb{X}_{3,n+1} + \vb{X}_{3,n} & = & \qty[\vb{X}_{2,n+1} +\vb{X}_{4,n} ]_{+} ,\\
\vb{X}_{4,n+1} + \vb{X}_{4,n} & = & \qty[\vb{X}_{5,n}+ \vb{X}_{6,n} + \vb{X}_{3,n+1} ]_{+}. \\
\vb{X}_{5,n+1} + \vb{X}_{5,n} & = & \qty[\vb{X}_{4,n+1} ]_{+}. \\
\vb{X}_{6,n+1} + \vb{X}_{6,n} & = & \qty[\vb{X}_{4,n+1} ]_{+}. \\
\end{array}
\end{equation}
where $ \qty[a]_{+} = \max(a,0)$.

Given arbitrary initial values $(\vb{X}_{1,0},\vb{X}_{2,0}, \vb{X}_{3,0}, \vb{X}_{4,0}, \vb{X}_{5,0},\vb{X}_{6,0})$, the quantities $\vb{X}_{j,n}$ ( and $\vb{Y}_{i,n}$) are periodic with period 6 for $1\leq i \leq 4$ and $1 \leq j \leq 6$. 
\end{lm}
%
\begin{proof}
The (max,+) equations in \eqref{maxD6} emerges from \eqref{bilinearD6deg} by rearranging the d-vectors so that they can be expressed in terms of quantities $\vb{X}_{j,n}$ in \eqref{eq:tropvarD6x}. Alternatively, this equations can be derived from the exchange relations of type $D_{6}$ cluster map, $\varphi_{D_{6}}$, \eqref{typeD4:clmu}, by considering the d- vectors of cluster variables $x_j$. Since  $\varphi_{D_{6}}$ is periodic with period 6, it follows that each quantity $\vb{X}_{j,n}$ inherits this periodicity. 
\end{proof}
%
The periodicity of $\vb{X}_{i,n}$ (or $\vb{Y}_{j,n}$) for all $i$, is an essential component in determining the degree growth of d-vectors of tau functions as demonstrated in the proof of the following statement. 
%
\begin{thm} Let $\cT$ be linear operator which shifts $n \to n+1$.
The  d-vectors $\vb{e}_{n}$,$\vb{d}_{n}$,$ \vb{f}_{n}$ and $\vb{g}_{n}$, which solve the system of equations \eqref{bilinearD6deg}, satisfy the following linear difference equations
%
\begin{equation}
\cL\vb{r}_{n}=(\cT^{6} - 1)(\cT^5 - 1)(\cT-1)\vb{r}_{n} = 0 
\end{equation}
%
where $\cT$ is shift operator corresponding to $n \to n+1$ and $\vb{r}_{n} = \vb{e}_{n}$,$\vb{d}_{n}$,$ \vb{f}_{n}, \vb{g}_{n}$.  For the tau functions generated, the leading order of degree growth of their denominators is given by 
%
\begin{equation}\label{degreegrowthD6}
\begin{split}
\vb{d}_{n} = \frac{n^2}{60} \vb{a} + O(n),& \quad \vb{v}_{n} = \frac{n^2}{60} \vb{a} + O(n), \quad \vb{j}_{n} = \frac{n^2}{60} \vb{a} + O(n)   \\
\vb{p}_{n} = \frac{n^2}{30}\vb{a} + O(n),& \quad \vb{q}_{n} = \frac{n^2}{30}\vb{a} + O(n), \quad \vb{r}_{n}=\frac{n^2}{30}\vb{a} + O(n),
\end{split}
\end{equation}
where $\vb{a} = (2,1,1,1,1,1,1,1,1,1,2,2)^{T}$. 
\end{thm}
%
\begin{proof} The quantity $\vb{X}_{1,n}$ can be written in terms of the shift  operator as following 
%
\begin{equation}\label{quantityX1}
\vb{X}_{1,n} = (\cT^6 - \cT^5 - \cT + 1)\vb{d}_{n}
\end{equation}
%
Since $\vb{X}_{1,n}$ exhibit periodicity of period $6$, shown in Lemma \ref{periodtropD6}, it follows that the quantity \eqref{quantityX1} yields characteristic equation in $\cT$,
%
\begin{equation}\label{relX1}
 (\cT^6 -1 )\vb{X}_{1,n} = (\cT-1)^{3} (\sum_{i=0}^{5}\cT^i) (\sum_{i=0}^{4}\cT^i)\vb{d}_{n}  = 0
\end{equation}
%
Solving this equation provides the general solution for the $\vb{d}_{n}$ whose leading order term is $n^2$ with some constant vector $\vb{a}$, 
%
\begin{equation}
\vb{d}_{n} = \vb{a}n^{2} + O(n) 
\end{equation}
%
We now consider an relation \eqref{relX1} once again to determine the coefficient constant of the leading term of $\vb{d}_{n}$. The expression can be rewritten in the form $(\cT^6 -1 )(\cT^5 - 1)(\cT-1)\vb{d}_{n}$ which yields following relation 
%
\begin{align*}
&(\cT^6 -1 )(\cT^5 - 1)(\cT-1)\vb{d}_{n}=  0 \\
& \implies (\cT^6 -1 )(\cT^5 - 1)\vb{d}_{n+1} = (\cT^6 -1 )(\cT^5 - 1)\vb{d}_{n}.
\end{align*}
Substituting the general solution into this relation gives
%
\begin{equation}\label{D6constantrel}
(\cT^6 -1 )(\cT^5 - 1)\vb{d}_{n} = 60 \vb{a}
\end{equation}
%
Evaluating the sequence of $\vb{d}_{n}$, obtained from the (max,+) relations \eqref{bilinearD6deg} with initial d-vectors \eqref{initialdvD6},and then substituting into \eqref{D6constantrel} gives rise to 
%
$$60 \vb{a} = (2,1,1,1,1,1,1,1,1,2,2)^{T} $$
%
Thus the leading order term of  $\vb{d}_{n}$ is:
%
$$\vb{d}_{n} = \frac{n^2}{60} \vb{a} + O(n)$$
%
which is one of the desired results stated in \eqref{degreegrowthD6}. 

By using a similar argument above, one can show that the d-vectors $\vb{p}_{n}$, $\vb{q}_{n}$ and $\vb{r}_{n}$ satisfy the same linear relation of $\cT$ in \eqref{relX1}. As for the rest of d-vectors $\vb{v}_{n}$ and $\vb{j}_{n}$, we first look at the last two (max,+) relations in \eqref{bilinearD6deg}. Subtracting these relations gives rise to expression 
%
\begin{equation}\label{eq:D6vj}
(\cT - 1)\vb{v}_{n} =  (\cT - 1)\vb{j}_{n}.
\end{equation}
Now applying periodicity in Lemma \ref{periodtropD6} to $\vb{Y}_{4,n}$, followed by using the recurrence of $\vb{d}_{n}$ in \eqref{relX1}, we have 
%
 \begin{equation}
 (\cT^6 -1)(\cT^5 -1)(\vb{v}_{n+1} + \vb{j}_{n+1} - \vb{v}_{n} - \vb{j}_{n}) = 0
 \end{equation}
 Then substituting the identity \eqref{eq:D6vj}, we find that both $\vb{v}_{n}$ and $\vb{j}_{n}$ satisfy the recurrence in \eqref{relX1}.

For the rest of proof (determining the coefficients of leading order terms of d-vectors), we can take the same approach as for the case $\vb{d}_{n}$ and the required results follows. 
\end{proof}

Since the degree growth of each variable is quadratic, associated algebraic entropy vanishes, which leads to the conjecture that the deformed type $\rD_{6}$ map is a Liouville integrable map. 


