\subsection{Outline} In Section \ref{sec:logthh}, we introduce necessary background material on graded cyclotomic spectra and their interaction with the variant of log ${\rm THH}$ recently introduced in \cite{RSS25}. Section \ref{sec:logthhloc} is dedicated to the proofs of Theorems \ref{thm:mainthm} and \ref{thm:mainthmspec}, while we prove Theorem \ref{thm:hmcomp} in Section \ref{sec:hmcomp}. 


\section{Logarithmic Topological Hochschild Homology}\label{sec:logthh} We now introduce the necessary background material on the variant of logarithmic ${\rm THH}$ we shall consider here. After recalling the construction of the replete bar construction following \cite{Rog09}, we introduce graded cyclotomic spectra following \cite{AMMN22}. Finally, we discuss the construction of log ${\rm THH}$ appearing in \cite{RSS25}. 

\subsection{The replete bar construction}\label{subsec:repbar} Let $M$ be a discrete commutative monoid. Its \emph{cyclic bar construction} $B^{\rm cyc}(M)$ is the simplicial commutative monoid with $q$-simplices $M^{\oplus (1 + q)}$ with the usual face and degeneracy maps. Since $M$ is commutative, the iterated multiplication maps induce an augmentation $B^{\rm cyc}(M) \to M$. The \emph{replete bar construction} $B^{\rm rep}(M)$ is the pullback \[\begin{tikzcd}B^{\rm rep}(M) \ar{r} \ar{d} & B^{\rm cyc}(M^{\rm gp}) \ar{d} \\ M \ar{r} & M^{\rm gp} \end{tikzcd}\] of simplicial commutative monoids, and it comes with a map $B^{\rm cyc}(M) \to B^{\rm rep}(M)$. There is a levelwise isomorphism \begin{equation}\label{eq:repiso}M \oplus B_qM^{\rm gp} \xrightarrow{} B^{\rm rep}_q(M), \quad (m, g_1, \dots, g_q) \mapsto (m, \gamma(m)(g_1 \cdots g_q)^{-1}, g_1, \dots, g_q)\end{equation} which gives rise to an isomorphism $M \oplus BM^{\rm gp} \cong B^{\rm rep}(M)$ of simplicial commutative monoids, cf.\ \cite[Lemma 3.17]{Rog09}. Here we have written $\gamma \colon M \to M^{\rm gp}$ for the canonical map from $M$ to its group completion $M^{\rm gp}$. 

\subsection{The circle action on the replete bar construction} For any commutative monoid $M$, the replete bar construction participates in a commutative diagram \begin{equation}\label{eq:repsquare}\begin{tikzcd}B^{\rm cyc}(M) \ar{d} \ar{r} & B^{\rm rep}(M) \ar{r} \ar{d} & B^{\rm cyc}(M^{\rm gp}) \ar{d} \\ M \ar{r}{=} & M \ar{r} & M^{\rm gp} \end{tikzcd}\end{equation} of simplicial commutative monoids. For $M = \langle t \rangle \cong {\Bbb N}$ a free commutative monoid on a single generator $t$, we recall the cyclic structure on the terms and maps involved in the upper horizontal composition $B^{\rm cyc}(\langle t \rangle) \to B^{\rm rep}(\langle t \rangle) \to B^{\rm cyc}(\langle t \rangle^{\rm gp})$. We refer to \cite[Propositions 3.20 and 3.21]{Rog09} and the references therein (in particular Hesselholt \cite{Hes96}) for proofs. 

Let us write $B^{\rm cyc}_{\{j\}}(\langle t \rangle)$ for the fiber over $t^j$ of the augmentation $B^{\rm cyc}(\langle t \rangle) \to \langle t \rangle$, and analogously for $B^{\rm rep}(\langle t \rangle)$ and $B^{\rm cyc}(\langle t \rangle^{\rm gp})$. The upper horizontal composite of \eqref{eq:repsquare} decomposes as \begin{equation}\label{eq:decomp1}\coprod_{j \ge 0} B^{\rm cyc}_{\{j \}}(\langle t \rangle) \to \coprod_{j \ge 0} B^{\rm rep}_{\{j\}}(\langle t \rangle) \to \coprod_{j \in {\Bbb Z}} B^{\rm cyc}_{\{j\}}(\langle t \rangle^{\rm gp}).\end{equation} By design, the latter map is an equivalence on each component for $j \ge 0$, while the former is an equivalence for each $j \ge 1$. One can identify \eqref{eq:decomp1} with the diagram \begin{equation}\label{eq:decomp2} \ast \sqcup \coprod_{j \ge 1} S^1/C_j \to \coprod_{j \ge 0} S^1 / C_j \to \coprod_{j \in {\Bbb Z}} S^1 / C_{|j|}\end{equation} of spaces with $S^1$-action, with trivial action on the weight zero component $S^1/C_0$. 

\subsection{Spectra with Frobenius lifts}\label{subsec:froblift} The decompositions \eqref{eq:decomp1} and \eqref{eq:decomp2}, as well as the equivalences relating them, are of \emph{spaces with Frobenius lifts} in the sense considered in \ \cite[Section 2.2]{McC24}, see \cite[Example 2.2.9]{McC24}. Consequently, the equivalence $B^{\rm rep}_{\{0\}}(\langle t \rangle) \simeq S^1 / C_0$ in weight zero is one of spaces with Frobenius lifts, which gives rise to an equivalence ${\Bbb S}[B^{\rm rep}_{\{0\}}(\langle t \rangle)] \simeq {\Bbb S}[S^1/C_0] \simeq {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1]$ of spectra with Frobenius lifts \cite[p.\ 4333]{McC24}. The latter category admits a left adjoint to cyclotomic spectra by \cite[Theorem 2.3.8]{McC24}, informally obtained by only remembering the ``underlying cyclotomic spectrum'' with cyclotomic structure maps $\varphi_p \colon X \xrightarrow{\psi_p} X^{hC_p} \xrightarrow{{\rm can}} X^{tC_p}$. In particular, ${\Bbb S}[B^{\rm rep}_{\{0\}}(\langle t \rangle)] \simeq {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1]$ as cyclotomic spectra.

\subsection{Mapping spaces in module categories} Let ${\cal C}$ be a presentably symmetric monoidal $\infty$-category and let $A$ be an algebra object in ${\cal C}$. We record the following well-known description of mapping spaces in ${\rm Mod}_{{A}}({\cal C})$: 

\begin{lemma}\label{lem:mappingspectramodules} There is an equivalence \[{\rm Map}_{{\rm Mod}_A({\cal C})}(M, N) \xrightarrow{\simeq} {\rm lim} ({\rm Map}_{{\cal C}}(M \otimes A^{\otimes n}, N)),\] functorial in $M$ and $N$. 
\end{lemma}

\begin{proof} Let us write the $A$-module $M$ as the colimit of the two-sided bar construction $B_{\bullet}(M, A, A)$ in ${\cal C}$. This gives rise to the first equivalence in the composition \[\begin{tikzcd}[row sep = small]{\rm Map}_{{\rm Mod}_A({\cal C})}(M, N) \ar{r}{\simeq} & {\rm lim}({\rm Map}_{{\rm Mod}_A({\cal C})}(M \otimes A^{\otimes n} \otimes A, N)) \ar{d}{\simeq}  \\ \vspace{10 mm} & {\rm lim}({\rm Map}_{{\cal C}}(M \otimes A^{\otimes n}, N)),\end{tikzcd}\] while the second follows from adjunction.  
\end{proof}

\subsection{Graded cyclotomic spectra} Following \cite[Appendix A]{AMMN22}, we now discuss some background material on graded cyclotomic spectra. We shall write ${\rm grSp}$ for the category of ${\Bbb Z}$-graded spectra; that is, the functor category ${\rm Fun}({\Bbb Z}, {\rm Sp})$ where ${\Bbb Z}$ is considered a discrete category. We consider the endofunctor \[F_p \colon {\rm grSp}^{BS^1} \to {\rm grSp}^{BS^1}, \quad X \mapsto X^{tC_p},\] where $(X^{tC_p})_i = X_{pi}^{tC_p}$. The category of \emph{graded cyclotomic spectra} is the pullback \[\begin{tikzcd}{\rm grCycSp} \ar{r} \ar{d} & \prod_p {\rm Fun}(\Delta^1, {\rm grSp}^{BS^1}) \ar{d}{({\rm ev}_0, {\rm ev}_1)} \\ {\rm grSp}^{BS^1} \ar{r}{({\rm id}, F_p)} & \prod_p {\rm grSp}^{BS^1}  \times {\rm grSp}^{BS^1}.  \end{tikzcd} \] If $R$ is a ${\Bbb Z}$-graded ${\Bbb E}_1$-ring, ${\rm THH}(R)$ is naturally an object of ${\rm grCycSp}$ by \cite[Example A.10]{AMMN22}, in the sense that its underlying cyclotomic spectrum is the ${\rm THH}$ of the underlying ${\Bbb E}_1$-ring of $R$ \cite[Example A.16]{AMMN22}. We consider ${\rm grSp}$ as a symmetric monoidal category via Day convolution and use \cite[Construction IV.2.1]{NS18} to obtain a symmetric monoidal structure on ${\rm grCycSp}$. 

To avoid confusion with the homotopical grading, we shall refer to the grading of objects in ${\rm grCycSp}$ as the \emph{weight}. The additional structure provided by the weight grading gives us important additional control of mapping spectra in specific cases. We isolate here the particular statement relevant to us:

\begin{lemma}\label{lem:gradedcontrol} Let $R \in {\rm Alg}({\rm grCycSp})$ be an ${\Bbb E}_1$-algebra in graded cyclotomic spectra concentrated in non-negative weights, and let $M$ and $N$ be $R$-modules in graded cyclotomic spectra. Suppose that 
\begin{enumerate}
\item the weight zero component $R_0$ of $R$ is ${\Bbb S}$;
\item $M$ is concentrated in non-negative weights; and
\item $N$ is concentrated in non-positive weights. 
\end{enumerate}
Then the forgetful functor ${\rm Mod}_R({\rm grCycSp}) \to {\rm grCycSp}$ induces an equivalence \[{\rm map}_{{\rm Mod}_R({\rm grCycSp})}(M, N) \xrightarrow{} {\rm map}_{{\rm grCycSp}}(M, N)\] of mapping spectra. 
\end{lemma}

\begin{proof} By Lemma \ref{lem:mappingspectramodules}, we obtain the top left-hand vertical equivalence in \begin{equation}\label{eq:compweightdiagram}\begin{tikzcd}{\rm map}_{{\rm Mod}_R({\rm grCycSp})}(M, N) \ar{r} \ar{d}{\simeq} & {\rm map}_{{\rm grCycSp}}(M, N) \ar{d}{\simeq} \\ {\rm lim}({\rm map}_{{\rm grCycSp}}(M \otimes R^{\otimes n}, N)) \ar{d}{\simeq} & {\rm lim}({\rm map}_{{\rm grCycSp}}(M \otimes {\Bbb S}^{\otimes n}, N)) \ar{d}{\simeq}\\ {\rm lim}({\rm map}_{{\rm grCycSp}}(M_0 \otimes R_0^{\otimes n}, N)) \ar{r}{\simeq } & {\rm lim}({\rm map}_{{\rm grCycSp}}(M_0 \otimes {\Bbb S}^{\otimes n}, N)). \end{tikzcd}\end{equation}  The top right-hand vertical map is an equivalence for the same reason (although in this case the limit is simply canonically equivalent to that of the constant diagram ${\rm map}_{{\rm grCycSp}}(M, N)$). We proceed to explain the remaining vertical equivalences. Since $M$ and $R$ are concentrated in non-negative weights, so is $M \otimes R^{\otimes n}$, and its weight zero piece is $M_0 \otimes R_0^{\otimes n}$. We now argue that the left-hand bottom vertical map is an equivalence. Each level of the limit in the source sits in the pullback \[\begin{tikzpicture}[baseline= (a).base]
\node[scale=.83] (a) at (0,0){\begin{tikzcd}[column sep = tiny]{\rm map}_{{\rm grCycSp}}(M \otimes R^{\otimes n}, N) \ar{r} \ar{d} & \prod_p {\rm map}_{{\rm Fun}(\Delta^1, {\rm grSp}^{BS^1})}(M \otimes R^{\otimes n} \to (M \otimes R^{\otimes n})^{tC_p}, N \to N^{tC_p}) \ar{d} \\ {\rm map}_{{\rm grSp}^{BS^1}}(M \otimes R^{\otimes n}, N) \ar{r} & \prod_p {\rm map}_{{\rm grSp}^{BS^1}}(M \otimes R^{\otimes n}, N) \times {\rm map}_{{\rm grSp}^{BS^1}}((M \otimes R^{\otimes n})^{tC_p}, N^{tC_p})\end{tikzcd}};\end{tikzpicture}\] of mapping spectra, while those of the target sit in the pullback square \[\begin{tikzpicture}[baseline= (a).base]
\node[scale=.81] (a) at (0,0){\begin{tikzcd}[column sep = tiny]{\rm map}_{{\rm grCycSp}}(M_0 \otimes R_0^{\otimes n}, N) \ar{r} \ar{d} & \prod_p {\rm map}_{{\rm Fun}(\Delta^1, {\rm grSp}^{BS^1})}(M_0 \otimes R_0^{\otimes n} \to (M_0 \otimes R_0^{\otimes n})^{tC_p}, N \to N^{tC_p}) \ar{d} \\ {\rm map}_{{\rm grSp}^{BS^1}}(M_0 \otimes R_0^{\otimes n}, N) \ar{r} & \prod_p {\rm map}_{{\rm grSp}^{BS^1}}(M_0 \otimes R_0^{\otimes n}, N) \times {\rm map}_{{\rm grSp}^{BS^1}}((M_0 \otimes R_0^{\otimes n})^{tC_p}, N^{tC_p}).\end{tikzcd}};\end{tikzpicture}\] The inclusion of the weight zero component $M_0 \otimes R_0^{\otimes n} \to M \otimes R^{\otimes n}$ induces compatible equivalences between each corner of the squares: For example, the induced morphism ${\rm map}_{{\rm grSp}^{BS^1}}(M \otimes R^{\otimes n}, N) \xrightarrow{} {\rm map}_{{\rm grSp}^{BS^1}}(M_0 \otimes R_0^{\otimes n}, N)$ is an equivalence, since $M$, $R$, and hence $M \otimes R^{\otimes n}$ are concentrated in non-negative weights, while $N$ is concentrated in non-positive weights. We observe the same is true once the objects are replaced by their $C_p$-Tate constructions, from which the equivalence involving mapping spaces in the arrow category ${\rm Fun}(\Delta^1, {\rm grSp}^{BS^1})$ follows from the usual ${\rm End}$-description of mapping spaces in functor categories. We conclude that the lower left-hand vertical map in \eqref{eq:compweightdiagram} is an equivalence, and the same argument applies to the lower right-hand vertical map. The bottom map in \eqref{eq:compweightdiagram} is an equivalence by the assumption that $R_0 = {\Bbb S}$, which concludes the proof. 
\end{proof}

\subsection{The setup of \cite{RSS25}}\label{subsec:rssrev} For an even ${\Bbb E}_2$-ring $A$ with $x \in \pi_{2d}(A)$, we now follow \cite{RSS25} to give one construction of the term ${\rm THH}(A, \langle x \rangle)$ participating in the cofiber sequences \eqref{eq:rssres}. While \cite{RSS25} provide a general theory for ${\Bbb E}_k$-log rings and their ${\rm THH}$, we restrict attention to the special cases relevant to Theorems \ref{thm:mainthm} and \ref{thm:mainthmspec}. Other sources with related material include \cite[Section 3.4]{Lur15}, \cite[Section 4.2]{HW22}, and \cite{ABM23}. 

As in \cite{Lur15}, there is a map of ${\Bbb E}_2$-spaces \[\xi_{2d} \colon {\Bbb N} \xrightarrow{\cdot d} {\Bbb Z} \simeq \Omega^2{\rm BU}(1) \to \Omega^2{\rm BU} \simeq {\rm BU} \times {\Bbb Z} \xrightarrow{J_{{\Bbb C}}} {\rm Pic}_{{\Bbb S}}\] with $J_{\Bbb C}$ the complex $J$-homomorphism. The associated Thom spectrum gives the ${\Bbb E}_{2}$-ring ${\Bbb S}[t_{2d}] := {\rm Th}_{{\Bbb S}}(\xi_{2d})$. The class $x$ gives a map of ${\Bbb E}_2$-rings ${\Bbb S}[t_{2d}] \to A$ by \cite[Corollary 4.8]{RSS25}; this can be achieved by the results of \cite{GKRW23} (see \cite[Proposition 4.6]{RSS25}), much in analogy with \cite[Proposition 3.15]{ABM23}. We here crucially use that $A$ is assumed to be even. The ${\Bbb E}_2$-ring ${\Bbb S}[t_{2d}]$ can be enhanced with a grading, and it is the free ${\Bbb E}_1$-ring on a class $t_{2d}$ of degree $2d$ in weight $1$. We may invert $t_{2d}$ to obtain ${\Bbb S}[t_{2d}^{\pm 1}]$, either by the formalism of \cite[Section 7.2.3]{Lur17} (the Ore condition is vacuous in this case, as $t_{2d}$ is of even degree), or as the Thom spectrum of the ${\Bbb E}_2$-map ${\xi}_{2d}^{\rm gp} \colon {\Bbb Z} \to {\rm Pic}_{{\Bbb S}}$.  

  There is a defining right-hand pullback square \[\begin{tikzcd}B^{\rm cyc}({\Bbb N}) \ar{r} \ar{d} & B^{\rm rep}({\Bbb N}) \ar{d} \ar{r} & B^{\rm cyc}({\Bbb Z}) \ar{d} \ar{r}{B^{\rm cyc}(\xi_{2d}^{\rm gp})} & B^{\rm cyc}({\rm Pic}_{\Bbb S}) \ar{r}{\epsilon} & {\rm Pic}_{\Bbb S} \\ {\Bbb N} \ar{r}{=} & {\Bbb N} \ar{r} & {\Bbb Z}.\end{tikzcd}\] We shall sometimes write \[B^{\rm cyc}({\Bbb N}) \xrightarrow{B^{\rm cyc}(\xi_{2d})} B^{\rm cyc}({\rm Pic}_{{\Bbb S}}) \quad \text{and} \quad B^{\rm cyc}({\Bbb Z}) \xrightarrow{B^{\rm cyc}(\xi_{2d}^{\rm gp})} B^{\rm cyc}({\rm Pic}_{{\Bbb S}})\] for the resulting maps to $B^{\rm cyc}({\rm Pic}_{\Bbb S})$. We have ${\rm THH}({\Bbb S}[t_{2d}]) \simeq {\rm Th}_{{\Bbb S}}(\epsilon \circ B^{\rm cyc}(\xi_{2d}))$ and ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]) \simeq {\rm Th}_{{\Bbb S}}(\epsilon \circ B^{\rm cyc}(\xi_{2d}^{\rm gp}))$ by \cite[Proposition 7.11]{RSS25}. We shall set ${\rm THH}({\Bbb S}[t_{2d}], \langle t_{2d} \rangle) := {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}$ to be ``weight-connective cover'' of ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$, and we define \[{\rm THH}(A, \langle x \rangle) := {\rm THH}(A) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}], \langle t_{2d} \rangle)\] as ${\rm THH}(A)$-modules in cyclotomic spectra. See \cite[Section 11]{RSS25} in particular for a discussion in this special case. 

\subsection{Discussion of the cyclotomic structure} We continue to follow \cite[Section 11]{RSS25}. The resulting diagram \begin{equation}\label{eq:diagramofgradedcyc}{\rm THH}({\Bbb S}[t_{2d}]) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])\end{equation} is one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in graded cyclotomic spectra. The first map is an equivalence in strictly positive weights, and the middle term is equivalent to ${\rm Th}_{\Bbb S}(\epsilon \circ B^{\rm rep}(\xi_{2d}))$ as ${\rm Th}_{{\Bbb S}}(\epsilon \circ B^{\rm cyc}(\xi_{2d})) \simeq {\rm THH}({\Bbb S}[t_{2d}])$-modules. At the level of underlying cyclotomic spectra, the diagram \eqref{eq:diagramofgradedcyc} splits as the inclusions \begin{equation}\label{eq:diagramofgradedcycsplit}\begin{tikzcd}[row sep = small]{\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \ar{d} \\ {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \ar{d} \\ {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{< 0}.\end{tikzcd}\end{equation} We have here used \cite[Proposition 11.3]{RSS25} together with \cite[Example 2.2.9]{McC24} to determine the weight zero component as ${\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1]$ (cf.\ Section \ref{subsec:froblift}). 

\begin{example}\label{ex:degreezero} Let us spell out the structures described above when $d = 0$. Let ${\Bbb Z} \to ({\Bbb Z}, \le)$ denote the canonical functor from the discrete category ${\Bbb Z}$ to the linearly ordered set $({\Bbb Z}, \le)$. Restriction along this functor induces the functor \[{\rm FilSp} := {\rm Fun}(({\Bbb Z}, \le), {\rm Sp}) \xrightarrow{{\rm Res}} {\rm Fun}({\Bbb Z}, {\rm Sp}) =: {\rm grSp} \] from filtered to graded spectra. The symmetric monoidal equivalence $(- 1) \cdot \colon {\Bbb Z} \xrightarrow{} {\Bbb Z}$ induces a monoidal functor $L_{-1} \colon {\rm grSp} \xrightarrow{} {\rm grSp}$. We shall write ${\Bbb S}[t] := L_{-1}{\rm Res}(1_{{\rm FilSp}})$ for the ${\Bbb E}_{\infty}$-algebra in ${\rm grSp}$ obtained by applying the lax monoidal composite functor to the monoidal unit $1_{{\rm FilSp}}$ of ${\rm FilSp}$. Concretely, the underlying graded spectrum of ${\Bbb S}[t]$ is concentrated as ${\Bbb S}$ in all non-negative weights: This is opposite the convention in \cite{Lur15} (where the functor $L_{-1}$ is not applied in the definition of ${\Bbb S}[t]$), but more convenient for our purposes. 

In this case, ${\rm THH}({\Bbb S}[t^{\pm 1}])$ is an ${\Bbb E}_{\infty}$-algebra in ${\rm grCycSp}$ by \cite[Corollary A.9, Example A.10]{AMMN22}. The splittings \eqref{eq:diagramofgradedcyc} now take the explicit form \begin{equation}\label{eq:susprepsplit}\begin{tikzcd}[row sep = small] {\Bbb S}^{\rm triv} \oplus {\Bbb S}[B^{\rm cyc}_{> 0}(\langle t \rangle)] \ar{d} \\  {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\Bbb S}[B^{\rm cyc}_{> 0}(\langle t \rangle)] \ar{d} \\  {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\Bbb S}[B^{\rm cyc}_{> 0}(\langle t \rangle)] \oplus {\Bbb S}[B^{\rm cyc}_{< 0}(\langle t \rangle)^{\rm gp}]\end{tikzcd}\end{equation} as cyclotomic spectra. 
\end{example}


\section{Logarithmic ${\rm THH}$ and localization}\label{sec:logthhloc}

This section is devoted to the proof of Theorem \ref{thm:mainthmspec}. After introducing our basic setup in Section \ref{subsec:transstudy}, we give an outline of the proof in Section \ref{subsec:proofoutline} that we proceed to realize. 

\subsection{Studying the transfer map}\label{subsec:transstudy} Consider the graded ${\Bbb E}_2$-ring ${\Bbb S}[t_{2d}]$ introduced in Section \ref{subsec:rssrev}. There is a map of ${\Bbb E}_2$-rings $p \colon {\Bbb S}[t_{2d}] \to {\Bbb S}$ obtained by collapsing the strictly positive weights (cf.\ \cite[Lemma B.0.6]{HW22}). It fits in the cofiber sequence \[{\Bbb S}[t_{2d}][2d] \xrightarrow{\cdot t_{2d}} {\Bbb S}[t_{2d}] \xrightarrow{} {\Bbb S}\] of ${\Bbb S}[t_{2d}]$-modules, which exhibits ${\Bbb S}$ as an object of ${\rm Perf}({\Bbb S}[t_{2d}])$. From this, we obtain a transfer map $p_* \colon {\rm Perf}({\Bbb S}) \to {\rm Perf}({\Bbb S}[t_{2d}])$. This sits in the commutative diagram \[\begin{tikzcd}{\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}} \ar{r} & {\rm Perf}({\Bbb S}[t_{2d}]) \ar{r} & {\rm Perf}({\Bbb S}[t_{2d}^{\pm 1}]) \\ {\rm Perf}({\Bbb S}) \ar{u}{p_*^{t_{2d} - {\rm nil}}} \ar{r}{p_*} & {\rm Perf}({\Bbb S}[t_{2d}]), \ar{u}{=}\end{tikzcd}\] where the upper horizontal sequence involving the $t_{2d}$-nilpotent perfect module spectra is Karoubi. Applying ${\rm THH}$ and taking the cofiber of ${\rm THH}(p_*)$, we obtain the diagram of horizontal cofiber sequences \begin{equation}\label{eq:t2dnilcofiberseq}\begin{tikzcd}{\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \ar{r} & {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])) \ar{r} & {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}^{\pm 1}])) \\ {\rm THH}({\rm Perf}({\Bbb S})) \ar{u}{{\rm THH}(p_*^{t_{2d} - {\rm nil}})} \ar{r}{{\rm THH}(p_*)} & {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])) \ar{u}{=} \ar{r} & {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}] | t_{2d})) \ar{u}{f}\end{tikzcd}\end{equation} in cyclotomic spectra that we shall consider throughout. 

The map ${\rm THH}({\Bbb S}[t_{2d}]) \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ is the inclusion of a summand of cyclotomic spectra, cf.\ \eqref{eq:diagramofgradedcycsplit}. Shuffling summands, we rewrite it as the inclusion \begin{equation}\label{eq:thspecinc}{\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \to ({\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]_{> 0}) \oplus ({\Bbb S}^{\rm triv}[1] \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{< 0}).\end{equation} Consequently, there is an equivalence \begin{equation}\label{eq:t2dnilsplit}{\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \simeq {\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{< 0}[-1]\end{equation} of cyclotomic spectra determined by the upper cofiber sequence in \eqref{eq:t2dnilcofiberseq}. 

\begin{lemma}\label{lem:nulltransspec} The map  ${\rm THH}({\Bbb S}) \xrightarrow{{\rm THH}(p_*)} {\rm THH}({\Bbb S}[t_{2d}])$ of cyclotomic spectra is null-homotopic. 
\end{lemma}

\begin{proof} The map ${\rm THH}(p_*)$ factors as the composition \[{\rm THH}({\rm Perf}({\Bbb S})) \xrightarrow{{\rm THH}(p_*^{t_{2d} - {\rm nil}})} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \xrightarrow{} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])),\] and the latter map is the fiber of the inclusion ${\rm THH}({\Bbb S}[t_{2d}]) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ of summands in cyclotomic spectra.
\end{proof}


\begin{corollary}\label{cor:undcycspspec} There is an equivalence of cyclotomic spectra \[{\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})\] under ${\rm THH}({\Bbb S}[t_{2d}])$.    
\end{corollary}

\begin{proof} There is a commutative diagram \[\begin{tikzcd}{\rm THH}({\Bbb S}[t_{2d}]) \ar{r} \ar{d} & {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \ar{d}  \\ {\Bbb S}^{\rm triv} \ar{r} & {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \end{tikzcd}\] of cyclotomic spectra. The two vertical maps are compatibly split, and so we may rewrite the diagram as \[\begin{tikzcd}{\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \ar{r} \ar{d} & {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \ar{d} \\ {\Bbb S}^{\rm triv} \ar{r} & {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1].\end{tikzcd}\] We conclude using Lemma \ref{lem:nulltransspec}, which implies that there are equivalences \[{\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \simeq {\rm THH}({\Bbb S}[t_{2d}]) \oplus {\Bbb S}^{\rm triv}[1] \simeq ({\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0}) \oplus {\Bbb S}^{\rm triv}[1]\] of cyclotomic spectra, with right-hand side equivalent to ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}$. 
\end{proof}

\begin{corollary}\label{cor:residuecycl} The residue maps \[{\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{\partial^{\rm rep}} {\Bbb S}^{\rm triv}[1] \text{ and } {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \xrightarrow{\partial} {\Bbb S}^{\rm triv}[1]\] are homotopic as maps of cyclotomic spectra. 
\end{corollary}

\begin{proof} Under the splittings \eqref{eq:susprepsplit}, both are homotopic to the projection onto the factor ${\Bbb S}^{\rm triv}[1]$. For $\partial$ this follows from Lemma \ref{lem:nulltransspec} and Corollary \ref{cor:undcycspspec}, while for $\partial^{\rm rep}$, this follows from combining \cite[Proposition 9.21]{RSS25} with the splitting \eqref{eq:diagramofgradedcyc}. 
\end{proof}


\subsection{Outline of proof of Theorem \ref{thm:mainthmspec}}\label{subsec:proofoutline} We now pause to give an overview of the ingredients that go into the proof of Theorem \ref{thm:mainthmspec}. The overall strategy is to upgrade to equivalence of Corollary \ref{cor:undcycspspec} to one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules, and obtain the equivalence of Theorem \ref{thm:mainthmspec}
by base-change. To realize this strategy, we proceed in the following steps:

\begin{itemize}
\item[(a)] Show that the transfer map is ${\rm THH}({\Bbb S}[t_{2d}])$-linear (Lemma \ref{lem:projectionformula}). The diagram \eqref{eq:t2dnilcofiberseq} may thus be considered one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in cyclotomic spectra. 
\item[(b)] Show that the underlying map of cyclotomic spectra $f \colon {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ is an inclusion of summands (Proposition \ref{prop:controllingf}). 
\item[(c)] Use (b) to lift the diagram \eqref{eq:t2dnilcofiberseq} to one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in \emph{graded} cyclotomic spectra (Construction \ref{constr:gradedlift}). A surprisingly subtle point is to show that this recovers the original diagram of ${\rm THH}({\Bbb S}[t_{2d}])$-modules once the graded structure is forgotten (Proposition \ref{prop:mainund}). 
\item[(d)] Combine (b) and (c) to upgrade the equivalence of Corollary \ref{cor:undcycspspec} to an equivalence of graded cyclotomic spectra (Proposition \ref{prop:eqgradedcyc}). This essentially boils down to both maps to ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ being the inclusion of non-negative weights, which follows from (b). 
\item[(e)] Use the additional control of mapping spectra provided by Lemma \ref{lem:gradedcontrol} in the graded setting to upgrade the identification of the residue maps in Corollary \ref{cor:residuecycl} to ${\rm THH}({\Bbb S}[t_{2d}])$-modules in graded cyclotomic spectra (Corollary \ref{cor:residuegradedspec}). 
\end{itemize}

Once steps (a)-(e) are established, Theorem \ref{thm:mainthmspec} follows by base-change along ${\rm THH}({\Bbb S}[t_{2d}]) \to {\rm THH}(A)$, as explained in Section \ref{subsec:finalizingproof}. 

\subsection{The transfer is a module map} Let $f \colon R \to S$ be a map of ${\Bbb E}_2$-ring spectra, and let $f^* \colon {\rm Perf}(R) \to {\rm Perf}(S)$ denote the extension of scalars functor, given by $f^*(M) = M \otimes_R S$. The category ${\rm Perf}(S)$ is a ${\rm Perf}(R)$-module. Informally, the module structure is induced by the composition \[{\rm Perf}(S) \otimes {\rm Perf}(R) \xrightarrow{{\rm id} \otimes f^*} {\rm Perf}(S) \otimes {\rm Perf}(S) \xrightarrow{\otimes_S} {\rm Perf}(S).\] If the map $f$ moreover exhibits $S$ as an object of ${\rm Perf}(R)$, we obtain an adjunction \[f^* \colon {\rm Perf}(R) \rightleftarrows {\rm Perf}(S) \colon f_*\] with $f^*$ ${\Bbb E}_1$-monoidal and $f_*$ lax ${\Bbb E}_1$-monoidal. 

\begin{lemma}\label{lem:projectionformula} The map $f_* \colon {\rm Perf}(S) \to {\rm Perf}(R)$ is a map of ${\rm Perf}(R)$-modules. 
\end{lemma}

\begin{proof} Spelling out the definitions, we ask for an equivalence \begin{equation}\label{eq:comparisonmappf}f_*(M) \otimes_R N \xrightarrow{\simeq} f_*(M \otimes_S f^*(N)),\end{equation} natural in $M \in {\rm Perf}(S)$ and $N \in {\rm Perf}(R)$, cf.\ \cite[Remark 1.11(3)]{Kha22}. The map \eqref{eq:comparisonmappf} is defined to be the adjoint of the composition \[f^*(f_*(M) \otimes_R N) \simeq f^*(f_*(M)) \otimes_S f^*(N) \xrightarrow{\epsilon \otimes {\rm id}} M \otimes_S f^*(N)\] obtained from monoidality and the counit of the adjunction. In other words, \eqref{eq:comparisonmappf} being an equivalence is the projection formula, for which the usual proof goes through: \eqref{eq:comparisonmappf} is an equivalence for $N = R$, and since the condition ``\eqref{eq:comparisonmappf} is an equivalence for $N$'' is closed under cofibers and retracts, it follows that \eqref{eq:comparisonmappf} is an equivalence for all $N \in {\rm Perf}(R)$. 
\end{proof} 

\begin{remark} Despite Lemma \ref{lem:nulltransspec}, it is \emph{not} the case that ${\rm THH}(p_*)$ is null-homotopic as a ${\rm THH}({\Bbb S}[t_{2d}])$-module map. If this had been the case, then one could show that e.g.\ the transfer map ${\rm THH}(p_*) \colon {\rm THH}(A / x) \to {\rm THH}(A)$ is null for any commutative ring $A$ and non-zero divisor $x \in A$. But this is false, as for instance seen by Hesselholt--Madsen's computations \cite[Proof of Theorem 2.4.1]{HM03}. 

The author found it reassuring to keep the following elementary example in mind: For an ordinary commutative ring $R$, the sequence \[0 \to R[t] \xrightarrow{t \cdot} R[t] \xrightarrow{t \mapsto 0} R \to 0\] splits as $R$-modules, but not as $R[t]$-modules. In particular, there are non-zero maps $R \to R[t][1]$ in $D(R[t])$, corresponding to ${\rm Ext}^1_{R[t]}(R, R[t]) \cong R$. These all restrict to the zero map in $D(R)$, since ${\rm Ext}^1_R(R, R[t]) \cong 0$. 
\end{remark}

\subsection{Involving the module structures} Lemma \ref{lem:projectionformula} and symmetric monoidality of ${\rm THH}$ (cf.\ \cite[Remark 6.10]{BGT14}) imply that ${\rm THH}(p_*) \colon {\rm THH}({\Bbb S}) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}])$ is one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in cyclotomic spectra. We consider its cofiber ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$ in this category. 

\begin{lemma}\label{lem:localization} There is an equivalence \[{\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]) \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])\] of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in cyclotomic spectra. 
\end{lemma}

\begin{proof} The defining cofiber sequence \[{\rm THH}({\Bbb S}) \xrightarrow{{\rm THH}(p_*)} {\rm THH}({\Bbb S}[t_{2d}]) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})\] is one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules by Lemma \ref{lem:projectionformula}. Base-changing along ${\rm THH}({\Bbb S}[t_{2d}]) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$, we obtain the cofiber sequence \[\begin{tikzcd}[row sep = small]{\rm THH}({\Bbb S}) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])\ar{d}{{\rm THH}(p_*) \otimes {\rm id}} \\  {\rm THH}({\Bbb S}[t_{2d}]) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]) \ar{d} \\  {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]).\end{tikzcd}\] The fiber term is null, since ${\rm THH}$ is symmetric monoidal and ${\Bbb S} \otimes_{{\Bbb S}[t_{2d}]} {\Bbb S}[t_{2d}^{\pm 1}] \simeq 0$. 
\end{proof}

We think of the following result as a spectral realization of the logarithmic derivative relation $t \cdot {\rm dlog}(t) = dt$ defining the log differentials. 

\begin{lemma}\label{lem:t2dfactor} Multiplication by $t_{2d}$ on ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$ participates in a factorization \[\begin{tikzcd}{\rm THH}({\Bbb S}[t_{2d}] | t_{2d})[2d] \ar{r}{\cdot t_{2d}} \ar[dashed]{d}{\widetilde{t_{2d}}} &  {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \\ {\rm THH}({\Bbb S}[t_{2d}]) \ar{ur} \end{tikzcd}\] of spectra, with diagonal map the canonical map to the cofiber.  
\end{lemma}

\begin{proof} By Lemma \ref{lem:projectionformula}, the cofiber sequence defining ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$ is one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules, which we consider one of ${\Bbb S}[t_{2d}]$-modules by restriction of scalars. Multiplication by $t_{2d}$ induces a solid commutative diagram \[\begin{tikzcd}{\rm THH}({\Bbb S})[2d] \ar{rr}{{\rm THH}(p_*)[2d]} \ar{d}{{\cdot t_{2d}}} & & {\rm THH}({\Bbb S}[t_{2d}])[2d] \ar{r} \ar{d}{\cdot t_{2d}} & {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})[2d] \ar{d}{\cdot t_{2d}} \ar[swap,dashed]{dl}{\widetilde{t_{2d}}} \\ {\rm THH}({\Bbb S}) \ar{rr}{{\rm THH}(p_*)} & & {\rm THH}({\Bbb S}[t_{2d}]) \ar{r} & {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})  \end{tikzcd}\] of horizontal cofiber sequences of spectra. Multiplication by $t_{2d}$ on ${\rm THH}({\Bbb S}) \cong {\Bbb S}$ is null-homotopic, since ${\Bbb S} \simeq {\rm cof}({\Bbb S}[t_{2d}][2d] \xrightarrow{\cdot t_{2d}} {\Bbb S}[t_{2d}])$ is a ring. This implies that the composition ${\rm THH}({\Bbb S})[2d] \xrightarrow{{\rm THH}(p_*)[2d]} {\rm THH}({\Bbb S}[t_{2d}])[2d] \xrightarrow{\cdot t_{2d}} {\rm THH}({\Bbb S}[t_{2d}])$ is null-homotopic, providing the indicated dashed arrow from the cofiber. 
\end{proof}


\subsection{Controlling the map $f \colon {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$} We now aim to explicitly describe the right-hand vertical map in \eqref{eq:t2dnilcofiberseq}:

\begin{proposition}\label{prop:controllingf} The map $f \colon {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ is equivalent to the inclusion of summands \[{\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \xrightarrow{} {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{< 0}\] of cyclotomic spectra. 
\end{proposition}


For ease of reference, we first record:

\begin{lemma}\label{lem:transretrspec} The left-hand vertical map \[{\rm THH}(p_*^{t_{2d} - {\rm nil}}) \colon {\rm THH}({\rm Perf}({\Bbb S})) \xrightarrow{} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}})\] of \eqref{eq:t2dnilcofiberseq} admits a retraction in cyclotomic spectra. 
\end{lemma}

\begin{proof} By Schwede--Shipley \cite[Theorem 3.3]{SS03} and Antieau--Barthel--Gepner \cite[Theorem 1.11]{ABG18}, there is an equivalence \[{\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}} \simeq {\rm Perf}({\rm End}_{{\Bbb S}[t_{2d}]}({\Bbb S}))\] under which the transfer ${\rm Perf}({\Bbb S}) \to {\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}$ is induced by the ${\Bbb E}_1$-ring map ${\Bbb S} \cong {\rm End}_{{\Bbb S}}({\Bbb S}) \to {\rm End}_{{\Bbb S}[t_{2d}]}({\Bbb S})$ given by restriction of scalars along ${\Bbb S}[t_{2d}] \xrightarrow{p} {\Bbb S}$. This ring map admits a retraction, by further restricting scalars along ${\Bbb S} \to {\Bbb S}[t_{2d}]$, giving a retraction ${\rm THH}({\Bbb S}) \xrightarrow{} {\rm THH}({\rm End}_{{\Bbb S}[t_{2d}]}({\Bbb S})) \xrightarrow{} {\rm THH}({\Bbb S})$ in cyclotomic spectra. 
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:controllingf}] By Lemma \ref{lem:transretrspec}, the map ${\rm THH}(p_*^{t_{2d} - {\rm nil}})$ splits off a cyclotomic summand in ${\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \simeq {\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{< 0}[-1]$, cf.\  \eqref{eq:t2dnilsplit}. This must necessarily be the first summand, as ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{< 0}[-1]$ does not contain any cyclotomic summands equivalent to ${\Bbb S}^{\rm triv}$, since the $p$-typical cyclotomic Frobenius multiplies weights by $p$. Thus the map $f$ is also a split injection, as the left-hand horizontal maps in \eqref{eq:t2dnilcofiberseq} are null-homotopic. 
\end{proof}

\begin{remark} One can also see directly that $f$ does not map non-trivially to the negative weights of ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$, for example by using Lemma \ref{lem:t2dfactor} to first deduce that $f$ factors through the subobject ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge - 1}$. Indeed, the diagram \begin{equation}\label{eq:t2dfactordiagramremark}\begin{tikzcd}{\rm THH}({\Bbb S}[t_{2d}] | t_{2d})[2d] \ar{r}{\widetilde{t_{2d}}} \ar{d}{f[2d]} & {\rm THH}({\Bbb S}[t_{2d}]) \ar{d} \\ {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])[2d] \ar{r}{\cdot t_{2d}} & {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])\end{tikzcd}\end{equation} commutes and multiplication by $t_{2d}$ increases weight by $1$. One then excludes the possibility of a non-zero map ${\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\{-1\}}$ participating in a ${\rm THH}({\Bbb S}[t_{2d}])$-module map of cyclotomic spectra by hand, using the analysis provided in \cite[Section 11]{RSS25}. 
\end{remark}





\subsection{Involving the graded structure} We now aim to upgrade the equivalence of Corollary \ref{cor:undcycspspec} to one which respects ${\rm THH}({\Bbb S}[t_{2d}])$-module structures. For this, we rely on the following observation: 

\begin{proposition}\label{prop:gradedlift} The canonical morphism \[\begin{tikzcd}[row sep = small]{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}({\rm THH}({\rm Perf}({\Bbb S})), {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}})) \ar{d}{\simeq} \\ {\rm map}_{{\rm grCycSp}}({\rm THH}({\rm Perf}({\Bbb S})), {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}))\end{tikzcd}\] of mapping spectra is an equivalence.
\end{proposition}

\begin{proof} Since the map ${\rm THH}({\Bbb S}[t_{2d}]) \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ is an equivalence in strictly positive weights, its fiber ${\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}})$ is concentrated in non-positive weights. Since ${\rm THH}({\rm Perf}({\Bbb S}))$ is concentrated in weight zero, Lemma \ref{lem:gradedcontrol} applies to conclude.
\end{proof}

Proposition \ref{prop:gradedlift} implies that ${\rm THH}(p_*) \colon {\rm THH}({\rm Perf}({\Bbb S})) \to {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))$ is a ${\rm THH}({\Bbb S}[t_{2d}])$-module map in graded cyclotomic spectra in the following sense: 

\begin{construction}\label{constr:gradedlift} By Lemma \ref{lem:transretrspec}, ${\rm THH}(p_*^{t_{2d} - {\rm nil}})$ is the inclusion ${\Bbb S}^{\rm triv} \to {\Bbb S}^{\rm triv} \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{< 0}[-1]$ of the weight zero component. This is a map of graded cyclotomic spectra, so Proposition \ref{prop:gradedlift} implies that ${\rm THH}(p_*^{t_{2d} - {\rm nil}})$ lifts to a map of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in graded cyclotomic spectra in an essentially unique way, which we also denote by ${\rm THH}(p_*^{t_{2d}- {\rm nil}})$. Moreover, each map in the upper horizontal composition \eqref{eq:t2dnilcofiberseq} is naturally one of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in graded cyclotomic spectra: This is the case for ${\rm THH}({\Bbb S}[t_{2d}]) \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ as it is induced from the map ${\Bbb S}[t_{2d}] \to {\Bbb S}[t_{2d}^{\pm 1}]$ of graded ${\Bbb E}_2$-rings; hence, it is also the case for its fiber ${\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \to {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))$. The resulting composition \[{\rm THH}({\rm Perf}({\Bbb S})) \xrightarrow{{\rm THH}(p_*^{t_{2d} - {\rm nil}})} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \xrightarrow{} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))\] in ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})$ recovers ${\rm THH}(p_*)$ on underlying cyclotomic spectra, and we shall continue to write ${\rm THH}(p_*)$ for this map. We write ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$ for the cofiber of ${\rm THH}(p_*)$ in ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})$, and consider the induced map ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ in this category. 
\end{construction}

In brief, Construction \ref{constr:gradedlift} gives a canonical lift of the diagram \eqref{eq:t2dnilcofiberseq} in ${\rm CycSp}$ to the category ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})$. It remains to show, however, that the resulting map \[{\rm THH}(p_*) \colon {\rm THH}({\rm Perf}({\Bbb S})) \xrightarrow{} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))\] of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in graded cyclotomic spectra recovers the ${\rm THH}({\Bbb S}[t_{2d}])$-module map in cyclotomic spectra arising from Lemma \ref{lem:projectionformula}, which we now denote \[{\rm THH}(p_*)_{\rm mod} \colon {\rm THH}({\rm Perf}({\Bbb S})) \xrightarrow{} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])).\] Let us write $U \colon {\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp}) \to {\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm CycSp})$ for the functor forgetting the graded structure. 

\begin{proposition}\label{prop:mainund} The maps ${\rm THH}(p_*)_{{\rm mod}}$ and $U({\rm THH}(p_*))$ are homotopic. 
\end{proposition}

\noindent The proof of Proposition \ref{prop:mainund} requires some preparation:

\begin{lemma}\label{lem:mainund} The map \[\begin{tikzcd}[row sep = small]{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm CycSp})}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])) \ar{d} \\ {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]))\end{tikzcd}\] of spectra induced by the forgetful functor ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm CycSp}) \to {\rm CycSp}$ admits a retraction. 
\end{lemma}

\begin{proof} For brevity, we shall write e.g.\ ${\rm CycSp}_{{\rm THH}({\Bbb S}[t_{2d}])}$ for ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm CycSp})$ throughout this proof. Consider the commutative diagram \[\begin{tikzpicture}[baseline= (a).base]
\node[scale=.78] (a) at (0,0){\begin{tikzcd}{\rm map}_{{\rm CycSp}}({\Bbb S}^{\rm triv}, {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])) \ar{r} \ar{d}{\simeq} & {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]))  \\ {\rm map}_{{\rm CycSp}_{{\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]), {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])) \ar{r}{\simeq} & {\rm map}_{{\rm CycSp}_{{\rm THH}({\Bbb S}[t_{2d}])}}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])) \ar[swap]{u}{} \end{tikzcd}};\end{tikzpicture}\] of mapping spectra. Here, the left-hand vertical equivalence arises from extension of scalars along ${\Bbb S}^{\rm triv} \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$, while the lower horizontal equivalence arises from Lemma \ref{lem:localization} and restriction of scalars along ${\rm THH}({\Bbb S}[t_{2d}]) \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$. The upper horizontal map is defined to be the indicated composition, which we claim admits a retraction. But this is provided by the map \[{\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])) \xrightarrow{} {\rm map}_{{\rm CycSp}}({\Bbb S}^{\rm triv}, {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]))\] induced by the inclusion ${\Bbb S}^{\rm triv} \to {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$. 
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:mainund}] The two maps participate in diagrams of the form \eqref{eq:t2dnilcofiberseq} in their respective categories. There is a factorization \[{\rm THH}({\rm Perf}({\Bbb S})) \xrightarrow{{\rm THH}(p_*^{t_{2d} - {\rm nil}})} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \xrightarrow{} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))\] of the map ${\rm THH}(p_*)$, and similarly of ${\rm THH}(p_*)_{\rm mod}$ in terms of a map we denote by ${\rm THH}(p_*^{t_{2d} - {\rm nil}})_{\rm mod}$. The two maps ${\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])^{t_{2d} - {\rm nil}}) \to {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))$ are clearly compatible under $U$, as they both arise from the fiber of the map ${\rm THH}({\Bbb S}[t_{2d}]) \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ in the relevant category. It thus suffices to prove that ${\rm THH}(p^{t_{2d} - {\rm nil}}_*)_{\rm mod} \simeq U({\rm THH}(p^{t_{2d} - {\rm nil}}_*))$. 

Let us denote by $f$ and $f_{\rm mod}$ the induced maps ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])$ in the categories ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})$ and ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm CycSp})$, respectively. We will prove that $f_{\rm mod} \simeq U(f)$, from which we get ${\rm THH}(p_*)_{\rm mod} \simeq U({\rm THH}(p_*))$ as induced maps of horizontal fibers in the diagram \eqref{eq:t2dnilcofiberseq} of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in cyclotomic spectra. But Lemma \ref{lem:mainund} implies that $f_{\rm mod}$ is unique among ${\rm THH}({\Bbb S}[t_{2d}])$-module maps in cyclotomic spectra with the property that the underlying map of cyclotomic spectra is the inclusion of the non-negative weights (Proposition \ref{prop:controllingf}). Since $U(f)$ also enjoys this property by Construction \ref{constr:gradedlift}, we conclude. 
\end{proof}

\subsection{Establishing the equivalence} We are now in a position to prove: 

\begin{proposition}\label{prop:eqgradedcyc} There is a canonical equivalence \[{\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \simeq {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})\] of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in graded cyclotomic spectra. 
\end{proposition}

\begin{proof} Let ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})_{\ge 0} \subset {\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})$ denote the full subcategory spanned by those objects whose underlying spectrum is concentrated in non-negative weights. The weight-connective cover ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}$ belongs to this category by definition, while ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$ belongs to it by construction: It is the cofiber of the map ${\rm THH}(p_*) \colon {\rm THH}({\rm Perf}({\Bbb S})) \xrightarrow{} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))$ between objects concentrated in non-negative weights. It thus suffices to show that, for any $X \in {\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})_{\ge 0}$, the maps \[\begin{tikzcd}[row sep = small]{\rm Map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}(X, {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}) \ar{d} \\ {\rm Map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}(X, {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])) \\ {\rm Map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}(X, {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})) \ar{u}\end{tikzcd}\] induced by the inclusion of the non-negative weights and the map $f$ in \eqref{eq:t2dnilcofiberseq} are equivalences. By Lemma \ref{lem:mappingspectramodules}, the above diagram may be rewritten as \[\begin{tikzcd}[row sep = small]{\rm lim}({\rm Map}_{{\rm grCycSp}}(X \otimes {\rm THH}({\Bbb S}[t_{2d}])^{\otimes n}, {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0})) \ar{d} \\ {\rm lim}({\rm Map}_{{\rm grCycSp}}(X \otimes {\rm THH}({\Bbb S}[t_{2d}])^{\otimes n}, {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]))) \\ {\rm lim}({\rm Map}_{{\rm grCycSp}}(X \otimes {\rm THH}({\Bbb S}[t_{2d}])^{\otimes n}, {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}))) \ar{u}\end{tikzcd}\] involving limits of  mapping spaces in ${\rm grCycSp}$. The domain in each mapping space remains concentrated in non-negative weights since ${\rm THH}({\Bbb S}[t_{2d}])$ is concentrated in non-negative weights. Hence the top arrow is an equivalence by construction, while the bottom is an equivalence by  Proposition \ref{prop:controllingf}.  
\end{proof}

\subsection{Identifying the residue maps} We now aim to identify the two residue maps \[{\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{\partial^{\rm rep}} {\Bbb S}^{\rm triv}[1] \text{ and } {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \xrightarrow{\partial} {\Bbb S}^{\rm triv}[1]\] as maps of ${\rm THH}({\Bbb S}[t_{2d}])$-modules. Following a suggestion of Rognes, we do this by studying the mapping spectra encoding all possible residue maps. Explicit descriptions of the equivalent mapping spectra \[{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm CycSp})}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \text{ and}\] \[{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm CycSp})}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\Bbb S}^{\rm triv}[1])\] are probably complicated, and we see no reason for the forgetful functor to cyclotomic spectra to retain enough information to reduce the problem to the case of underlying cyclotomic spectra (which we solved in Corollary \ref{cor:residuecycl}).  

This is our main reason for working with \emph{graded} cyclotomic spectra. The forgetful functors \begin{equation}\label{eq:forgetfulfunctors}{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp}) \to {\rm grCycSp} \xrightarrow{{\rm und}} {\rm CycSp}\end{equation} involving \emph{graded} cyclotomic spectra captures all relevant information: 

\begin{theorem}\label{thm:gradedagreement} The map \begin{equation}\label{eq:gradedagreementdiagram}\begin{tikzcd}[row sep = small]{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \ar{d} \\ {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \end{tikzcd}\end{equation} induced by \eqref{eq:forgetfulfunctors} is equivalent to the inclusion \[{\rm TC}({\Bbb S}) \oplus {\rm TC}({\Bbb S})[1] \to {\rm TC}({\Bbb S}) \oplus {\rm TC}({\Bbb S})[1] \oplus {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0}, X)[1]\] of spectra. The analogous statement holds for ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$.  
\end{theorem}

The proof of Theorem \ref{thm:gradedagreement} requires some preparation. We begin by identifying the source and target of \eqref{eq:gradedagreementdiagram}:  

\begin{proposition}\label{prop:equivalencetctc1spec} There is an equivalence of spectra \[{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}[1]) \simeq {\rm TC}({\Bbb S}) \oplus {\rm TC}({\Bbb S})[1],\] and similarly for ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$ by Proposition \ref{prop:eqgradedcyc}.  
\end{proposition}

\begin{proof} Using Lemma \ref{lem:gradedcontrol}, we find that forgetting the module structure induces an equivalence \[{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}[1]) \xrightarrow{\simeq} {\rm map}_{{{\rm grCycSp}}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}[1])\] of mapping spectra. Since ${\Bbb S}[1]$ is concentrated in weight zero, the inclusion of the weight zero component ${\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \to {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}$ induces an equivalence \[{\rm map}_{{{\rm grCycSp}}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}[1]) \xrightarrow{\simeq} {\rm map}_{{{\rm CycSp}}}({\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1], {\Bbb S}[1]).\] The result now follows from the definition of ${\rm TC}$ \cite[Definition II.1.8(i)]{NS18}. 
\end{proof}

\begin{lemma}\label{lem:equivalencetctc1tr1spec} The spectrum ${\rm map}_{\rm CycSp}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}[1])$ is equivalent to \[{\rm TC}({\Bbb S}) \oplus {\rm TC}({\Bbb S})[1] \oplus {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0}, {\Bbb S}[1]),\] and similarly for ${\rm THH}({\Bbb S}[t_{2d}] | t_{2d})$ by Proposition \ref{prop:eqgradedcyc}. 
\end{lemma}

\begin{proof} We use the decomposition \eqref{eq:diagramofgradedcycsplit} identifying ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}$ with  \[{\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \oplus {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0}\] and conclude by the definition of ${\rm TC}$. 
\end{proof}

\begin{remark} For a cyclotomic spectrum $X$, the mapping spectrum \[{\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0}, X)\] is a variant of ${\rm TR}$ of $X$, where the role of the flat affine line ${\Bbb S}[t]$ is replaced by its graded analog ${\Bbb S}[t_{2d}]$. Using the setup of Example \ref{ex:degreezero}, we find that the spectrum of Lemma \ref{lem:equivalencetctc1tr1spec} admits the clean description ${\rm TC}({\Bbb S}) \oplus {\rm TC}({\Bbb S})[1] \oplus {\rm TR}({\Bbb S})[1]$ by corepresentability of ${\rm TR}$ by ${\Bbb S}[B^{\rm cyc}_{> 0}(\langle t \rangle)]$ (cf.\ \cite[Theorem B]{McC24}) when $d = 0$. 
\end{remark}

\begin{proof}[Proof of Theorem \ref{thm:gradedagreement}] By Proposition \ref{prop:equivalencetctc1spec} and Lemma \ref{lem:equivalencetctc1tr1spec}, \eqref{eq:gradedagreementdiagram} is indeed a map of the form ${\rm TC}({\Bbb S}) \oplus {\rm TC}({\Bbb S})[1] \to {\rm TC}({\Bbb S}) \oplus {\rm TC}({\Bbb S})[1] \oplus {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{> 0}, {\Bbb S}[1])$. It remains to see that it is homotopic to the inclusion. For this, we consider the diagram \[\begin{tikzpicture}[baseline= (a).base]
\node[scale=.935] (a) at (0,0){\begin{tikzcd}[row sep = small, column sep = tiny]{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \ar[swap]{d}{\simeq} \ar{d}{\text{Lemma \ref{lem:gradedcontrol}}} \\ {\rm map}_{{\rm grCycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \ar{d} \ar{r}{\simeq} & {\rm map}_{{\rm CycSp}}({\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1], {\Bbb S}^{\rm triv}[1]) \ar[bend left = 3 mm]{dl} \\ {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \end{tikzcd}};\end{tikzpicture}\] of mapping spectra. The horizontal equivalence, induced by the inclusion of the weight zero component ${\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1] \xrightarrow{} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}$, comes to life from ${\Bbb S}^{\rm triv}[1]$ being concentrated in weight zero. The bent arrow is induced by the projection ${\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}\to {\Bbb S}^{\rm triv} \oplus {\Bbb S}^{\rm triv}[1]$, which is precisely the desired inclusion. 
\end{proof}

\begin{corollary}\label{cor:residuegradedspec} The residue maps \[{\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{\partial^{\rm rep}} {\Bbb S}^{\rm triv}[1] \quad \text{and} \quad {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}]_{\ge 0} \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \xrightarrow{\partial} {\Bbb S}^{\rm triv}[1]\] are homotopic as maps of ${\rm THH}({\Bbb S}[t_{2d}])$-modules in graded cyclotomic spectra. 
\end{corollary}

\begin{proof} They are homotopic as maps of cyclotomic spectra by Corollary \ref{cor:residuecycl}. But in the diagram \[\begin{tikzpicture}[baseline= (a).base]
\node[scale=.735] (a) at (0,0){\begin{tikzcd}[column sep = small]{\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \ar[swap]{d}{\simeq} \ar{d}{\text{Lemma \ref{lem:gradedcontrol}}} \ar{r}{\simeq} & {\rm map}_{{\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\Bbb S}^{\rm triv}[1]) \ar[swap]{d}{\simeq} \ar{d}{\text{Lemma \ref{lem:gradedcontrol}}}   \\ {\rm map}_{{\rm grCycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \ar{d} & {\rm map}_{{\rm grCycSp}}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\Bbb S}^{\rm triv}[1]) \ar{d} \\ {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0}, {\Bbb S}^{\rm triv}[1]) \ar{r}{\simeq} &  {\rm map}_{{\rm CycSp}}({\rm THH}({\Bbb S}[t_{2d}] | t_{2d}), {\Bbb S}^{\rm triv}[1]) \end{tikzcd}};\end{tikzpicture}\] with vertical maps induced by \eqref{eq:forgetfulfunctors} and horizontal equivalences induced by Proposition \ref{prop:eqgradedcyc} and Corollary \ref{cor:undcycspspec}, both vertical compositions are inclusions by Theorem \ref{thm:gradedagreement}. Hence the two residue maps are homotopic in ${\rm Mod}_{{\rm THH}({\Bbb S}[t_{2d}])}({\rm grCycSp})$, since they are homotopic in ${\rm CycSp}$. 
\end{proof}


\subsection{Finalizing the proof of Theorem \ref{thm:mainthmspec}}\label{subsec:finalizingproof} Base-changing the equivalence of Proposition \ref{prop:eqgradedcyc} of underlying ${\rm THH}({\Bbb S}[t_{2d}])$-modules in cyclotomic spectra along the map ${\rm THH}({\Bbb S}[t_{2d}]) \xrightarrow{t_{2d} \mapsto x} {\rm THH}(A)$ to obtain an equivalence \begin{equation}\label{eq:compmapalmosttherespec}{\rm THH}(A) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}^{\pm 1}])_{\ge 0} \xrightarrow{} {\rm THH}(A) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}] | t_{2d})\end{equation} of ${\rm THH}(A)$-modules in cyclotomic spectra. By definition, the source of this map is ${\rm THH}(A, \langle x \rangle)$. We now identify the target:

\begin{lemma}\label{lem:transbasechangespec} There is an equivalence \[{\rm THH}(A) \otimes_{{\rm THH}({\Bbb S}[t_{2d}])} {\rm THH}({\Bbb S}[t_{2d}] | t_{2d}) \xrightarrow{} {\rm THH}(A | x)\] of ${\rm THH}(A)$-modules in cyclotomic spectra. 
\end{lemma}


\begin{proof} We first observe that the diagram \[\begin{tikzcd}{\rm Perf}({\Bbb S}) \ar{r}{p_*} \ar{d} & {\rm Perf}({\Bbb S}[t_{2d}]) \ar{d} \\ {\rm Perf}(A / x) \ar{r}{p_*} & {\rm Perf}(A)\end{tikzcd}\] commutes, with vertical arrows defined by base-change along the maps  ${\Bbb S} \to  A / x$ and ${\Bbb S}[t_{2d}] \xrightarrow{t_{2d} \mapsto x} A$, respectively. This gives rise to the commutative diagram \[\begin{tikzcd}{\rm THH}({\rm Perf}({\Bbb S})) \ar{r}{{\rm THH}(p_*)} \ar{d} & {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])) \ar{d} \\ {\rm THH}({\rm Perf}(A / x)) \ar{r}{{\rm THH}(p_*)} & {\rm THH}({\rm Perf}(A))\end{tikzcd}\] of ${\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))$-modules by Lemma \ref{lem:projectionformula}. It thus base-changes to a diagram \[\begin{tikzpicture}[baseline= (a).base]
\node[scale=.74] (a) at (0,0){\begin{tikzcd}{\rm THH}({\rm Perf}(A)) \otimes_{{\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))} {\rm THH}({\rm Perf}({\Bbb S})) \ar{d}{\simeq} \ar{rr}{{\rm id} \otimes {\rm THH}(p_*)} & & {\rm THH}({\rm Perf}(A)) \otimes_{{\rm THH}({\rm Perf}({\Bbb S}[t_{2d}]))} {\rm THH}({\rm Perf}({\Bbb S}[t_{2d}])) \ar{d}{\simeq} \\ {\rm THH}({\rm Perf}(A / x)) \ar{rr}{{\rm THH}(p_*)} & & {\rm THH}({\rm Perf}(A))\end{tikzcd}};\end{tikzpicture}\] of ${\rm THH}({\rm Perf}(A))$-modules, where the left-hand vertical equivalence is symmetric monoidality of ${\rm THH}$ (cf. \cite[Remark 6.10]{BGT14}). The desired equivalence is that of horizontal cofibers. 
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:mainthmspec}] Both \eqref{eq:compmapalmosttherespec} the map of Lemma \ref{lem:transbasechangespec} are equivalences. The assertion about the residue maps follows from Corollary \ref{cor:residuegradedspec}. 
\end{proof}

Theorem \ref{thm:mainthm} may now be obtained as a special case with $A$ discrete and $d = 0$, or by copying the above argument in the context of Example \ref{ex:degreezero}. In particular, the structure map ${\Bbb S}[t] \xrightarrow{t \mapsto x} A$ and ${\rm THH}(A, \langle x \rangle)$ admit ${\Bbb E}_{\infty}$-structures in this case. 

We end this section with the following two remarks:

\begin{remark}\label{rem:rognesconj} Let us explain how to recover the exact formulation of \cite[Conjecture 7.5]{Rog14} as a consequence of Theorem \ref{thm:mainthmspec}. We recall its context: $E$ is an even-periodic ${\Bbb E}_{\infty}$-ring of period $2d$, $e = \tau_{\ge 0}(E)$ is its connective cover. We ask that $\pi_0(e)$ is regular, and moreover that $\tau_{\le (2d - 1)}(e) = \pi_0(e)$. The first and last hypotheses imply that $e$ is even with homotopy groups concentrated in degrees multiples of $2d$ so that the setup of \cite{RSS25} allows for the construction of ${\rm THH}(e, \langle x \rangle)$ with $x \in \pi_{2d}(e)$ the periodicity class.  

The conjecture predicts that \begin{equation}\label{eq:rognesconj}{\rm THH}(e, \langle x \rangle) \simeq {\rm WTHH}^\Gamma(e | E)\end{equation} as cyclotomic spectra, where ${\rm WTHH}^\Gamma(e | E)$ is the Blumberg--Mandell term \cite{BM20} participating in the localization sequence \[{\rm THH}(\pi_0(e)) \to {\rm THH}(e) \to {\rm WTHH}^\Gamma(e | E),\] and so it is equivalent to what we have written as ${\rm THH}(e | x)$. The left-hand side ${\rm THH}(e, \langle x \rangle)$ is strictly speaking described as the ${\rm THH}$ of the direct image log structure $j_*{\rm GL}_1^{\cal J}(E)$ formed using the model of \cites{RSS15, RSS18}: Under the present hypotheses, \cite[Lemma B.5]{RSS25} provides an equivalence ${\rm THH}(e, \langle x \rangle) \simeq {\rm THH}(e, j_*{\rm GL}_1^{\cal J}(E))$. As no cyclotomic structure has been constructed on the model ${\rm THH}(e, j_*{\rm GL}_1^{\cal J}(E))$, we interpret the conjecture as referring to the cyclotomic structure on the equivalent term ${\rm THH}(e, \langle x \rangle)$.  

Altogether, Theorem \ref{thm:mainthmspec} produces an equivalence \eqref{eq:rognesconj} of cyclotomic spectra with the predicted identification of the boundary maps. 
\end{remark}


\begin{remark}\label{rem:koinclude} Most of our arguments may be adapted to the context \cites{RSS15, RSS18}. While the setup of \cite{RSS25} does not include a pre-log structure of the form $({\rm ko}, \langle w \rangle)$ generated by the Bott class $w \in \pi_8({\rm ko})$, this works in their old model. If one writes down a cyclotomic structure on ${\rm THH}({\Bbb S}^{\cal J}[D(w)], D(w))$ (which plays the role of ${\rm THH}({\Bbb S}[t_{2d}], \langle t_{2d} \rangle)$ in this setting) with the expected properties, we obtain compatible horizontal cofiber sequences \[\begin{tikzcd}K(\tau_{\le 7}({\rm ko})) \ar{r} \ar{d} & K({\rm ko}) \ar{r} \ar{d} & K({\rm Perf}({\rm ko} | w)) \ar{d} \\ {\rm TC}(\tau_{\le 7}({\rm ko})) \ar{r} & {\rm TC}({\rm ko}) \ar{r} & {\rm TC}({\rm ko}, \langle w\rangle)\end{tikzcd}\] that differs from the cofiber sequences \[\begin{tikzcd}K({\Bbb Z}) \ar{r} \ar{d} & K({\rm ko}) \ar{r} \ar{d} & K({\rm KO}) \ar{d} \\ {\rm TC}({\Bbb Z}) \ar{r} & {\rm TC}({\rm ko}) \ar{r} & {\rm TC}({\rm ko} |  {\rm KO})\end{tikzcd}\] obtained from combining Barwick--Lawson \cite{BL14} and Blumberg--Mandell \cite{BM20}. 
\end{remark}


\section{Compatibility with the Hesselholt--Madsen construction}\label{sec:hmcomp} We now proceed to work towards the proof of Theorem \ref{thm:hmcomp}, making active use of the constructions of the previous sections. To begin, let us first recall the general notion of a log ring and how topological Hochschild homology is defined in this level of generality: 

\subsection{Pre-log and log rings} A \emph{pre-log ring} $(A, M) = (A, M, \alpha)$ consists of a commutative ring $A$, commutative monoid $M$, and map $\alpha \colon M \to (A, \cdot)$ of commutative monoids, adjoint to a map $\bar{\alpha} \colon {\Bbb Z}[M] \to A$ of commutative rings. It is a \emph{log ring} if the canonical map $\alpha^{-1}{\rm GL}_1(A) \xrightarrow{} {\rm GL}_1(A)$ is an isomorphism. The category of pre-log rings embeds fully faithfully into that of log rings, and the inclusion admits a left adjoint $(A, M, \alpha) \mapsto (A, M^a, \alpha^a)$ determined by \[M^a := M \oplus_{\alpha^{-1}{\rm GL}_1(A)} {\rm GL}_1(A) \xrightarrow{\alpha^a} (A, \cdot),\] where $\alpha^a$ is defined by $\alpha$ and the inclusion of units. 

\subsection{The log differentials} Let $(A, M)$ be a pre-log ring. The \emph{log differentials} $\Omega^1_{(A, M)}$ can be defined as the (ordinary, non-derived) pushout of the diagram \[\Omega^1_{A} \xleftarrow{ad\alpha(m)\mapsfrom a \otimes d(m)} A \otimes_{{\Bbb Z}[M]} \Omega^1_{{\Bbb Z}[M]} \xrightarrow{a \otimes d(m) \mapsto a\alpha(m) \otimes \gamma(m)} A \otimes_{{\Bbb Z}} M^{\rm gp}\] of $A$-modules, cf.\ \cite[(1.7)]{Kat89}. 


\subsection{Logarithmic topological Hochschild homology}\label{subsec:logthh} Recall the replete bar construction $B^{\rm rep}(M)$ of Section \ref{subsec:repbar}. The following definition is due to Rognes: 

\begin{definition}[{\cite[Definition 8.11]{Rog09}}]\label{def:logthh} Let $(A, M)$ be a pre-log ring. The \emph{log topological Hochschild homology} ${\rm THH}(A, M)$ is the ${\Bbb E}_{\infty}$-ring given by the relative tensor product \[{\rm THH}(A, M) := {\rm THH}(A) \otimes_{{\Bbb S}[B^{\rm cyc}(M)]} {\Bbb S}[B^{\rm rep}(M)]\] of ${\Bbb E}_{\infty}$-rings.
\end{definition}

There are isomorphisms \[\pi_0{\rm THH}(A, M) \cong A \quad \text{and} \quad \pi_1{\rm THH}(A, M) \cong \Omega^1_{(A, M)}\] obtained by combining \cite[Proposition 5.13]{BLPO23} with \cite[Corollary 3.4, Lemma 3.5]{BLPO23Prism}, cf.\ \cite[Definition 5.27]{Rog09} and the ensuing discussion. By \cite[Construction 3.7]{BLPO23Prism}, we find that ${\rm THH}(A, M)$ is naturally an ${\Bbb E}_{\infty}$-algebra in cyclotomic spectra. We set ${\rm TC}(A, M) := {\rm TC}({\rm THH}(A, M))$. 

\begin{remark}\label{rem:logthhinv} By \cite[Theorem 4.24]{RSS15}, logarithmic ${\rm THH}$ is invariant under the logification construction: The canonical map ${\rm THH}(A, M) \xrightarrow{} {\rm THH}(A, M^a)$ is an equivalence. In particular, if ${\cal O}_K$ is a discrete valuation ring with chosen uniformizer $\pi$, the canonical map ${\rm THH}({\cal O}_K, \langle \pi \rangle) \xrightarrow{} {\rm THH}({\cal O}_K, {\cal O}_K \cap {\rm GL}_1(K))$ is an equivalence. In this way, logarithmic ${\rm THH}$ is independent of the choice of uniformizer. Analogously, a variant of logification invariance is established for general log ring spectra in \cite[Theorem 8.15]{RSS25}, rendering the construction of ${\rm THH}(A, \langle x \rangle)$ studied in Section \ref{sec:logthhloc} independent of the choice of map ${\Bbb S}[t_{2d}] \xrightarrow{} A$ capturing $x \in \pi_{2d}(A)$. 
\end{remark}


\subsection{The log differential graded ring $\pi_*{\rm THH}(A, M)$}\label{subsec:logthhlogdiff} In general, the term ${\rm THH}(A, \langle x \rangle)$ carries \emph{a priori} more structure than the abstractly defined cofiber ${\rm THH}(A | x)$; it is an ${\Bbb E}_{\infty}$-ring, whose coefficient ring forms a log differential graded ring in the following sense (cf.\ \cite{Kat89} or \cite[p.\ 4]{HM03}):

\begin{definition}\label{def:logdiff} A \emph{log differential graded ring} $(B_*, M) = (B_*, M, d, \alpha, {\rm dlog})$ is
\begin{enumerate}
\item[(a)] a differential graded ring $(B_*, d)$;
\item[(b)] a pre-log ring $(B_0, M) = (B_0, M, \alpha)$; and
\item[(c)] a map ${\rm dlog} \colon M \to (B_1, +)$ of commutative monoids
\end{enumerate}
satisfying the relations $d(\alpha(m)) = \alpha(m){\rm dlog}(m)$ and $d({\rm dlog}(m)) = 0$. 
\end{definition}

We now explain how $\pi_*{\rm THH}(A, M)$ is an example for general $(A, M)$. The $S^1$-action on the spectrum ${\rm THH}(A, M)$ induces a map \[\delta \colon \pi_*{\rm THH}(A, M) \to \pi_{* + 1}{\rm THH}(A, M).\] We have $\delta^2 = \eta\delta = 0$, since ${\rm THH}(A, M)$ is an $A$-algebra.  The map $\delta$ exhibits $\pi_*{\rm THH}(A, M)$ as a differential graded ring (cf.\ \cite[Section 1]{Hes96}). In degree zero, we choose the given pre-log structure $(A, M)$. We define \[{\rm dlog} \colon M \to \pi_1{\rm THH}(A, M) \cong \Omega^1_{(A, M)}\] to be the canonical map $m \mapsto {\rm dlog}(m)$. This is indeed a log differential graded ring:

\begin{proposition}\label{prop:logthhlogdiff} The structure maps described above exhibit $\pi_*{\rm THH}(A, M)$ as a log differential graded ring. 
\end{proposition}

\begin{proof} The proof of \cite[Proposition 1.4.5]{Hes96} shows that the linearization map ${\rm THH}(A, M) \to {\rm HH}(A, M)$ participates in the left-hand commutative diagram \[\begin{tikzcd}\pi_n{\rm THH}(A, M) \ar{d}{\delta} \ar{r} & \pi_n{\rm HH}(A, M) \ar{d}{B} & \Omega^n_{(A, M)} \ar{d}{d} \ar{l} \\ \pi_{n + 1}{\rm THH}(A, M) \ar{r} & \pi_{n + 1}{\rm HH}(A, M) & \Omega^{n + 1}_{(A, M)} \ar{l},\end{tikzcd}\] where $B$ is Connes' operator. The right-hand commutative diagram is \cite[Proposition 2.12]{BLPO23Prism}. From this, the relation $\delta(\alpha(m)) = \alpha(m){\rm dlog}(m)$ follows from all horizontal maps being isomorphisms in degrees $0$ and $1$ and the relation $d(\alpha(m)) = \alpha(m){\rm dlog}(m)$ in $\Omega^1_{(A, M)}$. 

It remains to prove that $\delta({\rm dlog}(m)) = 0$. As the linearization map is still an isomorphism in degree $2$, this follows from the relation $B({\rm dlog}(m)) = 0$ established in the proof of \cite[Proposition 2.12]{BLPO23Prism}. 
\end{proof}

\subsection{The special case of regular quotients} We now consider the case of pre-log rings of the form $(A, \langle x \rangle)$ with $A$ regular Noetherian, and we moreover assume that the quotient $A/x$ is regular. Then d\'evissage implies that that there is a diagram \[\begin{tikzcd}K(A/x) \ar{r}{K(p_*)} \ar{d} & K(A) \ar{d} \ar{r} & K(A[x^{-1}]) \ar{d} \\ {\rm THH}(A/x) \ar{r}{{\rm THH}(p_*)} & {\rm THH}(A) \ar{r} & {\rm THH}(A | x)\end{tikzcd}\] of horizontal cofiber sequences. We have an explicit model of the right-hand trace map in mind, namely \[K(A[x^{-1}]) \xleftarrow{\simeq} K({\rm Perf}(A | x)) \xrightarrow{{\rm tr}} {\rm THH}({\rm Perf}(A | x)) =: {\rm THH}(A | x),\]  where ${\rm Perf}(A | x)$ is defined as the cofiber in ${\rm Cat}_{\infty}^{\rm perf}$ of the fully faithful functor appearing in the functorial factorization of the transfer $p_* \colon {\rm Perf}(A/x) \to {\rm Perf}(A)$ provided by \cite[Proposition 2.8]{RSW25}. With our hypotheses, the left-hand map $K({\rm Perf}(A | x)) \xrightarrow{} K(A[x^{-1}])$ is an equivalence by d\'evissage. 

The following statement makes reference to the map \[{\rm dlog} \colon {\Bbb S}[B\langle t \rangle^{\rm gp}] \xrightarrow{} {\Bbb S}[t] \otimes {\Bbb S}[B\langle t \rangle^{\rm gp}] \cong {\Bbb S}[B^{\rm rep}(\langle t \rangle)] \cong {\rm THH}({\Bbb S}[t], \langle t \rangle)\] of ${\Bbb E}_{\infty}$-rings. 

\begin{proposition}\label{prop:dlogcomp} The diagram \[\begin{tikzcd}{\Bbb S}[B\langle t \rangle^{\rm gp}] \ar{r}{t \mapsto x} \ar{d}{{\rm dlog}} & {\Bbb S}[{\rm BGL}_1(A[x^{-1}])] \ar{r} & K(A[x^{-1}]) \ar{d}{{\rm tr}} \\ {\rm THH}({\Bbb S}[t], \langle t \rangle) \ar{r}{\simeq} & {\rm THH}({\Bbb S}[t] | t) \ar{r}{t \mapsto x} & {\rm THH}(A | x)\end{tikzcd}\] of spectra commutes. 
\end{proposition}

\begin{proof} The diagram in question is equivalent to the outer diagram in \begin{equation}\label{eq:dlogcompproofdiagram}\begin{tikzcd}{\Bbb S}[B\langle t \rangle^{\rm gp}] \ar{r} \ar{d}{{\rm dlog}} & {\Bbb S}[{\rm BGL}_1(A[t^{\pm 1}])] \ar{r} & K(A[t^{\pm 1}]) \ar{d}{{\rm tr}}\ar{r}{t \mapsto x} & K(A[x^{\pm 1}]) \ar{d}{{\rm tr}}\\ {\rm THH}({\Bbb S}[t], \langle t \rangle) \ar{r}{\simeq} & {\rm THH}({\Bbb S}[t] | t) \ar{r} & {\rm THH}(A[t] | t) \ar{r}{t \mapsto x} & {\rm THH}(A | x),\end{tikzcd}\end{equation} and so it suffices to prove that the left-hand square commutes. The composition involving ${\rm dlog}$ is equivalent to the composition \begin{equation}\label{eq:dlogcompproofdiagram2}\begin{tikzcd}[row sep = small]{\Bbb S}[B\langle t \rangle^{\rm gp}] \ar{r} & {\rm THH}(A) \otimes {\Bbb S}[B\langle t \rangle^{\rm gp}] \ar{r}{{\rm id} \otimes {\rm dlog}} &  {\rm THH}(A) \otimes {\rm THH}({\Bbb S}[t], \langle t \rangle) \ar{d}{\simeq} \\ \vspace{10 mm} & &  {\rm THH}(A) \otimes {\rm THH}({\Bbb S}[t] | t) \ar{d}{\cong} \\ \vspace{10 mm} & & {\rm THH}(A[t]) \otimes_{{\rm THH}({\Bbb S}[t])} {\rm THH}({\Bbb S}[t] | t) \ar{d}{\simeq} \ar[swap]{d}{\text{Lemma \ref{lem:transbasechangespec}}} \\ \vspace{10 mm} & &  {\rm THH}(A[t] | t).\end{tikzcd}\end{equation} In other words, it is equivalent to the map ${\Bbb S}[B\langle t \rangle^{\rm gp}] \to {\rm THH}(A) \otimes {\Bbb S}[B\langle t \rangle^{\rm gp}]$ induced by the unit of ${\rm THH}(A)$ followed by the inclusion of summands \[{\rm THH}(A) \oplus {\rm THH}(A)[1] \to  {\rm THH}(A) \oplus {\rm THH}(A)[1] \oplus {\rm THH}(A)[B^{\rm cyc}_{> 0}(\langle t \rangle^{\rm gp})],\] cf.\ \eqref{eq:susprepsplit}. We now wish to make the same statement about the composition in the left-hand diagram of \eqref{eq:dlogcompproofdiagram} involving the trace. For this, we postcompose this composition with ${\rm THH}(A[t] | t) \to {\rm THH}(A[t^{\pm 1}])$; that is, we consider the composition \[{\Bbb S}[B\langle t \rangle^{\rm gp}] \xrightarrow{} {{\Bbb S}[{\rm BGL}_1(A[t^{\pm 1}])]} \xrightarrow{} K(A[t^{\pm 1}]) \xrightarrow{{\rm tr}} {\rm THH}(A[t] | t) \xrightarrow{} {\rm THH}(A[t^{\pm 1}]),\] where the composition of the last two maps is by construction the usual trace $K(A[t^{\pm 1}]) \to {\rm THH}(A[t^{\pm 1}])$. By Antieau--Barthel--Gepner \cite[Proposition 2.5]{ABG18}, this is equivalent to the upper horizontal composition in the commutative diagram \[\begin{tikzpicture}[baseline= (a).base]
\node[scale=.88] (a) at (0,0){\begin{tikzcd}[column sep = small, row sep = small]{\Bbb S}[B\langle t \rangle^{\rm gp}]  \ar[swap,bend right = 3 mm]{ddrr}{\eqref{eq:dlogcompproofdiagram2}}\ar{r}{{\rm dlog}} & {\rm THH}({\Bbb S}[t], \langle t \rangle) \ar{r}{\simeq} & {\rm THH}({\Bbb S}[t] | t) \ar{r} \ar{d} &  {\rm THH}({\Bbb S}[t^{\pm 1}]) \ar{r} & {\rm THH}(A[t^{\pm 1}]). \\ \vspace{10 mm} & & {\rm THH}(A) \otimes {\rm THH}({\Bbb S}[t] | t) \ar{d}{\simeq} \\ \vspace{10 mm} & & {\rm THH}(A[t] | t) \ar[bend right = 3 mm]{uurr}\end{tikzcd}};\end{tikzpicture}\] Since the map ${\rm THH}(A[t] | t) \to {\rm THH}(A[t^{\pm 1}])$ is equivalent to the inclusion \[\begin{tikzcd}[row sep = small]{\rm THH}(A) \oplus {\rm THH}(A)[1] \oplus {\rm THH}(A)[B^{\rm cyc}_{> 0}(\langle t \rangle^{\rm gp})] \ar{d} \\ {\rm THH}(A) \oplus {\rm THH}(A)[1] \oplus {\rm THH}(A)[B^{\rm cyc}_{> 0}(\langle t \rangle^{\rm gp})] \oplus {\rm THH}(A)[B^{\rm cyc}_{< 0}(\langle t \rangle^{\rm gp})] \end{tikzcd}\] by Proposition \ref{prop:controllingf} and Lemma \ref{lem:transbasechangespec}, we find that the two compositions already agree in ${\rm THH}(A[t] | t)$ (as both are ${\Bbb S}[B\langle t \rangle^{\rm gp}] \to {\rm THH}(A) \otimes {\Bbb S}[B\langle t \rangle^{\rm gp}]$ followed by the inclusion), which concludes the proof. 
\end{proof}

\subsection{Recollections from \cite{HM03}}\label{subsec:hmrecall} Suppose now that ${\cal O}_K$ is a complete discrete valuation ring of mixed characteristic with perfect residue field $k = {\cal O}_K / \pi$ and fraction field $K = {\cal O}_K[\pi^{-1}]$. We will now recall the (output of the) construction of the term ${\rm THH}({\cal O}_K | K)$. 

For a commutative ring $A$, let ${\cal P}(A)$ denote the category of perfect complexes of $A$-modules. For $A = {\cal O}_K$, there are two natural choices of weak equivalences on ${\cal P}({\cal O}_K)$ that participate in the structure of a Waldhausen category: the quasi-isomorphisms $w{\cal P}({\cal O}_K)$, and the maps that become quasi-isomorphisms after base-change along ${\cal O}_K \to K$, denoted $v{\cal P}({\cal O}_K)$. Waldhausen's fibration theorem \cite[Theorem 1.6.4]{Wal85} gives the upper horizontal cofiber sequence in the diagram \begin{equation}\label{eq:waldcof}\begin{tikzpicture}[baseline= (a).base]
\node[scale=.94] (a) at (0,0){\begin{tikzcd}[column sep = tiny] K({\cal P}({\cal O}_K)^{v{\cal P}({\cal O}_K)}, w{\cal P}({\cal O}_K)) \ar{r} \ar{d}{{\rm tr}} & K({\cal P}({\cal O}_K), w{\cal P}({\cal O}_K)) \ar{r} \ar{d}{{\rm tr}} & K({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K)) \ar{d}{{\rm tr}} \\ {\rm THH}({\cal P}({\cal O}_K)^{v{\cal P}({\cal O}_K)}, w{\cal P}({\cal O}_K)) \ar{r} & {\rm THH}({\cal P}({\cal O}_K), w{\cal P}({\cal O}_K)) \ar{r} & {\rm THH}({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K)),\end{tikzcd}};\end{tikzpicture}\end{equation} where ${\cal P}({\cal O}_K)^{v{\cal P}({\cal O}_K)}$ is the full subcategory of ${\cal P}({\cal O}_K)$ consisting of those complexes that are $v{\cal P}({\cal O}_K)$-acyclic; that is, those that become acyclic after base-change along ${\cal O}_K \to K$. Waldhausen's approximation theorem \cite[Theorem 1.6.7]{Wal85} implies that extension of scalars induces an equivalence $K({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K)) \xrightarrow{} K({\cal P}(K), w{\cal P}(K)) \simeq K(K)$, while d\'evissage implies that restriction of scalars induces an equivalence $K(k) \simeq K({\cal P}(k), w{\cal P}(k)) \to K({\cal P}({\cal O}_K)^{v{\cal P}({\cal O}_K)}, w{\cal P}({\cal O}_K))$. This identifies the upper horizontal cofiber sequence of \eqref{eq:waldcof} with the usual cofiber sequence $K(k) \xrightarrow{K(p_*)} K({\cal O}_K) \xrightarrow{} K(K)$ induced by the Karoubi sequence \[{\rm Perf}({\cal O}_K)^{\pi-{\rm nil}} \xrightarrow{} {\rm Perf}({\cal O}_K) \xrightarrow{} {\rm Perf}(K).\] We now discuss the lower horizontal sequence in \eqref{eq:waldcof}. The terms are defined in \cite[Section 1.2]{HM03}, in which Hesselholt--Madsen associate to any Waldhausen category enriched in abelian groups a spectrally enriched category, of which we can form the topological Hochschild homology using the usual cyclic nerve. This variant of ${\rm THH}$ comes with a version of the fibration theorem \cite[Theorem 1.3.11]{HM03} and d\'evissage \cite[Theorem 1]{Dun98} (see Remark \ref{rem:devissageweird}), but no approximation theorem. In conclusion, the diagram \eqref{eq:waldcof} takes the form  \begin{equation}\label{eq:waldcof2}\begin{tikzcd} K(k) \ar{r}{K(p_*)} \ar{d}{{\rm tr}} & K({\cal O}_K) \ar{r} \ar{d}{{\rm tr}} & K(K) \ar{d}{{\rm tr}} \\ {\rm THH}(k) \ar{r}{{\rm THH}(p_*)} & {\rm THH}({\cal O}_K) \ar{r} & {\rm THH}({\cal O}_K | K),\end{tikzcd}\end{equation} where ${\rm THH}({\cal O}_K | K) := {\rm THH}({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K))$.

\begin{remark}\label{rem:devissageweird} While the bottom horizontal cofiber sequence in \eqref{eq:waldcof2} comes to life from d\'evissage, it is not the case that the localizing invariant ${\rm THH}$ satisfies d\'evissage. We now flesh out this potentially confusing discrepancy. Throughout this remark, we sweep some details of the setup of \cite{BM20} under the rug so that the point of the discussion is not lost in technicalities. 

Any stable $\infty$-category ${\cal C}$ is naturally enriched in spectra, leading to the usual definition of ${\rm THH}({\cal C})$ as the realization of the cyclic nerve. There is also a different choice of enrichment, as explained in \cite[Section 2.2]{BM20}: One may define ${\rm map}_{{\cal C}}^{\Gamma}(x, y)$ to be the connective spectrum associated to the Segal $\Gamma$-space with $n$th space ${\rm Map}_{\cal C}(x, \bigoplus_{i = 1}^n y)$. Forming the cyclic nerve with respect to the resulting spectral enrichment, one obtains an alternative definition ${\rm THH}^\Gamma({\cal C})$. This choice is in fact rather natural; for example, following this recipe in the context of exact categories gives exactly the spectral enrichment considered by e.g.\ Dundas--McCarthy \cite{DM96} and Hesselholt--Madsen \cite{HM03} by \cite[Example 2.13]{BM20}. 

If $R$ is a \emph{connective} ${\Bbb E}_{\infty}$-ring, then ${\rm THH}^\Gamma({\rm Perf}(R)) \xrightarrow{\simeq} {\rm THH}({\rm Perf}(R))$ by \cite[Theorem 2.56]{BM20}. But the categories that naturally appear when studying the localization properties for localizing invariants very quickly forces you out of the connective setting: For example, in the diagram \begin{equation}\label{eq:nonconndiag}\begin{tikzcd}{\rm THH}^\Gamma({\rm Perf}({\Bbb Z})^{p - {\rm nil}}) \ar{r} \ar{d} & {\rm THH}^\Gamma({\rm Perf}({\Bbb Z})) \ar{d}{\simeq} \\ {\rm THH}({\rm Perf}({\Bbb Z})^{p - {\rm nil}}) \ar{r} & {\rm THH}({\rm Perf}({\Bbb Z})),\end{tikzcd}\end{equation} only the right-hand vertical map is an equivalence. Indeed, Schwede--Shipley \cite[Theorem 3.3]{SS03} applies to obtain an equivalence ${\rm Perf}({\Bbb Z})^{p - {\rm nil}} \simeq {\rm Perf}({\rm End}_{{\Bbb Z}}({\Bbb Z}/p))$, which are compact modules over a non-connective ring spectrum with homotopy groups as ${\Bbb Z}/p$ in degrees $-1$ and $0$. In this situation, \cite[Theorem 1]{Dun98} applies to identify \[{\rm THH}({\Bbb F}_p) \xleftarrow{\simeq} {\rm THH}^\Gamma({\rm Perf}({\Bbb F}_p)) \xrightarrow{\simeq} {\rm THH}^\Gamma({\rm Perf}({\Bbb Z})^{p - {\rm nil}}).\] The resulting cofiber of the top horizontal map in \eqref{eq:nonconndiag} is modelled as the ${\rm THH}^\Gamma$ of a Waldhausen category in \cite{HM03}, which differs from ${\rm THH}({\Bbb Z}[1/p])$. 
\end{remark}

\subsection{Constructing the comparison map} We now have two models for the cofiber of the transfer map ${\rm THH}(p_*) \colon {\rm THH}(k) \to {\rm THH}({\cal O}_K)$, namely the abstractly defined cofiber ${\rm THH}({\cal O}_K | \pi)$ and the Hesselholt--Madsen term ${\rm THH}({\cal O}_K | K)$. By virtue of its definition in terms of the Waldhausen category $({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K))$, the symmetric monoidal structure of ${\cal P}({\cal O}_K)$ endows ${\rm THH}({\cal O}_K | K)$ with the structure of an ${\Bbb E}_{\infty}$-algebra in cyclotomic spectra. We construct a map \begin{equation}\label{eq:tohm}{\rm THH}({\cal O}_K, \langle \pi \rangle) \to {\rm THH}({\cal O}_K | K)\end{equation} of ${\rm THH}({\cal O}_K)$-modules in cyclotomic spectra by base-changing the map \[{\Bbb S}[B^{\rm rep}(\langle t \rangle)] \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t] | t) \xrightarrow{t \mapsto \pi} {\rm THH}({\cal O}_K | K)\] of ${\Bbb S}[B^{\rm cyc}(\langle t \rangle)]$-modules in cyclotomic spectra along ${\Bbb S}[B^{\rm cyc}(\langle t \rangle)] \xrightarrow{t \mapsto \pi} {\rm THH}({\cal O}_K)$. 

\begin{proposition}\label{prop:dgrings} The map $\pi_*{\rm THH}({\cal O}_K, \langle \pi \rangle) \xrightarrow{\pi_*\eqref{eq:tohm}} \pi_*{\rm THH}({\cal O}_K | K)$ is one of differential graded rings. 
\end{proposition}

\begin{proof} Since both the source and target of \eqref{eq:tohm} are ${\Bbb E}_{\infty}$-algebras in cyclotomic spectra, and in particular ${\Bbb E}_{\infty}$-algebras in ${\rm Sp}^{BS^1}$, the degree-increasing differential $\delta$ induced by the $S^1$-action exhibits both as differential graded rings \cite[Section 1.4]{Hes96}. We have here used that both ${\rm THH}({\cal O}_K, \langle \pi \rangle)$ and ${\rm THH}({\cal O}_K | K)$ are ${\cal O}_K$-algebras to ensure that the differentials square to zero. Since \eqref{eq:tohm} is a map of cyclotomic spectra, we have that the square \[\begin{tikzcd}\pi_*{\rm THH}({\cal O}_K, \langle \pi \rangle) \ar{r}{\pi_*\eqref{eq:tohm}} \ar{d}{\delta} & \pi_*{\rm THH}({\cal O}_K | K) \ar{d}{\delta}\\ \pi_{* + 1}{\rm THH}({\cal O}_K, \langle \pi \rangle) \ar{r}{\pi_{* + 1}\eqref{eq:tohm}} & \pi_{* + 1}{\rm THH}({\cal O}_K | K) \end{tikzcd}\] commutes. It only remains to show that $\pi_*\eqref{eq:tohm}$ is a map of graded commutative rings. For this, let us consider the morphism \begin{equation}\label{eq:inducedstalg}{\Bbb S}[t] \otimes {\Bbb S}[B\langle t \rangle^{\rm gp}] \cong {\Bbb S}[B^{\rm rep}(\langle t \rangle)] \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t] | t) \xrightarrow{t \mapsto \pi} {\rm THH}({\cal O}_K | K)\end{equation} of ${\Bbb S}[B^{\rm cyc}(\langle t \rangle)]$-modules as a ${\Bbb S}[t]$-module map by restriction of scalars along the inclusion of $0$-simplices ${\Bbb S}[t] \to {\Bbb S}[B^{\rm cyc}(\langle t \rangle)]$. This ${\Bbb S}[t]$-module map is adjoint to the map of spectra \begin{equation}\label{eq:fromreptohm1}{\Bbb S}[B\langle t \rangle^{\rm gp}] \xrightarrow{{\rm dlog}} {\Bbb S}[B^{\rm rep}(\langle t \rangle)] \xrightarrow{\simeq} {\rm THH}({\Bbb S}[t] | t) \xrightarrow{t \mapsto \pi} {\rm THH}({\cal O}_K | K).\end{equation} By Proposition \ref{prop:dlogcomp}, this is equivalent to the composition \[{\Bbb S}[B\langle t \rangle^{\rm gp}] \xrightarrow{t \mapsto \pi} {\Bbb S}[B{\rm GL}_1(K)] \xrightarrow{} K(K) \xrightarrow{{\rm tr}} {\rm THH}({\cal O}_K | K)\] of (homotopy) commutative ring spectra. Since \eqref{eq:inducedstalg} is defined by extension of scalars along the map ${\Bbb S}[t] \to {\Bbb S}[B^{\rm cyc}(\langle t \rangle)] \xrightarrow{t \mapsto \pi} {\rm THH}({\cal O}_K) \xrightarrow{} {\rm THH}({\cal O}_K | K)$ of homotopy commutative ring spectra, it is a map of homotopy commutative ring spectra. Hence this is also the case of the base-change \eqref{eq:tohm} along the multiplicative map ${\rm THH}({\Bbb S}[t]) \xrightarrow{t \mapsto \pi} {\rm THH}({\cal O}_K)$, and in particular $\pi_*\eqref{eq:tohm}$ is a map of graded commutative rings, as claimed. 
\end{proof}

\begin{remark}\label{rem:awkward} The proof does \emph{not} show that \eqref{eq:tohm} is an equivalence of ${\Bbb E}_{\infty}$-algebras in cyclotomic spectra. While we strongly expect that this is the case, we abandon the $S^1$-action as soon as we make reference to the non-equivariant map ${\Bbb S}[t] \xrightarrow{} {\Bbb S}[B^{\rm cyc}(\langle t \rangle)]$. In our attempts to address this issue, the core difficulty lies with a lack of understanding of the mapping space ${\rm Map}_{{\rm CAlg}^{BS^1}}({\Bbb S}[B^{\rm rep}(\langle t \rangle)], {\rm THH}({\cal O}_K | K))$ and in particular its relation to the mapping space ${\rm Map}_{{\rm CAlg}^{BS^1}}({\Bbb S}[B\langle t \rangle^{\rm gp}], {\rm THH}({\cal O}_K | K))$. These difficulties are in stark contrast to the non-logarithmic situation, where there is an equivalence of mapping spaces \[{\rm Map}_{{\rm CAlg}^{BS^1}}({\Bbb S}[B^{\rm cyc}(\langle t \rangle)], {\rm THH}({\cal O}_K | K)) \simeq {\rm Map}_{{\rm CAlg}}({\Bbb S}[t], {\rm THH}({\cal O}_K | K))\] by McClure--Schw\"anzl--Vogt \cite{MSV97}. 

Nonetheless, one may use ${\rm THH}({\cal O}_K, \langle \pi \rangle)$ as a model to reproduce the spectacular result \cite[Theorem C]{HM03} relating logarithmic ${\rm TR}$ to the log de Rham--Witt complex. By inspection, one identifies \cite[p.\ 43]{HM03} as the crucial point in the argument of \emph{loc.\ cit.}\ where an explicit property of the transfer map ${\rm THH}(p_*)$ is used (as opposed to merely having a cofiber sequence with the correct terms). A suitable replacement for this property is the following: For a finite extension $K \subset L$ with ramification index $e_{L / K}$, the diagram \[\begin{tikzcd}[row sep = small]{\rm THH}({\cal O}_K, \langle \pi_K \rangle) \ar{d} \ar{r}{\partial^{\rm rep}} & {\rm THH}({\cal O}_K / \pi_K)[1] \ar{d}{{\rm THH}(i)[1] \cdot e_{L / K}} \\  {\rm THH}({\cal O}_L, \langle \pi_L \rangle) \ar{r}{\partial^{\rm rep}} & {\rm THH}({\cal O}_L / \pi_L)[1]\end{tikzcd}\] commutes, and recovers the diagram \[\begin{tikzcd}[row sep = small]\Omega^1_{({\cal O}_K, \langle \pi_K \rangle)} \ar{d} \ar{r}{} & {\cal O}_K / \pi_K \ar{d}{i \cdot e_{L / K}} \\  \Omega^1_{({\cal O}_L, \langle \pi_L \rangle)} \ar{r}{} & {\cal O}_L / \pi_L\end{tikzcd}\] on $\pi_1$, where $i \colon {\cal O}_K / \pi_K \to {\cal O}_L / \pi_L$ denotes the induced map of residue fields. Using this, one can mimic the argument of \cite{HM03} with ${\rm THH}({\cal O}_K, \langle \pi_K \rangle)$ in place of ${\rm THH}({\cal O}_K | K)$. We leave the details to the interested reader. 
\end{remark}




\subsection{The log differential graded ring $\pi_*{\rm THH}({\cal O}_K | K)$} So far, we have constructed an explicit equivalence ${\rm THH}({\cal O}_K, \langle \pi \rangle) \xrightarrow{\simeq} {\rm THH}({\cal O}_K | K)$ of ${\rm THH}({\cal O}_K)$-modules in cyclotomic spectra. By Proposition \ref{prop:dgrings}, the induced map \begin{equation}\label{eq:logdiffrings}\pi_*{\rm THH}({\cal O}_K, \langle \pi \rangle) \xrightarrow{\cong} \pi_*{\rm THH}({\cal O}_K | K)\end{equation} is an isomorphism of differential graded rings. 

We now aim to show that the map \eqref{eq:logdiffrings} preserves one final piece of structure, namely that of a log differential graded ring (cf.\ Definition \ref{def:logdiff}). We determined this structure on $\pi_*{\rm THH}({\cal O}_K, \langle \pi \rangle)$ in Proposition \ref{prop:logthhlogdiff}, and we will now recall from \cite[Proof of Proposition 2.3.1]{HM03} how it comes to life on $\pi_*{\rm THH}({\cal O}_K | K)$. 

We first observe that Hesselholt--Madsen phrase the log differentials as an invariant of log rings (as opposed to pre-log rings), and so they are concerned with $\Omega^1_{({\cal O}_K, {\cal O}_K \cap {\rm GL}_1(K))}$. By \cite[(1.7)]{Kat89}, the map $\Omega^1_{({\cal O}_K, \langle \pi \rangle)} \xrightarrow{} \Omega^1_{({\cal O}_K, {\cal O}_K \cap {\rm GL}_1(K))}$ is an isomorphism. As explained in the last paragraph of \cite[p.\ 37]{HM03}, one defines the morphism ${\rm dlog} \colon {\cal O}_K \cap {\rm GL}_1(K) \to \pi_1{\rm THH}({\cal O}_K | K)$ as a composite \[\begin{tikzcd}{\cal O}_K \cap {\rm GL}_1(K) \ar[bend right = 5 mm]{rrd}{{\rm dlog}} \ar{r} & \pi_1B({\cal O}_K \cap {\rm GL}_1(K)) \ar{r}{\pi_1\widetilde{{\rm det}}}  & \pi_1K({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K)) \ar{d}{{\rm tr}} \\ \vspace{10 mm} & &  \pi_1{\rm THH}({\cal O}_K | K),\end{tikzcd}\] where $({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K))$ is the Waldhausen category of perfect ${\cal O}_K$-modules with weak equivalences those maps that become equivalences after base-change along ${\cal O}_K \to K$, ${\rm tr}$ is the trace map to the ${\rm THH}$ of this Waldhausen category (which is how Hesselholt--Madsen define ${\rm THH}({\cal O}_K | K)$). 

We proceed to describe the map $\widetilde{{\rm det}}$. For any object $X$ of a Waldhausen category ${\cal C}$, we may define a map \[\widetilde{\rm det} \colon \Sigma^\infty B{\rm Aut}(X) \to K({\cal C}),\] as explained in \cite[p.\ 37]{HM03}. Here ${\rm Aut}(X)$ is defined to be the \emph{endo}morphisms in the category of weak equivalences in ${\cal C}$. In the example at hand we set $X = {\cal O}_K[0]$, so that ${\rm Aut}(X) = {\cal O}_K \cap {\rm GL}_1(K)$ since weak equivalences are checked after base-change along ${\cal O}_K \to K$. In the example where ${\cal C} = {\cal P}(K)$ is the category of perfect $K$-modules (with its usual weak equivalences) and $X = K[0]$, then ${\rm Aut}(X) = {\rm GL}_1(K)$ and the map $\widetilde{{\rm det}}$ is the usual map $\Sigma^\infty {\rm BGL}_1(K) \to {\Bbb S}[{\rm BGL}_1(K)] \to K(K)$. 

\begin{proof}[Proof of Theorem \ref{thm:hmcomp}] It only remains to prove that the map \eqref{eq:logdiffrings} is a map of log differential graded rings. Let us write ${\cal C} := ({\cal P}({\cal O}_K), v{\cal P}({\cal O}_K))$ for brevity. We contemplate the diagram  \[\begin{tikzcd}[column sep = small]{\cal O}_K \cap {\rm GL}_1(K) \ar{r} &  \pi_1B({\cal O}_K \cap {\rm GL}_1(K)) \ar{d} \ar{r}{\pi_1\widetilde{{\rm det}}} & \pi_1K({\cal C}) \ar{r}{\pi_1{\rm tr}} \ar{d}{\cong}& \pi_1{\rm THH}({\cal O}_K | K) \\ \vspace{10 mm} & \pi_1{\rm BGL}_1(K) \ar{r}{\pi_1\widetilde{\rm det}} & \pi_1K(K) \ar[swap]{ur}{\pi_1{\rm tr}} \\ \langle t \rangle \ar{uu}{t \mapsto \pi_K} \ar{r} & \pi_1B\langle t \rangle^{\rm gp} \ar{u}{t \mapsto \pi_K} \ar{rr}{\rm dlog} & & \pi_1{\rm THH}({\cal O}_K, \langle \pi \rangle) \ar[swap]{uu}{\pi_1\eqref{eq:tohm}} \end{tikzcd}\] of commutative monoids, where the isomorphism is provided by Waldhausen's approximation theorem \cite[Theorem 1.6.7]{Wal85}. We claim that this commutes by construction: For the left-hand square this is clear. For the rest, we observe that the composition \[\pi_1B\langle t \rangle^{\rm gp} \xrightarrow{{\rm dlog}} \pi_1{\rm THH}({\cal O}_K, \langle \pi \rangle) \xrightarrow{\pi_1\eqref{eq:tohm}} \pi_1{\rm THH}({\cal O}_K | K)\] is defined to be $\pi_1$ of the composition \eqref{eq:fromreptohm1}, and so the lower, right-hand square\footnote{With corners $\pi_1B\langle t \rangle^{\rm gp}$, $\pi_1{\rm BGL}_1(K)$, $\pi_1{\rm THH}({\cal O}_K, \langle \pi \rangle)$, and $\pi_1{\rm THH}({\cal O}_K | K)$.} commutes by Proposition \ref{prop:dlogcomp}. The square involving $\widetilde{{\rm det}}$ commutes, and the triangle involving the trace commutes by construction. This concludes the proof. 
\end{proof}



