\section{DAHA for $\Sigma_{2,0}$}
\label{sec:DAHA20}

Motivated by that the
$A_1$-type and the
$C^\vee C_1$-type spherical DAHAs are
isomorphic  to the skein algebra on once-punctured torus and
4-punctured sphere~\cite{Oblom04a,BerestSamuel16a,MortoSamue21a}
respectively,
we constructed 
the map
\begin{equation*}
  \mathcal{A}:
  \Sk_{A=q^{-\frac{1}{4}}}(\Sigma_{2,0}) 
  \to \End \mathbb{C}(q^{\frac{1}{4}},x_0,x_1)[x+x^{-1}]
\end{equation*}
in our previous papers~\cite{KHikami19a,KHikami24a}.
Explicitly
the simple closed curves in Fig.~\ref{fig:curves-20}
are mapped to
\begin{subequations}
  \label{define_A-k}
  \begin{align}
    &
      \mathcal{A}(\mathbb{k}_1)
      =\left. \ch(\I \, \mathsf{T}_0) \right|_{\text{sym}}
      = \ch(x_0) ,
    \\
    \label{T1T0_t-star}
    &
      \begin{aligned}[t]
        \mathcal{A}(\mathbb{k}_3)
        & =\left. \ch(\mathsf{T}_1\mathsf{T}_0) \right|_{\text{sym}}
        \\
        & =
          \sum_{\epsilon=\pm 1}
          \omega(x^\epsilon)
          \left\{
          -x^{-\epsilon}
          \left(x_0+ \frac{q^{\frac{1}{2}} x^\epsilon}{x_0} \right)
          \left(x_1+ \frac{q^{\frac{1}{2}} x^\epsilon}{x_1} \right)
          \eth^{2\epsilon}
          + q^{\frac{1}{2}} \ch(x_0) \ch(x_1)
          \right\} ,
      \end{aligned}
    \\
    &
      \mathcal{A}(\mathbb{k}_5)
      =\left. \ch(\I \, q^{-\frac{1}{2}}\mathsf{T}_1)
      \right|_{\text{sym}}
      = \ch(x_1) ,
    \\
    \label{A-k2_G}
    &
      \mathcal{A}(\mathbb{k}_2)
      =\left. \ch(\I \, \mathsf{U}_0) \right|_{\text{sym}}
      = \I  \, q^{-\frac{1}{4}} G_0(x_0;x) ,
    \\
    &
      \mathcal{A}(\mathbb{k}_4)
      =\left. \ch(\I \, q^{-\frac{1}{2}}\mathsf{U}_1)
      \right|_{\text{sym}}
      = \I \,  q^{-\frac{1}{4}} G_0(x_1;x) ,
    \\
    &
      \label{A-k6_U1U0}
      \begin{aligned}[t]
        \mathcal{A}(\mathbb{k}_6)
        & =\left. \ch( \mathsf{U}_1 \mathsf{U}_0) \right|_{\text{sym}}
        \\
        & =
          \sum_{\epsilon=\pm 1}
          \omega(x^\epsilon)
          \left\{
          K_0(x_0;x^\epsilon)  \, K_0(x_1;x^\epsilon) \eth^{2\epsilon}
          -G_0(x_0;x) \, G_0(x_1;x)
          \right\} .
      \end{aligned}
  \end{align}
\end{subequations}
Here ``sym'' denotes the action on the symmetric Laurent  polynomials
of~$x$,
and we mean
\begin{equation}
  \omega(x)= \frac{
    x(1+q^{\frac{1}{2}} x)}{
    q^{\frac{1}{2}} (1-x^2)(1-q^{\frac{1}{2}} x)
  } .
\end{equation}
By use of
the $q$-difference operators $K_n$ and $G_n$ defined by
\begin{subequations}
  \begin{align}
    \label{define_K_n}
    K_n(x_b; x)
    &= -\frac{x_b^{-n}}{1-x_b^2} \, \eth_b
    +
    \frac{x_b^n(q^{\frac{1}{2}} x + x_b^2) (q^{\frac{3}{2}} x+x_b^2)}{
    q x (1-x_b^2)} \,
    \eth_b^{-1} ,
    \\
    \label{define_G_n}
    G_n(x_b;x)
    & = - \frac{x_b^{-n}}{1-x_b^2}  \, \eth_b
      +
      \frac{x_b^n (q^{\frac{1}{2}}x + x_b^2) (q^{\frac{1}{2}}+x x_b^2)
      }{
      q^{\frac{1}{2}} x (1-x_b^2)
      } \,
      \eth_b^{-1} ,
  \end{align}
\end{subequations}
the Iwahori--Hecke operators~$\mathsf{T}_b$ and~$\mathsf{U}_b$ are written as~\cite{KHikami24a}
\begin{subequations}
  \label{define_U-T}
  \begin{align}
    \label{eq:3}
    \mathsf{T}_0
    &  \mapsto
      \I\frac{x}{q^{\frac{1}{2}}-x}
      \left(
      -\frac{q^{\frac{1}{2}} + x x_0^2}{x x_0} \,
      \mathsf{s} \,  \eth^2 + \ch(x_0)
      \right) ,
    \\
    \mathsf{T}_1
    & \mapsto
      \I
      \left(
      \frac{1+q^{\frac{1}{2}}x}{
      q^{\frac{1}{2}} (1-x^2)}
      \frac{q^{\frac{1}{2}} x + x_1^2}{x_1}
      \left(\mathsf{s} -1 \right)
      - q^{\frac{1}{2}}x_1^{-1}
      \right) ,
    \\
    \mathsf{U}_0
    & \mapsto
      \frac{q^{-\frac{1}{4}}x}{q^{\frac{1}{2}} - x}
      \left\{
      K_0(x_0;x^{-1}) \, \mathsf{s} \,  \eth^2 - G_0(x_0;x)
      \right\} ,
    \\
    \mathsf{U}_1
    & \mapsto
      -\frac{x(1+q^{\frac{1}{2}} x)}{
      q^{\frac{1}{4}} (1-x^2)
      }
      K_0(x_1;x) \left(\mathsf{s} -1 \right)
      +\frac{q^{\frac{1}{4}}}{1-q^{\frac{1}{2}}x}
      \left(
      G_0(x_1;x) - q^{\frac{1}{2}}x K_0(x_1;x)
      \right) ,
  \end{align}
\end{subequations}
which
satisfy the  Iwahori--Hecke relations,
\begin{subequations}
  \begin{gather}
      \left( \mathsf{T}_0 + \I \,  x_0\right)
      \left(\mathsf{T_0}+ \I \, x_0^{-1} \right)=0 ,      
%      \mathsf{T}_0 - \mathsf{T}_0^{-1} = -\I \ch(x_0),
    \\
      \left( \mathsf{T}_1 + \I  \, q^{-\frac{1}{2}}x_1 \right)
      \left( \mathsf{T}_1 + \I  \, q^{\frac{1}{2}}x_1^{-1} \right)
      =0,
%      \mathsf{T}_1- \mathsf{T}_1^{-1}      = -\I \ch(q^{-\frac{1}{2}}x_1),
    \\
      \left( \mathsf{U}_0 +
      \frac{q^{-\frac{1}{4}}x}{q^{\frac{1}{2}}-x}
      \left( G_0(x_0 ; x) - K_0(x_0; \tfrac{1}{x}) \right)
      \right)
      \left(
      \mathsf{U}_0 +
      \frac{q^{-\frac{1}{4}}}{q^{\frac{1}{2}}-x}
      \left(
      x  \, G_0(x_0;x) - q^{\frac{1}{2}} K_0(x_0; \tfrac{x}{q})
      \right)
      \right)=0 ,
    \\
      \left(
      \mathsf{U}_1 -
      \frac{q^{\frac{1}{4}}}{1-q^{\frac{1}{2}}x}
      \left( G_0(x_1 ; x) - q^{\frac{1}{2}}x \, K_0(x_1; x)
      \right)
  \right)
  \left(
  \mathsf{U}_1
  -\frac{q^{\frac{3}{4}}}{q^{\frac{3}{2}}-x}
      \left( G_0(x_1; \tfrac{x}{q}) - K_0(x_1; \tfrac{q}{x})
  \right)
  \right) =0 .
\end{gather}
\end{subequations}
It should be noted that
the operators $\mathsf{T}_b$ are the reductions of
the 
Iwahori--Hecke operators for  the  Askey--Wilson polynomial~\cite{NoumiStokm00a}.
See~\cite{KHikami24b} for an application of $\mathsf{U}_0$
to the skein algebra on
twice-punctured torus.

We remark that $x$ denotes the monodromy of the separating curve $\mathbb{x}$ in
Fig.~\ref{fig:curves-20}, and that
\begin{equation}
  \label{eq:1}
  \mathcal{A}(\mathbb{x})=
  \ch(x) .
\end{equation}


\section{Askey--Wilson Polynomial and $q$-Shift Operator}
\label{sec:AW}
The Askey--Wilson polynomials with 4 parameters
$\mathbf{t}=(t_0, t_1, t_2, t_3)$
are  defined as the basic  $q$-hypergeometric series~\cite{AsWi85}
(see also~\cite{GaspRahm04})
\begin{equation}
  \label{define_P_AW}
  \begin{aligned}[b]
    P_n(x; q, \mathbf{t})
    & =
      P_n^{(a,b,c,d)}
      =
      P_n^{(a,b,c,d)}(x)
    \\
    &  =
      \frac{
      \left( a b, a c, a d \right)_n
      }{
      a^n \left( a b c d q^{n-1} \right)_n
      }
      {}_4\phi_3
      \left[
      \begin{matrix}
        q^{-n}, q^{n-1} a b c d, a x, a x^{-1}
        \\
        a b , a c , a d
      \end{matrix}
      ; q, q
      \right] ,
  \end{aligned}
\end{equation}
where
\begin{equation*}
  a=\frac{1}{t_1 t_3}, \quad
  b=-\frac{t_3}{t_1}, \quad
  c= \frac{q^{\frac{1}{2}}}{t_0 t_2}, \quad
  d=-\frac{q^{\frac{1}{2}}t_2}{t_0} .
\end{equation*}
Here
the polynomials are symmetric in~$\{a, b, c, d\}$, and
we have normalized the symmetric Laurent polynomials so that
$P_n(x;q,\mathbf{t})=\ch(x^n)+\dots$,
where $\dots$ denotes a linear sum of $\ch(x^k)$ for
$0\leq k<n$.
% We also denote
% as
% $P_n^{(a,b,c,d)}$ for brevity.

We recall the $q$-difference operators introduced in~\cite{KalnMill89a};
\begin{subequations}
  \label{shift_Kalnins}
  \begin{align}
    \label{eq:16}
    & \widehat{\mathcal{m}}^{(a,b,c,d)}
      = \frac{1}{x-x^{-1}}
      \left(
      -\frac{1}{x} \left( 1 - a  q^{-\frac{1}{2}} x \right)
      \left( 1 - b q^{-\frac{1}{2}} x \right) \eth
      + x \left( 1-a q^{-\frac{1}{2}} x^{-1} \right)
      \left( 1- b q^{-\frac{1}{2}} x^{-1}  \right) \eth^{-1}
      \right) ,
    \\
    &\widehat{\mathcal{l}}^{(a,b,c,d)}
      =
      \frac{1}{x-x^{-1}} \left( \eth - \eth^{- 1 }
      \right) ,
    \\
    &
      \begin{multlined}[b][.84\textwidth]
        \widehat{\mathcal{l}}^{* (a q^{\frac{1}{2}} , b q^{\frac{1}{2}},
          c q^{\frac{1}{2}} , d q^{\frac{1}{2}})}
        =
        \frac{q^{-\frac{1}{2}}}{x-x^{-1}}
        \Bigl(
        \frac{
          (1- a x) (1- b x) ( 1- c x) ( 1-d x)}{x^2} \, 
        \eth
        \\
        -
        x^2  (1 - a x^{-1}) (1-b x^{-1}) (1-c x^{-1}) ( 1 - d x^{-1}) \,
        \eth^{-1}
        \Bigr) .
      \end{multlined}
  \end{align}
\end{subequations}
These act as parameter $q$-shift operators
on the Askey--Wilson polynomial~\eqref{define_P_AW} as
\begin{subequations}
  \label{action_shift_Kalnins}
  \begin{align}
    \label{eq:14}
    & \widehat{\mathcal{m}}^{(a,b,c,d)} P_n^{(a,b,c,d)}
      =
      q^{-\frac{n}{2}} (1 - a b q^{n-1} ) \,
      P_n^{(a q^{-\frac{1}{2}}, b q^{-\frac{1}{2}} , c q^{\frac{1}{2}},
      d q^{\frac{1}{2}})} ,
    \\
    & \widehat{\mathcal{l}}^{(a,b,c,d)} P_n^{(a,b,c,d)}
      = -q^{-\frac{n}{2}} ( 1-q^n) \,
      P_{n-1}^{(a q^{\frac{1}{2}}, b q^{\frac{1}{2}},
      c q^{\frac{1}{2}}, d q^{\frac{1}{2}})} ,
    \\
    & \widehat{\mathcal{l}}^{* (a q^{\frac{1}{2}} , b q^{\frac{1}{2}},
      c q^{\frac{1}{2}} , d q^{\frac{1}{2}})}
      P_n^{ (a q^{\frac{1}{2}} , b q^{\frac{1}{2}},
      c q^{\frac{1}{2}} , d q^{\frac{1}{2}})}
      =
      -q^{-\frac{n+1}{2}} (1 - a b c d q^n ) \,
      P_{n+1}^{(a,b,c,d)} .
  \end{align}
\end{subequations}
These $q$-shift operators were employed to simplify the proof of the orthogonality 
of~$P_n^{(a,b,c,d)}$~\cite{KalnMill89a}.

% This is an orthogonal polynomial
% \begin{equation}
%   \label{eq:11}
%   \frac{1}{2\pi\I}{\oint P_m(x;q, \mathbf{t}) \, P_n(x;q,\mathbf{t})
% \end{equation}
% It is known that the  polynomial $P_n(x;q,\mathbf{t})$
% is symmetric in $a$, $b$, $c$, $d$.
For our purpose of the genus-two skein algebra~$\Sk_A(\Sigma_{2,0})$,
we pay attention to the case~\cite{KHikami19a}
\begin{equation}
  \label{t-star}
%  \mathbf{t}=
  \mathbf{t}_\star=
  \left( \I \, x_0, \I \, q^{-\frac{1}{2}} x_1,
    \I \,  x_0, \I \,  x_1 \right) .
\end{equation}
Hereafter for simplicity
we denote the Askey--Wilson polynomial~\eqref{define_P_AW} at
$\mathbf{t}_\star$
as
\begin{align}
  \label{our_AW_from_symmetric}
  P_n
  & =
    P_n(x; x_0, x_1)
    =
    P_n^{(
    -q^{\frac{1}{2}}, - q^{\frac{1}{2}},
    - q^{\frac{1}{2}}/x_0^2,
    - q^{\frac{1}{2}}/x_1^2
    )}
  \\
  \nonumber
  &
    =
    P_n(x;q, \mathbf{t}_\star)
    =
    (-1)^n q^{-\frac{n}{2}}
    \frac{
    \left( q, \frac{q}{x_0^2}, \frac{q}{x_1^2} \right)_n}{
    \left( \frac{q^{n+1}}{x_0^2 x_1^2} \right)_n
    } 
    \sum_{k=0}^n
    q^k \,
    \frac{
    \left(q^{-n}, \frac{q^{n+1}}{x_0^2 x_1^2} \right)_k}{
    \left( q,q,\frac{q}{x_0^2} , \frac{q}{x_1^2}\right)_k
    }  \, g_k(x) ,
\end{align}
