%   \label{our_AW_from_symmetric}
%   P_n(x;x_0,x_1)
%   =
%   (-1)^n q^{-\frac{n}{2}}
%   \frac{
%     \left( q, \frac{q}{x_0^2}, \frac{q}{x_1^2} \right)_n}{
%     \left( \frac{q^{n+1}}{x_0^2 x_1^2} \right)_n
%   } 
%   \sum_{k=0}^n
%   q^k \,
%   \frac{
%     \left(q^{-n}, \frac{q^{n+1}}{x_0^2 x_1^2} \right)_k}{
%     \left( q,q,\frac{q}{x_0^2} , \frac{q}{x_1^2}\right)_k
%   }  \, g_k(x) ,
% \end{equation}
% where
% \begin{equation*}
%   \alpha_n(x_0,x_1)
%   =
%     (-1)^n q^{-\frac{n}{2}}
%   \frac{
%     \left( q, \frac{q}{x_0^2}, \frac{q}{x_1^2} \right)_n}{
%     \left( \frac{q^{n+1}}{x_0^2 x_1^2} \right)_n
%   } ,
% \end{equation*}
where  $g_k(x)$ is a basis of the symmetric Laurent polynomial
\begin{equation}
  \label{our_symmetric_base}
  g_k(x)=(-q^{\frac{1}{2}}x , -q^{\frac{1}{2}}x^{-1})_k .
\end{equation}
The expansion in terms of~$g_k(x)$
reminds the Habiro expansion of the colored Jones
polynomial~\cite{KHabiro06b}.
% and also
% the Bailey pair~\cite{KHikami06b}.

The reduced Askey--Wilson polynomial $P_n$
is characterized as an eigenpolynomial of the reduced
Askey--Wilson $q$-difference
operator
\begin{equation}
  \label{eigen_AW}
  \ch\left( \mathsf{T}_1 \mathsf{T}_0 \right) 
  P_n
  =
  - \ch \left( q^{-n-\frac{1}{2}} x_0 x_1 \right) 
  P_n ,
\end{equation}
where $\mathsf{T}_b$ are the Iwahori--Hecke operators
in~\eqref{define_U-T}.
See~\eqref{T1T0_t-star} for the explicit form of the reduced Askey--Wilson operator.
As an orthogonal polynomial,
the three-term recurrence relation for~$P_n$
is read as~\cite{AsWi85}~\cite[(7.5.3)]{GaspRahm04}
\begin{equation}
  \label{3-term-AW}
  \ch(x) \,
%  \left(x+\frac{1}{x}\right)
  P_n% (x; x_0, x_1)
  =
  % A_m(x_0,x_1)
  P_{n+1} %(x; x_0, x_1)
  +
  \beta_n(x_0,x_1) \,
  P_n %(x; x_0,x_1)
  + \gamma_n(x_0,x_1) \,
  P_{n-1} , %(x; x_0, x_1) 
\end{equation}
where
\begin{align}
  \label{define_Beta_n}
  % & A_m(x_0,x_1)
  %  =\frac{1-\frac{q^{2m}}{x_0^2 x_1^2}}{
  %   1-\frac{q^{m}}{x_0^2 x_1^2}
  %   }
  %     \\
  &
    \begin{multlined}[b][.84\textwidth]
      \beta_n(x_0,x_1)
      =
    q^{-\frac{1}{2}}
    \left\{
      \frac{
        \left(1-q^{n+1}\right)
        \left( 1- \frac{q^{n+1}}{x_0^2 x_1^2} \right)
        \left( 1- \frac{q^{n+1}}{x_0^2 } \right)
        \left( 1- \frac{q^{n+1}}{x_1^2} \right)
      }{
        \left(1- \frac{q^{2n+1}}{x_0^2 x_1^2} \right)
        \left(1- \frac{q^{2n+2}}{x_0^2 x_1^2} \right)
      }
      -1\right\}
    \\
    +
    q^{\frac{1}{2}}
    \left\{
      \frac{
        \left(1-q^{n}\right)
        \left( 1- \frac{q^{n}}{x_0^2 x_1^2} \right)
        \left( 1- \frac{q^{n}}{x_0^2 } \right)
        \left( 1- \frac{q^{n}}{x_1^2} \right)
      }{
        \left(1- \frac{q^{2 n}}{x_0^2 x_1^2} \right)
        \left(1- \frac{q^{2 n+1}}{x_0^2 x_1^2} \right)
      }
      -1\right\} ,
  \end{multlined}
  \\
  \label{define_Gamma_n}
    &
      \gamma_n(x_0,x_1) =
      \frac{
      (1-q^n)^2 \left(1-\frac{q^n}{x_0^2 x_1^2} \right)^2
      \left(1-\frac{q^n}{x_0^2 } \right)^2
      \left(1-\frac{q^n}{x_1^2} \right)^2
      }{
      \left(1-\frac{q^{2 n-1}}{x_0^2 x_1^2} \right)
      \left(1-\frac{q^{2 n}}{x_0^2 x_1^2} \right)^2
      \left(1-\frac{q^{2 n+1}}{x_0^2 x_1^2} \right)
      } .
\end{align}
We should note that,
at $\mathbf{t}_\star$~\eqref{t-star},
the connection formula~\cite{AsWi85}~\cite[(7.6.2)]{GaspRahm04} is simplified to be
\begin{equation}
  \label{connection-AW}
  P_n(x;q^{\frac{1}{2}}x_0 , x_1)
  =
  P_n %(x; x_0, x_1)
  +
  \lambda_n(x_0,x_1) \,
  P_{n-1} , %(x; x_0, x_1) 
\end{equation}
where
\begin{equation}
  \label{define_lambda}
  \lambda_n(x_0,x_1)
  =
  \frac{q^{-\frac{1}{2}} (1-q^n)^2
    \left(1-\frac{q^n}{x_1^2}\right)^2}{
    x_0^2
    \left( 1- \frac{q^{2 n-1}}{x_0^2 x_1^2} \right)
    \left(1- \frac{q^{2 n}}{x_0^2 x_1^2} \right)
  } .
  % =
  % \frac{q^{-\frac{1}{2}} (1-q^m)^2 x_0^2(x_1^2-q^m)^2}{
  %   (q^{2m-1}-x_0^2 x_1^2)
  %   (q^{2m}-x_0^2 x_1^2)
  % }
\end{equation}
We also have the similar identity by transposing $x_0$ and $x_1$.
We find that
the functions in~\eqref{define_Beta_n},~\eqref{define_Gamma_n}, and~\eqref{define_lambda},
satisfy
\begin{equation}
  \label{Beta_and_lambda_Gamma}
  \beta_n(x_0,x_1) +
  \ch(  x_0^2q^{\frac{1}{2}}) 
  =
  \lambda_{n+1}(x_0,x_1)+ \frac{\gamma_n(x_0,x_1)}{\lambda_n(x_0,x_1)} .
\end{equation}

