In the following, we study the actions of $\mathcal{A}(\mathbb{k}_a)$~\eqref{define_A-k}
on the
reduced Askey--Wilson
polynomial defined by
\begin{equation}
  \label{define_bar-P}
  % \widebar{P}_m
  % =
  \widebar{P}_n(x;x_0,x_1)
  =
  \nu_n(x_0,x_1)  \, P_n(x; x_0,x_1) ,
\end{equation}
with the scale function $\nu_n(x_0,x_1)$ to be determined.



\begin{prop}
  \label{prop:action}
  The action of the $q$-difference operators
  $\mathcal{A}(\mathbb{k}_a)$~\eqref{define_A-k} on the
  reduced Askey--Wilson polynomial~\eqref{define_bar-P} are given as follows;
  \begin{subequations}
    \label{A-action_on_P-bar}
  \begin{align}
    \label{A-action-1}
    & \mathcal{A}(\mathbb{k}_1) \,
      \widebar{P}_n
      =
      \ch(x_0) \, \widebar{P}_n,
    \\
    %
    & \mathcal{A}(\mathbb{k}_3) \,
      \widebar{P}_n
      =
      - \ch\left(
      q^{-n-\frac{1}{2}}x_0 x_1
      \right) 
      \widebar{P}_n ,
    \\
    %
    \label{A-action-5}
    & \mathcal{A}(\mathbb{k}_5) \,
      \widebar{P}_n
      =
      \ch(x_1) \, \widebar{P}_n ,
    \\
    %
    \label{k2_AW}
    &
      \begin{multlined}[b][.84\textwidth]
        \mathcal{A}(\mathbb{k}_2) \,
        \widebar{P}_n
        =
        \I \frac{q^{-\frac{1}{4}}}{1-x_0^2}
        \Biggl\{
                x_0^2 \frac{
          \nu_n(q^{-\frac{1}{2}}x_0, x_1)}{
          \nu_{n+1}(x_0,x_1)}
        \widebar{P}_{n+1}
        -
        \frac{\nu_n(q^{\frac{1}{2}}x_0,x_1)}{
          \nu_{n-1}(x_0,x_1)} \,
        \lambda_n(x_0,x_1) \,
        \widebar{P}_{n-1}
        \\
        +
        \left(
          x_0^2 \, \frac{\gamma_n(q^{-\frac{1}{2}}x_0,x_1)}{
            \lambda_n (q^{-\frac{1}{2}}x_0, x_1)}
          \frac{
            \nu_n(q^{-\frac{1}{2}}x_0, x_1)}{
            \nu_n(x_0, x_1)}
          -
          \frac{
            \nu_n(q^{\frac{1}{2}}x_0, x_1)}{
            \nu_n(x_0, x_1)}
        \right)
        \widebar{P}_n
        \Biggr\} ,
      \end{multlined}
    \\
    %
    \label{k4_AW}
    &
      \begin{multlined}[b][.84\textwidth]
        \mathcal{A}(\mathbb{k}_4) \,
        \widebar{P}_n
        =
        \I \frac{q^{-\frac{1}{4}}}{1-x_1^2}
        \Biggl\{
        x_1^2 \, \frac{
          \nu_n(x_0, q^{-\frac{1}{2}}x_1)}{
          \nu_{n+1}(x_0,x_1)}
        \widebar{P}_{n+1}
        -
        \frac{\nu_n(x_0, q^{\frac{1}{2}}x_1)}{
          \nu_{n-1}(x_0,x_1)} \,
        \lambda_n(x_1,x_0) \,
        \widebar{P}_{n-1}
        \\
        +
        \left(
          x_1^2 \, \frac{\gamma_n(x_0, q^{-\frac{1}{2}}x_1)}{
            \lambda_n ( q^{-\frac{1}{2}}x_1, x_0)}
          \frac{
            \nu_n(x_0, q^{-\frac{1}{2}}x_1)}{
            \nu_n(x_0, x_1)}
          -
          \frac{
            \nu_n(x_0, q^{\frac{1}{2}}x_1)}{
            \nu_n(x_0, x_1)}
        \right)
        \widebar{P}_n
        \Biggr\} ,
      \end{multlined}
    \\ 
    \label{A-k6_P6-bar}
    &
      \begin{multlined}[b][.84\textwidth]
        \mathcal{A}(\mathbb{k}_6) \,
        \widebar{P}_n
        =
        \frac{1}{(1-x_0^2)(1-x_1^2)}
        \Biggl\{
                \frac{\nu_n(q^{-\frac{1}{2}}x_0, q^{-\frac{1}{2}}
          x_1)}{
          \nu_{n+1}(x_0,x_1)}
        q^{-n-\frac{5}{2}}
        \left( x_0^2 x_1^2  - q^{n+2} \right)^2
        \widebar{P}_{n+1}
        \\
        -q^{-n-\frac{3}{2}}
        \left(
          \frac{\nu_n(q^{\frac{1}{2}}x_0,
            q^{-\frac{1}{2}}x_1)}{
            \nu_n(x_0,x_1)} 
          \left(x_1^2-q^{n+1}\right)^2
          +
          \frac{\nu_n(q^{-\frac{1}{2}}x_0,
            q^{\frac{1}{2}}x_1)}{
            \nu_n(x_0,x_1)} 
          \left(x_0^2- q^{n+1}\right)^2
        \right) \, \widebar{P}_n
        \\
        +
        \frac{
          \nu_n(q^{\frac{1}{2}}x_0, q^{\frac{1}{2}}x_1)}{
          \nu_{n-1}(x_0,x_1)}
        q^{-n-\frac{1}{2}} (1-q^n)^2 \,
        \widebar{P}_{n-1}
        \Biggr\} .
      \end{multlined}
  \end{align}
\end{subequations}
\end{prop}

\begin{proof}
  The cases for $\mathbb{k}_1$ and $\mathbb{k}_5$  are trivial.
  The action of $\mathcal{A}(\mathbb{k}_3)$
  is from the definition of the reduced Askey--Wilson operator~\eqref{eigen_AW}.

  For $\mathbb{k}_2$~\eqref{A-k2_G},
  the definition~\eqref{define_G_n}
  gives
  \begin{align*}
    & \mathcal{A}(\mathbb{k}_2) \, \widebar{P}_n
      =
      \I \, \frac{q^{-\frac{1}{4}}}{1-x_0^2}
      \left\{
      - \widebar{P}_n(x;q^{\frac{1}{2}}x_0, x_1)
      +
      x_0^2 \left(
      \ch\left(q^{-\frac{1}{2}}x_0^2 \right)
      +\ch(x)
      \right) \, \widebar{P}_n(x; q^{-\frac{1}{2}}x_0 , x_1)
      \right\}
    \\
    & =
      \begin{multlined}[t][.84\textwidth]
      \I \, \frac{q^{-\frac{1}{4}}}{1-x_0^2}
      \Biggl\{
      -   \frac{\nu_n(q^{\frac{1}{2}}x_0, x_1)
      }{\nu_n(x_0,x_1)} \, \widebar{P}_n
      - \frac{\nu_n(q^{\frac{1}{2}}x_0,x_1)
      }{ \nu_{n-1}(x_0,x_1)}  \, \lambda_n(x_0,x_1) \,
      \widebar{P}_{n-1}
      \\
      +x_0^2 \frac{\nu_n(q^{-\frac{1}{2}}x_0,x_1)}{
        \nu_{n+1}(q^{-\frac{1}{2}}x_0,x_1)} \,
      \widebar{P}_{n+1}(x;q^{-\frac{1}{2}}x_0,x_1)
      +x_0^2 \left( \ch ( q^{-\frac{1}{2}}x_0^2 )
        +\beta_n( q^{-\frac{1}{2}} x_0, x_1 )
        \right) \, \widebar{P}_n(x;q^{-\frac{1}{2}}x_0,x_1)
        \\
        +x_0^2 \frac{
          \nu_n(q^{-\frac{1}{2}}x_0,x_1)}{
          \nu_{n-1}(q^{-\frac{1}{2}}x_0,x_1)} \,
        \gamma_n(q^{-\frac{1}{2}}x_0, x_1) \,
        \widebar{P}_{n-1}(x;q^{-\frac{1}{2}}x_0,x_1)
      \Biggr\} ,
    \end{multlined}
  \end{align*}
  where, in the second equality,
  we have used~\eqref{3-term-AW} and~\eqref{connection-AW}.
  Using~\eqref{Beta_and_lambda_Gamma}
  and~\eqref{connection-AW},
  we obtain~\eqref{k2_AW}.
  The action~\eqref{k4_AW} of $\mathcal{A}(\mathbb{k}_4)$ is given similarly
  by
  transposing~$x_0$ and~$x_1$.

  For $\mathbb{k}_6$~\eqref{A-k6_U1U0},
  we may rewrite the  operator~$\mathcal{A}(\mathbb{k}_6)$ as
  \begin{equation}
    \label{A-k6_with_q-d}
    \mathcal{A}(\mathbb{k}_6)
    =
    \frac{1}{(1-x_0^2)( 1-x_1^2)}
    \sum_{a, b =\pm 1} (-1)^{\frac{a+b}{2}+1}
    \widehat{\mathcal{d}}_{a,b} \eth_0^a \eth_1^b ,
  \end{equation}
  where $\widehat{\mathcal{d}}_{a,b}$ are the $q$-difference operators
  for $x$ defined by
  \begin{subequations}
    \label{difference_in_k6}
    \begin{align}
      \widehat{\mathcal{d}}_{1,1}
      &=
        \sum_{\epsilon=\pm 1}
        \omega(x^\epsilon )
        \left( \eth^{2\epsilon} -1
        \right) ,
      \\
      \widehat{\mathcal{d}}_{1,-1}
      &    =
        \sum_{\epsilon=\pm 1}
        \omega(x^\epsilon)
        \left(
        b(x_1,x^\epsilon) \eth^{2\epsilon} - c(x_1,x)
        \right) ,
      \\
      \widehat{\mathcal{d}}_{-1,1}
      &    =
        \sum_{\epsilon=\pm 1}
        \omega(x^\epsilon)
        \left(
        b(x_0,x^\epsilon) \eth^{2\epsilon} - c(x_0,x)
        \right) ,
      \\
      \widehat{\mathcal{d}}_{-1,-1}
      & =
        \sum_{\epsilon=\pm 1}
        \omega(x^\epsilon)
        \left(
        b(x_0,x^\epsilon) b(x_1,x^\epsilon) \eth^{2\epsilon}
        -c(x_0,x) c(x_1,x)
        \right) .
    \end{align}
  \end{subequations}
  Here we have used
  \begin{equation*}
    b(x_b,x)=
    \frac{
      \bigl(q^{\frac{1}{2}} x + x_b^2 \bigr)
      \bigl(q^{\frac{3}{2}} x + x_b^2 \bigr)
    }{q \, x},
    \qquad
    c(x_b,x)=
    \frac{
      \bigl(q^{\frac{1}{2}} x + x_b^2 \bigr)
      \bigl(q^{\frac{1}{2}}  + x \, x_b^2 \bigr)
    }{q^{\frac{1}{2}} \, x}.
  \end{equation*}
  Recalling   the $q$-shift operators~\eqref{shift_Kalnins} for the
  Askey--Wilson polynomials,
  we can check by straightforward computations
  that 
  the operators~$\widehat{\mathcal{d}}_{a,b}$~\eqref{difference_in_k6}
  are factorized as
  \begin{subequations}
    \begin{align}
      \label{eq:17}
      \widehat{\mathcal{d}}_{1,1}
      & =
        -q^{-\frac{1}{2}} \,
        \widehat{\mathcal{l}}^{(-1,-1,c q^{-\frac{1}{2}} , d q^{-\frac{1}{2}})}
        \,
        \widehat{\mathcal{m}}^{(-q^{\frac{1}{2}} , - q^{\frac{1}{2}},
        c q^{-1}, d q^{-1})} ,
      \\
      % & =
      %   -q^{-\frac{1}{2}} \cdot
      %   \frac{x}{x^2-1}
      %   \left(
      %   \eth^{\frac{1}{2}}- \eth^{-\frac{1}{2}}
      %   \right) \cdot
      %   \frac{1+x}{1-x}
      %   \left( \eth^{\frac{1}{2}} - \eth^{-\frac{1}{2}}
      %   \right)
      %   ,
      %   \notag
      % \\
      \widehat{\mathcal{d}}_{1,-1}
      & =
        q^{-\frac{3}{2}} \, x_1^4 \,
        \widehat{\mathcal{m}}^{(-q, -q/x_1^2, - 1/x_0^2, -1)}
        \widehat{\mathcal{m}}^{(-q^{\frac{1}{2}} , -
        q^{\frac{3}{2}}/x_1^2,
        - q^{-\frac{1}{2}}/x_0^2, - q^{\frac{1}{2}})} ,
      \\
      \widehat{\mathcal{d}}_{-1,1}
      & =
        q^{-\frac{3}{2}}  \, x_0^4 \,
        \widehat{\mathcal{m}}^{(-q, -q/x_0^2, - 1/x_1^2, -1)}
        \widehat{\mathcal{m}}^{(-q^{\frac{1}{2}} ,
        - q^{\frac{3}{2}}/x_0^2,
        - q^{-\frac{1}{2}}/x_1^2,
        - q^{\frac{1}{2}})} ,
      \\
      \widehat{\mathcal{d}}_{-1,-1}
      & =
        -q^{-2} x_0^4 \,  x_1^4 \, 
        \widehat{\mathcal{l}}^{* ( -q/x_0^2,
        -q/x_1^2, -q, -q)}
        \widehat{\mathcal{m}}^{(-q^{\frac{3}{2}}/x_0^2 ,
        -  q^{\frac{3}{2}}/x_1^2, - q^{\frac{1}{2}}, -   q^{\frac{1}{2}})} .
    \end{align}
  \end{subequations}
  Here $c$ and $d$ in $\widehat{\mathcal{d}}_{1,1}$ are arbitrary.
  Then we  obtain
  the actions~\eqref{action_shift_Kalnins} on the Askey--Wilson polynomials
  as
  \begin{subequations}
    \label{k6_action_part}
    \begin{gather}
      \label{k6_supplement-1}
      \widehat{\mathcal{d}}_{1,1} P_n ( x; q^{\frac{1}{2}} x_0, q^{\frac{1}{2}} x_1)
      =
      q^{-n-\frac{1}{2}}
      (1-q^n)^2 \,
      P_{n-1} ,
      % \left( x; \tfrac{x_0}{\sqrt{q}}, \tfrac{x_1}{\sqrt{q}}
      % \right)
      \\
      % 
      \label{k6_supplement-2}
      \widehat{\mathcal{d}}_{1,-1}
      P_n \left( x; q^{\frac{1}{2}} x_0, q^{-\frac{1}{2}}x_1 \right)
      =
      q^{-n-\frac{3}{2}}    \left(x_1^2 - q^{n+1} \right)^2
      P_n ,
      \\
    %
      \label{k6_supplement-2a}
      \widehat{\mathcal{d}}_{-1,1}
      P_n \left( x; q^{-\frac{1}{2}} x_0, q^{\frac{1}{2}}x_1 \right)
      =
      q^{-n-\frac{3}{2}}    \left( x_0^2 - q^{n+1} \right)^2 \,
      P_n ,
      \\
      \label{k6_supplement-3}
      \widehat{\mathcal{d}}_{-1,-1}
      P_n\left(
        x; q^{-\frac{1}{2}}x_0 , q^{-\frac{1}{2}}x_1
      \right)
      =
      q^{-n-\frac{5}{2}}   
      \left( x_0^2 x_1^2 - q^{n+2} \right)^2
      P_{n+1} .
    \end{gather}
  \end{subequations}
  Combining the results~\eqref{k6_action_part} with~\eqref{A-k6_with_q-d},
  we get~\eqref{A-k6_P6-bar}.
\end{proof}



