\end{align}
then the
actions of~\eqref{A-action_on_P-bar} are  read   as
\begin{subequations}
  \label{k_special-nu}
  \begin{align}
    \label{k_special-nu-1}
    &
      \mathcal{A}(\mathbb{k}_1) \widebar{P}_n
      =\ch(x_0) \, \widebar{P}_n ,
    \\
    &
      \mathcal{A}(\mathbb{k}_3) \widebar{P}_n
      = - \ch\left(q^{-n-\frac{1}{2}}x_0 x_1 \right) \, \widebar{P}_n ,
    \\
    \label{k_special-nu-5}
    &
      \mathcal{A}(\mathbb{k}_5) \widebar{P}_n
      =\ch(x_1) \, \widebar{P}_n ,
    \\
    \label{k2_special-nu}
    &
      \begin{multlined}[b][.84\textwidth]
        \mathcal{A}(\mathbb{k}_2) \widebar{P}_n
        =
        - 
        \frac{
          q^{-n-\frac{3}{2}}x_0^2
          \left( 1- x_1^2 q^{-n-1}\right)^2
