    \\
    &
      \begin{multlined}[b][.84\textwidth]
        \mathcal{A}(\mathbb{k}_4) \widebar{P}_n
        =
        - 
        \frac{
          q^{-n-\frac{3}{2}}x_1^2
          \left( 1- x_0^2 q^{-n-1}\right)^2
        }{
          \left(1- x_0^2 x_1^2 q^{-2n-3} \right)
