        \\
        +
        \left( 1 +
          \frac{
            ( 1- x_1^2 q^{-n})^2
            (1- x_0^2 x_1^2 q^{-n})^2
          }{
            (1-x_1^2) ( 1- q \,x_1^2)
            (1-x_0^2 x_1^2 q^{-2n-1})
            (1-x_0^2 x_1^2 q^{-2n})
          }
          \right) \,
          \widebar{P}_n ,
      \end{multlined}
    \\
    &
      \begin{multlined}[b][.84\textwidth]
        \mathcal{A}(\mathbb{k}_6) \widebar{P}_n
        =
        \widebar{P}_{n+1}
        + \frac{(1-q^n)^2 (1-x_0^2 x_1^2 q^{-n+1})^2}{
