        -
        \left(
          \frac{
            q^{n+\frac{1}{2}} (1-x_0^2 q^{-n})^2}{
            (1-x_0^2) (1- q \, x_0^2)
          }
          +
          \frac{
            q^{n+\frac{1}{2}} (1-x_1^2 q^{-n})^2}{
            (1-x_1^2) (1- q  \, x_1^2)
          }
        \right) \,
        \widebar{P}_n .
      \end{multlined}
  \end{align}
\end{subequations}
\end{coro}
% The action $\mathcal{A}(\mathbb{k}_4)$ is given by transposing  $x_0$ and
% $x_1$ in~\eqref{k2_special-nu}.

It is now straightforward to see the correspondence with the genus-two
skein module~\eqref{k_and_theta-link}.
To construct explicitly
the map from the skein module,
we introduce
$\left| i,j,k \right\rangle$
for the admissible triple $(i,j,k)$, on which~$x_b$ and the $q$-difference operator~$\eth_b$ act as
\begin{equation}
  \label{eq:8}
  \begin{gathered}
    x_0  \left| i,j,k \right\rangle
    = -q^{\frac{i+1}{2}} \left| i,j,k \right\rangle,
    \qquad \qquad
    % &\eth_0 \left|i,j,k \right\rangle
    %   = \left| i-1,j,k\right\rangle ,
    % \\
    x_1  \left| i,j,k \right\rangle
    = -q^{\frac{k+1}{2}} \left| i,j,k \right\rangle,
    \\
    \eth_0^a \eth_1^b \left| i,j,k \right\rangle
    =
    \left|i-a, j, k-b \right\rangle
    .
    % &
    %   \qquad \qquad
    % &\eth_1 \left|i,j,k \right\rangle
    % = \left| i,j,k-1\right\rangle .
  \end{gathered}
\end{equation}
We then consider a composition of maps
\begin{equation}
  \label{map_for_module}
  n(i,j,k) \mapsto \left| i,j,k \right\rangle
  \mapsto
  \widebar{P}_{\frac{i-j+k}{2}}  ,
\end{equation}
associated to
$  \mathbb{k}_a \mapsto \mathcal{A}(\mathbb{k}_a)$
in~\eqref{define_A-k}.
The coefficients~$D_{a,b}(i,j,k)$ in~\eqref{k_and_theta-link}
can be rewritten as the actions of~$x_b$
on~$\left| i,j,k\right\rangle$.
It is easy to see that
the first three actions of~\eqref{k_and_theta-link}
map to~\eqref{k_special-nu-1}--\eqref{k_special-nu-5}.
% by sending the $\theta$-link to the reduced Askey--Wilson polynomial
We can check that
the remaining actions of~\eqref{k_and_theta-link} also map to
those in~\eqref{k_special-nu} by~\eqref{map_for_module}.
To conclude,
we have shown that the reduced Askey--Wilson
polynomials~$\widebar{P}_n$~\eqref{define_bar-P}
with~\eqref{define_nu} play a role of
the $\theta$-link~$n(i,j,k)$ in
the genus-two skein module~\eqref{k_and_theta-link}.






\section{Concluding Remarks}
We have shown the correspondence between the genus-two skein algebra
in~\cite{CookeSamue21a} and the family of the $q$-difference operators
including the reduced Askey--Wilson operators~\cite{KHikami19a}.
Given is
the topological
picture of the reduced Askey--Wilson polynomial
$\widebar{P}_n$~\eqref{define_bar-P}.
As a generalization of the Askey--Wilson polynomial,
it will be promising to study 
the 
roles of the $C^\vee C_n$-type DAHA and the
Macdonald--Koornwinder polynomials in the genus-two HOMFLY
skein algebra.


