\section{The continuous setting} \label{section:continuous}
%%
\paragraph*{Differential operators.}
%%
We denote the gradient, divergence, vector divergence,
Laplacian, bilaplacian, curl, symmetric curl, and Hessian operators
by~$\nabla$, $\div$, $\divbf$, $\Delta$, $\Delta^2$,
$\curlbold$, $\symcurlbold$, and~$\Dtwo$.

%%
\paragraph*{Lebesgue and basic Sobolev spaces.}
%%
In what follows, $D$ is a Lipschitz domain
with diameter~$\hD$ and boundary~$\partial D$.
The Lebesgue space of measurable functions with finite
$\Norm{v}{L^2(D)}
= \Norm{v}{0,D}
:= (\int_D \vert v \vert ^2 )^\frac12$ norm
is denoted by~$L^2(D)$;
this norm is induced by the inner product
$(u,v)_{0,D} := \int_D u \ v $.

Given a positive integer~$k$, $H^{k}(D)$ denotes the space
of $L^2(D)$ functions with distributional derivatives $D^{\boldalpha}$
of order~$k$ in $L^2(D)$.
We introduce the seminorms and norms
\[
\SemiNorm{v}{k,D}
:= \big(\sum_{\vert \boldalpha \vert=k} 
        \Norm{D^{\boldalpha} v}{0,D}\big)^{\frac12},
\qquad\qquad
\Norm{v}{k,D}
:= \Big( \sum_{\ell=0}^k \big(\hD^{k-\ell}
            \SemiNorm{v}{H^{k}(D)}\big)^2 \Big)^\frac12.
\]
Noninteger order Sobolev spaces are constructed via interpolation theory~\cite{Brenner-Gudi-Sung:2010}.
For vector and tensor Lebesgue and Sobolev spaces,
we replace the symbols~$H$ and~$L$
by $\Hbf$ and~$\Hbb$, and~$\Lbf$ and~$\Lbb$.
In the tensor case, additional subscripts~$\Sbb$ and~$\Tbb$
mean that we consider symmetric and trace free tensors.
As a matter of notation, we shall employ Latin letters to denote scalars,
boldface Greek (on occasions also Latin) letters to denote vector fields,
and blackboard bold Latin letters to denote tensors.

A trace theorem holds true for Sobolev spaces \cite[Chapter~3]{Ern-Guermond:2021}:
there exists a continuous operator mapping $H^s(D)$ to~$L^2(\partial D)$ for $s$ larger than $1/2$.
For $s$ in $(1/2, 3/2)$, we denote the image of~$H^s(D)$
through the trace operator by~$H^{s-\frac12}(\partial D)$.
For positive~$s$, $H^s_0(D)$ is the closure of~$\mathcal C^\infty_0(D)$
with respect to the~$H^s(D)$ norm.
The spaces $H^1_0(D)$ and $H^2_0(D)$ coincide
with the subspaces of~$H^1(D)$ and~$H^2(D)$
of functions with zero trace over~$\partial D$,
and zero trace and trace of the normal component of the gradient
over $\partial D$, respectively.

We define the Sobolev space $H^{-1}(\Omega)$ by duality:
\[
H^{-1}(D):= [H^1_0(D)]^*,
\qquad\qquad\qquad
\Norm{w}{-1,D} :=
\sup_{v \in H^1_0(D)} \frac{\langle w, v \rangle}{\Norm{v}{1,D}}.
\]

%%
\paragraph*{Some Sobolev boundary spaces.}
For a given simply connected, Lipschitz polygonal domain~$\Omega$,
we define two spaces on its boundary~$\partial\Omega$,
which will be useful to define trace operators
for a certain Sobolev space in~\eqref{Hdivdiv-spaces} below.
%see \cite{Chen-Huang:2021, Chen-Huang:2022, Amara-Capatina-Chatti:2002}.
The tangent and (outward) normal vectors of $\partial\Omega$
are~$\tauboldOmega$ and~$\nuboldOmega$.

For a given subset~$\F$ of~$\partial\Omega$
with nonzero $1$-dimensional measure, let
\[
\Hohzz(\F)
:=
\{ v \in H^{\frac12}(\F) \mid
    (\vtilde- v)_{|\F}=0 \text{ where } 
    \vtilde \in \Hoh(\partial\Omega),\    
    \vtilde_{\partial\Omega \setminus \F} =0 \}.
\]
We introduce a boundary space
as in \cite[Section~$2.3$]{Chen-Huang:2021}
\[
\Hnzoh(\partial\Omega)
:= \{ \partialnbfOmega v_{|\partial\Omega}
    \mid v \in H^2(\Omega) \cap H^1_0(\Omega) \}
 = \{ g \in L^2(\partial\Omega)
        \mid g_{|\F} \in \Hohzz(\F) 
        \quad \forall\ \text{facets } \F \}
\]
and endow it with the norm
\[
\Norm{g}{\Hnzoh(\partial\Omega)}
:= \inf_{v \in H^2(\Omega) \cap H^1_0(\Omega),\ \partialnbfOmega v_{|\partial\Omega} = g} 
    \Norm{v}{2,\Omega}.
\]
We also introduce the space
\[
\Hezth(\partial\Omega)
:=
\{ v_{|\partial\Omega} \mid
    v\in H^2(\Omega),\
    \partialnbfOmega v_{|\partial\Omega}=0,\quad
    v(\nu)=0\;\; \forall \nu \text{ vertices of } \Omega\}
\]
and endow it with the norm
\[
\Norm{g}{\Hezth(\partial\Omega)}
:= \inf_{\stackrel{v \in H^2(\Omega) ,\
    \partialnbfOmega v_{|\partial \Omega} = 0,\
    v_{|\partial \Omega}=g}
    {v(\nu)=0\; \forall \nu \text{ vertices of } \Omega}}
    \Norm{v}{2,\Omega}.
\]
Finally, we consider the spaces
\begin{equation} \label{dual-spaces-boundary}
\Hnmoh(\partial\Omega)
:= [\Hnzoh(\partial\Omega)]',
\qquad\qquad\qquad\qquad
\Hemth(\partial\Omega)
:= [\Hezth(\partial\Omega)]',
\end{equation}
which we can endow with their dual norms.

%%
\paragraph*{The $H(\divdivbf,\Omega)$ space.}
%%
Introduce the lowest order Raviart-Thomas space~$\RT_0(\Omega)$,
i.e., the span of $(1,0)$, $(0,1)$, and $(x,y)$,
and the spaces
\begin{equation} \label{Hdivdiv-spaces}
\begin{split}
\Hbb(\divdivbf,\Omega)
&:= \{ \Abb \in \Lbb^2(\Omega)
        \mid \divdivbf \Abb \in L^2(\Omega)\}, \\
\Hbb(\divdivbf^{\zerobf},\Omega)
& := \{ \Abb \in \Lbb^2(\Omega)
        \mid \divdivbf \Abb = 0\} ,
\end{split}
\end{equation}
which we endow with the norm
\[
\Norm{\cdot}{H(\divdivbf,\Omega)}
:= ( \text{diam}(\Omega)^{-4} \Norm{\cdot}{\Lbb^2(\Omega)}^2
    + \Norm{\divdivbf \cdot}{L^2(\Omega)}^2)^\frac12 .
\]
We define~$\Hbb_{\Sbb}(\divdivbf,\Omega)$ as the
subspace of symmetric tensors in~$\Hbb(\divdivbf,\Omega)$.
In what follows,
\[
\partialtbfOmega \cdot
\text{ and }
\partialnbfOmega \cdot
\text{ denote the tangential and normal derivatives along } \partial\Omega.
\]
A trace theorem for $\Hbb_{\Sbb}(\divdivbf)$ spaces is valid;
see \cite[Lemmas~$2.3$ and~$2.4$]{Chen-Huang:2021}.

%%%
\begin{proposition} \label{proposition:trace-divdiv}
For any~$\Bbb$ in $\Hbb_{\Sbb}(\divdivbf,\Omega)$,
there exists a positive constant~$C$ such that
\small\[
\begin{split}
& \Norm{\nuboldOmega^T \Bbb \nuboldOmega}{\Hnmoh(\partial\Omega)}
\le C \Norm{\Bbb}{H(\divdivbf,\Omega)},
\qquad \Norm{\partialtbfOmega(\tauboldOmega^T \Bbb \tauboldOmega)
+ \nuboldOmega^T \divbf \Bbb}{\Hemth(\partial\Omega)}
\le C \Norm{\Bbb}{H(\divdivbf,\Omega)}.
\end{split}
\]\normalsize
The two trace operators above admit continuous
right-inverses.
\end{proposition}
The proof of Proposition~\ref{proposition:trace-divdiv}
is strictly related to the validity of
the following Green's identity \cite[Lemma~2.1]{Chen-Huang:2021}:
for all~$v$ in $H^2(\Omega)$ and all~$\Bbb$
in the space of symmetric tensors in $\Ccal^2(\Omega)$,
\begin{equation} \label{Green-divdiv}
\begin{split}
(\divdivbf \Bbb, v)_{0,\Omega}
& = (\Bbb,\Dtwo v)_{0,\Omega}
   - \sum_{\F \in \FcalOmega}
      \sum_{\nu \in \VcalF}
      \sign_{\F,\nu}\ (\tauboldOmega^T \Bbb \nuboldOmega)(\nu) \ v(\nu) \\
& \quad - \sum_{\F\in\FcalOmega} \Big[
        (\nuboldOmega^T\Bbb\nuboldOmega,\partialnbfOmega v)_{0,\F}
        - \big( \partialtbfOmega (\tauboldOmega^T\Bbb\nuboldOmega)
        + \nuboldOmega^T \divbf\Bbb,v)_{0,\F} \big) \Big],
\end{split}
\end{equation}
where
\[
\sign_{\F,\nu}
:= \begin{cases}
    1  & \text{if~$\nu$ is the endpoint of~$\F$}\\
    -1 & \text{if~$\nu$ is the start endpoint of~$\F$}
\end{cases}
\qquad\qquad\qquad
\forall \F \in\FcalOmega, \nu \in \VcalF.
\]
The last two inner products in~\eqref{Green-divdiv}
are to be interpreted as suitable duality pairings
for tensors~$\Bbb$ in $\Hbb_{\Sbb}(\divdivbf,\Omega)$:
\[
\begin{split}
\sum_{\F\in\FcalOmega}
(\nuboldOmega^T\Bbb\nuboldOmega,\partialnbfOmega v)_{0,\F}
& = _{-\frac12,\partial\Omega} \langle \nuboldOmega^T\Bbb\nuboldOmega, 
    \partialnbfOmega v \rangle _{\frac12,\partial\Omega},\\
\sum_{\F\in\FcalOmega} 
\big( \partialtbfOmega (\tauboldOmega^T\Bbb\nuboldOmega)
        + \nuboldOmega^T \divbf\Bbb,v)_{0,\F}
& = _{-\frac32,\partial\Omega} \langle \partialtbfOmega (\tauboldOmega^T\Bbb\nuboldOmega)
        + \nuboldOmega^T \divbf\Bbb,v
        \rangle _{\frac32,\partial\Omega}.
\end{split}
\]
The bounds in Proposition~\ref{proposition:trace-divdiv}
follow from~\eqref{Green-divdiv}, picking first~$v$
in~$\Hnzoh(\partial\Omega)$ and then in~$\Hezth(\partial\Omega)$.


%%%%
\paragraph*{Some finite element spaces.}
%%%%
In what follows, $\VbfHoh$, $\Sigmabbh$, and~$\Vh$ denote
the standard vector Lagrange finite element space of order~$\p$,
the $\divdivbf$-conforming tensor finite element
space detailed, e.g., in~\cite{Chen-Huang:2021}
and \cite[Section~5.4]{Chen-Huang:2022} of order~$\p$,
see also Remark~\ref{remark:divdiv-conformity} below,
and  the standard DG space of order~$\p-2$.
In Section~\ref{section:apos-bounds} below,
for $\p=3,4$, we shall be using
the HCT space~\cite{Douglas-Dupont-Percell-Scott:1979}.
None of this spaces will be employed
in the implementation of the scheme~\eqref{method} below,
nor in the computation of the error estimator~\eqref{error-estimator};
the space~$\Sigmabbh$ is included for completeness as a pivot
space to construct the FE sequence in~\eqref{FE-divdiv-sequence},
but is not used in the forthcoming analysis.


%%%
\begin{remark} \label{remark:divdiv-conformity}
We recall \cite[Section~3.2]{Chen-Huang:2021}
that the space~$\Sigmabbh$ consists of piecewise tensors polynomials
that are $H(\divdivbf)$-conforming
on the whole domain in the sense that they
(\emph{i}) are continuous at the vertices;
(\emph{ii}) admit matching (polynomial) traces
in~$\Hnmoh$ and~$\Hemth$
in the sense of~\eqref{dual-spaces-boundary}
across all facets.
\end{remark}



%%
\paragraph*{Exact sequences.}
We are in a position to introduce the
two dimensional ``div-div'' complex,
see \cite{Chen-Huang:2021, Chen-Huang:2022}
and \cite[Section~2.4]{Chen-Huang:2024}:
\begin{equation} \label{complex:div-div}
\RT_0(\Omega)
\quad\overset{\subset}{\longrightarrow}\quad
\Hbf^1(\Omega)
\quad\overset{\symcurlbold}{\longrightarrow}\quad
\Hbb_{\Sbb}(\divdivbf,\Omega)
\quad\overset{\divdivbf}{\longrightarrow}\quad
L^2(\Omega) 
\quad\overset{0}{\longrightarrow}\quad
0 .
\end{equation}
A finite element counterpart of the sequence in~\eqref{complex:div-div}
is 
\begin{equation} \label{FE-divdiv-sequence}
\RT_0(\Omega)
\quad\overset{\subset}{\longrightarrow}\quad
\VbfHoh
\quad\overset{\symcurlbold}{\longrightarrow}\quad
\Sigmabbh
\quad\overset{\divdivbf}{\longrightarrow}\quad
\Vh
\quad\overset{0}{\longrightarrow}\quad
0 .
\end{equation}
The two sequences~\eqref{complex:div-div}
and~\eqref{FE-divdiv-sequence} are exact.

%%
\paragraph*{The model problem.}
Given~$f$ be in $L^{2}(\Omega)$,
we are interested in finding~$u:\Omega \to \Rbb$ such that
\begin{equation} \label{problem:strong}
\begin{cases}
\Delta^2 u = f                             & \text{in } \Omega \\
u = 0, \qquad \nuboldOmega^T \nabla u = 0  & \text{on } \partial \Omega.
\end{cases}
\end{equation}
Introduce
\[
V := H^2_0(\Omega),
\qquad\qquad\qquad\qquad
B(u,v) := (\Dtwo u, \Dtwo v)_{0,\Omega}
\qquad \forall u,v \in V.
\]
Noting that~$\Delta^2 = \div\divbf(\Dtwo)$,
a weak formulation of~\eqref{problem:strong} reads
\begin{equation} \label{problem:weak}
\begin{cases}
\text{find } u \in V \text{ such that}\\
B(u,v) = (f , v )_{0,\Omega} \qquad\qquad \forall v \in V.
\end{cases}
\end{equation}
Problem~\eqref{problem:weak} is well-posed;
see, e.g., \cite[Section 5.9]{Brenner-Scott:2008}.


\section{The method and a generalized Hessian} \label{section:method}
%%
\paragraph*{Meshes.}
We consider a simplicial mesh~$\tauh$.
Given~$\hT$ and~$\rhoT$ the diameter and the maximal inradius
of each element~$\T$ in~$\tauh$,
we introduce the positive shape-regularity parameter~$\gamma_\T$
% there exists a universal, positive constant~$\gamma$ such that
\begin{equation} \label{def:gamma}
    \frac{\hT}{\rhoT} \le \gamma_T.
\end{equation}
In what follows, the constants appearing in the inequalities
are allowed to depend on $\gamma:=\max_{\T\in\tauh} \gamma_\T$;
on occasions, for given positive constants~$a$ and~$b$,
we shall write $a \lesssim b$ if there exists a positive constant~$C$
only depending on~$\gamma$.


With each~$\tauh$, we associate its set of total~$\Fcaln$,
internal~$\FcalnI$, and boundary~$\FcalnB$ facets.
The diameter of a facet~$\F$ is~$\hF$.
For a given mesh with given set of vertices
$\{\mathfrak v\}$, $\h$ denotes a function defined
on~$\Omega \setminus \{\mathfrak v\}$
such that it equals~$\hT$ and~$\hF$
in the interior of each element~$\T$
and in the interior of each facet~$\F$, respectively.
The set of facets of an element~$\T$ is $\FcalT$.
Given~$\T$ and~$\F$ in~$\tauh$ and~$\Fcaln$,
we define the patches
\small\begin{equation} \label{patches}
\omegaT := \cup \{ \Ttilde \in \tauh \mid 
    \Ttilde \cap \T \ne \emptyset \},
\qquad
\omegaF := \cup \{ \omegaT \mid
    \T\in\tauh,\; \F \in \FcalT \},
\qquad
\omegatildeF := \cup \{ \T \mid \F \in \FcalT \}.
\end{equation}\normalsize
For positive~$s$, we introduce the broken Sobolev space
\[
H^s(\tauh,\Omega):= \{ v \in L^2(\Omega) \mid v_{\T} \in H^s(\T)
                    \quad \forall \T \in \tauh \}.
\]
For each facet~$\F$, we define the jump $\jump{\cdot}_\F$
and average $\average{\cdot}_{\F}$
operators on $L^2(\F)$ as follows:
for a boundary facet~$\F$ and~$v$ in $L^2(\F)$,
we set $\jump{v}_\F=\average{v}_\F=v$;
for an internal facet~$\F$
with fixed normal vector $\nuboldF$,
shared by~$\Tplus$ and~$\Tminus$
with outward unit normal vectors~$\nubold_{\Tplus}$
and~$\nubold_{\Tminus}$,
given $v$ in $H^1(\tauh,\Omega)$ with restrictions
$v_{\Tplus}$ and~$v_{\Tminus}$ over~$\Tplus$ and~$\Tminus$, we set
\[
\jump{v}_{\F} :=
(v_{\Tplus} \nuboldF \cdot \nubold_{\Tplus}
    + v_{\Tminus} \nuboldF \cdot \nubold_{\Tminus})_{|\F},
\qquad\qquad\qquad
\average{v}_{\F} = \frac12 (v_{\Tplus} + v_{\Tminus})_{|\F}.
\]
We employ the same notation for these operators while applied to vector fields
and remove the subscript~$\F$ when it is clear from the context.

We introduce the following skeletal inner product and norm:
for any subset~$\widetilde{\Fcal}_{\textrm h}$ of~$\Fcaln$,
\[
(u,v)_{0,\widetilde{\Fcal}_{\textrm h}} 
= \sum_{\F \in \widetilde{\Fcal}_{\textrm h}} (u,v)_{0,\F} ,
\qquad\quad \Norm{v}{0,\widetilde{\Fcal}_{\textrm h}}^2 := (v, v)_{0,\widetilde{\Fcal}_{\textrm h}}
\qquad\qquad\quad \forall v \in L^2(\F),
\; \forall \F \in \widetilde{\Fcal}_{\textrm h}.
\]
All differential operators defined piecewise over the mesh elements
are denoted with the same symbol of the original operator and a subscript~$\h$;
for instance, the piecewise Hessian over~$\tauh$ is denoted by~$\Dtwoh$.

%%%%%%
\paragraph{The method.}
Let~$\csigma$ and~$\ctau$ be two stabilization parameters
to be chosen sufficiently large;
see Lemma~\ref{lemma:coercivity-continuity} below.
We introduce the IPDG bilinear form
\small\begin{equation} \label{IPDG-bilinear-form-noL}
\begin{split}
\Bh(\uh,\vh)
:= & (\Dtwoh \uh, \Dtwoh \vh)_{0,\Omega}
    + \Big(\jump{\uh}, \average{\nuboldF^T \divbf\Dtwoh \uh} \Big)_{0,\Fcaln}
    - \Big(\jump{\nabla \uh}, \average{\nuboldF^T \Dtwoh \uh}\Big)_{0,\Fcaln} \\
   & + \Big(\average{\nuboldF^T \divbf\Dtwoh\uh}, \jump{\vh} \Big)_{0,\Fcaln}
     - \Big(\average{\nuboldF^T \Dtwoh\uh}, \jump{\nabla \vh}\Big)_{0,\Fcaln} \\
   & + \csigma (\h^{-3}\jump{\uh},\jump{\vh})_{0,\Fcaln}
     + \ctau (\h^{-1}\jump{\nablah \uh},\jump{\nablah \vh})_{0,\Fcaln}
\qquad\qquad \forall \uh,\vh\in\Vh.
\end{split}
\end{equation}\normalsize
We introduce the lifting operator~$\Lbbh : \Vh \oplus V \to [\Vh]^{2\times 2}$ as
\small\begin{equation} \label{lifting}
(\Lbbh (v), \Bbbh)_{0,\Omega}
:=  \Big(\jump{v}, \average{\nuboldF^T \divbf\Bbbh} \Big)_{0,\Fcaln}
   - \Big(\jump{\nabla v}, \average{\nuboldF^T \Bbbh}\Big)_{0,\Fcaln} 
   \qquad \forall \Bbbh \in [\Vh]^{2\times2},
\end{equation} \normalsize
which satisfies the following result;
see \cite[Lemma~5.1]{Georgoulis-Houston:2009}.
%%
\begin{lemma} \label{lemma:properties-Lcal}
The lifting operator in~\eqref{lifting}
is well-defined.
Moreover, there exists a positive constant~$\cLcalh$
only depending on~$\csigma$ and~$\ctau$
in~\eqref{IPDG-bilinear-form-noL},
the shape-regularity parameter~$\gamma$, and~$\p$ such that
\begin{equation} \label{stability-Lcal}
\Norm{\Lbbh(\vh)}{0,\Omega}
\le \cLcalh \left( \h^{-\frac32}\Norm{\jump{\vh}}{0,\Fcaln}
                    + \h^{-\frac12}\Norm{\jump{\nabla\vh}}{0,\Fcaln} \right)
\qquad\qquad \forall \vh \in \Vh.
\end{equation}
If~$v$ belongs to $V$, then $\Lbbh (v) = [0]^{d\times d}$.
\end{lemma}
%%
Using~\eqref{lifting}, the bilinear form
in~\eqref{IPDG-bilinear-form-noL}
can be equivalently rewritten as
\begin{equation} \label{IPDG-bilinear-form}
\begin{split}
\Bh(\uh,\vh)
:= & (\Dtwoh \uh, \Dtwoh \vh)_{0,\Omega}
    + (\Lbbh(\uh),\Dtwoh \vh)_{0,\Omega} 
   + (\Dtwoh \uh, \Lbbh(\vh))_{0,\Omega}\\
   & + \csigma (\jump{\uh},\jump{\vh})_{0,\Fcaln}
     + \ctau (\jump{\nablah \uh},\jump{\nablah \vh})_{0,\Fcaln}
\qquad\qquad \forall \uh,\vh\in\Vh.
\end{split}
\end{equation}
The bilinear form in~\eqref{IPDG-bilinear-form}
is well-defined also on $[H^2_0(\Omega)]^2$
whereas that in~\eqref{IPDG-bilinear-form-noL} is not.

Introduce the DG norm
\begin{equation} \label{DG-norm}
\Norm{\vh}{\DG}^2
:= \Norm{\Dtwoh \vh}{0,\Omega}^2 
   + \Norm{\h^{-\frac32}\jump{\vh}}{0,\Fcaln}^2
   + \Norm{\h^{-\frac12}\jump{\nabla \vh}}{0,\Fcaln}^2.
\end{equation}
The following result is valid; see \cite[Lemma~5.2]{Georgoulis-Houston:2009}.
%%
\begin{lemma} \label{lemma:coercivity-continuity}
Let the stabilization parameters~$\sigma$ and~$\ctau$ in~\eqref{IPDG-bilinear-form}
be sufficiently large.
The following coercivity and continuity properties hold true:
there exist positive constant~$c_{\flat}$ and~$c_{\sharp}$
only depending on~$\csigma$ and~$\ctau$
in~\eqref{IPDG-bilinear-form-noL},
the shape-regularity parameter~$\gamma$, and~$\p$ such that
\[
\Bh(\vh,\vh) \ge c_{\flat} \Norm{\vh}{\DG}^2,
\qquad\qquad\qquad
\Bh(\uh,\vh) \le c_{\sharp} \Norm{\uh}{\DG} \Norm{\vh}{\DG} .
\]
\end{lemma}
We are now in a position to introduce an IPDG method
for the discretization of problem~\eqref{problem:weak}:
\begin{equation} \label{method}
\begin{cases}
    \text{find } \uh \in \Vh \text{ such that}\\
    \Bh(\uh,\vh) = (f,\vh)_{0,\Omega} \qquad\qquad\forall\vh\in\Vh.
\end{cases}
\end{equation}
The well-posedness of method~\eqref{method}
follows from Lax-Milgram lemma, Lemma~\ref{lemma:coercivity-continuity},
Cauchy-Schwarz' inequality on the right-hand side of~\eqref{method},
and the Poincar\'e inequality
for piecewise $H^2$ functions in~\cite{Brenner-Wang-Zhao:2004}.

Given~$\uh$ the solution to~\eqref{method}
and $\Lbbh$ as in~\eqref{lifting},
we introduce the generalized Hessian
\begin{equation} \label{generalized:Hessian}
\Hbbhuh := \Dtwoh \uh + \Lbbh(\uh)
\end{equation}
and rewrite,
for all~$\uh$ and~$\vh$ in~$\Vh$,
the DG bilinear form in~\eqref{IPDG-bilinear-form} as
\small\[
\Bh(\uh,\vh)
= (\Hbb(\uh),\Hbb(\vh))_{0,\Omega}
    - (\Lbb(\uh),\Lbb(\vh))_{0,\Omega}
    + \csigma (\jump{\uh},\jump{\vh})_{0,\Fcaln}
    + \ctau (\jump{\nablah \uh},\jump{\nablah \vh})_{0,\Fcaln}.
\]\normalsize



%----------------------------------
\section{A splitting of the generalized Hessian error} \label{section:setting}
%----------------------------------
Given~$s$ in~$V$ such that
\begin{equation} \label{definition:s}
s := \argmin_{t \in V} \Norm{\Hbbhuh - \Dtwo t}{0,\Omega}
\qquad\Longleftrightarrow\qquad
(\Dtwo s -\Hbbhuh, \Dtwo v)=0 \quad\forall v\in V,
\end{equation}
Pythagoras' theorem implies
\begin{equation} \label{Pythagoras}
\Norm{\Dtwo u - \Hbbhuh}{0,\Omega}^2
= \Norm{\Dtwo (u - s)}{0,\Omega}^2
  + \Norm{\Dtwo s - \Hbbhuh}{0,\Omega}^2
=: T_1^2 + T_2^2  .
\end{equation}
As for the term~$T_1$, a duality argument reveals that
\begin{equation} \label{T1-as-sup}
T_1 
= \sup_{v\in V,\ \SemiNorm{v}{2,\Omega}=1} (\Dtwo(u-s), \Dtwo v)_{0,\Omega}
\overset{\eqref{definition:s}}{=}
    \sup_{v\in V,\ \SemiNorm{v}{2,\Omega}=1} (\Dtwo u -\Hbbhuh, \Dtwo v)_{0,\Omega} .
\end{equation}
We also rewrite the term~$T_2$ as a sup
over a suitable space. To this aim, we need a technical result.

%%%
\begin{proposition} \label{proposition:2nd-term-divdiv-zero}
The tensor $\Dtwo s - \Hbbh(\uh)$
belongs to $\Hbb(\divdivbf^{\zerobf},\Omega)$
in~\eqref{Hdivdiv-spaces}.
\end{proposition}
%%%%
\begin{proof}
The proof boils down to using the Green's identity
in~\eqref{Green-divdiv}
and showing that all the terms on the right-hand side vanish.
The latter task is achieved by taking
test functions~$v$ with a suitable local supports.
\end{proof}
%%

Using Proposition~\ref{proposition:2nd-term-divdiv-zero}
and observing that the space~$\Hbb(\divdivbf^{\zerobf},\Omega)$
is Hilbert with respect to the $L^2(\Omega)$ norm,
a duality argument entails
the following rewriting of the term~$\T_2$
in~\eqref{Pythagoras}:
\[
T_2 
= \sup_{\wbb\in H(\divdivbf^0,\Omega),\ \Norm{\wbb}{0,\Omega}=1}
       (\Hbbhuh - \Dtwo s, \wbb)_{0,\Omega} .
\]
Using the ``divdiv'' complex~\eqref{complex:div-div},
the fact that~$\Dtwo s$ is symmetric,
and an integration by parts,
we arrive at
\begin{equation} \label{T2-as-sup}
\begin{split}
T_2 
& = \sup_{\psibold \in \Hbf^1(\Omega),\ 
            \Norm{\symcurlbold \psibold}{0,\Omega}=1}
       (\Hbbhuh - \Dtwo s, \symcurlbold \psibold)_{0,\Omega} \\
& = \sup_{\psibold \in \Hbf^1(\Omega),\ 
            \Norm{\symcurlbold \psibold}{0,\Omega}=1}
       (\Hbbhuh, \symcurlbold \psibold)_{0,\Omega} .
\end{split}
\end{equation}
Collecting~\eqref{T1-as-sup} and~\eqref{T2-as-sup},
we obtain the crucial identity
\small{\begin{equation} \label{rewriting-in-terms-of-max}
\begin{aligned}
\Norm{\Dtwo u-\Hbbhuh}{0,\Omega} ^2
& = \Big(\sup_{v\in V,\ \SemiNorm{v}{2,\Omega}=1}  (\Dtwo u -\Hbbhuh, \Dtwo v)_{0,\Omega} \Big)^2 \\
& \quad +  \Big(\sup_{\psibold \in \Hbf^1(\Omega),\ 
            \Norm{\symcurlbold \psibold}{0,\Omega}=1}
       (\Hbbhuh, \symcurlbold \psibold)_{0,\Omega}) \Big)^2.
\end{aligned}
\end{equation}}\normalsize

%%%
%----------------------------------
\section{A posteriori bounds for a class of generalized Hessians} \label{section:apos-bounds}
%----------------------------------

The forthcoming analysis applies
to all piecewise polynomial tensor fields~$\Hbbh$
satisfying the following properties:
\begin{subequations} \label{properties-GH}
\begin{align}
(\Hbbh,\Dtwo \wh)_{0,\Omega} = (f,\wh) _{0,\Omega}
& \qquad\qquad\qquad\qquad \forall 
    \wh \in \Vh\cap  H^2_0(\Omega),
        \label{properties-GH:1}\\
(\Hbbh, \symcurlbold \thetaboldh)_{0,\Omega}=0
& \qquad\qquad\qquad\qquad \forall \thetaboldh \in \VbfHoh. \label{properties-GH:2}
\end{align}    
\end{subequations}
In what follows, we shall refer to such tensor fields
as generalized Hessians.
In~\eqref{properties-GH:2}, we recall that~$\VbfHoh$ denotes
the standard vector $H^1$-conforming finite
element space.
In Section~\ref{subsection:properties:GH}, we shall be proving
that~$\Hbbhuh$ in~\eqref{generalized:Hessian}
satisfies~\eqref{properties-GH}.

%%%
\begin{remark} \label{remark:C1-tests}
In~\eqref{properties-GH:1}, the space~$\Vh\cap  H^2_0(\Omega)$
is the finite element space~$\VHth$
as in \cite{Morgan-Scott:1975}
for $p$ larger than or equal to~$5$.
Assuming that a given mesh~$\tauh$
is an HCT refinement of a coarser mesh~$\tautildeh$
(i.e., an element~$\widetilde T$ in $\tautildeh$
is refined into three elements of $\tauh$
obtained connecting the vertices of~$\widetilde T$
to its centroid),
the space~$\Vh\cap  H^2_0(\Omega)$
contains the HCT finite element space of degree
$\p=3,4$ on the mesh~$\tautildeh$.
\end{remark}



Aim of this section is to derive upper and lower a posteriori error bounds
for the error in~\eqref{rewriting-in-terms-of-max}
in terms of the error estimator
\begin{subequations}
\label{error-estimator}
\begin{equation} \label{global-error-estimator}
    \eta^2 := \sum_{\T\in\tauh} \etaT^2,
\end{equation}
where
\begin{align}
\nonumber
\etaT^2
&   := \sum_{j=1}^5 \eta_{j,\T}^2
    :=  \hT^4 \Norm{f-\div\divbf \Hbbh}{0,\T}^2\\
\nonumber
& \quad + \frac12 \sum_{\F\in\FcalT\cap\FcalnI}
    \Big( \hF\Norm{\nuboldF^T\jump{\Hbbh}\nuboldF}{0,\F}^2
    + \hF^3 \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F}^2 \Big) \\
& \quad + \hT^2 \Norm{\curlsym\Hbbh}{0,\T}^2
     + \sum_{\F\in\FcalT} \hF \Norm{\tauboldF^T  \jump{\sym\Hbbh}}{0,\F}^2.
\label{local-error-estimator}
\end{align}
\end{subequations}
The local error estimators in~\eqref{local-error-estimator}
do not depend explicitly on the stabilization of the DG method.
The first two terms and the last two terms
on the right-hand side of~\eqref{local-error-estimator}
are residual-type terms related to the
conforming and nonconforming parts of the error,
respectively, i.e., the two terms on the right-hand side
in~\eqref{rewriting-in-terms-of-max}.

\begin{remark} \label{remark:powers-h}
All the powers of~$\h$ in~\eqref{local-error-estimator} are positive.
\end{remark}

The main result of this section is reported here;
its proof is a consequence of the computations in
Sections~\ref{subsection:upper-lower-bound-T1}
and~\ref{subsection:upper-lower-bound-T2}.

%%
\begin{theorem} \label{theorem:apos-bounds}
Given~$u$ and~$\uh$ the solutions
to~\eqref{problem:weak} and~\eqref{method},
let~$\Hbbh(\uh)$ be the generalized Hessian as in~\eqref{generalized:Hessian},
and~$\eta$ and $\etaT$ be the global and local error estimators as
in~\eqref{global-error-estimator} and~\eqref{local-error-estimator}.
Furthermore, let~$\fh$ denote the piecewise $L^2$ projection
onto the space of polynomials of degree~$\p$.
Then, the following reliability and efficiency error bounds are valid:
there exist positive constants $C_{\rm rel}$ and $C_{\rm eff}$
independent of~$\h$,
but depending on~$\gamma$ in~\eqref{def:gamma},
the domain~$\Omega$ through $C_{JG}$ in~\eqref{psibold-thetabold-relation},
and the polynomial degree~$\p$,
such that
\begin{subequations} \label{apos-bound}
\begin{align}
& \Norm{\Dtwo u - \Hbbh(\uh)}{0,\Omega}
\le C_{\rm rel} \eta, \label{apos-bound-1}\\
& \etaT \le C_{\rm eff} \big(\Norm{\Dtwoh u - \Hbbh(\uh)}{0,\omegaT}
            + \sum_{\Ttilde \in \omegaT}
             \h_{\Ttilde}^2 \Norm{f-\fh}{0,\Ttilde} \big)
             \qquad\qquad \forall \T \in \tauh \label{apos-bound-2}.
\end{align}
\end{subequations}
Bound~\eqref{apos-bound-2} holds true for any polynomial degree~$\p$
larger than or equal to~2.
Bound~\eqref{apos-bound-1} is valid assuming
$\p$ larger than or equal to~$5$ on any mesh,
and $\p=3,4$ on meshes stemming from HCT refinements
as discussed in Remark~\ref{remark:C1-tests}.
\end{theorem}
Numerical examples in Section~\ref{section:nr} below
indicate that bound~\eqref{apos-bound-1}
remains valid for $\p=2,3,4$ on any mesh.

The remainder of this section is organized as follows.
After introducing technical tools
in Section~\ref{subsection:technical-tools},
including quasi-interpolation results
and polynomial inverse estimates,
we derive a posteriori error bounds
in Sections~\ref{subsection:upper-lower-bound-T1}
and~\ref{subsection:upper-lower-bound-T2},
for any generalized Hessian satisfying
the properties detailed in~\eqref{properties-GH}.
We prove that the generalized Hessian in~\eqref{generalized:Hessian}
satisfies~\eqref{properties-GH} in Section~\ref{subsection:properties:GH}.
In order to shorten the notation, we shall write $\Hbbh$.
A comparison with standard DG residual error estimators
is given in Section~\ref{subsection:comparison-standard-ee}.


%%%%
\subsection{Technical tools} 
\label{subsection:technical-tools}
%%%%
This section is devoted to discussing several technical
tools, which will be instrumental
in the a posteriori error analysis.
Notably, we discuss:
the approximation properties
of $\mathcal C^0$ and $\mathcal C^1$
quasi-interpolants,
which are essential in deriving the reliability
of the error estimator;
extension operators, bubble functions,
and polynomial inverse estimates,
which are needed in deriving the efficiency
of the error estimator.


%%%%%%
\paragraph*{$\mathcal C^0$ quasi-interpolants.}
Introduce the vector Cl\'ement
quasi-interpolant~$\thetaboldI$
of~$\thetabold$ in $\Hbf^1(\Omega)$
as in~\cite{Ciarlet:1975}.
We have the standard approximation properties
\begin{equation} \label{Clement-qi}
\Norm{\thetabold-\thetaboldI}{0,\T}
+ \hT \SemiNorm{\thetabold-\thetaboldI}{1,\T}
\lesssim \hT \SemiNorm{\thetabold}{1,\omegaT},
\qquad\qquad
\Norm{\thetabold-\thetaboldI}{0,\F}
\lesssim \hT^\frac12 \SemiNorm{\thetabold}{1,\omegaF}.
\end{equation}


%%%%%%
\paragraph*{$\mathcal C^1$ quasi-interpolants
preserving nodal values.}
For $\p$ larger than or equal to~$5$,
consider the quasi-interpolant~$\vI$ in~$\VHth$
of a function~$v$~in $V$
as in \cite[Theorem~3.2]{Graessle:2022},
which is a modification of that in
\cite[Section~5]{Girault-Scott:2002}
and allows for exact pointwise interpolation
at the vertices of the mesh;
see also \cite[Theorem~2]{Carstensen-Hu:2021}.
The following interpolation estimates
can be derived from the results in \cite[Theorem~3.2]{Graessle:2022}
and standard trace inequalities:
for all elements~$\T$ and all~$\F$ in~$\FcalT$,
\begin{equation} \label{interpolation:C1}
\hT^{-2}  \Norm{v-\vI}{0,\T}
+ \sum_{\F \in \FcalT}
   \Big( \hF^{-\frac32} \Norm{v-\vI}{0,\F}
        + \hF^{-\frac12} \Norm{\nabla(v-\vI)}{0,\F}
   \Big)
\lesssim  \SemiNorm{v}{2,\omegaT}.
\end{equation}
Compared to other $\mathcal C^1$ quasi-interpolants,
e.g., that in \cite{Girault-Scott:2002},
the one we pick has the property
of interpolating functions at the vertices of the mesh
\cite[Theorem 3.2 (a)]{Graessle:2022}:
\begin{equation} \label{C1-vertices}
    (v-\vI)(\nu)=0
    \qquad\qquad\qquad
    \forall \nu \text{ vertex of $\tauh$}.
\end{equation}
With a similar reasoning,
for $\p=3,4$, and meshes as those discussed in
Remark~\ref{remark:C1-tests},
one can define an HCT quasi-interpolant
satisfying~\eqref{interpolation:C1}
and~\eqref{C1-vertices}.
In fact, the interpolant in~\cite{Girault-Scott:2002}
is based on nodal averaging employing
auxiliary $L^2$ dual basis on patches/elements.
If $v$ belongs to $H^2(\Omega)$, we may replace
averages with point values at the pointwise vertex
degrees of freedom.
This newly defined operator preserves polynomials
and is continuous in $H^2(\Omega)$,
which is enough to derive the interpolation estimates. 

%%%%%%
\paragraph*{A facet extension operator.}
We shall be considering
extension operators $\Ecal_\F = \Ecal : L^2(\F) \to L^2(\omegatildeF)$
for all~$\F$ in~$\Fcaln$.
Such operators are defined so as to satisfy
\begin{equation} \label{extension-operator}
\Ecal v (x) = v(x') \text{ in } \T, \quad \T \subset \omegaF,
\text{ if } x'\in \F \text{ is such that }
\lambda_j(x') = \lambda_j(x),
\end{equation}
where $\lambda_j$ is one of the two barycentric
coordinates of~$\T$.
In particular, this operator acts as the identity on the facet~$\F$.


%%%%%%
\paragraph*{$\Ccal^0$ bubble functions and inverse estimates.}
In the treatment of the lower bound for the nonconforming
part of the error, see Section~\ref{subsection:upper-lower-bound-T2},
we shall be using two different bubbles.
The first one is defined on the element~$\T$ and is given by
\begin{equation} \label{C0-bubble-bulk}
    \btildeT:=
    27 \ \Pi _{j=1}^3 \lambda_j^\T,
\end{equation}
where the~$\lambda_j^\T$, $j=1,2,3$,
are the barycentric coordinates of~$\T$.
We have \cite{Verfurth:2013}
the standard inverse estimates
\begin{equation} \label{C0-bubble-bulk-IE}
\Norm{\qp}{0,\T} 
    \lesssim \Norm{\btildeT^\frac12 \qp}{0,\T},
\qquad
\SemiNorm{\btildeT \qp}{1,\T} 
    \lesssim \hT^{-1} \Norm{\qp}{0,\T} 
\qquad\qquad\qquad
\forall \qp \in P_\p(\T).
\end{equation}
The second one is defined on the patch~$\omegatildeF$,
see~\eqref{patches},
for a given facet~$\F$ and is given by
\begin{equation} \label{C0-bubble-facet}
\btildeF{}_{|\T} = 4\ \Pi_{j=1}^2 \lambda_j^\T
\qquad\qquad\qquad \forall \T \subset \omegatildeF,
\end{equation}
where $\lambda_j^\T$, $j=1,2,3$,
are the barycentric coordinates of~$\T$
subset of~$\omegatildeF$,
$j=3$ being the index related to the facet~$\F$.
Given $\Ecal$ as in~\eqref{extension-operator},
we have \cite{Verfurth:2013} the inverse estimates
\small\begin{equation} \label{C0-bubble-facet-IE}
\Norm{\qp}{0,\F} 
    \lesssim \Norm{\btildeF^\frac12 \qp}{0,\F},
\quad
\SemiNorm{\btildeF \Ecal(\qp)}{1,\T} 
+ \hT^{-1}\Norm{\btildeF \Ecal(\qp)}{0,\T} 
    \lesssim \hF^{\frac12} \Norm{\qp}{0,\F} 
\qquad  \forall \qp \in P_\p(\F).
\end{equation} \normalsize

%%%%%%
\paragraph*{$\Ccal^1$ bubble functions and inverse estimates.}
In the treatment of the lower bound for the conforming
part of the error, see Section~\ref{subsection:upper-lower-bound-T1},
we shall be using three different bubbles.
The first one is defined on the element~$\T$ and,
for $\btildeT$ as in~\eqref{C0-bubble-bulk},
is given by
\begin{equation} \label{C1-bubble-bulk}
    \bT:= \btildeT^2.
\end{equation}
In particular, this is a $\Ccal^1$ bubble
vanishing and with vanishing normal component
of the gradient over~$\partial\T$.
We have \cite{Verfurth:2013}
the standard inverse estimates
\begin{equation} \label{C1-bubble-bulk-IE}
\Norm{\qp}{0,\T} 
    \lesssim \Norm{\bT^\frac12 \qp}{0,\T},
\qquad
\SemiNorm{\bT \qp}{2,\T} 
    \lesssim \hT^{-2} \Norm{\qp}{0,\T} 
\qquad\qquad\qquad
\forall \qp \in P_\p(\T).
\end{equation}
The second one is associated with the facet~$\F$ and,
for $\btildeF$ as in~\eqref{C0-bubble-facet}, is given by
\begin{equation} \label{C1-bubble-facet}
    \bF:= \btildeF^2.
\end{equation}
In particular, this is a $\Ccal^1$ bubble
vanishing and with vanishing normal component
of the gradient over~$\partial\omegatildeF$.
We have \cite{Verfurth:2013}
the standard inverse estimates:
given $\Ecal$ as in~\eqref{extension-operator},
\begin{equation} \label{C1-bubble-facet-IE}
\begin{split}
& \Norm{\qp}{0,\F} 
    \lesssim \Norm{\bF^\frac12 \qp}{0,\F},
\qquad
\hF^2 \SemiNorm{\bF \Ecal(\qp)}{2,\T} 
+ \Norm{\bF \Ecal(\qp)}{0,\T} 
    \lesssim \hF^{\frac12} \Norm{\qp}{0,\F} ,\\
& \Norm{\partial_{\nuboldF} (\bF \Ecal(\qp))}{0,\F}
    \lesssim \hF^{-1} \Norm{\qp}{0,\F}
\qquad\qquad  \forall \qp \in P_\p(\F).
\end{split}
\end{equation}
The third one is less standard,
see \cite[Lemma 4.3]{Brenner-Gudi-Sung:2010}
and \cite[Lemma 6]{Carstense-Gallistl-Gedicke:2019},
and is defined on the patch~$\omegatildeF$ as in~\eqref{patches}.
Given $\Ecal$ as in \eqref{extension-operator} and
\begin{equation}\label{C1-bubble-facet*}
    \bstarF
    \text{ as in \cite[eq. (10)]{Carstense-Gallistl-Gedicke:2019}
    satisfying }
    \bstarF{}_{|\partial\omegaF}=0,
    \;
    \Norm{\qp}{0,\F} \lesssim \Norm{(\bstarF)^\frac12 \qp}{0,\F}
    \quad \forall \qp \in P_\p(\F),
\end{equation}
for all $\qp$ in $P_\p(\F)$,
there exists a function~$\wF=\wF(\qp)$
in $H^2_0(\omegatildeF) \subset H^2_0(\Omega)$
piecewise in $P_{\p+4}(\T)$,
$\T$ in $\omegatildeF$, depending on~$\bstarF$
such that
\small\begin{equation}\label{C1-bubble-facet*-IE-1}
\begin{split}
& \partial_{\nuboldF} \wF
    = \bstarF \Ecal(\qp)
    = \bstarF \qp \text{ on } \F, 
    \qquad
    \wF = 0 \text{ on } \F,
    \qquad
    \Norm{\wF}{0,\omegatildeF} + \hF^2\SemiNorm{\wF}{2,\omegatildeF}
    \lesssim \hF^\frac32 \Norm{\qp}{0,\F} .
\end{split}
\end{equation}





%%%%
\subsection{Upper and lower bounds of the conforming part of the error} 
\label{subsection:upper-lower-bound-T1}


\paragraph*{The upper bound.}
For all~$v$ in~$V$ with $\SemiNorm{v}{2,\Omega}=1$, we have
\small\[
\begin{split}
& (\Dtwo(u-s), \Dtwo v)_{0,\Omega}
 \overset{\eqref{definition:s}}{=}
 (\Dtwo u - \Hbbh, \Dtwo v)_{0,\Omega}
  \overset{\eqref{properties-GH:1}}{=}
    (\Dtwo u - \Hbbh, \Dtwo (v-\vI))_{0,\Omega} \\
& \overset{\eqref{Green-divdiv}}{=}
    \sum_{\T\in\tauh} (f-\div\divbf \Hbbh, v-\vI)_{0,\T}
    - \sum_{\F\in\FcalnI} (\nuboldF^T \jump{\Hbbh}, \nabla(v-\vI))_{0,\F}
    + \sum_{\F\in\FcalnI} (\nuboldF^T \jump{\divbf\Hbbh}, v-\vI)_{0,\F}\\
& \overset{\eqref{C1-vertices}}{=}
    \sum_{\T\in\tauh} (f-\div\divbf \Hbbh, v-\vI)_{0,\T}
    - \sum_{\F\in\FcalnI} (\nuboldF^T\jump{\Hbbh}\nuboldF,
    \nuboldF^T\nabla(v-\vI))_{0,\F} \\
& \qquad
    + \sum_{\F\in\FcalnI} (\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}, v-\vI)_{0,\F}.
\end{split}
\]\normalsize
Further using Cauchy-Schwarz' inequality
(first for integrals, then for sequences)
and the approximation properties~\eqref{interpolation:C1}
of $\mathcal C^1$ quasi-interpolants,
and recalling that $\SemiNorm{v}{2,\Omega}=1$
yield
\[
\begin{split}
(\Dtwo(u-s), \Dtwo v)_{0,\Omega}
& \lesssim  \Big[  \sum_{\T\in\tauh} \hT^4 \Norm{f-\div\divbf \Hbbh}{0,\T}^2
    + \sum_{\F\in\FcalnI} \Big( \hF \Norm{\nuboldF^T\jump{\Hbbh}\nuboldF}{0,\F}^2 \\
& \qquad     
    + \hF^3 \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F}^2 \Big)
    \Big]^\frac12 
    \overset{\eqref{local-error-estimator}}{\le}
    \eta.
\end{split}
\]

%%%%%%
\paragraph*{The lower bound.}
We begin with estimating the elemental terms.
Given $\bT$ as in~\eqref{C1-bubble-bulk}, we observe that
\[
\begin{split}
\Norm{\fh-\div\divbf \Hbbh}{0,\T}^2
& \lesssim (\fh-\div\divbf \Hbbh, \underbrace{\bT^2 (\fh-\div\divbf \Hbbh)}_{=:\wT})_{0,\T} \\
& \overset{\eqref{problem:weak}}{=} 
    (f-\fh,\wT)_{0,\T} + (\Dtwo u - \Hbbh, \Dtwo \wT)_{0,\T} \\
& \le \Norm{f-\fh}{0,\T} \Norm{\wT}{0,\T} +  \Norm{\Dtwo u - \Hbbh}{0,\T} \Norm{\Dtwo\wT}{0,\T}\\
& \overset{\eqref{C1-bubble-bulk-IE}}{\lesssim} 
    \Norm{f-\fh}{0,\T} \Norm{\wT}{0,\T} 
        + \Norm{\Dtwo u - \Hbbh}{0,\T} \hT^{-2} \Norm{\wT}{0,\T}\\
&   \overset{\eqref{C0-bubble-bulk}}{\le}
    (\Norm{f-\fh}{0,\T} + \hT^{-2} \Norm{\Dtwo u - \Hbbh}{0,\T})
        \Norm{\fh-\div\divbf \Hbbh}{0,\T}. 
\end{split}
\]
For all~$\T$ in~$\tauh$, we deduce
\[
\hT^2 \Norm{\fh-\div\divbf \Hbbh}{0,\T}
\lesssim \hT^2 \Norm{f-\fh}{0,\T} + \Norm{\Dtwo u - \Hbbh}{0,\T},
\]
and, by the triangle inequality,
\begin{equation} \label{lower-bound:c-bulk}
\hT^2 \Norm{f-\div\divbf \Hbbh}{0,\T}
\lesssim \hT^2 \Norm{f-\fh}{0,\T} + \Norm{\Dtwo u - \Hbbh}{0,\T} .
\end{equation}
Next, we focus on the normal-normal component term
appearing in~\eqref{local-error-estimator}.
% Observe that
% \[
% \hF^\frac12 \Norm{\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}}{0,\F}
% \lesssim \hT^2 \Norm{f-\fh}{0,\omegaF} 
%         + \Norm{\Dtwo u - \Hbbh}{0,\omegaF} .
% \]
Given $\Ecal$ and $\bstarF$ as in
\eqref{extension-operator} and~\eqref{C1-bubble-facet*}
(here $\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}$
plays the role of $\qp$), we write
\small\[
\begin{split}
& \Norm{\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}}{0,\F}^2
 \overset{\eqref{C1-bubble-facet*}}{\lesssim}
 (\bstarF\Ecal(\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}),
            \nubold_{\F}^T \jump{\Hbbh} \nubold_{\F})_{0,\F}
    \overset{\eqref{C1-bubble-facet*-IE-1}}{=}  (\partial_{\nuboldF} \wF,
            \nubold_{\F}^T \jump{\Hbbh} \nubold_{\F})_{0,\F}\\
& \overset{\eqref{C1-bubble-facet*}}{=}
    \sum_{j=1}^2 (\partial_{\nubold_{\Tj}} \wF,
            \nubold_{\Tj}^T \Hbbh \nubold_{\Tj})_{0,\partial\Tj} 
 \overset{\eqref{Green-divdiv}}{=}
        -(\divdivbf \Hbbh, \wF)_{0,\omegatildeF}
        + (\Hbbh, \Dtwo \wF)_{0,\omegatildeF} \\
& \overset{\eqref{problem:weak}}{=}
    -(\divdivbf \Hbbh - f, \wF)_{0,\omegatildeF}
        + (\Hbbh-\Dtwo u, \Dtwo \wF)_{0,\omegatildeF} \\
&   \overset{\eqref{C1-bubble-facet*-IE-1}}{\lesssim}
    \big(\hF^2\Norm{f-\divdivbf\Hbbh}{0,\omegatildeF}
    + \Norm{\Dtwo u - \Hbbh}{0,\omegatildeF} \big)
    \hF^{-\frac12} \Norm{\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}}{0,\F}.
\end{split}    
\] \normalsize
We simplify the display above into
\begin{equation} \label{bound:normal-normal}
\h^\frac12 \Norm{\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}}{0,\F}
\overset{\eqref{lower-bound:c-bulk}}{\lesssim}
    \hT^2 \Norm{f-\fh}{0,\omegatildeF} 
        + \Norm{\Dtwo u - \Hbbh}{0,\omegatildeF}.
\end{equation}
Finally, we handle the facet terms involving the normal component of the divergence
and the normal-tangential component of the generalized Hessian.
Let~$\F$ be shared by the elements~$\To$ and~$\Ttw$.
Given $\Ecal$ and $\bF$ as in
\eqref{extension-operator} and~\eqref{C1-bubble-facet}, we have
\small\[
\begin{split}
& \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F}^2\\
&  \overset{\eqref{C1-bubble-facet-IE}}{\lesssim}
    (\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh},
    \underbrace{\bF \Ecal(\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh})}_{=:\wF})_{0,\F}\\
&  \overset{\eqref{Green-divdiv}}{=}
    \sum_{j=1}^2 \Big[ -(\divdivbf \Hbbh, \wF)_{0,\Tj}
        + ( \Hbbh, \Dtwo \wF)_{0,\Tj} \\
&  \qquad\qquad -\sum_{\Ftilde \in\Fcal^{\Tj}} \sum_{\nu \in \mathcal V^{\Ftilde}}
                (\taubold_{\Tj}^T \Hbbh \nubold_{\Tj})(\nu) 
                    \underbrace{\wF(\nu)}_{=0}
    - \sum_{\Ftilde \in \Fcal^{\Tj}}
    (\nubold_{\Tj}^T \Hbbh \nubold_{\Tj},
    \underbrace{\partial_{\nubold_{\Tj}} \wF}_{=0 \text{ if $\Ftilde \ne \F$}})_{0,\Ftilde} \Big]    \\
& \overset{\eqref{problem:weak}}{=}
    (f - \divdivbfh \Hbbh, \wF)_{0,\omegaF}
    + (\Hbbh - \Dtwo u, \Dtwo \wF)_{0,\omegaF}
    + (\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F},
    \partial_{\nubold_{\F}} \wF)_{0,\F}
 =: S_1 + S_2 +S_3.
\end{split}
\] \normalsize
We estimate the three terms on the right-hand side separately.
As for the term~$S_1$, we write
\[
\begin{split}
S_1
& \le \Norm{f-\divdivbfh\Hbbh}{0,\omegaF} \Norm{\wF}{0,\omegaF}\\
& \overset{\eqref{C1-bubble-facet-IE}}{\lesssim}
    \Norm{f-\divdivbfh\Hbbh}{0,\omegaF}
    \hF^{\frac12} \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F} \\
& \overset{\eqref{lower-bound:c-bulk}}{\lesssim}
    \hF^{-\frac32} \big[ \hT^2 \Norm{f-\fh}{0,\omegaF}
                + \Norm{\Dtwo u - \Hbbh}{0,\omegaF} \big]
    \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F} .
\end{split}
\]
As for the term~$S_2$, we have
\small\[
\begin{split}
S_2
& \le \Norm{\Dtwo u - \Hbbh}{0,\omegaF} \Norm{\Dtwo \wF}{0,\omegaF} 
\overset{\eqref{C1-bubble-facet-IE}}{\lesssim}
    \hF^{-\frac32} \Norm{\Dtwo u - \Hbbh}{0,\omegaF}
          \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F} .
\end{split}
\]\normalsize
We now focus on the term~$S_3$:
\small\[
\begin{split}
S_3
& \le  \Norm{\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}}{0,\F}
        \Norm{\partial_{\nubold_{\F}} \wF}{0,\F}
\overset{\eqref{C1-bubble-facet-IE}}{\lesssim}
    \hF^{\frac12}\Norm{\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}}{0,\F}
            \hF^{-\frac32} \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F}.
\end{split}
\]\normalsize
Collecting the four displays above yields
\begin{equation} \label{lower-bound:c-facet-1}
\begin{split}
& \hF^{\frac32} \Norm{\partialtbfF(\tauboldF^T \jump{\Hbbh}\nuboldF)
    + \nuboldF^T \jump{\divbf\Hbbh}}{0,\F}\\
& \lesssim  \hT^2 \Norm{f-\fh}{0,\omegaF} 
    + \Norm{\Dtwo u - \Hbbh}{0,\omegaF} 
    + \hF^{\frac12}\Norm{\nubold_{\F}^T \jump{\Hbbh} \nubold_{\F}}{0,\F}\\
& \overset{\eqref{bound:normal-normal}}{\lesssim}
    \hT^2 \Norm{f-\fh}{0,\omegaF} 
    + \Norm{\Dtwo u - \Hbbh}{0,\omegaF} .
\end{split}
\end{equation}
The lower bound for the conforming part of the error is then
a consequence of~\eqref{lower-bound:c-bulk},
\eqref{bound:normal-normal},
and~\eqref{lower-bound:c-facet-1}.


%%%%
\subsection{Upper and lower bounds of the nonconforming part of the error}
\label{subsection:upper-lower-bound-T2}
%%%%%

\paragraph*{A right-inverse of the $\symcurlbold$ operator.}
There exists a stable right-inverse of the $\symcurlbold$ operator:
given~$\Bbb$ in $\Hbb(\divdivbf^{\zerobf},\Omega)$,
it is possible to construct~$\thetabold$ in~$\Hbf^1(\Omega)$
satisfying the following:
there exists a positive constant~$C_{\rm JG}$ only depending on the shape of~$\Omega$ such that
\begin{equation} \label{psibold-thetabold-relation}
\symcurlbold(\thetabold) = \Bbb,
\qquad\qquad\qquad\qquad
\Norm{\thetabold}{1,\Omega}
\le C_{\rm JG} \Norm{\Bbb}{0,\Omega}.
\end{equation}
We refer to Appendix~\ref{appendix:right-inverse} for a proof.

%%%%%%
\paragraph*{The upper bound.}
Using~\eqref{psibold-thetabold-relation}
with $\Bbb$ equal to $\symcurlbold \psibold$,
we pick~$\thetabold$ in $\Hbf^1(\Omega)$ as the $\symcurlbold$
right-inverse of $\symcurlbold \psibold$,
and given~$\thetaboldI$ the vector Cl\'ement quasi-interpolant
of~$\thetabold$ in $\Hbf^1(\Omega)$
as in~\eqref{Clement-qi},
we have
\[
\begin{split}
& (\Hbbh, \symcurlbold \psibold)_{0,\Omega}
   \overset{\eqref{psibold-thetabold-relation}}{=}
  (\Hbbh, \symcurlbold \thetabold)_{0,\Omega}\\
& \overset{\eqref{properties-GH:2}}{=}  
    (\Hbbh, \symcurlbold (\thetabold-\thetaboldI))_{0,\Omega}
    =  (\sym\Hbbh, \curlbold (\thetabold-\thetaboldI))_{0,\Omega}\\
& \overset{\eqref{Clement-qi}}{\lesssim}
    \Big[ \sum_{\T\in\tauh} \hT^2 \Norm{\curlsym\Hbbh}{0,\T}^2
    + \sum_{\F\in\Fcaln} \hF \Norm{\tauboldF^T \jump{\sym\Hbbh}}{0,\F}^2
        \Big]^\frac12 \SemiNorm{\thetabold}{1,\Omega} \\
& \overset{\eqref{psibold-thetabold-relation}}{\lesssim}     
    \Big[ \sum_{\T\in\tauh} \hT^2 \Norm{\curlsym\Hbbh}{0,\T}^2
    + \sum_{\F\in\Fcaln} \hF \Norm{\tauboldF^T \jump{\sym\Hbbh}}{0,\F}^2 \Big]^\frac12 
    \underbrace{\Norm{\symcurlbold \psibold}{0,\Omega}}_{=1}.
\end{split}
\]

%%%%%%
\paragraph*{The lower bound.}
We begin with estimating the elemental terms.
For all~$\T$ in~$\tauh$, given $\btildeT$ as in \eqref{C0-bubble-bulk},
we have
\[
\begin{split}
\Norm{\curlsym \Hbbh}{0,\T}^2
& \lesssim (\curlsym \Hbbh,
        \underbrace{\btildeT \curlsym \Hbbh}_{=:\wbfT})_{0,\T} 
    = (\curl (\sym\Hbbh-\Dtwo u), \wbfT )_{0,\T} \\
& = (\sym \Hbbh-\Dtwo u, \curlbold \wbfT)_{0,\T}
  \le \Norm{\Dtwo u - \Hbbh}{0,\T} \Norm{\curlbold \wbfT}{0,\T}.
\end{split}
\]
By noting that
\[
\Norm{\curlbold \wbfT}{0,\T}
\lesssim \SemiNorm{\wbfT}{1,\T}
\overset{\eqref{C0-bubble-bulk-IE}}{\lesssim}
    \hT^{-1}  \Norm{\curlsym \Hbbh}{0,\T},
\]
we deduce, for all elements~$\T$,
\begin{equation} \label{lower-bound:nc-bulk}
\hT  \Norm{\curlsym \Hbbh}{0,\T}
\lesssim  \Norm{\Dtwo u - \Hbbh}{0,\T}.
\end{equation}
%%%%%%
We now focus on the facet terms.
We focus on internal facets~$\F$
shared by the elements~$\To$ and~$\Ttw$;
the analysis for boundary facets is dealt with analogously.
Given $\Ecal$ and $\btildeF$ as in
\eqref{extension-operator} and \eqref{C0-bubble-facet},
we have
\[
\begin{split}
\Norm{\tauboldF^T \jump{\sym\Hbbh}}{0,\F}^2
& \overset{\eqref{C0-bubble-facet-IE}}{\lesssim}
    (\tauboldF^T \jump{\sym\Hbbh},
    \underbrace{\btildeF \Ecal(\tauboldF^T \jump{\sym\Hbbh})}_{=:\wbfF})_{0,\F} \\
& = \sum_{j=1}^2 \big[ (\curlsym \Hbbh, \wbfF)_{0,\Tj}
                        + (\sym \Hbbh, \curlbold \wbfF)_{0,\Tj} \big] \\
& = (\curlhsym \Hbbh, \wbfF)_{0,\omegatildeF}
                        + (\sym \Hbbh, \curlbold \wbfF)_{0,\omegatildeF}
  =: S_1 + S_2.
\end{split}
\]
We estimate the two terms on the right-hand side separately.
As for the term~$S_1$, we note that
\[
\begin{split}
S_1
& \lesssim  \hF \Norm{\curlhsym \Hbbh}{0,\omegaF} 
            \hF^{-1} \Norm{\wbfF}{0,\omegaF}  \\
& \overset{\eqref{C0-bubble-facet-IE}, \eqref{lower-bound:nc-bulk}}{\lesssim}
    \Norm{\Dtwo u - \Hbbh}{0,\T} \hF^{-\frac12} \Norm{\wbfF}{0,\F} 
  \le \Norm{\Dtwo u - \Hbbh}{0,\T} \hF^{-\frac12} \Norm{\tauboldF^T \jump{\sym\Hbbh}}{0,\F}.
\end{split}
\]
As for the term~$S_2$, using the fact that each column of~$\Dtwo u$ belongs
to~$\Hbf(\curlbold^{\zerobf},\Omega)$ and an integration by parts, we deduce
\[
\begin{split}
S_2
& = (\sym \Hbbh - \Dtwo u, \curlbold \wbfF)_{0,\omegaF}
  \le \Norm{\Dtwo u - \Hbbh}{0,\omegaF}  \Norm{\curlbold\wbfF}{0,\omegaF} \\
& \overset{\eqref{C0-bubble-facet-IE}}{\lesssim}
    \Norm{\Dtwo u - \Hbbh}{0,\omegaF} \hF^{-\frac12} \Norm{\wbfF}{0,\F} 
   \le \Norm{\Dtwo u - \Hbbh}{0,\omegaF} \hF^{-\frac12} \Norm{\tauboldF^T \jump{\sym\Hbbh}}{0,\F} .
\end{split}
\]
We combine the displays above and get
\begin{equation} \label{lower-bound:nc-facet}
\hF^{\frac12} \Norm{\tauboldF^T \jump{\sym\Hbbh}}{0,\F}
\lesssim \Norm{\Dtwo u - \Hbbh}{0,\omegaF}.
\end{equation}
The lower bound for the nonconforming part of the error
follows from~\eqref{lower-bound:nc-bulk}
and~\eqref{lower-bound:nc-facet}.


%%%%%
\subsection{Properties of the generalized Hessian}
\label{subsection:properties:GH}
%%%%%
Here, we prove
that the generalized Hessian in~\eqref{generalized:Hessian}
satisfies~\eqref{properties-GH:1} and~\eqref{properties-GH:2}.
Identity~\eqref{properties-GH:1}
is a consequence of the following computations:
for all $\wh$ in $\Vh\cap H^2_0(\Omega)$,
\[
\begin{split}
(\Hbbh(\uh), \Dtwo \wh)_{0,\Omega}
\overset{\eqref{generalized:Hessian}}{=}
    (\Dtwoh\uh + \Lbbh(\uh), \Dtwo \wh)_{0,\Omega}
  \overset{\wh\in H^2_0(\Omega),
        \eqref{IPDG-bilinear-form}}{=}
        \Bh(\uh,\wh)
    \overset{\wh\in\Vh, \eqref{method}}{=}
    (f,\wh).
\end{split}
\]
The proof of identity~\eqref{properties-GH:2}
is more involved and is intrinsically related
to the proof of Green's identity~\eqref{Green-divdiv}.
We shall be equivalently proving that, cf. \eqref{FE-divdiv-sequence},
\begin{equation} \label{equivalent-version-2nd-property}
(\Dtwoh \uh, \Abbh)_{0,\Omega}
= -(\Lbbh(\uh), \Abbh)_{0,\Omega},
\qquad\qquad
\Abbh = \symcurlbold\thetaboldh
\qquad
\forall \thetaboldh \in \VbfHoh.
\end{equation}
As for the left-hand side of~\eqref{equivalent-version-2nd-property},
we integrate by parts elementwise twice and get
\[
\begin{split}
(\Dtwoh \uh, \Abbh)_{0,\Omega}
= \sum_{\T \in \tauh}
    \big[ (\uh, \divdivbf \Abbh)_{0,\T}
         + (\nabla\uh, \Abbh \nuboldT)_{0,\partial\T}
         - (\uh, \nuboldT^T (\divbf\Abbh))_{0,\partial\T}   \big].
\end{split}
\]
The bulk terms vanish since $\divdivbf\Abbh=0$ over~$\Omega$.
Consider the decomposition into tangential and normal parts
\begin{equation} \label{normal-tangential:splitting}
\Abbh \nuboldT
= (\nuboldT^T\Abbh\nuboldT)\nuboldT
  + (\tauboldT^T\Abbh\nuboldT)\tauboldT
\end{equation}
This allows us to write
\small\[
(\Dtwoh \uh, \Abbh)_{0,\Omega}
= \sum_{\T \in \tauh}
    \big[ (\nuboldT^T \nabla\uh, \nuboldT^T\Abbh\nuboldT)_{0,\partial\T}
    + (\tauboldT^T \nabla\uh, \tauboldT^T\Abbh\nuboldT)_{0,\partial\T}
    - (\uh, \nuboldT^T (\divbf\Abbh))_{0,\partial\T}   \big] .
\]\normalsize
As for the second terms, we observe that
\[
(\tauboldT^T \nabla\uh, \tauboldT^T\Abbh\nuboldT)_{0,\partial\T}
= (\partialtbfOmega \uh, \tauboldT^T\Abbh\nuboldT)_{0,\partial\T}.
\]
With the notation as in~\eqref{Green-divdiv},
a tangential integration by parts on~$\partial\T$ gives
\[
(\tauboldT^T \nabla\uh, \tauboldT^T\Abbh\nuboldT)_{0,\partial\T}
= - (\uh, \partialtbfT (\tauboldT^T\Abbh\nuboldT))_{0,\partial\T}
   + \sum_{\F \in \Fcaln}  \sum_{\nu \in \VcalF}
    \sign_{\F,\nu} \uh(\nu) (\tauboldT^T \Abbh \nuboldT)(\nu) .
\]
Overall, we get
\begin{equation} \label{identities-Dtwouh}
\begin{split}
(\Dtwoh \uh, \Abbh)_{0,\Omega}
& = \sum_{\T \in \tauh}
    \big[ (\nuboldT^T \nabla\uh, \nuboldT^T\Abbh\nuboldT)_{0,\partial\T}
    - (\uh, \nuboldT^T \divbf\Abbh
    + \partialtbfT( \tauboldT^T \Abbh \nuboldT))_{0,\partial\T} \big] \\
& \quad + \sum_{\F \in \Fcaln}  \sum_{\nu \in \VcalF}
    \sign_{\F,\nu} \uh(\nu) (\tauboldF^T \Abbh \nuboldF)(\nu).
\end{split}
\end{equation}
We focus on the term on the
right-hand side of~\eqref{equivalent-version-2nd-property}.
The definition of the lifting operator in~\eqref{lifting}
and the splitting in~\eqref{normal-tangential:splitting} imply
\small\[
\begin{split}
& (\Lbbh(\uh), \Abbh)_{0,\Omega} \\
& = \Big(\jump{\uh}, 
    \average{\nuboldF^T \divbf \Abbh}\Big)_{0,\Fcaln}
  - \big(\jump{\nabla \uh}, 
    \average{\Abbh \nuboldF} \big)_{0,\Fcaln} \\
& = \Big( \jump{\uh}, 
    \average{\nuboldF^T \divbf \Abbh} \Big)_{0,\Fcaln}
  - \Big( \jump{\nuboldF^T \nabla \uh}, 
    \average{\nuboldF^T\Abbh \nuboldF} \Big)_{0,\Fcaln}
  - \Big( \jump{\tauboldF^T \nabla \uh}, 
    \average{\tauboldF^T\Abbh \nuboldF} \Big)_{0,\Fcaln}.
\end{split}
\] \normalsize
The continuity of~$\nuboldF^T\Abbh \nuboldF$ through facets,
cf. the $H(\divdivbf)$ conformity of $\Abbh$
discussed in Remark~\ref{remark:divdiv-conformity}, implies
\[
\begin{split}
 (\Lbbh(\uh), \Abbh)_{0,\Omega} 
& = \big( \jump{\uh}, 
    \average{\nuboldF^T \divbf \Abbh} \big)_{0,\Fcaln}
    - \big(\jump{\nuboldF^T \nabla \uh}, 
    \nuboldF^T\Abbh \nuboldF \big)_{0,\Fcaln} \\
& \quad  - \big( \jump{\tauboldF^T \nabla \uh}, 
    \average{\tauboldF^T\Abbh \nuboldF} \big)_{0,\Fcaln}.
\end{split}
\]
We rewrite the last term on the right-hand side,
also using an integration by parts on the boundaries
of the elements and standard DG manipulations, as
\[
\begin{split}
& - (\jump{\tauboldF^T \nabla \uh}, 
    \average{\tauboldF^T\Abbh \nuboldF})_{0,\Fcaln} 
= - (\jump{\partialtbfF \uh}, 
    \average{\tauboldF^T\Abbh \nuboldF})_{0,\Fcaln}\\
& = (\jump{\uh}, 
    \average{\partialtbfF  (\tauboldF^T\Abbh \nuboldF)})_{0,\Fcaln}
    - \sum_{\F \in \Fcaln}  \sum_{\nu \in \VcalF}
    \sign_{\F,\nu} \uh(\nu) (\tauboldF^T \Abbh \nuboldF)(\nu).
\end{split}
\]
Combining the above displays yields
\[
\begin{split}
(\Lbbh(\uh), \Abbh)_{0,\Omega}
& = (\jump{\uh}, 
    \average{\nuboldF^T \divbf \Abbh
            + \partialtbfF  (\tauboldF^T\Abbh \nuboldF)})_{0,\Fcaln} \\
& \quad 
    - (\jump{\nuboldF^T \nabla \uh}, 
    \nuboldF^T\Abbh \nuboldF)_{0,\Fcaln} 
    - \sum_{\F \in \Fcaln}  \sum_{\nu \in \VcalF}
    \sign_{\F,\nu} \uh(\nu) (\tauboldF^T \Abbh \nuboldF)(\nu).
\end{split}
\]
The continuity of~$\nuboldF^T \divbf \Abbh
+ \partialtbfF  (\tauboldF^T\Abbh \nuboldF)$ through facets,
cf. the $H(\divdivbf)$ conformity of~$\Abbh$
discussed in Remark~\ref{remark:divdiv-conformity}, implies
\begin{equation} \label{identities-Lcalh}
\begin{split}
-(\Lbbh(\uh), \Abbh)_{0,\Omega}
& = - (\jump{\uh}, 
    \nuboldF^T \divbf \Abbh
            + \partialtbfF  (\tauboldF^T\Abbh \nuboldF))_{0,\Fcaln} \\
& \quad 
    + (\jump{\nuboldF^T \nabla \uh}, 
    \nuboldF^T\Abbh \nuboldF)_{0,\Fcaln} 
    + \sum_{\F \in \Fcaln}  \sum_{\nu \in \VcalF}
    \sign_{\F,\nu} (\tauboldF^T \Abbh \nuboldF)(\nu) \uh(\nu).
\end{split}
\end{equation}
Up to rewriting the sum over the facets
as sums over the boundary of elements,
the right-hand sides in~\eqref{identities-Dtwouh} and~\eqref{identities-Lcalh}
coincide.
Identity~\eqref{equivalent-version-2nd-property}
and thus also~\eqref{properties-GH:2} follow.

