\section{Numerical results} \label{section:nr}
%%%%%%%%%%%%%%%%%%%%%%%%


%%%%%
\paragraph*{Test cases.}
The first test case,
cf. with \cite[pp. 107--108]{Grisvard:1992},
is set on the L-shaped domain
$\Omega_1:= (-1,1)^2 \setminus ( [0,1) \times (-1,0] )$
with exact solution
\begin{equation} \label{u1}
u_1(r,\theta) = r^{1+z} g(\theta),
\end{equation}
where $(r,\theta)$ are the polar coordinates at the
re-entrant corner $(0,0)$,
$z=0.544483736782464$,
and, for $\omega=3\pi/2$,
\[
\begin{split}
g(\theta)
& := \Big[ \frac{1}{1-z} \sin( (z-1) \omega)
            - \frac{1}{z+1} \sin( (z+1)\omega) \Big]
            \cos( (z-1)\theta) - \cos( (z+1)\theta)\\
&   \qquad -\Big[ \frac{1}{1-z} \sin( (z-1) \theta)
            - \frac{1}{z+1} \sin( (z+1)\theta) \Big]
            \cos( (z-1)\omega) - \cos( (z+1)\omega) .
\end{split}
\]
The function~$u_1$ has inhomogeneous clamped boundary
conditions on part of~$\partial \Omega_1$
(it has effectively homogeneous boundary
conditions on the two edges at the re-entrant corner);
we refer to the next paragraph for further discussions
on this aspect.

The second test case is set on the unit square domain $\Omega_2=(0,1)^2$ with exact solution
\begin{equation} \label{u2}
    u_2(x,y) = \sin^2(\pi \ x) \sin^2(\pi \ y).
\end{equation}

%%%%%
\paragraph*{Handling inhomogeneous boundary conditions.}
The analysis discussed so far considered
the biharmonic problem with homogeneous 
clamped boundary conditions.
The inhomogeneous case follows closely the presentation
of the previous sections.
For the sake of completeness, we sketch
here some details on the inhomogeneous boundary conditions
\[
u=g_1,
\qquad\qquad\qquad\qquad\qquad
\partialnbfOmega u = g_2
\qquad\qquad\qquad \text{on } \partial\Omega.
\]
Formal computations reveal that
\begin{equation} \label{formal-computations}
\begin{split}
\taubfOmega^T \Dtwo u_{|\partial\Omega}
&   = \partialtbfOmega (\nabla u_{|\partial\Omega} )
    = \partialtbfOmega ( (\partialtbfOmega g_1)\tauboldOmega
                        + g_2 \nuboldOmega)
    = (\partialtwotbfOmegatwo g_1)\tauboldOmega
            + (\partialtbfOmega g_2) \nuboldOmega,\\
\nabla u_{|\partial\Omega}
&   = (\nuboldOmega^T \nabla u_{|\partial\Omega}) \nuboldF
        + (\tauboldOmega^T \nabla u_{|\partial\Omega}) \tauboldOmega
    =  g_2 \nuboldOmega + (\partialtbfOmega g_1)\tauboldOmega. \\
\end{split}
\end{equation}
For the definition of the lifting
operators~\eqref{lifting},
the jump operators on boundary facets
modify into
\[
\jump{\uh}_{\F} = \uh{}_{|\F} - g_1,
\qquad\qquad\qquad\qquad
\jump{\nabla \uh} _\F
\overset{\eqref{formal-computations}}{=}
\nabla \uh{}_{|\F} - [g_2 \nuboldOmega + (\partialtbfOmega g_1)\tauboldOmega].
\]
Identity~\eqref{properties-GH:2} holds true only
up to some terms involving the boundary data
that eventually modifies
the local error estimator in~\eqref{local-error-estimator},
and notably the term $\eta_{5,\T}$, which
on boundary facets~$\F$ in $\EcalT$ now reads
\begin{equation} \label{jump:sym-GH}
\tauboldOmega^T \jump{\sym\Hbbhuh}_{\F}
= (\taubfOmega^T \sym\Hbbhuh 
    - (\partialtwotbfOmegatwo g_1)\tauboldOmega
    - (\partialtbfOmega g_2) \nuboldOmega)_{|\F} .
\end{equation}
The reason for this resides in the fact that
identity~\eqref{T2-as-sup}
is not true any more.
In particular, we have
\[
\begin{split}
& (\Dtwo u, \symcurlbold \thetabold)_{0,\Omega}
    = (\Dtwo u, \curlbold \thetabold)_{0,\Omega}
    = (\nabla u, \curlbold\thetabold \cdot
                \nuboldOmega)_{0,\partial\Omega}
    = (\nabla u, \nabla\thetabold \cdot
                \tauboldOmega)_{0,\partial\Omega} \\
&   \overset{\eqref{formal-computations}}{=}
    ((\partialtbfOmega g_1)\tauboldOmega
    + g_2 \nuboldOmega ,
        \partialtbfOmega \thetabold)_{0,\partial\Omega}
    = - ((\partialtwotbfOmegatwo g_1) \tauboldOmega, \thetabold)_{0,\partial\Omega}
        - ( (\partialtbfOmega g_2) \nuboldOmega,
        \thetabold)_{0,\partial\Omega},
\end{split}
\]
which is different from zero in general
(while it was zero for homogeneous
boundary conditions).
In fact, the discrete counterpart
of the above identities holds,
whence~\eqref{properties-GH:2}
is not valid in general,
but should involve the boundary data
on the right-hand side
with an arbitrary test function $\thetaboldh$.
This reasoning eventually combines with the estimates
in Section~\ref{subsection:upper-lower-bound-T2}
and yields~\eqref{jump:sym-GH}.

%%%
\paragraph*{Outline of the remainder of the section.}
In Section~\ref{subsection:nr-2error-measures},
we compare the performance of the error measure
on the left-hand side of~\eqref{rewriting-in-terms-of-max}
with the standard DG error under uniform refinements
and for different orders.
We investigate the practical efficiency of the error
estimators in~\eqref{global-error-estimator}
and the standard DG-residual error estimator
under uniform $\h$- and $\p$-refinements
in Section~\ref{subsection:nr-effectivity-h}.
Section~\ref{subsection:nr-adaptive} is devoted
to introduce an adaptive algorithm driven
by the error estimator in~\eqref{global-error-estimator}
and investigate its performance.
In~\eqref{IPDG-bilinear-form}, we shall always consider
\[
\csigma = 3 \p^6,
\qquad\qquad\qquad
\ctau   = 9 \p^2.
\]
Moreover, in the local estimators
\eqref{error-estimator} and~\eqref{DG-error-estimator},
we replace $\h^{\lambda}$,
$\lambda$ in $\mathbb Z$,
with $\h^{\lambda}/\p^{\lambda}$;
this poses no modifications
in the analysis and gives a more reasonable
scaling in terms of the degree of the scheme.


