\section{Regularized right-inverse of the $\symcurlbold$ operator}
\label{appendix:right-inverse}
%%%%
Define
\[
\Hbb(\divbf^{\zerobf},\Omega)
:= \{ \Bbb \in \Lbb^2(\Omega) \mid \divbf \Bbb = \zerobf \}.
\]
Recall the following two estimates
from \cite[Theorem 4.9]{Costabel-McIntosh:2010}
(with $s=-1$, and $s=0$ row-wise).
There exists positive constants
$C_1(\Omega)$ and $C_2(\Omega)$ only depending on~$\Omega$
such that, for all $\taubf$ in $\Hbf^{-1}(\Omega)$ with $\div \taubf = 0$
and for all~$\Bbb$ in $\Hbb(\divbf^{\zerobf},\Omega)$,
it is possible to construct $\omega$ in $L^2(\Omega)$
and~$\thetabold$ in $\Hbf^1(\Omega)$ satisfying
\begin{equation} \label{eq_curl_m1}
\curlbold \omega = \taubf,
\qquad\qquad
\|\omega\|_{0,\Omega} \leq C_1(\Omega) \|\taubf\|_{-1,\Omega},
\end{equation}
and
\begin{equation} \label{eq_curl_L2}
\curlbold\thetabold = \Bbb,
\qquad\qquad\qquad
|\thetabold|_{1,\Omega} \leq C_2(\Omega)\|\Bbb\|_{0,\Omega}.
\end{equation}
We are in a position to prove the following result.
%%%%%
\begin{theorem}[Regularized right-inverse of the $\symcurlbold$ operator]
The $\symcurlbold$ operator admits a stable right-inverse.
More precisely, given $C_1(\Omega)$ and~$C_2(\Omega)$
as in~\eqref{eq_curl_m1} and~\eqref{eq_curl_L2},
for all~$\Abb$ in $\Hbb_{\Sbb} (\divdivbf^{\zerobf},\Omega)$,
it is possible to construct~$\thetabold$ in $\Hbf^1(\Omega)$ satisfying
\begin{equation}
\symcurlbold\thetabold = \Abb,
\qquad\qquad\qquad
|\thetabold|_{1,\Omega}
\leq    C_2(\Omega)\big( 1 + 2 C_1(\Omega) \big) 
        \|\Abb\|_{0,\Omega}.
\end{equation}
\end{theorem}
%%%
\begin{proof}
Any $\Abb$ in $\Hbb_{\Sbb}(\divdivbf^{\zerobf},\Omega)$
is such that $\divbf \Abb$ is divergence free,
and
\begin{equation} \label{eq_Abb_m1}
\divbf \Abb \in \Hbf^{-1}(\Omega),
\qquad\qquad\qquad
\|\divbf \Abb\|_{-1,\Omega}
    \leq \|\Abb\|_{0,\Omega}.
\end{equation}
We invoke~\eqref{eq_curl_m1}, giving the existence
of~$\omega$ in~$L^2(\Omega)$ such that
\begin{equation} \label{tmp_omega_L2}
\curlbold \omega = \divbf \Abb,
\qquad\qquad\qquad
\|\omega\|_{0,\Omega}
\overset{\eqref{eq_curl_m1}}{\leq}
    C_1(\Omega) \|\divbf \Abb\|_{-1,\Omega}
\overset{\eqref{eq_Abb_m1}}{\leq}
    C_1(\Omega) \|\Abb\|_{0,\Omega}.
\end{equation}\normalsize
Consider the skew-symmetric matrix
\begin{equation} \label{eq_Obb-Abb}
\Obb := \left (
\begin{array}{cc}
0       & \omega \\
-\omega & 0
\end{array}
\right ) \in \Lbb^2(\Omega),
\qquad\qquad\qquad
\Norm{\Obb}{0,\Omega}
\le 2 \Norm{\omega}{0,\Omega}
\overset{\eqref{tmp_omega_L2}}{\le} 2 C_1(\Omega) \Norm{\Abb}{0,\Omega} ,
\end{equation}
and observe that $\divbf \Obb = \curlbold \omega = \divbf \Abb$.
We readily deduce that~$\Abb-\Obb$ belongs to~$\Hbb(\divbf^{\zerobf},\Omega)$.

We invoke~\eqref{eq_curl_L2}, giving the existence
of~$\thetabold$ in $\Hbf^1(\Omega)$ such that
\begin{equation*}
\curlbold \thetabold = \Abb-\Obb,
\qquad\qquad\qquad
|\thetabold|_{1,\Omega}
\overset{\eqref{eq_curl_L2}}{\le}
    C_2(\Omega) \|\Abb-\Obb\|_{0,\Omega}
\overset{\eqref{eq_Obb-Abb}}{\le}
    C_2(\Omega)\big( 1 + 2 C_1(\Omega) \big) \|\Abb\|_{0,\Omega}.
\end{equation*}
Since~$\Abb$ is symmetric and~$\Obb$ is skew-symmetric,
$\symcurlbold\thetabold = \sym(\Abb-\Obb) = \Abb$.
\end{proof}

