        % set A
        \draw[line width=1pt] (-0.8,0.8) circle (1) node[shift={(-6pt,6pt)}, anchor=center, align=center] {$A:$ \\ $1001\!\rightarrow$};
        % set B
        \draw[line width=1pt] (0.8,0.8) circle (1) node[shift={(6pt,6pt)}, anchor=center, align=center] {$B:$ \\ $\leftarrow\!0110$};
        % set C
        \draw[line width=1pt] (0.8,-0.8) circle (1) node[shift={(6pt,-3pt)}, anchor=center, align=center] {$C:$ \\ $0110\!\rightarrow$};
        % set D
        \draw[line width=1pt] (-0.8,-0.8) circle (1) node[shift={(-6pt,-3pt)}, anchor=center, align=center] {$D:$ \\ $\leftarrow\!1001$};
        % Hatch the intersection of A and B
        \begin{scope}
            \clip (-0.8,0.8) circle (1);
            \fill[pattern=north east lines] (0.8,0.8) circle (1);
        \end{scope}
        % Hatch the intersection of C and D
        \begin{scope}
            \clip (-0.8,-0.8) circle (1);
            \fill[pattern=north east lines] (0.8,-0.8) circle (1);
        \end{scope}
        % Hatch the intersection of A and D
        \begin{scope}
            \clip (-0.8,-0.8) circle (1);
            \fill[pattern=north east lines] (-0.8,0.8) circle (1);
        \end{scope}
        % Hatch the intersection of B and C
        \begin{scope}
