\section{Counting decoherence-free states in the unfragmented case}
\label{app:unfragmented_DFS}

For a given particle number $N$, the dipole moment $D$ is minimum for the state $1 \dots 1 0 \dots 0$ and increases in steps of $1$ as we move each particle $L-N$ sites to the right, one at a time. Hence, the number of distinct $(N, D)$ sectors is given by $N_{\text{sector}} = \sum_{N=0}^L 1 + N(L-N) = (L^3 + 5L + 6)/6$.

The number of disjoint DFSs can be found by counting configurations of the type in Eq.~\eqref{eq:DFS_root} with $p \leq N-1$ that can fit in $L$ sites, i.e., $N+p+1 \leq L$. Thus,
\begin{equation}
    N_{\text{DFS}} 
    = \sum_{N=1}^{L-1} \sum_{p = 0}^{\text{min}(N,L-N)-1} 1 
    = \left\lfloor \frac{L^2}{4} \right\rfloor \;.
\end{equation}

As shown in Eqs.~\eqref{eq:partition_1} and \eqref{eq:partition_2}, the size of a DFS is given by the number of integer partitions of $p$, denoted by $d_p$. Hence, the total count of all decoherence-free states amounts to
\begin{equation}
    d_{\text{DFS}} 
    = \sum_{N=1}^{L-1} \sum_{p = 0}^{\text{min}(N,L-N)-1} d_p 
    = \sum_{p=0}^{\lfloor L/2 \rfloor -1} \sum_{N=p+1}^{L-p-1} d_p
    = \sum_{p=0}^{\lfloor L/2 \rfloor -1} (L-2p-1) d_p \;.
\end{equation}
Using $d_p \sim \exp(\pi\sqrt{2p/3}) / (4\sqrt{3}p)$ for $p \gg 1$ \cite{Andrews_1984_paritions}, we find
\begin{equation}
    d_{\text{DFS}} \sim 
    \int_1^{L/2} {\rm d}p \;(L-2p) \frac{e^{\pi\sqrt{2p/3}}}{4\sqrt{3}p} 
    = F(L) - F(2) \;,
\end{equation}
where 
\begin{equation}
    F(x) \coloneqq 
    \frac{L}{2\sqrt{3}} \text{ Ei} \bigg(\pi \sqrt{\frac{x}{3}} \bigg) 
    - e^{\pi \sqrt{x/3}} \bigg( \frac{\sqrt{x}}{2\pi} - \frac{\sqrt{3}}{2\pi^2} \bigg) \;
\end{equation}
and Ei is the exponential integral function \cite{Book_NIST}. Using the asymptotic expansion
\begin{equation}
    \text{Ei}(x) \sim \frac{e^x}{x} \left(1 + \frac{1!}{x} + \frac{2!}{x^2} + \cdots \right)
\end{equation}
gives the scaling
\begin{equation}
    d_{\text{DFS}} \sim \frac{\sqrt{3}}{\pi^2} e^{\pi \sqrt{L/3}} \left[ 1 + \frac{\sqrt{3}}{\pi \sqrt{L}} + O\left(\frac{1}{L}\right) \right] \;.
\end{equation}

\section{Counting decoherence-free states in the fragmented case}
\label{app:fragmented_DFS}

First we count the $1001$ family given by the configurations in Eq.~\eqref{eq:1001_family}. The lead sequence of such a state can be labeled the number of collective spins, $n \geq 2$, and the number of domain walls of the form $\Uparrow 0 \Downarrow$ and $\Downarrow 1 \Uparrow$, $k \leq n-2$. For a finite system they also satisfy $2n+k \leq L-1$. There are $\binom{n-2}{k}$ ways of placing the domain walls and $2^{L-1-2n-k}$ arrangements of the sites in the box for a given lead sequence [see Eq.~\eqref{eq:1001_family}]. Hence, the total number of states is given by
\begin{equation}
    N_{1001} = 
    \sum_{n=2}^{\lfloor (L-1)/2 \rfloor} \;
    \sum_{k=0}^{\min(n-2, L-1-2n)} 
    \binom{n-2}{k} \; 2^{L-1-2n-k}
    \; \approx \frac{2^{L-2}}{5} \;.
    \label{eq:N_1001}
\end{equation}
For odd values of $L \geq 7$, one has to add states for which the lead sequence spans the lattice, ending with $0110$. These have an odd number of domain walls that can placed in $(L-k)/2-2$ positions, yielding a total count of approximately $0.13 \times 1.32^L$.

Next we turn to the $0110$ family, for which the last site can eventually flip from $0$ to $1$. Like the $1001$ family, the states are generated by recursively applying the expansion rules
\begin{equation}
    \begin{minipage}{0.8\textwidth}
    \centering
    \begin{tikzpicture}
        % First graph
        \node at (-2,0) (label1) {$\underline{01}$};
        \node at (-3,-1) (nodeA1) {$\underline{01}10$};
        \node at (-1,-1) (nodeB1) {$\underline{10}011$};

        \draw[->, line width=1pt] (label1) -- (nodeA1);
        \draw[->, line width=1pt] (label1) -- (nodeB1);

        % Second graph
        \node at (2,0) (label2) {$\underline{10}$};
        \node at (1,-1) (nodeA2) {$\underline{10}01$};
        \node at (3,-1) (nodeB2) {$\underline{01}100$};

        \draw[->, line width=1pt] (label2) -- (nodeA2);
        \draw[->, line width=1pt] (label2) -- (nodeB2);
    \end{tikzpicture}
    \end{minipage}
    \label{eq:expand_left}
\end{equation}
to the leftmost two digits (underlined), which leads to the form
\begin{subequations}
\begin{align}
    1 \; \fbox{\phantom{Arbitrary}} \;
    {\color{red}\Uparrow \Downarrow} \dots \Downarrow 1 
    \cdots \; \cdots 
    0 \Downarrow \dots \Downarrow 
    1 \Uparrow \dots \Uparrow 
    0 \Downarrow \dots \Downarrow 
    1 \Uparrow \dots \Uparrow & 
    \label{eq:0110_family_1} \\[2pt]
    \text{or} \quad 
    1 \; \fbox{\phantom{Arbitrary}} \;
    {\color{red}\Downarrow \Uparrow} \dots \Uparrow 0 
    \cdots \; \cdots 
    0 \Downarrow \dots \Downarrow 
    1 \Uparrow \dots \Uparrow 
    0 \Downarrow \dots \Downarrow 
    1 \Uparrow \dots \Uparrow & \;, 
    \label{eq:0110_family_2}
\end{align}
\label{eq:0110_family}
\end{subequations}
By symmetry the two families have equal size, $N_{0110} = N_{1001} \approx 2^{L-2}/5$ [see Fig.~\ref{fig:dfs_count}(a)].

\begin{figure}[!b]
    \centering
    \includegraphics[width=1\columnwidth]{Fig3_DFS-Count.pdf}
    \caption{\label{fig:dfs_count}(a) Number of states in the $1001$ family, having configurations of the form in Eq.~\eqref{eq:1001_family} for which the first site can flip from $1$ to $0$ through a sequence of swaps between $1001$ to $0110$. (b) Number of states of the form in Eq.~\eqref{eq:nonoverlapping_states}, for which both the first site and the last site can flip from $1$ and $0$, respectively. (c) Number of such unstable states for which the lead sequences on either side overlap, in comparison. 
    }
\end{figure}

The number of states shared between the two is dominated by configurations of the form
\begin{equation}
    \Uparrow \dots \Uparrow 
    0 \Downarrow \dots \Downarrow 
    1 \cdots \; \cdots 
    {\color{red}\Uparrow \Downarrow} \; 
    \fbox{\phantom{Arbitrary sequence}} \;
    {\color{red}\Downarrow \Uparrow} 
    \cdots \; \cdots 
    0 \Downarrow \dots \Downarrow 
    1 \Uparrow \dots \Uparrow \;,
    \label{eq:nonoverlapping_states}
\end{equation}
where the lead sequences do not overlap. Labeling the number of collective spins in these two sequences by $m$ and $n$, and the number of domain walls by $p$ and $q$, we find [as in Eq.~\eqref{eq:N_1001}]
\begin{equation}
    N_{1001 \cap 0110}^{\text{no-overlap}} = 
    \underset{2(m+n)+p+q \leq L}{
    \sum_{m,n \geq 2} \;
    \sum_{p=0}^{m-2} \;
    \sum_{q=0}^{n-2}
    } \;\;
    \binom{m-2}{p} \binom{n-2}{q} \;
    2^{L-2(m+n)-p-q} \;
    \approx \frac{2^{L-2}}{25} \;.
\end{equation}

For the other shared states, the lead sequences overlap by at most $4$ sites. This is because the patterns $1001$ and $0110$ only appear at the active edges (red collective spins). As we show in Fig.~\ref{fig:dfs_count}(c), this overlapping set is exponentially small compared to the non-overlapping set. Hence, the total size of the two families can be estimated as
\begin{equation}
    N_{1001 \cup 0110} \approx 
    N_{1001} + N_{0110} - N_{1001 \cap 0110}^{\text{no-overlap}} 
    \approx (9/25) \; 2^{L-2} \;.
\end{equation}


