\begin{document}

\begin{abstract}
We consider the filtering and smoothing problems for an infinite-dimensional diffusion process $X$, observed through a finite-dimensional representation at discrete points in time. 
At the heart of our proposed methodology lies the construction of a path measure, termed the guided distribution of $X$, that is absolutely continuous with respect to the law of $X$, conditioned on the observations. 
We show that this distribution can be incorporated as a potent proposal measure for both sequential Monte Carlo as well as Markov Chain Monte Carlo schemes to tackle the filtering and smoothing problems respectively. 
In the offline setting, we extend our approach to incorporate parameter estimation of unknown model parameters. % 
The proposed methodology is numerically illustrated in a case study for the stochastic Amari equation. 
\end{abstract}
\keywords{Data assimilation; Doob's h-transform; Exponential change of measure; Guided particle filter; 
Infinite-dimensional diffusions; Markov chain Monte Carlo; Parameter estimation; Smoothing; Stochastic Amari equation; Stochastic partial differential equations}

\maketitle

\section{Introduction}
Consider an \textit{infinite-dimensional diffusion} equation of the form
\begin{equation}\label{eq: dXt} 
\begin{cases}
\df X_t &= \left[ A X_t + F(t, X_t) \right] \df t + Q^{\frac12} \df W_t, \quad  t \geq 0,\\ 
 \quad X_0 &\sim \mu_0.
\end{cases}
\end{equation}
Here, $A$ denotes the generator of a strongly continuous semigroup $(S_t)_{t \geq 0}$ on a Hilbert space $H$, whereas $F$ is a Lipschitz continuous non-linearity and $Q$ a symmetric, positive operator of trace class on $H$. The process $(W_t)_{t \geq 0}$ is a cylindrical Wiener process on $H$, defined on a stochastic basis $(\Omega, \calF, (\calF_t)_{t \geq 0},\P)$ and $\mu_0$ denotes a Borel measure on $H$.
Infinite-dimensional diffusions like that of \cref{eq: dXt} arise, for example, in the context of semilinear stochastic partial differential equations or stochastic field equations.

Throughout this work, we assume that \cref{eq: dXt} admits a unique mild solution $X$ satisfying
\begin{align}
\label{eq: Xt}
X_t &= S_t X_0 + \int_0^t S_{t-s} F(s, X_s) \df s + \int_0^t S_{t-s} Q^{\frac12} \df W_s.
\end{align}
The process $X$ is an $H$-valued, predictable Markov process with transition kernel $(\mu_{s,t})_{s \leq t}$ defined by $\mu_{s,t}(x,B) := \P(X_t \in B \mid X_s = x)$ for all Borel sets $B \subset H$ and $x \in H$.

Suppose at discrete observation times $0 < t_1 < t_2 < \ldots < t_n = T$, we are given \textit{finite-dimensional observations} $y_i$ through realisations $Y_i = y_i$ of 
\begin{align}
\label{eq: def_Y}
    Y_i \mid X_{\ti} &\sim k_i(X_{\ti}, \cdot), \quad i = 1, \ldots, n.
\end{align}
Here, $k_i(X_{\ti}, \cdot)$ denotes a conditional density on $\R^{m_i}$, where $m_i$ is the dimension of the observation at time $t_i$. 
For the sake of convenience, we assume from now on that
\begin{align}
\label{eq: def_Y2}
    Y_i \mid X_{\ti} \sim f(\cdot; L X_{\ti}, \Sigma), \quad i = 1, \ldots, n,
\end{align}
where $L: H \to \R^m$ is a bounded linear operator, termed the \textit{observation operator}, $\Sigma$ is a positive-definite matrix and $f(\cdot; Lx, \Sigma)$ is the Gaussian density with mean $Lx$ and covariance $\Sigma$.
However, our methods generalise to non-Gaussian observation densities and we will discuss how to adapt to such cases towards the end of the paper.


Based on the described setup, we address three estimation problems. 
Firstly, we are concerned with \textit{state estimation} of the unobserved, latent path $X$. 
Here, we consider both the \textit{online} problem of estimating the \textit{filtering} distribution 
\begin{align}
\label{eq: def_filtering}
    \P(X_{\ti} \in B \mid Y_1, \ldots, Y_i), \quad i = 1, \ldots, n,
\end{align}
and as well as the \textit{offline} problem of estimating the \textit{smoothing} distribution
\begin{align}
\label{eq: def_smoothing}
    \P(X_{t} \in B \mid Y_1, \ldots, Y_n), \quad t \in [0,T],
\end{align}
for any Borel set $B \subset H$.
Moreover, if \cref{eq: dXt} is parametrised by some unknown model parameters $\theta \in \R^p$, we are interested in \textit{parameter estimation} of $\theta$ in the offline setting. 


\subsection{Approach}
\label{sec: approach}
Our approach relies heavily on the exponential changes of measure studied in \cite{Piepersethmacher2025Class}.
Consider for now the case that $n=1$, i.e. we observe one realisation $y$ of the random variable $Y \mid X_T \sim k(X_T, \cdot)$. In this simplified case, estimating the conditional distribution of $X$ given $Y = y$ solves both the filtering as well as the smoothing problem. 

It is well-known that this conditional distribution can be derived by a change of measure known as \textit{Doob's h-transform} as follows. Defining for any fixed $y \in \R^{m}$ the likelihood function 
\begin{align*}
%\label{eq: def_h}
h(t,x) &= \int_H k(z,y) \mu_{t,T}(x, \df z), \quad t \in [0,T], x \in H,
\end{align*}
one shows that the process $(h(t,X_t))_{t \in [0,T]}$ is a non-negative $\P$-martingale and hence defines a unique change of measure $\P^h$ on $\calF_T$ by 
\begin{align*}
%\label{eq: dPh}
\df \P^h_{\mid \calF_T} &= \frac{h(T,X_T)}{C^h} \df \P_{\mid \calF_T},
\end{align*}
with $C^h := \E[h(0,X_0)]$ acting as a normalising constant. Under the new measure $\P^h$, the law $\calL^h(X)$ of $X$ is exactly the conditional distribution of $X$ given $Y = y$ in the sense that 
\begin{align*}
	\E^h[\varphi(X)]= \E[\varphi(X) \mid Y = y]
\end{align*} for any bounded and measurable function $\varphi$.
Moreover, under certain regularity conditions on $h$, it was shown in \cite{Piepersethmacher2025Class} that the change of measure $\P^h$ is of Girsanov type. The process $X$ under $\P^h$ is then a mild solution to the SPDE 
\begin{align}
\label{eq: dXh}
\df X^h_t &= \left[ A X^h_t + F(t, X^h_t) + Q \Df_x \log h (t,X^h_t) \right] \df t + Q^{\frac12} \df W^h_t,
\end{align}
where $W^h$ is a $\P^h$-cylindrical Wiener process. 
\cref{eq: dXh} differs from the original dynamics in \cref{eq: dXt} only by an additional drift term involving the \textit{score} $\Df_x \log h (t,x)$ of the likelihood function $x \mapsto h(t,x)$ that steers the process $X^h$ into regions of high probability given the observation $Y = y$. 
With slight abuse of notation, we write $X^h$ for the process $X$ defined on the stochastic basis $(\Omega, \calF, (\calF_t)_{t \in [0,T]},\P^h)$ and call it the \textit{conditioned process}. Note that the existence of $\P^h$ and $X^h$ does not rely on the existence of a mild solution to Equation \eqref{eq: dXh}.

\vspace{\baselineskip}

In most cases, the transition kernel $\mu$ of $X$, and hence the function $h$, is intractable. This renders directly sampling the conditioned process infeasible, even if conditions for the well-posedness of Equation \eqref{eq: dXh} are satisfied. 
A natural approach to overcome this problem is to substitute the intractable function $h$ by a tractable function $g$ that `approximates' $h$ in some sense.
Besides being tractable, the function $g$ should
\begin{itemize}
    \item[(i)] be informed by the observed data in a way that resembles the original function $h$,
    \item[(ii)] be such that there exists a mild solution $X^g$ to the equation
  \begin{align}
  \label{eq: dX^g}
  	    \df X^g_t &= \left[ A X^g_t + F(t, X^g_t) + Q \Df_x \log g (t,X^g_t) \right] \df t + Q^{\frac12} \df W_t,
  \end{align}
    \item[(iii)] be such that the laws of $X^h$ and $X^g$ are absolutely continuous in path space with a tractable Radon-Nikodym (R.N.) derivative $\Phi$.% := \df \calL(X^h)/\df \calL(X^g)$.
\end{itemize}
One can then obtain \textit{weighted samples} of the conditioned process $X^h$ by sampling the process $X^g$ and associating with each sample the weight $\Phi(X^g)$. 
Since $X^g$ is `guided' by the observation $Y = y$, we refer to it as the \textit{guided process} and its law as the \textit{guided distribution}.

\vspace{\baselineskip}


In our approach, we define $g$ by substituting the transition kernel $\mu$ in the definition of $h$ with a tractable transition kernel $\nu$ of an auxiliary process $Z$. If $Z$ is an Ornstein-Uhlenbeck process, we show that the function $g$ defines a change of measure on $\calF_T$ by 
\begin{align*}
\df \P^g_{\mid \calF_T} &= \frac{g(T,X_T)}{C^g} \exp \left(- \int_0^T \dfrac{\calK g}{g}(s,X_s) \, \df s \right) \df \P_{\mid \calF_T}
\end{align*}
such that $X$ under $\P^g$ satisfies Equation \eqref{eq: dX^g} with respect to a $\P^g$-cylindrical Wiener process $W^g$.
Here, $\calK$ denotes the infinitesimal generator of the original, unconditioned process $X$ and $C^g$ is another normalising constant.

The function $x \mapsto g(t,x)$ is to be interpreted as the likelihood function of $Z_t = x$ under the simplified dynamics of $Z$ and therefore satisfies condition (i). Moreover, condition (ii) is ensured by the Gaussian nature of $g(t,x)$ implying a global Lipschitz condition of the score function $\Df_x \log g(t,x)$.
Lastly, by construction of $\P^h$ and $\P^g$, the laws of $X^g$ and $X^h$ are absolutely continuous in path space, hence satisfying the third condition imposed on $g$. 
In \cite{Piepersethmacher2025Simulation} it was shown that this absolute continuity persists if the observation kernel degenerates to a Dirac measure in $Lx$, i.e. if $Y \mid X_T \sim \delta_{Lx}(\cdot)$. In other words, the guided distribution remains a valid importance sampling distribution for $X^h$ even under highly informative observations. 

\vspace{\baselineskip}

Our aim in this paper is to apply this basic idea of constructing the conditioned process $X^h$ as well as the guided process $X^g$ by a change of measure to derive solutions to both the filtering as well as the smoothing problem. 

For the filtering problem, we propose the law of $X^g$ as a natural candidate for the proposal distribution in a 
\textit{particle filter} (or \textit{sequential Monte Carlo}) approach. The particle filter is a well-established algorithm that approximates the filtering distribution in \eqref{eq: def_filtering} by a set of samples (`particles') $X_{t_i}^{(j)}$ with associated weights $w_i^{(j)}$. At each iteration $i$, the particles are evolved forward following a proposal distribution $X_{[\ti,\tip]}^{(j)} \sim \Q(\cdot \mid X_{t_i}^{(j)})$ with the associated weights following the recursive update 
\begin{align*}
    w_{i+1}^{(j)} \propto w_i^{(j)} \, k(X^{(j)}_{\tip}, y_{i+1}) \frac{\df \P\left(X^{(j)}_{[\ti,\tip]} \in \cdot \mid X_{t_i}^{(j)} \right)}{\df \Q(\cdot  \mid X_{t_i}^{(j)}) } \left(X^{(j)}_{[\ti,\tip]} \right).
\end{align*}
It is well-known that the locally optimal proposal distribution $\Q$ is given by the conditional distribution of $X^{(j)}_{[\ti,\tip]} \mid X^{(j)}_{\ti}, Y_{i+1} = y_{i+1}$ (cf. 10.3, \cite{Chopin2020Introduction}).
This corresponds to the $h$-transform introduced above with the intractable function
\begin{align*}
    h_i(t,x) &= \int_H k(z,y_{i+1}) \mu_{t,\tip}(x, \df z), \quad t \in (\ti,\tip], x \in H.
\end{align*}
A natural candidate for a substitute proposal distribution is therefore the guided distribution corresponding to the observation $y_{i+1}$. 

\vspace{\baselineskip}

On the other hand, the smoothing problem can be solved after extending the change of measure $\P^h$ to include the complete set of observations $(Y_1,\ldots,Y_n) = (y_1,\ldots,y_n)$ by defining the function
\begin{align*}
    h(t,x) := \int k(x_{\ti}, y_i) \left( \prod_{j=i}^{n-1} k(x_{\tjp},y_{j+1}) \, \mu_{\tj,\tjp}(x_{\tj}, \df x_{\tjp}) \right) \mu_{t, \ti}(x, \df x_{\ti}),  \quad t \in (\tim,\ti]. 
\end{align*}
In Section \ref{sec: changes_measure} we show that $h$ defines a change measure $\P^h$ under which the law of $X^h$ is exactly the smoothing distribution \eqref{eq: def_smoothing} of $X$. 
Substituting again the Markov kernel $\mu$ with the kernel $\nu$ of an auxiliary process $Z$ leads to a tractable change of measure $\P^g$ and a corresponding guided process $X^g$ that satisfies yet another SPDE, while maintaining absolute continuity of the laws of $X^h$ and $X^g$ with a tractable Radon-Nikodym derivative $\Phi$. 

For certain choices of $Z$, we show that $g$ can be directly computed on the basis of the recursion known as the \textit{backwards information filter}
\begin{align}
\begin{split}
\label{eq: g_BIF}
    g(t,x) &= \int g(t_i,x_{\ti}) \, \nu_{t,\ti}(x, \df x_{\ti}), \quad t \in (\tim, \ti], \\
    g(\ti, x) &= k(x,y_{j}) \, g^+(\ti,x), \quad i \in \{1,\dots,n\},
\end{split}
\end{align}
with $g^+(\ti,x) :=  \lim_{\substack{t \downarrow \ti \\ t \neq \ti}} g(t,x)$.  
This enables drawing weighted samples of $X^h$ which can then be passed onto general Markov chain Monte Carlo or importance sampling schemes to sample from the smoothing distribution of $X$.

\vspace{\baselineskip}




\subsection{Outline}
In Section \ref{sec: changes_measure} we derive the two changes of measure that define the smoothing and guided distribution of $X$. In particular, we present two ways of efficiently computing the score $\Df_x \log g$ needed to sample from the guiding distribution and evaluate the corresponding weights.
The implementation of the guided distribution into a particle filtering scheme is discussed in Section \ref{sec: guided_particle_filter}. Section \ref{sec: guided_MCMC} derives a Markov Chain Monte Carlo algorithm that targets the smoothing distribution of $X$ and posterior of model parameters $\theta$.
Performance of the proposed methodology is illustrated in Section \ref{sec: amari} through an example based on the stochastic Amari equation.



\subsection{Frequently used notation}
We denote by $H$ a Hilbert space with inner product $\langle x,y \rangle$ and norm $|x| = \sqrt{ \langle x, x \rangle }$. 
The process $X$ denotes the mild solution to Equation \eqref{eq: dXt}, defined on the stochastic basis $(\Omega, \calF, (\calF_t)_{t \geq 0},\P)$, with Markov transition kernel $\mu = (\mu_{s,t})_{s \leq t}$. If $F$ is independent of $X$ and instead $F(t,X_t) = a_t$ for some predictable, $H$-valued process $(a_t)_t$, we write $Z$ in place of $X$ for the Ornstein-Uhlenbeck process that satisfies \eqref{eq: dXt} and $\nu = (\nu_{s,t})_{s \leq t}$ for its transition kernel.
\vspace{\baselineskip}

The kernel $k_i(x,\cdot)$ defines a conditional density on $\R^{m_i}$ for any $x \in H$. For most of the paper, we assume $k_i(x, \cdot) = k(x,\cdot)$ to be a Gaussian density on $\R^m$ with mean $Lx$ and covariance matrix $\Sigma$, where $L:H \to \R^m$ is a bounded linear observation operator. 
By $Y_i \in \R^{m_i}$ we denote the observations of $X_{\ti}$ with density $k_i(X_{\ti}, \cdot)$ at observation time $t_i$, with $Y = (Y_1,\ldots Y_n)$ defined as the joint vector of all observations. We refer to individual components of one observation vector $Y_i \in \R^{m_i}$ as measurements.
For realisations of $Y_i$, we write $y_i \in \R^{m_i}$. We shall also write $y_i^+ = (y_i,\ldots,y_n)$ for the vector of all non-past observations at time $t_i$. Moreover, $m_i^+$ denotes the dimension of $y_i^+$, i.e. $m_i^+ = \sum_{j=i}^n m_j$. For a function $f$, $f^+(t) := \lim_{\substack{s \downarrow t}} f(s)$ is defined as the right-sided limit of $f$ at $t$ whenever existent.

\vspace{\baselineskip}
By $C([0,T];H)$ we denote the space of continuous, $H$-valued functions endowed with the supremum norm and its Borel algebra. 
For the laws of $X$ and $Z$ on the Borel algebra of $C([0,T];H)$ we write $\calL(X)$ and $\calL(Z)$ respectively. 
With slight abuse of notation, we shall also write $X_{[\tim, \ti]}$ for the process $(X_t)_{t \in [\tim, \ti]}$ and $\calL(X_{[\tim,\ti]})$ for its law on $C([\tim,\ti];H)$.

The realised observations $y$ together with the transition kernels $\mu$ and $\nu$ define the functions $h$ and $g$. 
These define the changes of measure $\P^h$ and $\P^g$ under which the law of $X$ is, respectively, the smoothing and guided distribution given the observations $y$. We denote these by $\calL^h(X)$ and $\calL^g(X)$.



\section{Changes of measure}
\label{sec: changes_measure}

The aim of this section is to derive the two changes of measure $\P^h$ and $\P^g$ that respectively define the intractable smoothing distribution $\calL^h(X)$ and the tractable guided distribution $\calL^g(X)$ of $X$. In particular, the construction will show that 
\begin{itemize}
    \item[(i)] $\calL^h(X)$ and $\calL^g(X)$ are absolutely continuous with Radon-Nikodym derivative
\begin{align*}
    \Phi(X) := \dfrac{\df \calL^h(X)}{\df \calL^g(X)}(X) = \frac{C^g}{C^h} \exp \left(  \int_0^T \langle F(s,X_s), G(s,X_s) \rangle \df s \right),
\end{align*}
where $C^g$ and $C^h$ are normalising constants and $G(t,x) = \Df_x \log g(t,x )$ is a tractable function,
    \item[(ii)] the distribution $\calL^g(X)$ can be sampled by numerically solving the SPDE
    \begin{align*}
        \df X^g_t &= \left[ A X^g_t + F(t, X^g_t) + Q G (t,X^g_t) \right] \df t + Q^{\frac12} \df W^g_t.
    \end{align*}
\end{itemize}
Moreover, we derive two ways of efficiently computing $G$ needed to sample from $X^g$ and evaluate the corresponding weights. 
The proofs of the results in this section can be found in Appendix \ref{app: A}.

\subsection{The smoothing distribution}
\label{sec: smoothing_measure}
We start by constructing the smoothing distribution of $X$ given $Y_1 = y_1, \ldots, Y_n = y_n$. We do so by defining a measure $\P^h$ on $\calF_T$ such that 
\begin{align}
\label{eq: smoothingEh}
    \E^h \left[ \varphi(X) \right] &=  \E[ \varphi(X) \mid Y_1 = y_1, \ldots, Y_n = y_n] 
\end{align}
for all bounded and measurable functionals $\varphi: C([0,T],H) \to \R$.
Note that for $n = 1$, this includes the locally optimal proposal distribution in the guided particle filter as introduced in \cref{sec: approach}.

To this end, define the function $h: [0,T] \times H \to \R_+$ by
\begin{align}
\label{eq: def_h}
h(t,x) := \int k(x_{\ti}, y_i) \left( \prod_{j=i}^{n-1} k(x_{\tjp},y_{j+1}) \, \mu_{\tj,\tjp}(x_{\tj}, \df x_{\tjp}) \right) \mu_{t, \ti}(x, \df x_{\ti}),  \quad t \in (\tim,\ti], 
\end{align}
with $h(0,x) := h^+(0,x)$.
For the sake of notational clarity, we drop the dependence of $h$ on the observations $(y_1,\ldots,y_n)$. 
However, it is worth pointing out that on any time interval $(\tim,\ti]$, $h(t,x)$ has a natural interpretation as the likelihood function of $X_t = x$ given all non-past observations $y_i^+ = (y_i,\ldots,y_n)$, i.e. in Bayesian notation
\begin{align*}
    h(t,x_t) = p(y_i^+ \mid x_t), \quad t \in (\tim,\ti].
\end{align*}

A direct consequence of the definition of $h$ is that it satisfies the following recursive relation known as the \textit{backwards information filter}.
\begin{proposition}
\label{prop: h_properties}
The function $h(t,x)$ defined in \eqref{eq: def_h} satisfies 
\begin{align*}
%\label{eq: h_BIF}
h(t,x) = \int h(t_i,x_{\ti}) \, \mu_{t,\ti}(x, \df x_{\ti}), \quad t \in (\tim, \ti].
\end{align*}
In particular, $h$ is continuous on any interval $(\tim, \ti)$ and left continuous at any $\ti, i = 1,\dots,n$.
Moreover, at the observation times $\ti$, it holds that
\begin{align*}
%\label{eq: h_BIF2}
h(\ti, x) = k(x,y_{j}) \int h(\tip,x_{\tip}) \, \mu_{\ti,\tip}(x, \df x_{\ti}) = k(x,y_{j}) \, h^+(\ti,x).
\end{align*}
\end{proposition}


With the choice of $h$ established, define now the process $(E^h_t)_{t \in [0,T]}$ by
\begin{align}
\label{eq: def_Eht}
E^h_t := \frac{1}{C^{h}} \left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) h(t,X_t), \quad t \in (\tim,\ti],
\end{align}
with $E^{h}_0 := h(0,X_0)/C^{h}$ and $C^h := \E[h(0,X_0)]$ acting as a normalising constant.

\begin{remark}
\label{rem: prodkh_likelihood}
At any time $t \in (\tim,\ti]$, the product $\prod_{j=1}^{i-1} k(x_{t_j},y_j)$ appearing on the right-hand side of \eqref{eq: def_Eht} is the likelihood of previous states of $X$ at observation times given past observations, whereas $h(t,x_t)$ is the likelihood of $X_t = x_t$ given all non-past observations. 
Hence, in total, the term 
\begin{align*}
    \left( \prod_{j=1}^{i-1} k(x_{\tj},y_j) \right) h(t,x_t,y), \quad t \in (\tim,\ti],
\end{align*} 
is the likelihood of $(X_{t_1} = x_{t_1}, \ldots , X_{t_{i-1}} = x_{t_{i-1}}, X_t = x_t)$ given all observations $y_j$, $j = 1,\dots,n$.
\end{remark}



\begin{proposition}
\label{prop: Eht_martingale}
The process $(E^h_t)_{t \in [0,T]}$ defined in \eqref{eq: def_Eht} is a non-negative $\P$-martingale with respect to the filtration $(\calF_t)_{t \in [0,T]}$.
\end{proposition}

Given its martingale property and noting that $E^h_0 = 1$, the process $E^h$ defines a measure $\P^h$ on $\calF_T$ by
\begin{align}
\label{eq: def_dPh}
\df \P^h_{\mid \calF_T} &= E^h_T \df \P_{\mid \calF_T}.
\end{align}
The following theorem establishes that this is indeed the change of measure under which the law of $X$ is the smoothing distribution. 

\begin{theorem}
\label{thm: dPh} \,
\begin{itemize} 
    \item[(i)] The measure $\P^h$ satisfies \eqref{eq: smoothingEh}.
    \item[(ii)] In addition, if $h$ is Fréchet differentiable in $x$ such that $\Df_x h \in C_m((\tim,\ti);H)$ for all $i = 1 \ldots n$, then the process $X$ under $\P^h$ is a mild solution to the SPDE
    \begin{align}
    \label{eq: dXh2}
    \begin{cases}
        \df X^h_t &= \left[ A X^h_t + F(t, X^h_t) + Q \Df_x \log h (t,X^h_t) \right] \df t + Q^{\frac12} \df W^h_t, \\
        X^h_0 &\sim \mu_0^h,
    \end{cases}
    \end{align}
    where $W^h$ is a $\P^h$-cylindrical Wiener process and $\mu_0^h(B) := \P^h(X_0 \in B)$.
\end{itemize}
\end{theorem}


\begin{remark}
    The assumption in Theorem \ref{thm: dPh} (ii) is in general hard to verify. However, to sample from the law of $X$ under $
    \P^h$, the differential form of $X^h$ in \cref{eq: dXh2} is not necessary. 
    Instead, weighted samples of the smoothing distribution are obtained by sampling $X$ under the substitute measure $\P^g$ defined in the next subsection.
\end{remark}



\subsection{The guided distribution}
\label{sec: guided_measure}

To construct the guided distribution, we follow similar steps as in the previous section, replacing $\mu$ in the definition of $h$ with a tractable transition kernel $\nu$ of an auxiliary process $Z$.

For this, let $Z$ be the Ornstein-Uhlenbeck process, defined as the unique mild solution to the SPDE 
\begin{align}
\label{eq: dZt}
\begin{cases}   
\df Z_t &= \left[ A Z_t + a_t \right] \df t+ Q^{\frac12} \df W_t, \quad  t \geq 0, \\
Z_0 &\sim \nu_0.
\end{cases}
\end{align}
The $H$-valued process $(a_t)_{t \geq 0}$ is assumed to be predictable with integrable trajectories and $\nu_0$ denotes a Gaussian measure on $H$. 
Let $(\nu_{s,t})_{s \leq t}$ be the transition kernel of $Z$ defined by $\nu_{s,t}(x, B) := \P(Z_t \in B \mid Z_s =x)$ for any $0 \leq s \leq t$, $x \in H$ and Borel set $B \subset H$. It is well-known that $\nu_{s,t}(x, \cdot)$ is a Gaussian measure on $H$ with mean $S_{t-s} x + \int_s^t S_{t-u} a_u \df u$ and covariance operator
\begin{align}
\label{eq: def_Qt}
    Q_{t-s} := \int_0^{t-s} S_{u} Q S_{u}^* \df u.
\end{align} 

Following the definition of $h$ in Equation \eqref{eq: def_h}, we define the mapping $g$ by 
\begin{align}
\label{eq: def_g}
g(t,x) := \int k(x_{\ti}, y_i) \left( \prod_{j=i}^{n-1} k(x_{\tjp},y_{j+1}) \, \nu_{\tj,\tjp}(x_{\tj}, \df x_{\tjp}) \right) \nu_{t, \ti}(x, \df x_{\ti}),  \quad t \in (\tim,\ti],
\end{align}
with the convention that $g(0,x) := g^+(0,x)$.

The function $g(t,x)$ on $(\tim, \ti]$ has a natural interpretation as the likelihood of $Z_t = x$ given the vector $(y_i,\dots,y_n)$ of non-past observations $y_i \sim k(Z_{\ti}, \cdot)$ under the simplified dynamics of \cref{eq: dZt}.
Moreover, just like the $h$-function, $g$ satisfies the recursion of the backwards information filter 
\begin{align}
\begin{split}
\label{eq: g_BIF2}
    g(t,x) &= \int g(t_i,x_{\ti}) \, \nu_{t,\ti}(x, \df x_{\ti}), \quad t \in (\tim, \ti], \\
    g(\ti, x) &= k(x,y_{i}) \, g^+(\ti,x), \quad i \in \{1,\dots,n\},
\end{split}
\end{align}
with $g^+(\ti,x) = \int g(\tip,x_{\tip}) \, \nu_{\ti,\tip}(x, \df x_{\ti})$.

Contrary to the generally intractable $h$, the Gaussian nature of $\nu_{s,t}(x, \cdot)$ and $k(x, \cdot)$ enables us to compute the function $g$ using the recursion in \eqref{eq: g_BIF2} as shown in the next theorem.
\begin{theorem}
\label{thm: g_LtRtalphat}
On any interval $(\tim, \ti]$, $i =1, \dots,n,$ let $L_t \in L(H, \R^{m^+_i})$ be given by
\begin{align}
\label{eq: def_Lt}
L_t := \begin{bmatrix}  L S_{\ti-t} \\  L S_{\tip -t} \\ \vdots \\ L S_{\tn-t} \end{bmatrix} 
\end{align}
and let $R_t \in L(\R^{m^+_i})$ and $\alpha_t \in \R^{m^+_i}$ be defined by the backwards recursions
\begin{align}
\label{eq: def_Rt_alphat}
\begin{split}
    R_t &:= \begin{cases} \Sigma + L Q_{\tn-t} L^*,  & i =  n,\\
        \begin{bmatrix} 
\Sigma & 0 \\
0 & R^+_{\ti} 
\end{bmatrix} + L_{\ti} Q_{\ti-t} L^*_{\ti},  &\text{else},
    \end{cases}   \\
\alpha_t &:= \begin{cases}
    L \left( \int_t^{\tn} S_{\tn-s} a_s \, \df s \right), & i = n, \\
\begin{bmatrix}  0 \\ \alpha^+_{\ti} \end{bmatrix} + L_{\ti} \left( \int_t^{\ti} S_{\ti -s} a_s \, \df s\right), & \text{else}.
\end{cases}
\end{split}
\end{align}

Then, the function $g(t,x)$ is given by
\begin{align}
\label{eq: g_BIF_computed}
g(t,x) = f(y_i^+ ; L_tx + \alpha_t, R_t), \quad t \in (\tim, \ti].
\end{align}
\end{theorem}

\vspace{\baselineskip}



Following Theorem \ref{thm: g_LtRtalphat}, the function $g$ can be expressed on any interval $(\tim,\ti]$ as the Gaussian density in Equation \eqref{eq: g_BIF_computed}. This lets us define a tractable change of measure $\P^g$ on $\calF_T$ as follows. 
Denote by $G$ the score function of the likelihood $x \mapsto g(t,x)$, i.e.
\begin{align}
\label{eq: def_G}
G(t,x) := \Df_x \log g(t,x) = L_t^* R_t^{-1} (y_i^+ - L_tx - \alpha_t), \quad t \in (\tim,\ti], x \in H.
\end{align}


Moreover, define the process $(E^g_t)_{t \in [0,T]}$ by setting
\begin{align}
\label{eq: def_Egt} 
E^g_t := \frac{1}{C^{g}} \left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) g(t,X_t) \exp \left(- \int_0^t \langle F(s,X_s), G(s,X_s) \rangle \, \df s \right), \quad t \in (\tim,\ti],
\end{align}
with $E^g_0 := g(0,X_0)/C^{g}$ and $C^g := \E[g(0,X_0)]$ acting as a normalizing constant.

The theorem presented below shows that $E^g$ is a martingale that defines a measure $\P^g$ on $\calF_T$ under which the law of $X$ is exactly the guided distribution as introduced in \cref{sec: approach}.
\begin{theorem}
\label{thm: dPg} \,
\begin{itemize}
    \item[(i)] The process $E^g$ defined in \eqref{eq: def_Egt} is a non-negative $\P$-martingale with respect to the filtration $(\calF_t)_{t \in [0,T]}$.
    \item[(ii)] Under the measure $\P^g$ defined on $\calF_T$ by $\df \P^g_{\mid \calF_T} = E^g_T \df \P_{\mid \calF_T}$, the process $X$ is the unique mild solution to the SPDE 
    \begin{align}
    \begin{split}
    \begin{cases}
        \label{eq: dXg}
        \df X^g_t &= \left[ A X^g_t + F(t, X^g_t) + Q G (t,X^g_t) \right] \df t + Q^{\frac12} \df W^g_t,
        \quad t \in [0,T], \\
        X^g_0 &\sim \mu_0^g,
    \end{cases}
    \end{split}
    \end{align}
    where $W^{g}$ is a cylindrical Wiener process under $\P^g$. 
\end{itemize}
\end{theorem}


From the construction of $\P^h$ and $\P^g$ it follows that the smoothing and guided distribution of $X$ are absolutely continuous with Radon-Nikodym derivative given by 
\begin{align}
\label{eq: dPh_dPg}
\Phi(X) = \frac{C^g}{C^h} \Psi(X) 
\end{align}
where $\Psi(X)$ is defined as 
\begin{align}
\label{eq: def_Psi}
	\Psi(X) := \exp \left(  \int_0^T \langle F(s,X_s), G(s,X_s) \rangle \df s \right).
\end{align}
Hence, weighted samples of the smoothing distribution $\calL^h(X)$ can be obtained by drawing samples from $\calL^g(X)$ and evaluating the weights $\Phi(X)$. As a consequence of Theorem \ref{thm: dPg}, the sampling step corresponds to numerically solving Equation \eqref{eq: dXg}. 


\begin{remark}
Drawing samples from $\calL^g(X)$ as well as evaluating the weights $\Phi(X)$ requires computation of the function $G$ defined in Equation \eqref{eq: def_G}.
In practical applications, this is carried out on a gridded domain in both space and time. 

In that case, the infinite-dimensional operators $A$, $S_t$ and $Q$ are typically approximated by $M{\times}M$-dimensional matrices on the given spatial - or spectral - grid. Likewise, the observation operator $L$ is represented by a $m{\times}M$-dimensional matrix. 
Evaluating $G$ based on Theorem \ref{thm: g_LtRtalphat} on a temporal grid of $(\tim,\ti]$ with $N$ grid points then requires the following operations:
\begin{itemize}
    \item[1.] The operators $L_t$ are given in closed form and are a simple concatenation of linear compositions of $L$ and the semigroup $S$. For each observation time $\ti$, the matrix multiplication $L_t = L_{\ti} S_{t_i -t}$ needs to be carried out for $N$ grid points of $(\tim,\ti]$. This results in $O(N m_i^+ M^2)$ operations.
    \item[2.] To compute $R_t$, the matrix approximations of $Q_{\ti-t} = \int_0^{\ti-t} S_s Q S_s^* \df s$ need to evaluated. If this integral cannot be solved directly, it needs to be numerically integrated with computational complexity of $O(N M^3).$ Additionally, the matrix multiplications $L_{\ti} Q_{\ti-t} L^*_{\ti}$ will need to be carried out, leading to an additional total cost of $O(N m_i^+ M^2)$.
    Moreover, evaluation of $G$ will require the matrix inversion of $R_t$. Due to the block matrix structure of $R_t$, this is of cost $O((n-i+1)m^3) = O(m_i^+ m^2)$ for each inversion. 
    \item[3.] Lastly, to compute $\alpha_t$, we need to numerically backwards integrate the term $\int_t^{\ti} S_{\ti -s} a_s \, \df s$. This is of complexity $O(N M^2)$ after discretisation, on top of the cost $O(N m^+_i M)$ of evaluating $L_{\ti} \int_t^{\ti} S_{\ti -s} a_s \, \df s$. 
\end{itemize}

Hence, in total, the cost of the operations required to compute $G$ using Theorem \ref{thm: g_LtRtalphat} on a spatio-temporal grid with $(N,M)$ grid points is of complexity
\begin{align*}
    O( N \max\{M^3, m^+_i M^2, m_i^+ m^2\}).
\end{align*}
In principle, the spatial grid size $M$ chosen by the user is fixed but can be arbitrarily large.
However, with growing number of observations $n$, the dimension $m^+_i = (n-i+1)m$ quickly grows larger than $M$, leading to a computational costs of complexity $O(N m^+_i M^2)$.
In that case, it is beneficial to parametrise $g$ in a different manner as we will explore in the next section.
\end{remark}


\subsection{Computationally efficient guiding}
\label{sec: comp_efficient_guiding}

We derive an alternative to Theorem \ref{thm: g_LtRtalphat} of computing $G$ to sample from the guided process $X^g$. 
Define the functions $(V_t)_{t \in [0,T]}$ and $(U_t)_{t \in [0,T]}$ by
\begin{align}
\begin{split}
\label{eq: def_Ut_Vt}
    U_t &:= L^*_t R^{-1}_t L_t \\
    V_t &:= L^*_t R^{-1}_t (y_i^+ - \alpha_t), \quad t \in (\tim,\ti]
\end{split}   
\end{align}
for each $i = 1,\ldots,n$ with $U_0 := U^+_0$ and $V_0 := V^+_0$.
Following Theorem \ref{thm: g_LtRtalphat}, it holds that 
\begin{align}
\label{eq: G}
    G(t,x) = V_t - U_t x.
\end{align}
As the upcoming theorem shows, $U_t$ and $V_t$ can be obtained by solving a set of infinite-dimensional backwards differential equations. 



\begin{theorem}
    \label{thm: G_UtVt}
    On each interval\footnote{If $i=n$, $U$ needs to be initialised with $U_{\tn} = L^* \Sigma L $ and $V$ with $V_{\tn} = L^* \Sigma^{-1} y_n$.} $(\tim, \ti]$, $i = 1,\ldots,n,$  $U$ is the unique mild solution to the backwards Ricatti equation 
    \begin{align}
    \begin{split}
    \label{eq: dU_t}
    \begin{cases}
    \df U_t &=  \left[ -A^* U_t - U_t A + U_t Q U_t \right] \df t\\
    U_{\ti} &= L^* \Sigma^{-1} L + U^+_{\ti},
    \end{cases}
    \end{split}
    \end{align}
    whereas $V$ is the unique mild solution to the backwards equation
    \begin{align}
    \begin{split}
    \label{eq: dV_t}
    \begin{cases}
        \df V_t &= \left[ -A^* V_t + U_t Q V_t + U_t a_t \right] \df t,\\
        V_{\ti} &= L^* \Sigma^{-1} y_i + V^+_{\ti}. 
    \end{cases}
    \end{split}
    \end{align}
\end{theorem}


\vspace{\baselineskip}


\begin{remark}
    Without going into too much detail, it is worth pointing out that there exists extensive literature on the approximation of the infinite-dimensional Ricatti equation. We refer to \cite{Gibson1983Linear}, \cite{Burns2015Solutions}, \cite{Cheung2025Approximation} and references within for an introduction into the relevant literature. 

    For numerical purposes, the infinite-dimensional operators $A$ and $Q$ are typically approximated by $M{\times}M$-dimensional matrices on a spatial - or spectral - grid.
    Given such approximations of $A$ and $Q$, the backwards Ricatti equation \eqref{eq: dU_t} can be numerically solved using standard solvers for ODEs with total costs of $O(N M^3)$ on a temporal grid of $N$ points. 
    In a similar fashion, the backwards evolution equation \eqref{eq: dV_t} can be solved using standard ODE solvers with total costs of $O(N M^3)$.
    Note that, contrary to the computation of $G$ based on Theorem \ref{thm: g_LtRtalphat}, this cost is independent of the number of observations. Moreover, in many cases, structural properties of the matrix approximations of $A$ and $Q$, such as sparsity, can be taken advantage of to further reduce the computational costs. 
\end{remark}


\begin{remark}
    In certain cases, the backwards Ricatti equation \eqref{eq: dU_t} can be solved in closed form. 
    This includes the highly relevant case that $A$, $Q$ and $L$ are diagonalisable, i.e. if there exists an orthonormal basis $(e_j)_{j=1}^{\infty}$ with 
    \begin{align*}
        A e_j &= - a_j e_j, \\
        Q e_j &= q_j e_j 
    \end{align*}
    such that $0 < a_j \to \infty$ and $0 < q_j < \sup_j q_j <\infty$ and $\im(L^*) \subset \spn\{e_j : j = 1, \ldots m\}$.

    Equation \eqref{eq: dU_t} then decouples into a sequence $(u^j)_{j=1}^m$ of scalar-valued Ricatti differential equations
    \begin{align*}
        d u^j_t = 2 a_j u^j_t + q_j (u^j_t)^2 \df t, \quad t \in (\tim, \ti), 
    \end{align*}
    which are solved in closed form for all $j = 1 \ldots m$ by (cf. \cite{Zaitsev2002Handbook}, Chapter 1.1)
    \begin{align*}
        u^j_t 
        &= \frac{\exp(- 2 a_j (t_i - t))}{(u_{\ti}^j)^{-1} + \dfrac{q_j}{2 a_j} \left[ 1 - \exp( - 2 a_j (\ti-t)) \right]}, \quad \quad t \in (\tim, \ti).
    \end{align*}
\end{remark}

\vspace{\baselineskip}

When computing $G$ based on Theorem \ref{thm: G_UtVt}, the following proposition is useful to derive the full expression of $g$. This is required, for example, when inferring not only unobserved states of $X$ but also unknown model parameters $\theta$.   
\begin{proposition}
\label{prop: dct}
In addition to $U$ and $V$ as defined in Theorem \ref{thm: G_UtVt}, let $c$ be defined by
\begin{align*}
c_t = - \dfrac{1}{2} \left[ \log((2 \pi)^{m^+_i}) + \log(\det(R_t))  + \langle y^+_i - \alpha_t, R^{-1}_t (y^+_i - \alpha_t)\rangle \right], \quad t \in (\tim, \ti].
\end{align*}
Then $\log g(t,x) = c_t + \langle V_t,x \rangle - \dfrac{1}{2} \langle x, U_t x \rangle.$
Moreover, on any interval $(\tim, \ti]$, $i = 1, \ldots, n$, $c_t$ solves the backwards differential equation
\begin{align}
\begin{split}
\begin{cases}
\label{eq: dct}
\df c_t &= \left[ \dfrac{1}{2} \tr \left[ U_t Q  \right] - \left \langle   a_t ,  V_t \right \rangle -\dfrac{1}{2} \left \langle V_t, Q V_t \right \rangle\right] \df t,  \\
c_{\ti} &= \log f(y_i; 0, \Sigma) - c^+_{\ti}.
\end{cases}
\end{split}
\end{align}
\end{proposition}


\section{Guided particle filtering}
\label{sec: guided_particle_filter}

In this section, we show how a special case of the guided distribution can be used as proposal distribution in a particle filtering scheme. 
For the convenience of the reader, we give a brief outline of the particle filter (PF).
We refer to \cite{Doucet2001Sequential} or \cite{Chopin2020Introduction} for book-length treatments of this field. 

The particle filter uses a set of particles $\{X^{(j)}_{\ti} : j = 1,\ldots, J\}$ with associated weights $\{w^{(j)}_{i} : j = 1,\ldots, J\}$ to approximate the filtering distribution \eqref{eq: def_filtering} at any observation time $\ti$ by a Monte Carlo approximation
\begin{align*}
    \E[ \varphi(X_{\ti}) \mid Y_1 = y_1, \ldots, Y_n = y_i] &\approx \sum_j w^{(j)}_{\ti} \varphi(X^{(j)}_{\ti})
\end{align*}
for any bounded and measurable function $\varphi: H \to \R$.

The particles and their weights are sequentially updated with incoming observations as per the following recursion. 
Given an estimate $\{ (X^{(j)}_{\tim},w^{(j)}_{i-1})  : j = 1,\ldots, J\}$ of the filtering distribution at time $\tim$ and given a Markov kernel $\Q(\cdot \mid x)$ from $H$ to $C([\tim, \ti];H)$, the particles evolve forward to the next observation time $\ti$ according to
\begin{align*}
    X^{(j)}_{[\tim,\ti]} \sim \Q( \cdot \mid  X^{(j)}_{\tim}), \quad j = 1 , \ldots J.
\end{align*}
The weights are then updated (and normalised) via
\begin{align*}
   w_{i}^{(j)} \propto w_{i-1}^{(j)} \, k(X^{(j)}_{\ti}, y_{i}) \frac{\df \calL(X_{[\tim,\ti]} \mid X^{(j)}_{\tim})}{\df \Q( \cdot \mid X^{(j)}_{\tim})} \left(X^{(j)}_{[\tim,\ti]}\right), \quad \text{s.t. } \sum_{j=1}^J w_{i}^{(j)} = 1.
\end{align*}
Here, $\calL(X_{[\tim,\ti]} \mid X^{(j)}_{\tim})$ denotes the law of $X_{[\tim,\ti]}$ satisfying \eqref{eq: dXt} with initial state $X_{\tim} = X^{(j)}_{\tim}$.

Typically, to prevent \textit{weight degeneracy}, i.e. one or few weights dominating the others, a resampling step of the particles based on the normalized weights is introduced. This can be done every fixed number of steps or in an adaptive number based on maintaining the \textit{effective sample size} $ESS_i := 1/\left( \sum_{j=1}^J(w_{i}^{(j)})^2 \right)$ above a predefined threshold.

\vspace{\baselineskip}
\begin{algorithm}[b]
    %\SetAlgoNoLine
    \LinesNotNumbered  
    \label{alg: guided_particle_filter}
    \caption{Guided Particle Filter}
    \KwIn{Observations $\{y_i\}_{i=1}^n$, number of particles $J$, threshold $J_0$}
    \KwOut{Particles and weights $\Bigl\{ \left(X_{\ti}^{(j)}, w_i^{(j)} \right) : j = 1 \ldots J\Bigr\}$ for each $i = 1, \dots, n$}
    Initialise $\{X_0^{(j)}\}_{j=1}^J \sim \mu_0$ and set $w_0^{(j)} = \frac{1}{J}$\;
    \For{$i = 1$ \KwTo $n$}{
        \textbf{1. Evolve particles:} \\
        \For{$j = 1$ \KwTo $J$}{
            (i) Sample guided proposal: \[ X^{(j)}_{[\tim,\ti]} \sim \calL^{\gi}( X_{[\tim,\ti]} \mid X^{(j)}_{\tim});\] \\
            (ii) Compute unnormalized weight:
            \[
            \tilde{w}_{i}^{(j)} = w_{i-1}^{(j)} \, g_i(\tim, X^{(j)}_{\tim}) \exp \left( \int_{\tim}^{\ti} \langle F(s, X^{(j)}_s), G_i(s, X^{(j)}_s)\rangle \df s\right);
            \]
        }
        \textbf{2. Normalize Weights:} 
        \[w_{i}^{(j)} = \frac{\tilde{w}_{i}^{(j)}}{\sum_{k=1}^J \tilde{w}_{i}^{(k)}};\]
        Compute effective sample size:
        $\text{ESS} = 1/\sum_{j=1}^J \left(w_{i}^{(j)}\right)^2$\;
        \textbf{3. Resample:}
        \If{\textnormal{ESS}   $< J_0$}{
            Resample $\{X_{\ti}^{(j)}\}_{j=1}^J$ according to weights $w_{i}^{(j)}$\;
            Set $w_{i}^{(j)} = \frac{1}{J}$ for all $j$\;
        }
    }
\end{algorithm}
The proposal kernel $\Q$ is a parameter of the particle filter that is to be chosen by the user. 
If $\Q( \cdot \mid X^{(j)}_{\tim}) = \calL(X_{[\tim,\ti]} \mid X^{(j)}_{\tim})$, the algorithm is known as the \textit{bootstrap particle filter (BPF)}. Since proposals in the BPF are `uninformed' by the observations, it is known to typically struggle with highly degenerate weights. 

On the other hand, the locally optimal proposal kernel is given by the conditional distribution 
\begin{align*}
    \Q( \cdot \mid X^{(j)}_{\tim}) = \P(X_{[\tim,\ti]} \in \cdot \mid X_{\tim} = X^{(j)}_{\tim}, Y_{i} = y_{i}).
\end{align*}
The proposal $\Q$ minimises the variance of the weights $w_{i}^{(j)}$, see for example \cite{Chopin2020Introduction}, Theorem 10.1 for details.
However, as noted in the introduction and previous section, this proposal kernel is typically intractable. 

\vspace{\baselineskip}

We propose instead to steer the particles on the interval $[\tim,\ti]$ into regions of high probability given $Y_{i} = y_{i}$ by the guided distribution introduced in Section \ref{sec: guided_measure}.
For this, define 
\begin{align*}
    \gi(t,x) := \int k(x_{\ti}, y_{i})\nu_{t, \ti}(x, \df x_{\ti}), \quad t \in [\tim, \ti],
\end{align*}
and let $\P^{\gi}$ be the change of measure on $\calF_{\ti}$ as defined in Theorem \ref{thm: dPg}.
We adopt as proposal kernel the guided distribution
\begin{align}
\label{eq: guided_filtering_proposal}
    \Q( \cdot \mid X^{(j)}_{\tim}) = \calL^{\gi}( X_{[\tim,\ti]} \mid X^{(j)}_{\tim}),
\end{align}
i.e. the law of $X_{[\tim,\ti]}$ under $\P^{\gi}$ initiated at $X_{\tim} = X^{(j)}_{\tim}$. 
Particles are then evolved forward in time by simulating the guided process
\begin{align}
\label{eq: dXg2}
\df X^{\gi}_t &= \left[ A X^{\gi}_t + F(t, X^{\gi}_t) + Q G_i (t,X^{\gi}_t) \right] \df t + Q^{\frac12} \df W^{\gi}_t,
        \quad t \in [\tim,\ti], 
\end{align}
with respective initial conditions $X^{(j)}_{\tim}, j = 1, \ldots J$ and $G_i(t,x) = \Df_x \log g_i(t,x)$. Moreover, Theorem \ref{thm: dPg} implies that the update step in the corresponding weights is given by
\begin{align}
\begin{split}
w_{i}^{(j)} &\propto w_{i-1}^{(j)} \, k(X^{(j)}_{\ti}, y_{i}) \frac{\df \calL(X_{[\tim,\ti]} \mid X^{(j)}_{\tim})}{\df \calL^{\gi}(X_{[\tim,\ti]} \mid X^{(j)}_{\tim})} \left(X^{(j)}_{[\tim,\ti]}\right) \\ 
&= w_{i-1}^{(j)} \, k(X^{(j)}_{\ti}, y_{i}) \, \dfrac{g_i(\tim, X^{(j)}_{\tim})}{g_i(\ti, X^{(j)}_{\ti})} \exp \left( \int_{\tim}^{\ti} \langle F(s, X^{(j)}_s), G_i(s, X^{(j)}_s)\rangle \df s\right) \\
&= w_{i-1}^{(j)} \, g_i(\tim, X^{(j)}_{\tim}) \exp \left( \int_{\tim}^{\ti} \langle F(s, X^{(j)}_s), G_i(s, X^{(j)}_s)\rangle \df s\right).
\end{split}
\end{align}


The resulting \textit{guided particle filter} is summarised in Algorithm \ref{alg: guided_particle_filter}. 




\begin{remark}
\label{rem: filtering_G}
The measure $\calL^{\gi}( X_{[\tim,\ti]})$ is the `one-step-ahead' guided distribution on $[\tim, \ti]$ corresponding to the next observation $y_i$. Hence, the functions $g_i$ and $G_i$ only need to be computed as functions of $y_i$ and the parametrisation of Theorem \ref{thm: g_LtRtalphat} remains a computationally valid choice. 
Specifically, on any $[\tim, \ti]$, $g_i(t,x)$ is the Gaussian likelihood $g_i(t,x) = f(y_i ; L_tx + \alpha_t, R_t)$ 
with $L_t = L S_{\ti-t}$, $\alpha_t = L \left( \int_t^{\ti} S_{\ti-s} a_s \, \df s \right)$ and $R_t = \Sigma + L Q_{\ti-t} L^*$, whereas $G_i$ is the score
\begin{align*}
	G_i(t,x) = L_t^* R_t^{-1} \left( y_i - L_t x - \alpha_t\right), \quad t \in [\tim,\ti].
\end{align*}
\end{remark}



\subsection{Tempering and moving steps}
Even though the proposal kernel introduced in Equation \eqref{eq: guided_filtering_proposal} defines a suitable, likelihood-informed importance sampling distribution, the guided particle filter might still face weight degeneracy due to the high dimensionality of the state space. 
Since this is a common issue in particle-based inference, many solutions to overcome it have been proposed and studied in the literature. For the purpose of our numerical experiments in Section \ref{sec: amari}, we introduce two such solutions - \textit{tempering} and \textit{moving} (or \textit{particle rejuvenation}) steps - into the guided particle filter. This follows the suggestions made in \cite{Llopis2018Particle}, where the filtering problem was considered in a similar setup to ours. 
The following brief exposition is based on that work. 

Denoting by $\Pi_i$ the conditioned law $\Pi_i := \calL(X_{[0,t_i]} \mid Y_{1} \dots Y_{i})$, an application of the Bayes theorem and the change of measure $\eqref{eq: guided_filtering_proposal}$ gives the recursion 
\begin{align}
\label{eq: Lambda}
\begin{split}
	\dfrac{\df \Pi_i}{\df ( \Pi_{i-1} \otimes \calL^{g_i})} (X_{[0,t_i]}) &\propto  g_i(\tim, X_{\tim}) \exp \left( \int_{\tim}^{\ti} \langle F(s, X_s), G_i(s, X_s)\rangle \df s\right) \\
	&=: \Lambda_i(X_{[\tim,\ti]}).
\end{split}
\end{align}

Suppose that, at observation time $t_i$, we have an evenly weighted set of samples of the distribution $\Pi_{i-1}$. 
The filtering step at $t_i$ then corresponds to targeting the measure $\Pi_i$ by an importance sampling scheme with proposal distribution $ \Q_i := \Pi_{i-1} \otimes \calL^{g_i}$. Samples from this proposal are drawn by forward propagating the given particles of $\Pi_{i-1}$ following the dynamics in \eqref{eq: dXg2} with IS weights given by $\Lambda_i$ in \eqref{eq: Lambda}.

\vspace{\baselineskip}
Now fix the observation time $t_i$ and drop the subscript $i$ to simplify notation. 
In state spaces of high dimension and/or the situation of highly informative observations, the proposal distribution $\Q$ might not be a sufficiently good approximation for the target $\Pi$.  

Tempering aims to overcome the distance between $\Pi$ and $\Q$ by introducing a sequence of intermediate distributions $\Pi^l$ between $\Pi$ and $\Q$ defined by 
\begin{align}
\label{eq: dPi^l}
	\dfrac{\df \Pi^l}{\df \Q}(X) \propto \Lambda(X)^{\psi_l}
\end{align}
for a set of inverse temperatures $0 = \psi_0 < \ldots < \psi_L = 1$.
Notably, we have absolute continuity of $\Pi^{l+1}$ with respect to $\Pi^l$ with R.N. derivative proportional to $ \Lambda(X)^{\psi_{l+1} - \psi_l}$. 
Instead of targeting $\Pi$ directly by $\Q$, one progressively steps through this sequence of artificial distributions, starting from $\Q$ to target the flattened $\Pi^1$ and ending up at targeting $\Pi$ with proposals drawn from $\Pi^{L-1}$.


Crucially, the parameters $\{ \psi_l \}_l$ can be chosen adaptively as follows. 
Given a set of evenly weighted particles of $\Pi^l$ at current inverse temperature $\psi_l$, the parameter $\psi_{l+1}$ is set by 
\begin{align*}
	\psi_{l+1} := \inf \{ \psi \in (\psi_l, 1] : \ESS_{l,l+1} \leq \alpha J \}
\end{align*}
with the definition of $\inf \O := 1$.
The hyperparameter $\alpha \in (0,1)$ is pre-specified by the user and $\ESS_{l,l+1}$ denotes the essential sample size of the weights $\Lambda(X)^{\psi_{l+1} - \psi_l}$ between $\Lambda^{l+1}$ and $\Lambda^l$. 

After $\Pi^{l+1}$ has been determined, particles are resampled based on the weights $\Lambda(X)^{\psi_{l+1} - \psi_l}$.
Subsequently, to increase particle diversity, each particle is moved by a few steps of an MCMC scheme that targets $\Pi^{l+1}$. 
This can be done by proposing independent samples from $\Q$ and accepting/rejecting the proposals in a Metropolis-Hastings step based on the likelihood in Equation \eqref{eq: dPi^l}.
Alternatively, proposals can be localised based on the preconditioned Crank-Nicolson scheme, see Section \ref{sec: guided_MCMC} for details. 
The complete \textit{tempering and move} procedure is summarised in Algorithm \ref{alg: tempering_steps}. 
It is to be carried out at each observation time $t_i$ in place of Steps $2.$ and $3.$ in Algorithm \ref{alg: guided_particle_filter}.


\vspace{\baselineskip}
\begin{algorithm}[b]
    %\SetAlgoNoLine
    \LinesNotNumbered  
    \label{alg: tempering_steps}
    \caption{Tempering and move steps at fixed observation time $t_i$}
    \KwIn{Samples $X^{(j)}$ of $\Q = \Pi_{i-1} \otimes \calL^{g_i}$ with weights $\Lambda(X^{(j)})$, hyperparameters $\alpha$ and $N$}
    \KwOut{Evenly weighted samples $X^{(j)}$ of $\Pi = \Pi_i$}
    Initialise $l = 0$ and $\psi_l = 0$\;
    \While{$\psi < 1$}{
        \textbf{1. Compute next $\psi$:} set $l \gets l + 1$ and
        \[ \psi_{l} = \inf \{ \psi \in (\psi_{l-1}, 1] : \ESS_{l-1, l} \leq \alpha J \}; \]
        \textbf{2. Specify $\Pi^l$ and resample:} 
        \begin{itemize}
        	\item[(i)]	Compute weights and normalise 
        	 \[ w_l^{(j)} \propto \Lambda(X^{(j)})^{\psi_{l} - \psi_{l-1}} \quad \text{s.t.} \sum_{j=1}^J w_l^{(j)} = 1 \]

        	\item[(ii)] Resample $\{X^{(j)}\}_{j=1}^J$ according to weights $w_{l}^{(j)}$\;

        \end{itemize}


        \textbf{3. Move particles:} \\
        \For{$j = 1$ \KwTo $J$}{
           \For{$n = 1$ \KwTo $N$}{
            (i) Sample guided proposal: $ X' \sim \Q $\;
            (ii) Compute $M = \min\left(1, \left( \dfrac{\Lambda(X')}{\Lambda(X^{(j)})} \right)^{\psi_l} \right)$\;

            (iii) Draw $U \sim \text{Unif}(0,1)$\; 
        	\quad \quad \If{$U < M $}{
      		\quad \quad Set $X^{(j)} = X'$\;}
        }
        }

   }
\end{algorithm}


\begin{remark}
For ease of exposition, the MCMC move step in Algorithm \ref{alg: tempering_steps} is presented using independent proposals drawn from $X' \sim \Q$. 
These proposals can be localised in Wiener space by using the preconditioned Crank-Nicolson scheme as is further explained in Section \ref{sec: guided_MCMC}.
For practical purposes, this implies having to store at the observation time $t_i$ for each particle $X^{(j)}$ the sample of the Wiener process $W$ that corresponds to simulating the sample path $X^{(j)}_{[\tim, \ti]}$ following the dynamics in \eqref{eq: dXg2}.
Note that this is still carried out in an online setting since the stored Wiener paths relate to the evolution on $[\tim, \ti]$ only and may hence be discarded after each complete filtering step.
\end{remark}






\section{Guided smoothing via Metropolis-Hastings sampling}
\label{sec: guided_MCMC}

The following section introduces a solution to the smoothing problem via a Metropolis-Hastings (MH) algorithm that targets the smoothing distribution $\calL^h(X)$ based on proposals drawn from the guided distribution $\calL^g(X)$. 


\subsection{The case of known $X_0$.}
Assume first that the initial distribution $\mu_0$ is given by a Dirac measure $\delta_{x_0}$ for some $x_0 \in H$. In that case, $X_0 = x_0$ remains unchanged under the changes of measure $\P^h$ and $\P^g$ and the Radon-Nikodym derivative in \eqref{eq: dPh_dPg} reduces to 
\begin{align*}
	\Phi(X) = \frac{g(0,x_0)}{h(0,x_0)} \Psi(X) 
\end{align*}
with $\Psi(X)$ as defined in Equation \eqref{eq: def_Psi}. A basic MH sampler that targets $\calL^h(X)$ can then be constructed by proposing samples from $\calL^g(X)$ and accepting or rejecting the proposals with an acceptance probability based on $\Phi(X)$. Note that $\Phi(X)$ includes the intractable term $h(0,x_0)$ which acts as a proportionality constant and cancels out in an MH acceptance step for a known $x_0$.

Sampling from $\calL^g(X)$ and evaluating $\Psi(X)$ relies on the function $G$. This function needs to be computed \textit{once} as a function of the complete set of observations on the basis of the backwards information filter in Equation \eqref{eq: g_BIF2}. Either of the parametrisations in Theorem \ref{thm: g_LtRtalphat} or Theorem \ref{thm: G_UtVt} can be used for this, though in practice the latter is usually the computationally favourable one. 

\vspace{\baselineskip}

To localise the proposals drawn from $\calL^g(X)$ we introduce random-walk-type proposals in the Wiener space by adapting a \textit{preconditioned Crank-Nicolson (pCN)} scheme (see \cite{Neal1999Regression}, \cite{Beskos08MCMC}, \cite{Cotter2013MCMC}) as follows.  

By Theorem \ref{thm: dPg}, drawing samples of $\calL^g(X)$ is equivalent to sampling the mild solution $X^g$ to Equation \eqref{eq: dXg}. 
The well-posedness of Equation \eqref{eq: dXg} implies the existence of a measurable map $\Gamma$ such that 
\begin{align}
\label{eq: solution_map}
	X^g = \Gamma(x_0, W), \quad \P^g\text{-a.s.,}
\end{align}
where $W$ is a $\P^g$-cylindrical Wiener process.
Assume now that the current value $X$ of the MH sampler is such that $X = \Gamma(x_0, V)$ for some process $V$. 
The pCN proposal is then given by:
\begin{itemize}
    \item[(i)] Draw a Wiener process $W$, independent of $V$;
    \item[(ii)] Set $V'= \sqrt{1 - \beta^2} V + \beta W$;
    \item[(iii)] Propose $X' = \Gamma(x_0, V')$.
\end{itemize}
The parameter $\beta \in (0,1]$ determines the size of the pCN step. For $\beta = 1$, independent proposals of $X^g$ are drawn.
The resulting MH sampler is given in Algorithm \ref{alg: MH_sampler1}.




\begin{algorithm}[t]
\label{alg: MH_sampler1}
\caption{MH Sampler of $\calL^h(X)$}
\LinesNotNumbered  
    \KwIn{Parameters $A,~F, ~Q$ and $x_0$, observations $y$, iterations $N, N_0$, step size $\beta$}
	\KwOut{Samples $\{X_i \}$ of $\calL^h(X)$ (after burn-in period $N_0$)}
	\textbf{Initialize:} \\
	Precompute $G$ by solving the backwards ODEs $(U_t)_{t \in [0,T]}$ and $(V_t)_{t \in [0,T]}$ in \eqref{eq: dU_t} and \eqref{eq: dV_t}\;

	Draw a Wiener process $V$ and set $X = \Gamma(x_0,V)$\;
	\For{$i = 0... ~N-1$}{
	 	\textbf{1. MH step in $X$} \\
                \quad(i) ~Draw a Wiener process $W$ and set $V'= \sqrt{1 - \beta^2} V + \beta W$\; 
            \quad(ii) Compute $X' = \Gamma(x_0,V')$ and $M = \min\left(1, \dfrac{\Psi(X')}{\Psi(X)} \right)$\;
            \quad(iii) Draw $U \sim \text{Unif}(0,1)$\; 
        \quad \quad \If{$U < M $}{
      \quad \quad Set $X = X'$ and $V = V'$\;
    }
 	\textbf{2. Save current state $X$} \\
    \quad \If{$i > N_0 $}{
      \quad \quad Set  $X_i = X$\;

    } 
  	}
\end{algorithm}

\begin{remark}
\label{rem: solution_map}
	Since $W$ is a cylindrical Wiener process on $H$, it cannot be treated directly as an $H$-valued process. However, $W$ can be defined as a Wiener process taking values in a larger Hilbert space $H'$ such that $H \hookrightarrow H'$ is embedded in a Hilbert-Schmidt way. Note that such an embedding always exists, see \cite{Hairer2009Introduction}, Section 4.4 for details.
	The solution map $\Gamma$ in \eqref{eq: solution_map} is then to be understood as a measurable mapping $\Gamma: H \times C([0,T];H') \to C([0,T];H)$. 

\end{remark}

\begin{remark}
\label{rem: bbV^x0}
	In the spirit of Remark \ref{rem: solution_map}, the MH sampler in Algorithm \ref{alg: MH_sampler1} can be rephrased as targeting a measure $\mathbb{V}^{x_0}$  that is absolutely continuous with respect to a Wiener measure $\mathbb{W}$ on $C([0,T];H')$. For this, let $V$ be a $\P^g$-cylindrical Wiener process on $H$, taking values in the enlargement $H'$ of $H$.
	 Note that the measures $\P^g$ and $\P^h$ depend on the fixed initial state $x_0$.
	Define $\mathbb{V}^{x_0} = \calL^h(V)$ as the law of $V$ under $\P^h$ on $C([0,T];H')$. It immediately follows that
	\begin{align}
	\label{eq: dV^x0}
		\dfrac{\df \mathbb{V}^{x_0}}{\df \mathbb{W}}(V) = \dfrac{\df \calL^h(V)}{\df \calL^g(V)}(V) = \Phi(\Gamma(x_0,V)) = \frac{g(0,x_0)}{h(0,x_0)} \Psi(\Gamma(x_0,V)). 
	\end{align}
	On the other hand, it holds for any bounded and measurable functional $f$ that 
	\begin{align*}
		\E^h\left[ f(\Gamma(x_0,V)) \right] &= \E^g[ f(\Gamma(x_0,V)) \Phi(\Gamma(x_0,V))] =  \E^g[ f(X) \Phi(X)] = \E^h[f(X)].
	\end{align*}
	Hence, $\mathbb{V}^{x_0}$ is the unique measure on $C([0,T];H')$ that is absolutely continuous with respect to $\mathbb{W}$ such that, if $V \sim \mathbb{V}^{x_0}$, then $\Gamma(x_0,V)$ equals in law the smoothing distribution of $X$ given $x_0$.
\end{remark}





\subsection{The case of unknown $X_0$.}
Let now $X_0$ be unknown with prior distribution $\mu_0$ and suppose the following assumption is satisfied.
\begin{assumption}
\label{ass: nu_0}
	There exists a Gaussian measure $\nu_0$ on $(H, \calB(H))$ such that $\mu_0 \ll \nu_0$ with density $\rho(x_0) := \tfrac{\df \mu_0}{\df \nu_0}(x_0)$.
\end{assumption}
A simple calculation shows that the conditional law $\mu_0^h = \calL^h(X_0)$ of $X_0$ given $Y=y$ remains absolutely continuous with respect to $\nu_0$ with density 
\begin{align}
\label{eq: dmu_0^h/dnu_0^h}
	\frac{\df \mu_0^h}{\df \nu_0}(x_0) = \frac{h(0,x_0) \rho(x_0)}{C^h}.
\end{align}
Alternatively, using Bayesian notation and recalling that $h(0,x_0) = p(y \mid x_0)$ and $C^h = \E[h(0,X_0)] = p(y)$, Equation \eqref{eq: dmu_0^h/dnu_0^h} is simply a restatement of the Bayes theorem. 



The decomposition $X = \Gamma(X_0,V)$ introduced in the previous section suggests to sample from the full smoothing distribution of $X$ by targeting the  joint measure $\mathbb{V}\otimes \mu_0^h$ defined through the disintegration $\mathbb{V}\otimes \mu_0^h := \mathbb{V}^{x_0}(\df V) \mu_0^h(\df x_0)$ on $C([0,T];H') \otimes H$. Sampling from the disintegrated measure corresponds to first sampling an initial state $X_0 = x_0$ given the observations $y$ and subsequently drawing a sample $V \sim \mathbb{V}^{x_0}$ of the measure $\mathbb{V}^{x_0}$ introduced in Remark \ref{rem: bbV^x0}. The sample $\Gamma(x_0,V)$ then represents a realisation from the smoothing distribution of $X$.

Plugging in the densities in \eqref{eq: dV^x0} and \eqref{eq: dmu_0^h/dnu_0^h} shows that $\mathbb{V}\otimes \mu_0^h$ is absolutely continuous with respect to $\mathbb{W} \otimes \nu_0$ with Radon–Nikodym derivative
\begin{align}
\label{eq: dVmu0dWnu0}
\dfrac{\df (\mathbb{V}\otimes \mu_0^h)}{\df (\mathbb{W} \otimes \nu_0) }(V, x_0) &= \dfrac{g(0,x_0) \rho(x_0)}{C^h} \Psi(\Gamma(x_0,V)).
\end{align}
This density can be used to construct a Gibbs sampler targeting $\mathbb{V}\otimes \mu_0^h$ as summarised in Algorithm \ref{alg: Gibbs_sampler1}. 



\begin{algorithm}[b]
\label{alg: Gibbs_sampler1}
\caption{Gibbs Sampler of $\mathbb{V}\otimes \mu_0^h$}
\LinesNotNumbered  
    \KwIn{Parameters $A,~F, ~Q$ and $\rho$, observations $y$, iterations $N, N_0$, step sizes $\beta, \beta_0$}
	\KwOut{Samples $\{(V,X_{0})_i \}$ of $\mathbb{V}\otimes \mu_0^h$ (after burn-in period $N_0$)}
	\textbf{Initialise:} \\
	Precompute $G$ by solving the backwards ODEs $(U_t)_{t \in [0,T]}$ and $(V_t)_{t \in [0,T]}$ in \eqref{eq: dU_t} and \eqref{eq: dV_t}\;

	Draw a Wiener process $V$ and $X_0 \sim \nu_0$\;
	\For{$i = 0... ~N-1$}{
 	\textbf{1. Update $V \mid X_0$} \\
                \quad(i) ~Draw a Wiener process $W$ and set $V'= \sqrt{1 - \beta^2} V + \beta W$ \; 
  			\quad(ii) ~Compute $M = \min\left(1, \dfrac{\Psi(\Gamma(X_0,V'))}{\Psi(\Gamma(X_0,V))} \right)$\;
			\quad(iii) Draw $U \sim \text{Unif}(0,1)$\; 
        \quad \quad \If{$U < M $}{
      \quad \quad Set  $V = V'$\;
    }
      \textbf{2. Update $X_0 \mid V$} \\
                \quad(i) ~Draw $z \sim \nu_0$ and set $X_0'= \sqrt{1 - \beta_0^2} X_0 + \beta_0 z$ \; 
  			\quad(ii) ~Compute $M = \min\left(1, \dfrac{\rho(X_0') g(0,X_0')  \Psi(\Gamma(X_0',V))}{\rho(X_0) g(0,X_0)  \Psi(\Gamma(X_0,V))} \right)$\;
			\quad(iii) Draw $U \sim \text{Unif}(0,1)$\; 
        \quad \quad \If{$U < M $}{
      \quad \quad Set  $X_0 = X_0'$\;
    }  
    \textbf{3. Save current state $(V, X_0)$} \\
    \quad \If{$i > N_0 $}{
      \quad \quad Set  $(V, X_0)_i = (V, X_0)$\;

    }  

  	}
\end{algorithm}





\subsection{Parameter estimation}
Suppose the parameters $A, F, Q$ and $\mu_0$ of the dynamics in Equation \eqref{eq: dXt} depend on some unknown parameter $\theta \in \R^p$. 
This dependence carries over to the majority of the processes and functions that we have discussed so far. 
However, for notational clarity, we only make this dependence explicit in certain cases by adding a subscript $\theta$ onto the dependent variables. 
In particular, let us highlight the dependence of the functions $h_{\theta}$, $g_{\theta}$ and $\Gamma_{\theta}$ as well as the measures $\mathbb{V}^{x_0}_{\theta}$ and $\mu_{0,\theta}$ on $\theta$. 


The unknown parameter $\theta$ is to be inferred jointly with the unobserved states of $X$, based on the observations $y$. Our methodology makes it natural to do so in a fully Bayesian approach. 
For this, assume that $\theta$ is the realisation of some $\calF_0$-measurable random variable $\Theta$ with Lebesgue density $\pi(\theta)$. With slight abuse of notation, denote by $\pi^y$ the conditional distribution of $\theta$ given $y$. 
We then aim to sample from the joint posterior measure defined by $\mathbb{V}\otimes \mu_0^h \otimes \pi^y := \mathbb{V}_{\theta}^{x_0}(\df V) \mu_{0,\theta}^{h_{\theta}}(\df x_0) \pi^y(\df \theta)$.
Following Equation \eqref{eq: dVmu0dWnu0} and the Bayes theorem, $\mathbb{V}\otimes \mu_0^h \otimes \pi^y$ has density with respect to $\mathbb{W}\otimes \nu_0 \otimes \text{Leb}(\R^p)$ given by 
\begin{align}
\begin{split}
\label{eq: full_posterior_density}
\frac{\df (\mathbb{V}\otimes \mu_0^h \otimes \pi^y)}{\df (\mathbb{W}\otimes \nu_0 \otimes \text{Leb}(\R^p))}(V, x_0, \theta) &= \dfrac{g_{\theta}(0,x_0) \rho_{\theta}(x_0)}{C^{h_{\theta}}} \Psi_{\theta}(\Gamma_{\theta}(x_0,V)) \dfrac{p(y \mid \theta) \pi(\theta)}{\int p(y \mid \theta) \pi(\theta) \df \theta} \\ 
&\propto g_{\theta}(0,x_0) \rho_{\theta}(x_0) \pi(\theta) \Psi_{\theta}(\Gamma_{\theta}(x_0,V)),
\end{split}
\end{align}
where we used that $C^{h_{\theta}} = \E[h_{\theta}(0,X_0)] = p(y \mid \theta)$.
An MCMC algorithm sampler that targets $\mathbb{V}\otimes \mu_0^h \otimes \pi^y$ can hence be defined by adding a Gibbs sampling step $\theta \mid V, x_0$ to Algorithm \ref{alg: Gibbs_sampler1}. The details are summarised in Algorithm \ref{alg: Gibbs_sampler2}.



\begin{algorithm}[t]
\label{alg: Gibbs_sampler2}
\caption{Gibbs Sampler of $\mathbb{V}\otimes \mu_0^h \otimes \pi^y$}
\LinesNotNumbered  
    \KwIn{Parameters $A_{\theta},~F_{\theta}, ~Q_{\theta}$ and $\rho_{\theta}$, observations $y$, prior $\pi$, proposal kernel $q$, \\ iterations $N, N_0$, step sizes $\beta, \beta_0$}
	\KwOut{Samples $\{(V,X_{0}, \theta)_i \}$ of $\mathbb{V}\otimes \mu_0^h \otimes \pi^y$ (after burn-in period $N_0$)}
	\textbf{Initialize:} \\
	Draw $\theta \sim \pi$, a Wiener process $V$ and $X_0 \sim \rho_{\theta} \df \nu_0$;\\
	Compute $G_{\theta}$ by solving the backwards ODEs $(U_t)_{t \in [0,T]}$ and $(V_t)_{t \in [0,T]}$ in \eqref{eq: dU_t} and \eqref{eq: dV_t}\;

	\For{$i = 0... ~N-1$}{
 	\textbf{1. Update $V \mid X_0, \theta$} \\
 	See Algorithm \ref{alg: Gibbs_sampler1}, Step 1 with $(\Psi, \Gamma) = (\Psi_{\theta}, \Gamma_{\theta})$;\\
    \textbf{2. Update $X_0 \mid V, \theta$} \\  
     See Algorithm \ref{alg: Gibbs_sampler1}, Step 2 with $(\rho_{\theta}, g_{\theta}, \Psi, \Gamma) = (\rho_{\theta}, g_{\theta}, \Psi_{\theta}, \Gamma_{\theta})$; \\
    \textbf{3. Update $\theta \mid X_0, V$} \\  
     \quad(i) ~Draw $\theta' \sim q(\cdot \mid \theta)$ \; 
    \quad(ii) ~If $A, Q$ depend on $\theta$: Compute $G_{\theta'}$ by solving Eq. \eqref{eq: dU_t} and Eq. \eqref{eq: dV_t};\\
    \quad(iii) ~Compute $M = \min\left(1, \dfrac{q(\theta \mid \theta') \pi(\theta') \rho_{\theta'}(X_0) g_{\theta'}(0,X_0)  \Psi_{\theta'}(\Gamma_{\theta'}(X_0,V))}{q(\theta' \mid \theta) \pi(\theta)  \rho_{\theta}(X_0) g_{\theta}(0,X_0) \Psi_{\theta}(\Gamma_{\theta}(X_0,V))} \right)$\;
			\quad(iii) Draw $U \sim \text{Unif}(0,1)$\; 
        \quad \quad \If{$U < M $}{
      \quad \quad Set  $\theta = \theta'$ and $G_{\theta} = G_{\theta'}$\;
    }
    \textbf{4. Save current state $(V, X_0, \theta)$} \\
    \quad \If{$i > N_0 $}{
      \quad \quad Set  $(V, X_0, \theta)_i = (V, X_0, \theta)$\;

    }  

  	}
\end{algorithm}

\begin{remark}
	If $A$ and $Q$ are independent of the unknown parameter $\theta$, one only needs to solve the backwards ODEs $(U_t)_{t \in [0,T]}$ and $(V_t)_{t \in [0,T]}$ in \eqref{eq: dU_t} and \eqref{eq: dV_t} once. 
	This severely eases the computational burden of Algorithm \ref{alg: Gibbs_sampler2} for the highly relevant case that the parameter $\theta$ of interest parametrises only the non-linearity $F = F_{\theta}$.
\end{remark}




\subsection{Non-Gaussian observations}
So far we have assumed the observations $Y_i$ given $X_{\ti}$ to be Gaussian with conditional density $k(X_{\ti}, \cdot) = f(\cdot; L X_{\ti}, \Sigma)$.
It is straightforward to let the kernel $k$ depend on the observation time $t_i$ by setting $k_i(X_{\ti}, \cdot) = f(\cdot; L_i X_{\ti}, \Sigma_i)$ for time varying observation operators $L_i: H \to \R^{m_i}$ and extrinsic noise matrices $\Sigma_i \in \R^{m_i \times m_i}$.

More crucially, our proposed methodology can be extended to the case of non-Gaussian observations in the following way. 
Let $l_i$ be some Markov kernel from $H$ to $\R^{m_i}$ and assume observations $Y_i$ are distributed following 
\begin{align}
\label{eq: ap192873}
	Y_i \mid X_{\ti} \sim l_i(X_{\ti}, \cdot).
\end{align}

Substituting $l_i(x_{\ti}, y_i)$ for $k(x_{\ti}, y_i)$ in the definition of the $h$-function in Equation \eqref{eq: def_h} preserves the properties of $h(t,x)$ established in Propositions \ref{prop: h_properties} and \ref{prop: Eht_martingale} as well as Theorem \ref{thm: dPh}.
Hence, the smoothing distribution of $X$ under the observation scheme in \eqref{eq: ap192873} is the law of $X$ under the change of measure 
\begin{align*}
	\dfrac{\df \P^h}{\df \P}(X) = E^h_T = \frac{1}{C^{h}} \left( \prod_{i=1}^{n} l_i(X_{\ti},y_i) \right)
\end{align*}
on $\calF_T$. 
For the guided distribution of $X$, the Markov kernel $k_i$ needs to remain Gaussian in order to preserve the tractable expressions for $g(t,x)$ obtained in Section \ref{sec: guided_measure}. It is therefore defined under the change of measure
\begin{align*}
	\dfrac{\df \P^g}{\df \P}(X) = E^g_T = \frac{1}{C^{g}} \left( \prod_{i=1}^{n} k_i(X_{\ti},y_i) \right) \Psi(X).
\end{align*}
In total, the R.N. derivative of the smoothing distribution with respect to the guided distribution then takes on the form 
\begin{align*}
	\Phi(X) = \frac{C^g}{C^h} \left( \prod_{i=1}^n \dfrac{l_i(X_{\ti}, y_i)}{k_i(X_{\ti}, y_i)} \right) \Psi(X).
\end{align*}



\section{Case study: stochastic Amari equation}
\label{sec: amari}

\subsection{Stochastic Amari equation}
In the following section, we evaluate our proposed methodology for filtering, smoothing, and parameter estimation in the context of a partially observed stochastic Amari model. 
For this, let $H = L^2(D)$ for some bounded spatial domain $D \subset \R^d$. For ease of exposition, we assume the domain $D$ to be rectangular and impose periodic boundary conditions on it.
Consider then the mild solution $X$ to the stochastic Amari equation
\begin{align}
\begin{split}
\label{eq: dX_Amari}
\df X_t &= \left[ - X_t + F(X_t) \right] \df t + Q^{\frac12} \df W_t, \quad  t \geq 0,\\ 
 \quad X_0 &= x_0,
\end{split}
\end{align}
with non-linearity $F: L^2(D) \to L^2(D)$ defined by 
\begin{align}
\label{eq: F_Amari}
F(X_t) &= \int_D k_F(\xi, \xi') f(X_t(\xi')) \df \xi'.
\end{align}
The process $X_t$ models a stochastic neural field on $D$, with $X_t(\xi)$ representing the average neural activity at location $\xi \in D$ and time $t \geq 0$. 

The kernel $k_F(\xi,\xi')$ captures neural connectivity between locations $\xi$ and $\xi'$, whereas $f$ is an activation function, typically a sigmoid-like function or similar. 
In our experiments, we consider 
\begin{align}
\label{eq: def_kf}
\begin{split}
		k_F(\xi, \xi') &= \frac{A}{\sqrt{\pi}} \exp\left( -(|\xi - \xi'| - \delta)^2 \right) - \frac{A}{\sqrt{\pi} B} \exp\left( -\left( \frac{|\xi - \xi'| - \delta}{B} \right)^2 \right) \\
		f(x) &= \frac{1}{1 + \exp\big(-\eta \, x + \zeta \big)} - \frac{1}{1 + \exp(\zeta)},
\end{split}
\end{align}
for a set of parameters $A >0, B >0, \eta >0, \zeta >0$ and $\delta \in \R$.

For the mild solution $X$ to exist, one may consider any trace-class operator $Q$ on $L^2(D)$. We let $Q$ be a diagonal operator defined by its eigenvalues 
\begin{align}
\label{eq: def_qj}
	q_l = \sigma_0^2 (\rho_0^{-2} + (2 \pi l)^2)^{-(d/2 + \eta_0)}
\end{align}
with respect to the Fourier basis functions $(e_l)_{l=1}^{\infty}$ on $L^2(D)$. The operator $Q$ is then the Hilbert-Schmidt integral operator defined by the Matérn kernel on $D$, see for example \cite{Borovitskiy2020Matern}, Theorem 5. 


\vspace{\baselineskip}


\paragraph{\bfseries Observation and guiding scheme}
We consider observations $Y_i \in \R^m$ of the latent process $X$ at observation times $(t_i)_{i=1}^n$ defined as in Eq. \eqref{eq: def_Y2}. The observation operator $L: L^2(D) \to \R^m$ we set as 
\begin{align}
\label{eq: def_L}
L x = \left( \int_D x(\xi) \om_j(\xi) \, \df \xi \right)_{j =1}^m = \left( \langle x, \om_j \rangle  \right)_{j =1}^m \in \R^m
\end{align}
for a set of positive, square-integrable functions $\om_j \in L^2(D), j = 1, \ldots m$.
The adjoint operator $L^*$ then takes the form 
\begin{align*}
	L^* y = \sum_{j=1}^m y_j \om_j \in L^2(D), \quad y \in \R^m.
\end{align*}
Specifically, we let $\om_j = \tfrac{1}{|D_j|}\mathbbm{1}_{D_j}$ for a series of mutually disjoint subsets $D_j \subset D$, $j =1 \ldots m$. The operator $L$ then represents observing localised spatial averages of $X_{t_i}(\xi)$ over the domains $D_j$ at observation time $t_i$.


