\vspace{\baselineskip}
To construct the guiding distribution, we set $(a_t)_{t \geq 0}$ in \eqref{eq: dZt} as $a_t \equiv 0$.
For the one-step ahead guiding distribution we receive the following closed-term expression. The computations can be found in Appendix \ref{app: B}.
\begin{proposition}
\label{prop: amari_G}
In the setup above, the guiding term $G_i$ of Eq. \eqref{eq: dXg2} at observation time $t_i$ is given by 
\begin{align*}
	G_i(t,x) &= \exp(- (t - t_i)) L^* \left( \Sigma + \frac{1 - \exp(- 2 (t - t_i))}{2} L Q L^* \right)^{-1} \left( y_i - \exp(-(t - t_i)) L x \right)\end{align*}
where $L Q L^*$ is the symmetric, positive definite $m \times m$-matrix with entries
\begin{align*}
	(L Q L^*)[i,j] = \sum_{l=1}^{\infty} q_l \langle \om_i, e_l \rangle \langle \om_j, e_l \rangle.
\end{align*}
\end{proposition}



\subsection{Filtering}

\paragraph{\bfseries Model setup}
For the filtering problem, we run two experiments with different choices $\delta_0 = 0$ and $\delta_1 = 0.5$ of the model parameter $\delta$. 
The remaining model parameters in \eqref{eq: def_kf} and \eqref{eq: def_qj} are set in both experiments as
\begin{align}
\label{eq: params}
	[A, B, \eta, \zeta, \sigma_0, \rho_0, \eta_0] = [4.0, 1.5, 10.0, 0.5, 3 \cdot 10^5, 5 \cdot 10^{-5}, 1.0]
\end{align}
and the initial state is set to be $X_0 \equiv 0$. Under this parametrisation, the stochastic Amari equation exhibits either steady state Turing patterns ($\delta_0 = 0$) or travelling waves ($\delta_1 = 0.5$) emerging from the initial state $X_0$. 

Experiments are carried out on data generated by forward simulating the solution $X$ to Equation \eqref{eq: dX_Amari} on the spatio-temporal domain $[0,T] \times D = [0,20] \times [-10 \pi, 10\pi]$ with step sizes $\Delta_t = 0.02$ and $\Delta_x = 20 \pi / 2^8$.
