\begin{proof}[Proof of Proposition \ref{prop: Eht_martingale}]
We first show that the function $h$ defined in \eqref{eq: def_h} is space-time harmonic on any time interval $(\tim,\ti]$, i.e. 
\begin{align}
\label{eq: hspacetimeharmonic}
    \E[ h(t, X_{t}) \mid X_s = x] &= h(s,x)
\end{align}
for any $x \in H$ and $s,t \in (\tim,\ti]$ such that $ s < t.$

Indeed, from plugging in \eqref{eq: def_h} and using the Chapman-Kolmogorov equation, it follows that 
\begin{align*}
    \E[ h(t, X_{t}) \mid X_s = x] &= \int h(t,x_t) \mu_{s,t}(x, \df x_t) \\
    &= \int k(x_{\ti}, y_i) \left( \prod_{j=i}^{n-1} k(x_{\tjp},y_{j+1}) \, \mu_{\tj,\tjp}(x_{\tj}, \df x_{\tjp}) \right) \mu_{s,t}(x, \df x_t) \mu_{t, \ti}(x_t, \df x_{\ti}) \\
    &= \int k(x_{\ti}, y_i) \left( \prod_{j=i}^{n-1} k(x_{\tjp},y_{j+1}) \, \mu_{\tj,\tjp}(x_{\tj}, \df x_{\tjp}) \right) \mu_{s,\ti}(x,\df x_{\ti}) \\
    &= h(s,x).
\end{align*}
This gives \eqref{eq: hspacetimeharmonic}.
To show that $E^h$ is a $\P$-martingale, first consider the case that $\tim < s < t \leq t_i$.
Then, by the Markov property of $X$, the definition of $E^h$ and the preceding display we have
\begin{align*}
    \E[ E^h_t \mid \calF_s] &= \frac{1}{C^h} \E\left[\left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) h(t,X_t) \mid \calF_s\right] \\
    &= \frac{1}{C^h} \prod_{j=1}^{i-1} k(X_{t_j},y_j)  \E \left[ h(t,X_t) \mid X_s \right] \\
    &= \frac{1}{C^h} \prod_{j=1}^{i-1} k(X_{t_j},y_j) h(s,X_s) = E^h_s.
\end{align*}

On the other hand, if $t_{i-2} < s \leq \tim < t \leq t_i$, then it holds that
\begin{align*}
    \E[ E^h_t \mid \calF_s] &= \frac{1}{C^h} \E\left[\left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) h(t,X_t) \mid \calF_s\right] \\ 
    &= \frac{1}{C^h} \left(\prod_{j=1}^{i-2} k(X_{t_j},y_j) \right) \E\left[  k(X_{\tim},y_{i-1})  h(t,X_t) \mid X_s\right] \\
    &= \frac{1}{C^h} \left(\prod_{j=1}^{i-2} k(X_{t_j},y_j) \right) \int k(x_{\tim},y_{i-1}) h(t,x_t) \,\mu_{s,\tim}(X_s, \df x_{\tim}) \mu_{\tim, t}(x_{\tim},\df x_t) \\
    &= \frac{1}{C^h} \left(\prod_{j=1}^{i-2} k(X_{t_j},y_j) \right) h(s,X_s) = E^h_s.
\end{align*}
Here, we use the Markov property of $X$ as well as the definition of $E^h_t$ in the first step and the $\calF_s$-measurability of $X_{t_j}, j \leq i-2$ in the second step. The last step follows by plugging in the definition of $h(t,x_t)$ and integrating out the latent variable $X_t$. The general case $s < t$ follows by the same arguments.

\end{proof}


\begin{proof}[Proof of Theorem \ref{thm: dPh}]
We begin by showing that $\P^h$ satisfies \eqref{eq: smoothingEh}. For the proof of this first claim, let us write $\P^{h,y}$ and $E^{h,y}$ to emphasise the dependence of the measure $\P^h$ and process $E^h$ on the observation $Y = y$.
To prove \eqref{eq: smoothingEh} it suffices to show that 
\begin{align}
\label{eq: aap918273}
    \E \left[ \E^{h,Y} \left[ \varphi(X_t) \right] \mathbbm{1}_{\{Y \in A\}} \right] &= \E[\varphi(X_t) \mathbbm{1}_{\{Y \in A\}}]
\end{align}
for any $A \in (\calB(\R^{k}))^n$ and bounded, measurable function $\varphi$ and $t \in [0,T].$
Without loss of generality let $t \in (\tim, \ti]$ for some $i \in \{1,\dots,n\}$.
Then indeed we have that
\begin{align*}
    \E \left[ \E^{h,Y} \left[ \varphi(X_t) \right] \mathbbm{1}_{\{Y \in A\}} \right] &= \int_A \E^{h,y} \left[ \varphi(X_t)  \right] p(y) \df y \\
    &= \int_A \E \left[ \varphi(X_t)  \frac{1}{C^{h,y}} \left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) h(t,X_t) \right] p(y) \, \df y \\
    &= \int_A \E \left[ \varphi(X_t)  \left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) h(t,X_t) \right]  \, \df y \\
    &= \E \left[ \varphi(X_t)  \int_A  \left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) h(t,X_t) \, \df y\right] \\
    &= \E \left[ \varphi(X_t)  \E \left[\mathbbm{1}_{\{Y \in A\}} \mid X_{t_1}, \dots, X_{\tim}, X_t \right] \right] \\
    &= \E \left[ \varphi(X_t) \mathbbm{1}_{\{Y \in A\}} \right].
\end{align*}
Here, we used in the second step the definition of $\P^{h,y}$ and the martingale property of $E^{h,y}_t$ and in the third step the equality $C^{h,y} = p(y)$. Moreover, we used Fubini's theorem in the fourth equality as well as the identity of $p(y \mid x_{t_1}, \dots, x_{t}) = \left( \prod_{j=1}^{i-1} k(x_{t_j},y_j) \right) h(t,x_t)$ as derived in Remark \ref{rem: prodkh_likelihood} in the second to last step.

We continue to prove the second claim of Theorem \ref{thm: dPh}. 
To do so, we show that the martingale $E^h_t$ defined in \eqref{eq: def_Eht} is given by 
\begin{align}
\label{eq: a1p092873}
E^{h}_t = \dfrac{h(0,X_0)}{C^h} \calE(M^h)_t, \quad t \in [0,T],
\end{align}
where $\calE(M^h)$ denotes the Doléans-Dade exponential of 
\begin{align*}
	M^h_t := \int_0^t \langle Q^{\frac12} \Df_x \log h(s,X_s), \df W_s \rangle, \quad t \in [0,T].
\end{align*}
The claim then follows by an application of the Girsanov theorem. 

Let first $t \in [0,t_1]$ and denote by $K$ the infinitesimal space-time generator of the Markov process $X$. 
Following \eqref{eq: hspacetimeharmonic}, it holds that $K h = 0$. 
From this and the Fréchet differentiability of $h$ in $x$ it follows with Lemma 3.3 in \cite{Piepersethmacher2025Class} that 
\begin{align*}
    h(t,X_t) = h(0,X_0) + \int_0^t \langle Q^{\frac12} \Df_x h(s,X_s), \df W_s \rangle, \quad t \in [0, t_1).
\end{align*}
Hence the process $\bar{h}(t,X_t) := h(t,X_t)/h(0,X_0)$ is the unique solution to 
\begin{align*}
\begin{cases}
        \df \bar{h}(t,X_t) &= \bar{h}(t,X_t) \df M^{h}_t \\
    \bar{h}(0,X_0) &= 1.
\end{cases}
\end{align*}
From this and the left-continuity of $h$ it follows that
\begin{align*}
    h(t,X_t) = h(0,X_0) \calE(M^{h})_t, \quad t \in [0,t_1].
\end{align*}
This, jointly with $E^h_t = h(t,X_t)/C^h, ~t \in [0,t_1],$ shows \eqref{eq: a1p092873} on $[0,t_1]$.
Now, let $t \in (\tim, \ti], i \geq 2,$ and assume \eqref{eq: a1p092873} holds for all $[0,\tim].$

Again, by the definition of $E^{h}$, Equation \eqref{eq: hspacetimeharmonic} and Lemma 3.3 in \cite{Piepersethmacher2025Class} we have that
\begin{align*}
    \df E^{h}_t &=  \frac{1}{C^{h}} \left( \prod_{j=1}^{i-1} k(X_{t_j},y_j) \right) \df h(t,X_t) \\
    &= \frac{1}{C^{h}} \left( \prod_{j=1}^{i-1} k(X_{t_j},y_i) \right) \langle Q^{\frac12} \Df_x h(t,X_t), \df W_t \rangle \\
    &= E^{h}_t \df M^{h}_t, \quad t \in (\tim,\ti).
\end{align*}

From this it is apparent that $\bar{E}^{h}_t := E^{h}_t/E^{h}_{\tim}$ solves 
\begin{align}
    \begin{cases}
        \df \bar{E}^{h}_t &= \bar{E}^{h}_t \df M^{h}_t, \quad t \in (\tim,\ti),  \\
    \df \bar{E}^{h}_{\tim} &= 1.
\end{cases}
\end{align}
It follows that 
\begin{align*}
    \bar{E}^h_t = \exp \left(\int_{\tim}^t \langle Q^{\frac12} \Df_x \log h(s,X_s), \df W_s \rangle  - \frac{1}{2} \int_{\tim}^t |\langle Q^{\frac12} \Df_x \log h(s,X_s)|^2 \, \df s \right)
\end{align*}
for all $t \in (\tim,\ti]$ and hence
\begin{align*}
E^h_t &= E^h_{\tim} \exp \left(\int_{\tim}^t \langle Q^{\frac12} \Df_x \log h(s,X_s), \df W_s \rangle  - \frac{1}{2} \int_{\tim}^t |\langle Q^{\frac12} \Df_x \log h(s,X_s)|^2 \, \df s \right) \\
&= \dfrac{h(0,X_0)}{C^h} \calE(M^h)_{\tim} \exp \left(\int_{\tim}^t \langle Q^{\frac12} \Df_x \log h(s,X_s), \df W_s \rangle  - \frac{1}{2} \int_{\tim}^t |\langle Q^{\frac12} \Df_x \log h(s,X_s)|^2 \, \df s \right)\\
&= \dfrac{h(0,X_0)}{C^h} \calE(M^h)_t.
\end{align*}
The claim in \eqref{eq: a1p092873} then follows inductively, thereby finishing the proof. 




\end{proof}


\subsection{Proofs of Section \ref{sec: guided_measure}}

\begin{proof}[Proof of Theorem \ref{thm: g_LtRtalphat}]

\textit{Step One.} We begin deriving $L_t, R_t$ and $\alpha_t$ on the interval $(\tnm,\tn]$.
By definition of $g$ in \eqref{eq: def_g}, we have $g(\tn,x) = k(x_n,y_n) = f(y_n ; L x, \Sigma)$.
Moreover, from the backwards recursion \eqref{eq: g_BIF2} it follows that 
\begin{align*}
        g(t,x) &= \int f(y_n ; L x_{\tn}, \Sigma)\, \nu_{t,\tn}(x, \df x_{\tn}) \\
        &= \int f(y_n ; \xi, \Sigma) f\left(\xi; L S_{t_n-t}x + L \int_t^{t_n} S_{t_n-s} a_s \, \df s, L Q_{t_n-t} L^*\right)\, \df \xi \\% \nu_{t,\tn}(x, \df x_{\tn}) \\
        &= \int f(y_n ; \xi, \Sigma) f\left(\xi; L_t x + \alpha_t, L Q_{t_n-t} L^*\right)\, \df \xi.
\end{align*}
Here we use in the second equality that $\xi = Lx_{\tn}$ under $\nu_{t,\tn}(x, \df x_{\tn})$ is a Gaussian measure on $\R^m$ with mean 
\begin{align*}
    L S_{t_n-t}x + L \int_t^{t_n} S_{t_n-s} a_s \, \df s = L_t x + \alpha_t
\end{align*}
and covariance matrix $L Q_{t_n-t} L^*$. Now, integrating out the latent Gaussian variable $\xi$ gives
\begin{align*}
    g(t,x) = f(y_n; L_t x + \alpha_t, \Sigma + L Q_{t_n-t} L^*) = f(y_n; L_t x + \alpha_t, R_t),
\end{align*}
with $L_t$, $\alpha_t$ and $R_t$ as defined in \eqref{eq: def_Lt} and \eqref{eq: def_Rt_alphat}.

\textit{Step Two.} 
Consider $g(\tnm,x)$ evaluated at the observation time $\tnm$. From the second equality in the backwards recursion \eqref{eq: g_BIF2} it follows that
\begin{align*}
    g(\tnm,x) = k(y_{n-1},x) \, g^+(\tnm,x) = f(y_{n-1}; L x, \Sigma) \,f(y_n; L^+_{\tnm} + \alpha^+_{\tnm}, R^+_{\tnm}).
\end{align*}
Expanding the Gaussian densities on the right-hand side and simple algebra gives that
\begin{align*}
    g(\tnm,x) &= f(y_{n-1}^+; L_{\tnm} x + \alpha_{\tnm}, R_{\tnm}) 
\end{align*}
with 
\begin{align*}
    L_{\tnm} &= \begin{bmatrix}  L  \\  L^+_{\tnm}\end{bmatrix}, \,
    R_{\tnm} = \begin{bmatrix} 
\Sigma & 0 \\
0 & R^+_{\tnm} \\ 
\end{bmatrix}, \,
\alpha_{\tnm} = \begin{bmatrix}  0 \\ \alpha^+_{\tnm} \end{bmatrix}.
\end{align*}

\textit{Step Three.}
The general claim follows by repeating the backwards recursion of the first two steps to obtain $g(t,x)$ on the complete interval $[0,t_n].$
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm: dPg}]
The proof of Theorem \ref{thm: dPg} follows roughly the same structure as the second part of the proof of Theorem \ref{thm: dPh}.
We show that $E^g$ as defined in Eq. \eqref{eq: def_Egt} equals the Doléans-Dade exponential
\begin{align}
\label{eq: ap912783987p123}
	E^g_t = \frac{g(0,X_0)}{C^g}\calE(M^g)_t, \quad t \in [0,T],
\end{align}
of the martingale $M^g_t := \int_0^t \langle Q^{\frac12} G(s,X_s), \df W_s \rangle$. If $\calE(M^g)_t$ is then a $\P$-martingale, Theorem \ref{thm: dPg} follows from an application of the Girsanov theorem. 

First note that, following Theorem \ref{thm: g_LtRtalphat}, $g(t,x)$ is bounded, continuous and Fréchet differentiable in $x$ on any interval $(\tim, \ti)$ with 
\begin{align*}
	\Df_x g(t,x) = g(t,x) \Df_x \log g(t,x) = g(t,x) G(t,x). 
\end{align*}
Hence, denoting by $K$ the infinitesimal space-time generator of $X$, it follows from \cite{Manca2009Fokker}, Theorem 4.1 that $K g(t,x) = \langle F(t,x), \Df_x g(t,x) \rangle$. Lemma 3.3 of \cite{Piepersethmacher2025Class} therefore gives that 
\begin{align}
\label{eq: ap918273123123}
g(t,X_t) = g(0,X_0) + \int_0^t \langle  F(s,X_s), \Df_x g(s,X_s) \rangle \df s + \int_0^t \langle Q^{\frac12} \Df_x g(s,X_s), \df W_s \rangle, \quad t \in [0,t_1). 
\end{align}
Consequently, plugging in $E^g$ as in \eqref{eq: def_Egt} and applying the integration by parts for semimartingales we have on $[0,t_1)$ that
\begin{align*}
\df E^g_t &= \dfrac{1}{C^g} \df \left( g(t,X_t)  \exp \left(- \int_0^t \langle F(s,X_s), G(s,X_s) \rangle \, \df s \right) \right) \\
&=\dfrac{1}{C^g}   \exp \left(- \int_0^t \langle F(s,X_s), G(s,X_s) \rangle \, \df s \right)\left[ \langle F(t,X_t), \Df_x g(t,X_t) \rangle \df t  + \langle Q^{\frac12} \Df_x g(t,X_t), \df W_t \rangle \right] \\
&\quad - \dfrac{1}{C^g} g(t,X_t) \exp \left(- \int_0^t \langle F(s,X_s), G(s,X_s) \rangle \, \df s \right)  \langle F(t,X_t), G(t,X_t) \rangle \, \df t \\
&= \dfrac{1}{C^g}   \exp \left(- \int_0^t \langle F(s,X_s), G(s,X_s) \rangle \, \df s \right) \langle Q^{\frac12} \Df_x g(t,X_t), \df W_t \rangle \\
&= \dfrac{g(t,X_t)}{C^g}   \exp \left(- \int_0^t \langle F(s,X_s), G(s,X_s) \rangle \, \df s \right) \langle Q^{\frac12}  G(t,X_t), \df W_t \rangle \\
&= E^g_t \df M^g_t.
\end{align*}
This shows that $\bar{E}^g_t := E^g_t / E^g_0 = \calE(M^g)_t$ and hence \eqref{eq: ap912783987p123} for all $t \in [0,t_1]$. The extension onto the complete time interval $[0,T]$ follows by the same inductive argument as in the proof of Theorem \ref{thm: dPh}.
Lastly, to show that $\calE(M^g)$ is a proper martingale, it suffices to note that $x \mapsto G(t,x)$ is Lipschitz continuous in $x$, uniformly on $[0,T]$. The martingale property of $\calE(M^g)$ then follows from \cite{Piepersethmacher2025Class}, Lemma C.1.
\end{proof}



