\section{Proof}\label{proof}

\pfof{Proposition \ref{prop:Vc_property}}
The boundedness of $V_c(x)$ is straightforward from the boundedness of $l_t$ and $r_t$, that is,
\begin{align*}
V_c(x) \leq \expect\left[\int_0^\infty e^{-\rho t} \bar l dt \right] = \frac{\bar l}{\rho}, \;
V_c(x) \geq \expect\left[\int_0^\infty e^{-\rho t} (-\phi \bar r) dt \right] = - \frac{\phi \bar r}{\rho}.
\end{align*}

Next, we show the concavity of $V_c(x)$. Let ${\bf u}^{(1)}$ and ${\bf u}^{(2)}$ be optimal strategies given initial surplus level $x_1$ and $x_2$ respectively. For $\lambda \in [0, 1]$, we define a strategy as $u^{\xi}_t := \lambda u^{(1)}_t + (1-\lambda)u^{(2)}_t$. Given initial surplus $X^{{\bf u}^{\xi}}_0 = \lambda x_1 + (1-\lambda) x_2$, according to \eqref{eq:surplus_process}, the controlled surplus process should evolve like
\begin{align*}
X_t^{{\bf u}^{\xi}} &= (\mu - \lambda l^{(1)}_t - (1-\lambda)l^{(2)}_t + \lambda r^{(1)}_t + (1-\lambda)r^{(2)}_t )dt+ \sigma dW_t\\
&=  \lambda \left[(\mu - l^{(1)}_t + r^{(1)}_t )dt+ \sigma dW_t\right] + (1-\lambda) \left[(\mu - l^{(2)}_t + r^{(2)}_t )dt+ \sigma dW_t\right]\\
&= \lambda X_t^{{\bf u}^{(1)}} + (1-\lambda) X_t^{{\bf u}^{(2)}}.
\end{align*}
Thus, $\tau_{0, \lambda x_1 + (1-\lambda) x_2}^{{\bf u}^{\xi}} = \tau_{0, x_1}^{{\bf u}^{(1)}} \vee \tau_{0, x_2}^{{\bf u}^{(2)}}$. Then the objective function corresponding to strategy ${\bf u}^{\xi}$ could be written as
\begin{align*}
& J_c(\lambda x_1 + (1-\lambda) x_2, {\bf u}^{\xi})\\
=& \expect\left[\int_0^{\tau_{0, x_1}^{{\bf u}^{(1)}} \vee \tau_{0, x_2}^{{\bf u}^{(2)}}} e^{-\rho t} \left(\lambda l^{(1)}_t + (1-\lambda)l^{(2)}_t - \phi \lambda r^{(1)}_t - \phi (1-\lambda)r^{(2)}_t \right) dt \right]\\
=&  \lambda \expect\left[\int_0^{\tau_{0, x_1}^{{\bf u}^{(1)}}} e^{-\rho t} \left(l^{(1)}_t - \phi r^{(1)}_t \right) dt \right] + (1-\lambda) \expect\left[\int_0^{\tau_{0, x_2}^{{\bf u}^{(2)}}} e^{-\rho t} \left(l^{(2)}_t - \phi r^{(2)}_t \right) dt \right]\\
=& \lambda V_c(x_1) + (1-\lambda) V_c(x_2).
\end{align*}
Therefore, we conclude that
\begin{align*}
V_c(\lambda x_1 + (1-\lambda) x_2) \geq J_c(\lambda x_1 + (1-\lambda) x_2, {\bf u}^{\xi}) = \lambda V_c(x_1) + (1-\lambda) V_c(x_2).
\end{align*}

Finally, to show the limit of $V_c$, we consider a constant strategy $\tilde u_t = (\tilde l_t, \tilde r_t) := (\bar l, 0)$, and the corresponding objective function is
\begin{align*}
J_c(x,{\bf \tilde u}) = \expect\left[\int_0^{\tau_{0, x}^{\bf \tilde u}} e^{-\rho t} \left(\tilde l_t - \phi \tilde r_t \right) dt \right] = \expect\left[\int_0^{\tau_{0, x}^{\bf \tilde u}} e^{-\rho t} \bar l dt \right].
\end{align*}
Therefore, by definition of value function:
\begin{align*}
V_c(x) \geq J_c(x,{\bf \tilde u}) = \expect\left[\int_0^{\tau_{0, x}^{\bf \tilde u}} e^{-\rho t} \bar l dt \right].
\end{align*}
Taking limit on both sides of the above inequality and by bounded convergence theorem,
$$
\lim_{x\to\infty} V_c(x) \geq \lim_{x\to\infty} \expect\left[\int_0^{\tau_{0, x}^{\bf \tilde u}} e^{-\rho t} \bar l dt \right] = \int_0^{\infty} e^{-\rho t} \bar l dt = \frac{\bar l}{\rho}.
$$
Combined with the fact we proved above, which states that $V_c$ is upper bounded by $\frac{\bar l}{\rho}$, we then reach the conclusion that $\lim_{x\to\infty} V_c(x) = \frac{\bar l}{\rho}$.
\qed


