\begin{lemma}\label{lemma:thetas_equivalent}
Given $\theta_3$, $\theta_4$, $\theta_5$ defined in \eqref{eq:thetas}, the following statements are equivalent:
$$
(i)\ \frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0;\quad (ii)\ \theta_5 > \theta_3 + \theta_4; \quad (iii)\ \bar l > \frac{1}{2} \frac{\rho \sigma^2}{\mu}.
$$
\end{lemma}

\begin{proof}
First, we show that $(i)$ is equivalent to $(iii)$. Note that $\frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0$ indicates $\theta_5 < -\rho/\bar l$, where $\theta_5$ is given in \eqref{eq:thetas}. By the definition of $\theta_5$, the inequality is equivalent to $-\mu + \bar l + \rho \sigma^2 /\bar l < \sqrt{(\mu-\bar l)^2 + 2 \rho \sigma^2}$. Taking square on both sides of the inequality, we obtain that $2\mu \bar l > \rho \sigma^2$.

If $(ii)$ holds, then $\theta_3+\theta_4 = -2\mu/\sigma^2 < \theta_5$. By the definition of $\theta_5$, $\mu+\bar l > \sqrt{(\mu-\bar l)^2 + 2 \rho \sigma^2}$. Taking square on both sides leads to $(iii)$, which completes our proof.
\end{proof}




\begin{lemma}\label{lemma:thetas_imply}
Given $\theta_i$ defined in \eqref{eq:thetas}, if $\ln\phi < \frac{1}{\theta4-\theta3} \left( \theta_4 \ln\frac{\theta_5-\theta_4}{\theta_3} + \theta_3 \ln\frac{-\theta_4}{\theta_3-\theta_5} \right)$, then $\frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0$.
\end{lemma}

\begin{proof}
Since $\phi$ is defined to be greater than $1$, we have $\frac{1}{\theta4-\theta3} \left(\theta_4 \ln\frac{\theta_5-\theta_4}{\theta_3} + \theta_3 \ln\frac{-\theta_4}{\theta_3-\theta_5} \right) > \ln\phi > 0$, that is,
\begin{equation}\label{ineq:thetas_imply}
\theta_4 \ln\frac{\theta_5-\theta_4}{\theta_3} + \theta_3 \ln\frac{-\theta_4}{\theta_3-\theta_5} < 0.
\end{equation}
Suppose $\theta_5 < \theta_3 + \theta_4$, then $0 < (\theta_5-\theta_4)(\theta_3-\theta_5) = \theta_5 (\theta_3 + \theta_4 - \theta_5) - \theta_3 \theta_4 < - \theta_3 \theta_4$. Dividing $\theta_3 (\theta_3 - \theta_5)$ on both sides of the above inequality leads to $0 < \frac{\theta_5-\theta_4}{\theta_3} < \frac{-\theta_4}{\theta_3 - \theta_5}$, and $\frac{-\theta_4}{\theta_3 - \theta_5} < 1$ is directly obtained from $\theta_5 < \theta_3 + \theta_4$, hence $\ln\frac{\theta_5-\theta_4}{\theta_3} < \ln\frac{-\theta_4}{\theta_3-\theta_5} < 0$. Combined with $\theta_4 < -\theta_3$, it can be derived that $\theta_4 \ln\frac{\theta_5-\theta_4}{\theta_3} > \theta_4 \ln\frac{-\theta_4}{\theta_3-\theta_5} > -\theta_3 \ln\frac{-\theta_4}{\theta_3-\theta_5}$, which is a contradiction with \eqref{ineq:thetas_imply}. Therefore, it requires $\theta_5 > \theta_3 + \theta_4$, and according to Lemma \ref{lemma:thetas_equivalent}, it is equivalent to have $\frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0$. So the inequality $\ln\phi < \frac{1}{\theta4-\theta3} \left( \theta_4 \ln\frac{\theta_5-\theta_4}{\theta_3} + \theta_3 \ln\frac{-\theta_4}{\theta_3-\theta_5} \right)$ implies that $\frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0$.
\end{proof}




Define an auxiliary function
\begin{equation}\label{eq:f_c}
f_c(x) := \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \left(\frac{e^{\theta_1 x} - e^{\theta_2 x} + \frac{\bar r}{\rho} (\theta_1-\theta_2) e^{(\theta_1+\theta_2) x}}{\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x}} -\frac{\bar r}{\rho} - \frac{1}{\theta_3}\right), \qquad x\in[0, \infty),
\end{equation}
where $\theta_i$ is given in \eqref{eq:thetas}.

\begin{lemma}\label{lemma:f_c}
Given function $f_c$ defined in \eqref{eq:f_c}, it satisfies the following properties:
\begin{enumerate}
\item[(i)] $f_c(0) = \frac{-\theta_4}{\theta_3 - \theta_5} \phi > \lim_{x\to\infty} f_c(x) = \frac{\theta_3 - \theta_1}{\theta_3 - \theta_5} \phi$;
\item[(ii)] there exists an unique $x^* \in (0, \infty)$ such that $f_c(x)$ decreases on $x \in [0, x^*]$ and then increases on $x\in[x^*, \infty)$.
\end{enumerate}
\end{lemma}


\begin{proof}
We first show $(i)$. It is obvious that $f_c(0) = \frac{-\theta_4}{\theta_3 - \theta_5} \phi$, and
\begin{align*}
\lim_{x\to\infty} f_c(x) &= \lim_{x\to\infty} \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \left(\frac{e^{\theta_1 x} - e^{\theta_2 x} + \frac{\bar r}{\rho} (\theta_1-\theta_2) e^{(\theta_1+\theta_2) x}}{\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x}} -\frac{\bar r}{\rho} - \frac{1}{\theta_3}\right)\\
&= \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \left(\frac{1}{\theta_1} - \frac{1}{\theta_3} - \frac{\bar r}{\rho}\right)\\
&= \frac{\phi}{\theta_3 - \theta_5} \left(\theta_2 - \theta_4 + \frac{2 \bar r}{\sigma^2}\right)\\
&= \frac{\phi}{\theta_3 - \theta_5} \left(\theta_2 - \theta_4 + \theta_3 + \theta_4 - \theta_1 - \theta_2\right) = \frac{\theta_3 - \theta_1}{\theta_3 - \theta_5} \phi > 0,
\end{align*}
where the third equality holds because $\theta_1\theta_2 = \theta_3\theta_4 = -\frac{2\rho}{\sigma^2}$, and the fourth due to $\theta_3 + \theta_4 - (\theta_1 + \theta_2) = \frac{2 \bar r}{\sigma^2}$. $f_c(0) > \lim_{x\to\infty} f_c(x)$ follows from $\theta_3 + \theta_4 - \theta_1 < 0$.

To show the monotonicity of $f_c$, taking the derivative leads to
\begin{align*}
f_c^\prime(x) &= \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \frac{\left(\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x}\right)^2 + \frac{\bar r}{\rho} (\theta_1^2-\theta_2^2) e^{(\theta_1+\theta_2) x} \left(\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x}\right)}{\left(\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x}\right)^2}\\
& \quad - \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \frac{\left(e^{\theta_1 x} - e^{\theta_2 x}\right) \left(\theta_1^2 e^{\theta_1 x} - \theta_2^2 e^{\theta_2 x}\right) + \frac{\bar r}{\rho} (\theta_1-\theta_2) e^{(\theta_1+\theta_2) x} \left(\theta_1^2 e^{\theta_1 x} - \theta_2^2 e^{\theta_2 x}\right)}{\left(\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x}\right)^2}\\
&= \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \frac{(\theta_1 - \theta_2)^2 e^{(\theta_1+\theta_2) x} + \frac{\bar r}{\rho} \theta_1\theta_2 (\theta_1 - \theta_2) \left(e^{\theta_1 x} - e^{\theta_2 x}\right) e^{(\theta_1+\theta_2) x}}{\left(\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x}\right)^2}\\
&= \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \frac{(\theta_1 - \theta_2) e^{(\theta_1+\theta_2) x} \left(\theta_1 - \theta_2 + \frac{\bar r}{\rho} \theta_1\theta_2 \left(e^{\theta_1 x} - e^{\theta_2 x}\right) \right)}{(\theta_1 e^{\theta_1 x} - \theta_2 e^{\theta_2 x})^2}.
\end{align*}
It is obvious that $f_c^\prime(x) < 0$ for $x \in [0, x^*)$ and $f_c^\prime(x) > 0$ for $x \in (x^*, \infty)$, with $x^*$ satisfying $\theta_1 - \theta_2 + \frac{\bar r}{\rho} \theta_1\theta_2 \left(e^{\theta_1 x^*} - e^{\theta_2 x^*}\right) = 0$.
\end{proof}

Define
\begin{equation}\label{eq:g_c}
g_c(x) := (\theta_4 - \theta_5) \left(f_c(x)\right)^\frac{\theta_3}{\theta_4} - (\theta_3 - \theta_5) f_c(x) + (\theta_3 - \theta_4) \phi, \qquad x\in\mathcal{O},
\end{equation}
where $f_c$ is defined in \eqref{eq:f_c} and $\mathcal{O} := \{x\in[0, \infty): f_c(x) \geq 1\}$.

\begin{lemma}\label{lemma:g_c}
$g_c(x)$ is defined in \eqref{eq:g_c} with domain $\mathcal{O}$. The monotonicity of $g_c$ is classified into the following cases based on the properties of $f_c$ given in Lemma \ref{lemma:f_c}:
\begin{enumerate}
\item[(i)] $\mathcal{O} = \emptyset$;
\item[(ii)] $\mathcal{O} = [0, \tilde{x}]$ for some $\tilde{x}\in[0, x^*)$: $g_c(x)$ is monotonically increasing in $[0, \tilde{x}]$, with $g_c(\tilde{x}) > 0$;
\item[(iii)] $\mathcal{O} = [0, \underline{x}] \cup [\bar x, \infty)$ for some $(\underline{x}, \bar x) \in [0,  x^*) \times (x^*, \infty)$:  $g_c(x)$ is increasing in $ [0, \underline{x}]$ and decreasing in $[\bar x, \infty)$, with $g_c(\underline{x}) = g_c(\bar{x}) > 0$ and $\lim_{x\to\infty} g_c(x) > 0$;
\item[(iv)] $\mathcal{O} = [0, \infty)$: $g_c(x)$ is increasing in $ [0, x^*]$ and decreasing in $[x^*, \infty)$, with $\lim_{x\to\infty} g_c(x) > 0$,
\end{enumerate}
where $x^*$ is solved from $f^\prime(x^*) = 0$.
\end{lemma}

\begin{proof}
First, if $f_c(x) = 1$, it is straightforward that $g_c(x) = (\theta_3 - \theta_4)(\phi - 1) > 0$ because of $\phi > 1$. Considering the monotonicity of $f_c(x)$ and the definition of $\mathcal{O}$, we must have $f(\tilde{x}) = f(\underline{x}) = f(\bar x) = 1$, thus $g_c(\tilde{x}) = g_c(\underline{x}) = g_c(\bar{x}) > 0$. To obtain the monotonicity of $g_c$, taking the first order derivative leads to
$$
g_c^\prime(x) = \left(\frac{\theta_3(\theta_4 - \theta_5)}{\theta_4} \left(f_c(x)\right)^{\frac{\theta_3}{\theta_4} -1} - (\theta_3 - \theta_5)\right) f^\prime_c(x), \qquad x \in  \mathcal{O}.
$$
Since $f_c(x) \geq 1$ for $x \in  \mathcal{O}$ and $\frac{\theta_3}{\theta_4} - 1 < 0$, we find that $\left(f_c(x)\right)^{\frac{\theta_3}{\theta_4} -1} < 1$, and
$$
\frac{\theta_3(\theta_4 - \theta_5)}{\theta_4} \left(f_c(x)\right)^{\frac{\theta_3}{\theta_4} -1} - (\theta_3 - \theta_5) < \frac{\theta_3(\theta_4 - \theta_5) - \theta_4 (\theta_3 - \theta_5)}{\theta_4} = \frac{(\theta_4-\theta_3) \theta_5}{\theta_4} < 0.
$$
For case $(ii)$, we have $f^\prime(x) < 0$ for $x \in [0, \tilde{x})$, thus $g_c^\prime(x) > 0$ for $x \in  \mathcal{O}$, which indicates that $g_c$ is monotonically increasing in $x$. Similarly for case $(iii)$, since $f^\prime(x) < 0$ for $x \in [0, \underline{x})$ and $f^\prime(x) > 0$ for $x \in (\bar x, \infty)$, we obtain that $g_c^\prime(x) > 0$ for $x \in [0, \underline{x})$ and $g^\prime(x) < 0$ for $x \in (\bar x, \infty)$. For case $(iv)$, as Lemma \ref{lemma:f_c} shows that $f^\prime(x) < 0$ for $x \in [0, x^*)$ and $f^\prime(x) > 0$ for $x \in (x^*, \infty)$, which implies that $g^\prime(x) > 0$ for $x \in [0, x^*)$ and $g^\prime(x) < 0$ for $x \in (x^*, \infty)$.

Note that in both case $(iii)$ and $(iv)$, $\lim_{x\to\infty} f_c(x) = \frac{\theta_3 - \theta_1}{\theta_3 - \theta_5} \phi > 1$, which implies that
\begin{equation}\label{ineq:lnphi_lb}
\ln \phi > \ln \frac{\theta_3 - \theta_5}{\theta_3 - \theta_1}.
\end{equation}

Suppose that $\lim_{x\to\infty} g_c(x) = (\theta_4 - \theta_5) \left(\frac{\theta_3 - \theta_1}{\theta_3 - \theta_5} \phi\right)^\frac{\theta_3}{\theta_4} + (\theta_1 - \theta_4) \phi < 0$. Rearranging the inequality leads to
\begin{equation}\label{ineq:lnphi_ub}
\ln\phi< \frac{\theta_4}{\theta_4 - \theta_3}  \ln\frac{\theta_5 - \theta_4}{\theta_1 - \theta_4} + \frac{\theta_3}{\theta_4 - \theta_3} \ln\frac{\theta_3 - \theta_1}{\theta_3 - \theta_5}.
\end{equation}
Combining the upper bound \eqref{ineq:lnphi_ub} with the lower bound \eqref{ineq:lnphi_lb},
\begin{equation}\label{ineq:lnphi_diff}
\ln \frac{\theta_3 - \theta_5}{\theta_3 - \theta_1} < \frac{\theta_4}{\theta_4 - \theta_3}  \ln\frac{\theta_5 - \theta_4}{\theta_1 - \theta_4} + \frac{\theta_3}{\theta_4 - \theta_3} \ln\frac{\theta_3 - \theta_1}{\theta_3 - \theta_5}.
\end{equation}
However,
\begin{align}\label{eq:lnphi_diff}
&\ln \frac{\theta_3 - \theta_5}{\theta_3 - \theta_1} - \frac{\theta_4}{\theta_4 - \theta_3}  \ln\frac{\theta_5 - \theta_4}{\theta_1 - \theta_4} - \frac{\theta_3}{\theta_4 - \theta_3} \ln\frac{\theta_3 - \theta_1}{\theta_3 - \theta_5}\notag\\
=& \frac{\theta_4}{\theta_4 - \theta_3} \left(\ln \frac{\theta_3 - \theta_5}{\theta_3 - \theta_1} - \ln\frac{\theta_5 - \theta_4}{\theta_1 - \theta_4}\right)\notag\\
=& \frac{\theta_4}{\theta_4 - \theta_3} \ln \frac{(\theta_3 - \theta_5)(\theta_1 - \theta_4)}{(\theta_3 - \theta_1)(\theta_5 - \theta_4)},
\end{align}
where
\begin{align*}
\frac{(\theta_3 - \theta_5)(\theta_1 - \theta_4)}{(\theta_3 - \theta_1)(\theta_5 - \theta_4)} - 1&= \frac{(\theta_3 - \theta_5)(\theta_1 - \theta_4) - (\theta_3 - \theta_1)(\theta_5 - \theta_4)}{(\theta_3 - \theta_1)(\theta_5 - \theta_4)}\\
&= \frac{(\theta_1-\theta_5)(\theta_3 - \theta_4)}{(\theta_3 - \theta_1)(\theta_5 - \theta_4)} > 0.
\end{align*}
Substituting the above inequality into \eqref{eq:lnphi_diff}, we have
$$
\ln \frac{\theta_3 - \theta_5}{\theta_3 - \theta_1} - \frac{\theta_4}{\theta_4 - \theta_3}  \ln\frac{\theta_5 - \theta_4}{\theta_1 - \theta_4} - \frac{\theta_3}{\theta_4 - \theta_3} \ln\frac{\theta_3 - \theta_1}{\theta_3 - \theta_5} > 0,
$$
which contradicts with \eqref{ineq:lnphi_diff}. Thus we conclude that when $\lim_{x\to\infty} f_c(x) > 1$, $\lim_{x\to\infty} g_c(x) > 0$.
\end{proof}


\pfof{Proposition \ref{thm:xrxl}}
First, using expression $V_c(x_l) = \frac{\bar l}{\rho} + A_4 e^{\theta_5 x_l}$ and $V_c^\prime(x_l) = 1$, it can be obtained that $A_4 = \frac{1}{\theta_5} e^{-\theta_5 x_l}$, thus $V_c(x_l) = \frac{\bar l}{\rho} + \frac{1}{\theta_5}$ and $V^{\prime\prime}_c(x_l) = A_4 \theta_5^2 e^{\theta_5 x_l} = \theta_5$. If $V_c(x_l) = \frac{\bar l}{\rho} + \frac{1}{\theta_5} \leq 0$, it contradicts with Corollary \ref{corollary:Vc_bound} which shows that $V_c(x)$ is an increasing function with $V_c(0) = 0$, thus in this case, there doesn't exist $x\in(0, \infty)$ that satisfies $V_c^\prime(x) = 1$, nor $V_c^\prime(x) = \phi > 1$, which proves $(iii)$.

In the following, we shall assume $\frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0$. Using the smooth fit principle and combining with the ODE system \eqref{eq:Vc_ODE}, we find that
\begin{equation}\label{eq:smooth1}
V^{\prime}_c(x_l-) = A_2 \theta_3 e^{\theta_3 x_l} + A_3 \theta_4 e^{\theta_4 x_l} = 1,
\end{equation}
and
\begin{align}\label{eq:smooth2}
V^{\prime\prime}_c(x_l-) = A_2 \theta_3^2 e^{\theta_3 x_l} + A_3 \theta_4^2 e^{\theta_4 x_l} &= - \frac{2 \mu}{\sigma^2} V^\prime_c(x_l-) + \frac{2 \rho}{\sigma^2} V_c(x_l-) \notag\\
&= - \frac{2 (\mu - \bar l)}{\sigma^2} V^\prime_c(x_l) + \frac{2 \rho}{\sigma^2} V_c(x_l) - \frac{2 \bar l}{\sigma^2}\notag\\
& = V^{\prime\prime}_c(x_l) = \theta_5.
\end{align}
Multiplying $\theta_4$ on both sides of equation \eqref{eq:smooth1} and subtracting \eqref{eq:smooth2} leads to
\begin{equation}\label{eq:A2_xl}
A_2 = \frac{\theta_4 - \theta_5}{(\theta_4 - \theta_3) \theta_3} e^{-\theta_3 x_l}.
\end{equation}
Similarly, we obtain
\begin{equation}\label{eq:A3_xl}
A_3 = \frac{\theta_3 - \theta_5}{(\theta_3 - \theta_4) \theta_4} e^{-\theta_4 x_l}.
\end{equation}
Then according to $V_c(x_l-) = A_2 e^{\theta_3 x_l} + A_3 e^{\theta_4 x_l} = V_c(x_l) = \frac{\bar l}{\rho} + \frac{1}{\theta_5}$ and combining with expression \eqref{eq:A2_xl} and \eqref{eq:A3_xl}, we have
\begin{equation}\label{eq:Vc_xl}
\frac{\theta_4 - \theta_5}{(\theta_4 - \theta_3) \theta_3} + \frac{\theta_3 - \theta_5}{(\theta_3 - \theta_4) \theta_4} = \frac{\theta_3 + \theta_4 - \theta_5}{\theta_3\theta_4} = \frac{\bar l}{\rho} + \frac{1}{\theta_5}.
\end{equation}

Next, suppose there exits $x_r \in (0, \infty)$ such that $V^{\prime}_c(x_r) = \phi$. We establish the relationship between point $x_r$ and $x_l$ using expression \eqref{eq:A2_xl}-\eqref{eq:A3_xl} and smooth fit condition at point $x_r$. Since $V^{\prime}_c(x_r) = A_2 \theta_3 e^{\theta_3 x_r} + A_3 \theta_4 e^{\theta_4 x_r} = \phi$, we have $A_2 e^{\theta_3 x_r} = \frac{1}{\theta_3} \left(\phi - A_3 \theta_4 e^{\theta_4 x_r}\right)$ and substituting it into $V_c(x_r)$ leads to
$$
V_c(x_r) = \frac{1}{\theta_3} \left(\phi - A_3 \theta_4 e^{\theta_4 x_r}\right) + A_3 e^{\theta_4 x_r} = \frac{\phi}{\theta_3} + \frac{\theta_3 - \theta_4}{\theta_3} A_3 e^{\theta_4 x_r} = \frac{\phi}{\theta_3} + \frac{\theta_3 - \theta_5}{\theta_3 \theta_4} e^{-\theta_4 (x_l-x_r)}.
$$
On the other hand, $V^{\prime}_c(x_r-) = A_1 \left(\theta_1 e^{\theta_1 x_r} - \theta_2 e^{\theta_2 x_r}\right) + \frac{\phi \bar r}{\rho}\theta_2 e^{\theta_2 x_r} = \phi$ implies that $A_1 = \frac{\rho - \bar r \theta_2 e^{\theta_2 x_r}}{\theta_1 e^{\theta_1 x_r} - \theta_2 e^{\theta_2 x_r}} \frac{\phi}{\rho}$. Thus,
\begin{align*}
V_c(x_r-) &= A_1 \left(e^{\theta_1 x_r} - e^{\theta_2 x_r}\right) + \frac{\phi \bar r}{\rho} \left(e^{\theta_2 x_r} - 1\right)\\
&=\frac{\phi - \frac{\phi \bar r}{\rho} \theta_2 e^{\theta_2 x_r}}{\theta_1 e^{\theta_1 x_r} - \theta_2 e^{\theta_2 x_r}} \left(e^{\theta_1 x_r} - e^{\theta_2 x_r}\right) + \frac{\phi \bar r}{\rho} \left(e^{\theta_2 x_r} - 1\right)\\
&= -\frac{\phi \bar r}{\rho} + \phi \frac{e^{\theta_1 x_r} - e^{\theta_2 x_r} + \frac{\bar r}{\rho}(\theta_1-\theta_2) e^{(\theta_1+\theta_2) x_r}}{\theta_1 e^{\theta_1 x_r} - \theta_2 e^{\theta_2 x_r}}.
\end{align*}
Then by smooth fit principle, i.e., $V_c(x_r) = V_c(x_r-)$, we establish that
\begin{equation}\label{eq:xl-xr}
e^{-\theta_4 (x_l-x_r)} = \frac{\theta_3 \theta_4 \phi}{\theta_3 - \theta_5} \left(\frac{e^{\theta_1 x_r} - e^{\theta_2 x_r} + \frac{\bar r}{\rho} (\theta_1-\theta_2) e^{(\theta_1+\theta_2) x_r}}{\theta_1 e^{\theta_1 x_r} - \theta_2 e^{\theta_2 x_r}} -\frac{\bar r}{\rho} - \frac{1}{\theta_3}\right) = f_c(x_r),
\end{equation}
where $f_c(x)$ is defined in \eqref{eq:f_c}. Hence $x_l = x_r + \frac{1}{-\theta_4} \ln f_c(x_r)$, and $e^{-\theta_3 (x_l-x_r)} = \left(f_c(x_r)\right)^\frac{\theta_3}{\theta_4}$.

Recall that
\begin{align*}
V^{\prime}_c(x_r) &= A_2 \theta_3 e^{\theta_3 x_r} + A_3 \theta_4 e^{\theta_4 x_r}\\
&= \frac{\theta_4 - \theta_5}{\theta_4 - \theta_3} e^{-\theta_3 (x_l - x_r)} + \frac{\theta_3 - \theta_5}{\theta_3 - \theta_4} e^{-\theta_4 (x_l - x_r)}\\
&= \frac{\theta_4 - \theta_5}{\theta_4 - \theta_3} \left(f_c(x_r)\right)^\frac{\theta_3}{\theta_4} + \frac{\theta_3 - \theta_5}{\theta_3 - \theta_4} f_c(x_r) = \phi,
\end{align*}
where we use the relationship between $x_l$ and $x_r$ in \eqref{eq:xl-xr} and expression \eqref{eq:A2_xl}-\eqref{eq:A3_xl}. We construct a nonlinear equation that $x_r$ should satisfy, that is, $g_c(x_r) = 0$, where $g_c$ is defined in \eqref{eq:g_c}. Once $x_r$ is obtained, $x_l$ can be solved from \eqref{eq:xl-xr}. Besides, as Proposition \ref{prop:Vc_property} shows that $V_c$ is concave, it is required that $x_l \geq x_r$, that is, $f_c(x_r) \geq 1$ according to \eqref{eq:xl-xr}, thus the domain of function $g_c(x)$ should be restricted to $\mathcal{O} := \{x\in[0, \infty): f_c(x) \geq 1\}$.

Thanks to  Lemma \ref{lemma:f_c} and Lemma \ref{lemma:g_c}, we can classify the solution to $g_c(x_r) = 0$ into the following four cases. First, $\mathcal{O} = \emptyset$ if $f_c(0) = \frac{-\theta_4}{\theta_3 - \theta_5} \phi < 1$. As required above, $\frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0$, which is equivalent to $\theta_5 > \theta_3 + \theta_4$ according to Lemma \ref{lemma:thetas_equivalent}, thus we have $\frac{-\theta_4}{\theta_3 - \theta_5} \phi > 1$, which implies that $\mathcal{O} = \emptyset$ cannot happen. In the second case, $\mathcal{O} = [0, \tilde{x}]$ for some $\tilde{x}\in[0, x^*)$, where $x^*$ is solved from $f^\prime(x^*) = 0$, since $g_c(x)$ is monotonically increasing in $[0, \tilde{x}]$ with $g_c(\tilde{x}) > 0$, there exists an unique $x_r \in (0, \infty)$ such that $g(x_r) = 0$ if and only if $g_c(0) = (\theta_4 - \theta_5) \left(\frac{-\theta_4}{\theta_3 - \theta_5} \phi\right)^\frac{\theta_3}{\theta_4} + \theta_3 \phi < 0$, which is equivalent to $\ln\phi < \frac{1}{\theta4-\theta3} \left( \theta_4 \ln\frac{\theta_5-\theta_4}{\theta_3} + \theta_3 \ln\frac{-\theta_4}{\theta_3-\theta_5} \right)$, otherwise, if $\ln\phi \geq \frac{1}{\theta4-\theta3} \left( \theta_4 \ln\frac{\theta_5-\theta_4}{\theta_3} + \theta_3 \ln\frac{-\theta_4}{\theta_3-\theta_5} \right)$,
there is no such $x_r\in(0,\infty)$ that satisfies $g_c(x_r) = 0$. Similarly for Case $(iii)$ and $(iv)$ in Lemma \ref{lemma:g_c}, since $g_c(x) > 0$ for $x \in [\bar x, \infty)$ and $x \in [x^*, \infty)$ respectively, and $g_c(\underline{x})>0$, there exists a unique $x_r \in (0, \infty)$ if and only if $g_c(0) < 0$, otherwise, if $g_c(0) \geq 0$, such $x_r \in (0, \infty)$ doesn't exits.

Then it remains to check the existence of $x_l$. If a unique $x_r \in (0, \infty)$ exists, i.e., $g_c(0) < 0$, a unique $x_l \in[x_r, \infty)$ follows from \eqref{eq:xl-xr}. If there doesn't exists $x_r \in \mathcal{O}$ such that $g_c(x_r) = 0$, then let $x_r = 0$, and solving $x_l$ from $V_c^\prime(x_l) = A_4 \theta_5 e^{\theta_5 x_l}= 1$, that is,
$$
\left(1-\left(\frac{\bar l}{\rho} + \frac{1}{\theta_5}\right)\theta_3\right) e^{\theta_3 x_l} = \left(1-\left(\frac{\bar l}{\rho} + \frac{1}{\theta_5}\right)\theta_4\right) e^{\theta_4 x_l},
$$
since $\frac{\bar l}{\rho} + \frac{1}{\theta_5} = \frac{\theta_3 + \theta_4 - \theta_5}{\theta_3\theta_4}$ as derived in \eqref{eq:Vc_xl}, we can see that $1-\left(\frac{\bar l}{\rho} + \frac{1}{\theta_5}\right)\theta_3 = 1-\frac{\theta_3 + \theta_4 - \theta_5}{\theta_4} = \frac{\theta_5 - \theta_3}{\theta_4} > 0$, and obviously $1-\left(\frac{\bar l}{\rho} + \frac{1}{\theta_5}\right)\theta_4 = \frac{\theta_5 - \theta_4}{\theta_3} > 0$. Thus taking the logarithm on both sides of the above equation and rearranging it leads to
$$
x_l = \frac{1}{\theta_3 - \theta_4} \ln\frac{\theta_4(\theta_5-\theta_4)}{\theta_3(\theta_5-\theta_3)}.
$$
Thus, there always exists a unique $x_l \in (0, \infty)$ such that $V_c^\prime(x_l) = 1$ if $\frac{\bar l}{\rho} + \frac{1}{\theta_5} > 0$, which completes our proof.
\qed



\pfof{Theorem \ref{thm:verification_equilibrium}}
First, we show that $V(s, x) = J(s, x, {\bf \hat u})$, where ${\bf \hat u}$ solves the supremum. Applying It\^{o}'s Lemma on $g(t, X_{t}^{\bf \hat u}; k)$, one obtains that for any $T > s$,
\begin{align*}
g(s, X_s^{\bf \hat u}; k) &= g(T \wedge \tau_{s, x}^{\bf \hat u}, X_{T \wedge \tau_{s, x}^{\bf \hat u}}^{\bf \hat u}; k)\\
& \quad -  \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \left(g_s(t, X_t^{\bf \hat u}; k) + \left(\mu - \hat l_t + \hat r_t \right) g_x(t, X_t^{\bf \hat u}; k) + \frac{1}{2}\sigma^2 g_{xx}(t, X_t^{\bf \hat u}; k) \right) dt\\
& \quad - \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \sigma g_x(t, X_t^{\bf \hat u}; k) dW_t\\
&= g(T \wedge \tau_{s, x}^{\bf \hat u}, X_{T \wedge \tau_{s, x}^{\bf \hat u}}^{\bf \hat u}; k) +  \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \delta(k,t) \left( \hat l_t - \phi \hat r_t \right) dt \\
& \quad - \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \sigma g_x(t, X_t^{\bf \hat u}; k) dW_t,
\end{align*}
where the last equality is due to \eqref{extended_HJB:2}. Taking expectation conditional on $X_s^{\bf \hat u} = x$ leads to
\begin{align}\label{eq:g_expect}
g(s,x; k) &= \mathbb{E}_{s, x}\left[ g(T \wedge \tau_{s, x}^{\bf \hat u}, X_{T \wedge \tau_{s, x}^{\bf \hat u}}^{\bf \hat u}; k) \right] + \mathbb{E}_{s, x}\left[ \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \delta(k,t) \left( \hat l_t - \phi \hat r_t \right) dt \right]\notag\\
&\quad - \mathbb{E}_{s, x}\left[ \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \sigma g_x(t, X_t^{\bf \hat u}; k) dW_t\right].
\end{align}
For the first term on the right-hand side of \eqref{eq:g_expect}, since $\left\vert g \right\vert$ is bounded, then by bounded convergence theorem and the boundary condition \eqref{extended_HJB:bound2},
\begin{align*}
\lim_{T\to\infty} \mathbb{E}_{s, x}\left[  g(T \wedge \tau_{s, x}^{\bf \hat u}, X_{T \wedge \tau_{s, x}^{\bf \hat u}}^{\bf \hat u}; k) \right] = \mathbb{E}_{s, x}\left[ g(\tau_{s, x}^{\bf \hat u}, 0; k) \right] = 0.
\end{align*}
For the second term on the right hand side of \eqref{eq:g_expect}, since ${\bf \hat u}$ is admissible and satisfies Definition \ref{def:admissible_control}, by monotone convergence theorem,
\begin{align*}
 \lim_{T\to\infty} \mathbb{E}_{s, x}\left[ \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \delta(k,t) \left(\hat l_t - \phi \hat r_t \right) dt \right] =  \mathbb{E}_{s, x}\left[ \int_s^{\tau_{s, x}^{\bf \hat u}} \delta(k,t) \left(\hat l_t - \phi \hat r_t \right) dt \right].
\end{align*}
For the third term on the right hand side of \eqref{eq:g_expect}, since $\left\vert g_x \right\vert$ is bounded, the stochastic integral $\left\{\int_s^{\tilde s} \sigma g_x(t, X_t^{\bf \hat u}; k) dW_t \right\}_{{\tilde s}\ge s}$ is a martingale, then by optional sampling theorem,
\begin{align*}
\mathbb{E}_{s, x}\left[ \int_s^{T \wedge \tau_{s, x}^{\bf \hat u}} \sigma g_x(t, X_t^{\bf \hat u}; k) dW_t \right] = 0.
\end{align*}
Thus, letting $T \to \infty$ on both sides of \eqref{eq:g_expect} leads to
\begin{equation}
\label{eq:g}
g(s, x; k)  =  \mathbb{E}_{s, x}\left[ \int_s^{\tau_{s, x}^{\bf \hat u}} \delta(k,t) \left(\hat l_t - \phi \hat r_t \right) dt \right].
\end{equation}
Then by relation \eqref{extended_HJB:3},
\begin{equation}\label{eq:f}
f(s, x) = g(s, x; s) = \mathbb{E}_{s, x} \left[\int_s^{\tau_{s, x}^{\bf \hat u}} \delta(s,t) \left(\hat l_t - \phi \hat r_t \right) dt\right].
\end{equation}
Because $\hat u_s = (\hat l_s, \hat r_s)$ reaches the supremum in \eqref{extended_HJB:1}, combining with \eqref{extended_HJB:2}, we obtain
\begin{align}\label{eq:V_f}
&V_s(s,x) + (\mu - \hat l_s + \hat r_s) V_x(s,x) + \frac{1}{2} \sigma^2 V_{xx}(s,x)\notag\\
=& f_s(s,x) + (\mu - \hat l_s + \hat r_s) f_x(s,x) + \frac{1}{2} \sigma^2 f_{xx}(s,x).
\end{align}
Applying It\^{o}'s Lemma on $f(t, X_{t}^{\bf \hat u})$ and $V(t, X_{t}^{\bf \hat u})$, respectively, and taking conditional expectations on both sides,
\begin{align*}
f(s, x) = - \mathbb{E}_{s, x}\left[\int_s^{\tau_{s, x}^{\bf \hat u}} \left( f_s(t,X_t^{\bf \hat u}) + (\mu - \hat l_t + \hat r_t) f_x(t,X_t^{\bf \hat u}) + \frac{1}{2} \sigma^2 f_{xx}(t,X_t^{\bf \hat u}) \right) dt \right].
\end{align*}
By \eqref{eq:V_f} and \eqref{eq:f},
\begin{align}
V(s, x) & = - \mathbb{E}_{s, x}\left[\int_s^{\tau_{s, x}^{\bf \hat u}} \left( V_s(t,X_t^{\bf \hat u}) + (\mu - \hat l_t + \hat r_t) V_x(t,X_t^{\bf \hat u}) + \frac{1}{2} \sigma^2 V_{xx}(t,X_t^{\bf \hat u}) \right) dt \right] \notag\\
& = f(s, x). \label{eq:Vf}
\end{align}
It is also shown that
\begin{align*}
 f(s, x)  = \mathbb{E}_{s, x} \left[ \int_s^{\tau_{s, x}^{\bf \hat u}} \delta(s,t) \left(\hat l_t - \phi \hat r_t \right) dt \right] = J(s, x, {\bf \hat u}).
\end{align*}

Next, we show that ${\bf \hat u}$ is an equilibrium strategy. The $\epsilon$-perturbed strategy ${\bf u}^{\epsilon,l,r}$ is defined as in Definition \ref{def:eq}, where $(l, r)\in[0,\bar l]\times[0,\bar r]$ are arbitrary constants. In the following, we write ${\bf u}^{\epsilon}$ for simplicity. Note that
\begin{align*}
&J(s, x, {\bf u^\epsilon})\\
=& \mathbb{E}_{s, x} \left[\int_{s}^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \delta(s,t) \left(l - \phi r \right) dt \right] + \mathbb{E}_{s, x} \left[\int_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\tau_{s, x}^{\bf u^\epsilon}} \delta(s,t) \left(\hat l_t - \phi \hat r_t \right) dt \right] \\
=& \mathbb{E}_{s, x} \left[\int_{s}^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \delta(s,t) dt \right] \left(l - \phi r \right) \\
\quad & + \mathbb{E}_{s, x} \left[\mathbb{E}_{ (s+\epsilon)\wedge \tau_{s, x}^{\bf u^\epsilon}, X_{ (s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon}} \left[\int_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\tau_{(s+\epsilon)\wedge \tau_{s,x}^{\bf u^\epsilon},  X_{ (s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon} }^{\bf \hat u}} \delta(s,t) \left(\hat l_t - \phi \hat r_t \right) dt \right]\right]\\
=& \mathbb{E}_{s, x} \left[\int_{s}^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \delta(s,t) dt \right] \left(l - \phi r \right)  + \mathbb{E}_{s, x} \left[g\left( (s+\epsilon) \wedge\tau_{s, x}^{\bf u^\epsilon} , X_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon}; s \right) \right],
\end{align*}
where the last equality comes from \eqref{eq:g}.
Applying It\^{o}'s Lemma on $V(t, X_{t}^{\bf u^{\epsilon}})$ and taking conditional expectation on both sides,
\begin{align*}
V(s, x) &= \mathbb{E}_{s, x}\left[V( (s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}, X_{ (s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon})\right] \\
 & \quad - \mathbb{E}_{s, x}\left[\int_s^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \left( V_s(t, X_{t}^{\bf u^{\epsilon}}) + (\mu - l + r) V_x(t, X_{t}^{\bf u^{\epsilon}}) + \frac{1}{2} \sigma^2 V_{xx}(t, X_{t}^{\bf u^{\epsilon}}) \right) dt \right] \\
&= \mathbb{E}_{s, x}\left[f( (s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}, X_{ (s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon})\right] \\
& \quad - \mathbb{E}_{s, x}\left[\int_s^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \left( V_s(t, X_{t}^{\bf u^{\epsilon}}) + (\mu - l + r) V_x(t, X_{t}^{\bf u^{\epsilon}}) + \frac{1}{2} \sigma^2 V_{xx}(t, X_{t}^{\bf u^{\epsilon}}) \right) dt \right],
\end{align*}
where the last equality comes from \eqref{eq:Vf}. Noting that $V(s, x) = J(s, x, {\bf \hat u})$, we obtain
\begin{equation}\label{eq:J_diff}
\begin{aligned}
& J(s, x, {\bf \hat u}) - J(s, x, {\bf u^\epsilon})\\
=& \mathbb{E}_{s, x}\left[f((s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}, X_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon}) - g\left( (s+\epsilon) \wedge\tau_{s, x}^{\bf u^\epsilon} , X_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon}; s \right) \right]\\
\quad & - \mathbb{E}_{s, x}\left[\int_s^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \left( V_s(t, X_{t}^{\bf u^{\epsilon}}) + (\mu - l + r) V_x(t, X_{t}^{\bf u^{\epsilon}}) + \frac{1}{2} \sigma^2 V_{xx}(t, X_{t}^{\bf u^{\epsilon}}) \right) dt \right] \\
\quad & - \mathbb{E}_{s, x} \left[\int_{s}^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \delta(s,t) dt \right] \left(l - \phi r \right).
\end{aligned}
\end{equation}
For the first term on the right-hand side of \eqref{eq:J_diff},
\begin{equation}\label{eq:f-g}
\begin{aligned}
& \quad \lim_{\epsilon \to 0}\frac{\mathbb{E}_{s, x}\left[f((s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}, X_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon}) - g\left( (s+\epsilon) \wedge\tau_{s, x}^{\bf u^\epsilon} , X_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon}; s \right) \right]}{\epsilon}\\
& = \lim_{\epsilon \to 0}\frac{\mathbb{E}_{s, x}\left[f((s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}, X_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon})\right]   - f(s, x)}{\epsilon}\\
&\quad - \lim_{\epsilon \to 0} \frac{ \mathbb{E}_{s, x}\left[g((s+\epsilon) \wedge\tau_{s, x}^{\bf u^\epsilon} , X_{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}}^{\bf u^\epsilon}; s)\right] - g(s, x; s)}{\epsilon}\\
& = f_s(s,x) + (\mu - l + r) f_x(s,x) + \frac{1}{2} \sigma^2 f_{xx}(s,x) \\
& \quad - \left(  g_s(s,x;s) + (\mu - l + r) g_x(s,x;s) + \frac{1}{2} \sigma^2 g_{xx}(s,x; s)\right).
\end{aligned}
\end{equation}
For the second term on the right-hand side of \eqref{eq:J_diff},
\begin{align*}
& \quad \lim_{\epsilon \to 0} -\frac{\mathbb{E}_{s, x}\left[\int_s^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \left( V_s(t, X_{t}^{\bf u^{\epsilon}}) + (\mu - l + r) V_x(t, X_{t}^{\bf u^{\epsilon}}) + \frac{1}{2} \sigma^2 V_{xx}(t, X_{t}^{\bf u^{\epsilon}}) \right) dt\right]}{\epsilon}\\
&= - \left( V_s(s,x) + (\mu - l + r) V_x(s,x) + \frac{1}{2} \sigma^2 V_{xx}(s,x) \right).
\end{align*}
For the third term on the right-hand side of \eqref{eq:J_diff},
\begin{align*}
\lim_{\epsilon \to 0} -\frac{\mathbb{E}_{s, x} \left[\int_{s}^{(s+\epsilon) \wedge \tau_{s, x}^{\bf u^\epsilon}} \delta(s,t) dt \right] \left(l - \phi r \right) }{\epsilon}
= -\left( l - \phi r \right).
\end{align*}
Therefore, dividing $\epsilon$ and letting $\epsilon\to 0$ on both sides of \eqref{eq:J_diff} leads to
\begin{align*}
& \quad \liminf_{\epsilon \downarrow 0} \frac{ J(s, x, {\bf \hat u}) - J(s, x, {\bf u^\epsilon})}{\epsilon} \\
& = f_s(s,x) + (\mu - l + r) f_x(s,x) + \frac{1}{2} \sigma^2 f_{xx}(s,x) \\
& \quad - \left(  g_s(s,x;s) + (\mu - l + r) g_x(s,x;s) + \frac{1}{2} \sigma^2 g_{xx}(s,x; s)\right) \\
& \quad -\left( V_s(s,x) + (\mu - l + r) V_x(s,x) + \frac{1}{2} \sigma^2 V_{xx}(s,x) \right) - \left( l - \phi r \right) \\
& \geq - \sup_{l \in [0, \bar l], r \in [0, \bar r]} \Big\{ V_s(s,x) + (\mu - l + r) V_x(s,x) + \frac{1}{2} \sigma^2 V_{xx}(s,x) +  \left( l - \phi r \right) \\
& \quad - \left( f_s(s,x) + (\mu - l + r) f_x(s,x) + \frac{1}{2} \sigma^2 f_{xx}(s,x) \right ) \\
& \quad + g_s(s,x;s) + (\mu - l + r) g_x(s,x;s) + \frac{1}{2} \sigma^2 g_{xx}(s,x; s) \Big\}\\
& = 0,
\end{align*}
where the last equality is due to \eqref{extended_HJB:1}.
\qed




\pfof{Proposition \ref{prop:simplified_HJB}}
Note that $f(s, x) = g(s, x; s)$ as given by \eqref{extended_HJB:3}, we have
$$
f_x(s,x) = \lim_{\epsilon\to0} \frac{f(s, x+\epsilon) - f(s, x)}{\epsilon} = \lim_{\epsilon\to0} \frac{g(s, x+\epsilon; s) - g(s, x; s)}{\epsilon} = g_x(s,x;s),
$$
and similarly, $f_{xx}(s,x) = g_{xx}(s,x;s)$. Thus
\begin{align*}
& f_s(s,x) + (\mu - l + r) f_x(s,x) + \frac{1}{2} \sigma^2 f_{xx}(s,x) \\
& \quad - \left(g_s(s,x;s) + (\mu - l + r) g_x(s,x;s) + \frac{1}{2} \sigma^2 g_{xx}(s,x; s)\right) = f_s(s,x) - g_s(s,x;s).
\end{align*}

Note the fact that $\hat l_{\tau_{s, x}^{\bf \hat u}} = \hat r_{\tau_{s, x}^{\bf \hat u}} = 0$ given initial pair $(s, x)$. Recall the probabilistic interpretation \eqref{eq:g}-\eqref{eq:f}, by using Leibniz formula, we derive that
$$
g_s(s,x;k) = \mathbb{E}_{s, x} \left[\frac{\partial \int_s^{\tau_{s, x}^{\bf \hat u}} \delta(k, t) \left(\hat l_t - \phi \hat r_t \right) dt}{\partial s}\right]= - \delta(k, s) \left(\hat l_s - \phi \hat r_s \right),
$$
and
\begin{align*}
f_s(s,x) &= \mathbb{E}_{s, x} \left[\frac{\partial \int_s^{\tau_{s, x}^{\bf \hat u}} \delta(s, t) \left(\hat l_t - \phi \hat r_t \right) dt}{\partial s}\right]\\
&= - \delta(s, s) \left(\hat l_s - \phi \hat r_s \right) + \mathbb{E}_{s, x} \left[\int_s^{\tau_{s, x}^{\bf \hat u}} \delta_s(s, t) \left(\hat l_t - \phi \hat r_t \right) dt\right]\\
&= - \left(\hat l_s - \phi \hat r_s \right) + \mathbb{E}_{s, x} \left[\int_s^{\tau_{s, x}^{\bf \hat u}} \delta_s(s, t) \left(\hat l_t - \phi \hat r_t \right) dt\right],
\end{align*}
where $\delta_s(s, t)$ is the partial derivative with respect to variable $s$. Therefore,
\begin{align*}
f_s(s,x) - g_s(s,x;s) &= - \left(\hat l_s - \phi \hat r_s \right) + \mathbb{E}_{s, x} \left[\int_s^{\tau_{s, x}^{\bf \hat u}} \delta_s(s, t) \left(\hat l_t - \phi \hat r_t \right) dt\right] + \delta(s, s) \left(\hat l_s - \phi \hat r_s \right)\\
&= \mathbb{E}_{s, x} \left[\int_s^{\tau_{s, x}^{\bf \hat u}} \delta_s(s, t) \left(\hat l_t - \phi \hat r_t \right) dt\right].
\end{align*}
It is obvious that the above term has nothing to do with strategy $u = (l, r)$, thus we take it out of the supremum in \eqref{extended_HJB:1}, which leads to the conclusion.
\qed





\pfof{Proposition \ref{prop:Vi}}
Note that given the equilibrium strategy \eqref{eq:equilibrium_feedback_strategy}, the ODEs \eqref{eq:Vi_ODE} is equivalent to
\begin{equation}\label{eq:Vi_HJB}
\frac{1}{2} \sigma^2 v^{\prime\prime}_i(x) + (\mu - \hat l(x) + \hat r(x)) v^\prime_i(x) - \rho_i v_i(x) + (\hat l(x) - \phi \hat r(x)) = 0.
\end{equation}
Then we show that $v_i\in {\cal C}^2$ solves \eqref{eq:Vi_HJB} has the probabilistic interpretation \eqref{eq:Vi}. Applying It\^{o}'s Lemma on $e^{-\rho_i t} v_i(X_{t}^{\bf \hat u})$, for any $T > 0$,
\begin{align*}
v_i(x) &= e^{-\rho_i (T \wedge \tau_{0, x}^{\bf \hat u})} v_i(X_{T \wedge \tau_{0, x}^{\bf \hat u})}^{\bf \hat u})\\
& \quad - \int_0^{T \wedge \tau_{0, x}^{\bf \hat u}} e^{-\rho_i t} \left(-\rho_i v_i(X_t^{\bf \hat u}) + \left(\mu - \hat l(X_t^{\bf \hat u}) + \hat r(X_t^{\bf \hat u})\right)v^\prime_i(X_t^{\bf \hat u}) + \frac{1}{2} \sigma^2 v^{\prime\prime}_i(X_t^{\bf \hat u}) \right) dt\\
&\quad - \int_0^{T \wedge \tau_{0, x}^{\bf \hat u}} \sigma e^{-\rho_i t} v_i^\prime(x) dW_t\\
&= e^{-\rho_i (T \wedge \tau_{0, x}^{\bf \hat u})} v_i(X_{T \wedge \tau_{0, x}^{\bf \hat u})}^{\bf \hat u}) + \int_0^{T \wedge \tau_{0, x}^{\bf \hat u}} e^{-\rho_i t} \left(\hat l(X_t^{\bf \hat u}) - \phi \hat r(X_t^{\bf \hat u})\right) dt \\
& \quad - \int_0^{T \wedge \tau_{0, x}^{\bf \hat u}} \sigma e^{-\rho_i t} v_i^\prime(x) dW_t,
\end{align*}
where the last equality is due to \eqref{eq:Vi_HJB}. Then taking expectations on both sides,
\begin{align*}
v_i(x) &= \expect_{0,x}\left[e^{-\rho_i (T \wedge \tau_{0, x}^{\bf \hat u})} v_i(X_{T \wedge \tau_{0, x}^{\bf \hat u})}^{\bf \hat u})\right] + \expect_{0,x}\left[\int_0^{T \wedge \tau_{0, x}^{\bf \hat u}} e^{-\rho_i t} \left(\hat l(X_t^{\bf \hat u}) - \phi \hat r(X_t^{\bf \hat u})\right) dt \right] \\
& \quad - \expect_{0,x}\left[\int_0^{T \wedge \tau_{0, x}^{\bf \hat u}} \sigma e^{-\rho_i t} v_i^\prime(x) dW_t \right].
\end{align*}
Letting $T \to \infty$ and similar to the arguments in the proof of Theorem \ref{thm:verification_equilibrium}, we have
$$
v_i(x) = \expect_{0,x}\left[\int_0^{\tau_{0, x}^{\bf \hat u}} e^{-\rho_i t} \left(\hat l(X_t^{\bf \hat u}) - \phi \hat r(X_t^{\bf \hat u})\right) dt \right].
$$
Thus, $V(x) = \omega v_1(x) + (1-\omega) v_2(x)$ is the equilibrium value function.
\qed


\begin{proposition}\label{prop:parameter_sign}
Let $A_{i1}$, $B_{i3}$ be given by \eqref{eq:ABs} with $C_{ij}$, $D_{ij}$, $E_i$ defined in \eqref{eq:CDEs}, then $A_{i1} > 0$ and $B_{i3} < 0$, $\forall i = 1, 2$.
\end{proposition}


\pfof{Proposition \ref{prop:parameter_sign}}
First, to show the sign of $A_{i1}$, notice that $C_{i1}  < 0$. Recall the definition of $\theta_{ij}$ given in \eqref{eq:theta_i}, we derive that
$$
\theta_{i3} - \theta_{i1} = \frac{\bar r + \sqrt{\mu^2 + 2 \rho_i \sigma^2} - \sqrt{(\mu + \bar r)^2 + 2 \rho_i \sigma^2}}{\sigma^2} > 0,
$$
where we use the fact that
$$
\left(\bar r + \sqrt{\mu^2 + 2 \rho_i \sigma^2}\right)^2 - \left[(\mu + \bar r)^2 + 2 \rho_i \sigma^2\right] = 2 \bar r \left(\sqrt{\mu^2 + 2 \rho_i \sigma^2} - \mu\right) > 0,
$$
and we can show $\theta_{i2} < \theta_{i4} < \theta_{i5}$ using the same argument. Recall that
\begin{align*}
E_i  &= (\theta_{i3} - \theta_{i1}) (\theta_{i4} - \theta_{i5}) e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2}  + (\theta_{i1} - \theta_{i4}) (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2} \\
&\quad + (\theta_{i2} - \theta_{i3}) (\theta_{i4} - \theta_{i5}) e^{(\theta_{i2}+\theta_{i3} ) x_1 + \theta_{i4} x_2} +(\theta_{i4} - \theta_{i2}) (\theta_{i3} - \theta_{i5}) e^{(\theta_{i2}+\theta_{i4}) x_1 + \theta_{i3} x_2}.
\end{align*}
It is obvious that the last two terms of $E_i$ are positive, and the first two terms of $E_i$ can be rearranged as follows:
\begin{align*}
& (\theta_{i3} - \theta_{i1}) (\theta_{i4} - \theta_{i5}) e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2}  + (\theta_{i1} - \theta_{i4}) (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2} \\
= & \theta_{i4} (\theta_{i3} - \theta_{i1}) e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2} - \theta_{i5}  (\theta_{i3} - \theta_{i1}) e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2} \\
\quad& + \theta_{i1} (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2} - \theta_{i4} (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2}\\
= & \theta_{i4} (\theta_{i3} - \theta_{i1}) e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2} - \theta_{i4} (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2} \\
\quad & - \theta_{i5}  (\theta_{i3} - \theta_{i1}) e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2} + \theta_{i1} (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2}.
\end{align*}
The last two terms above are positive by definition, and it remains to check the first two terms. Note that $0 < x_1 \le x_2$, thus $(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2 \le (\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2$ and $e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2} \le e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2}$. Then we obtain that
\begin{align*}
& \theta_{i4} (\theta_{i3} - \theta_{i1}) e^{(\theta_{i1}+\theta_{i3}) x_1 + \theta_{i4} x_2} - \theta_{i4} (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2}\\
\ge & \theta_{i4} (\theta_{i3} - \theta_{i1}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2} - \theta_{i4} (\theta_{i3} - \theta_{i5}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2}\\
= & \theta_{i4} (\theta_{i5} - \theta_{i1}) e^{(\theta_{i1} + \theta_{i4}) x_1 + \theta_{i3} x_2} >  0.
\end{align*}
Then it shows that $E_i > 0$.
Note that
\begin{align*}
D_{i1} &= \theta_{i3} \theta_{i4} \left(e^{\theta_{i4} x_1 + \theta_{i3} x_2} - e^{\theta_{i3} x_1 + \theta_{i4} x_2}\right) + \theta_{i3} \theta_{i5} e^{\theta_{i3} x_1 + \theta_{i4} x_2} - \theta_{i4} \theta_{i5} e^{\theta_{i4} x_1 + \theta_{i3} x_2}\\
& \quad + (\theta_{i3} - \theta_{i2}) (\theta_{i4} - \theta_{i5}) e^{(\theta_{i2} + \theta_{i3}) x_1+ \theta_{i4} x_2} + (\theta_{i2} - \theta_{i4}) (\theta_{i3} - \theta_{i5}) e^{(\theta_{i2} + \theta_{i4}) x_1 + \theta_{i3} x_2}\\
& < \theta_{i3} \theta_{i4} \left(e^{\theta_{i4} x_1 + \theta_{i3} x_2} - e^{\theta_{i3} x_1 + \theta_{i4} x_2}\right).
\end{align*}
Since $0 < x_1 \le x_2$, $\theta_{i4} x_1 + \theta_{i3} x_2 \ge \theta_{i3} x_1 + \theta_{i4} x_2$, thus $e^{\theta_{i4} x_1 + \theta_{i3} x_2} - e^{\theta_{i3} x_1 + \theta_{i4} x_2} \ge 0$, from which we obtain that $D_{i1} \le 0$. Therefore, $A_{i1}$ given in \eqref{eq:ABs} is positive.

Next, to show $B_{i3} < 0$, knowing that, for $x \in [x_2, \infty)$,
$$
V_i(x) = \frac{\bar l}{\rho_i} + B_{i3} e^{\theta_{i5} x} \leq \frac{\bar l}{\rho_i},
$$
where the inequality comes directly from Proposition \ref{corollary:Vi_bounded}, it can be inferred that $B_{i3} \le 0$.

Suppose $B_{i3} = 0$. If $0 < x_1 < x_2$, according to smooth fit principle, we have $V_i(x_2-) = V_i(x_2) = \frac{\bar l}{\rho_i} > 0$ and $V^\prime_i(x_2-) = V^\prime_i(x_2) = B_{i3} \theta_{i5} e^{\theta_{i5} x_2} = 0$. Using expression of $V_i$ given in \eqref{eq:Vi_solution},
\begin{equation*}
\left\{\begin{aligned}
& V_i(x_2-) = A_{i2} e^{\theta_{i3} x_2-} + B_{i2} e^{\theta_{i4} x_2-} > 0,\\
& V^\prime_i(x_2-) = A_{i2} \theta_{i3} e^{\theta_{i3} x_2-} + B_{i2} \theta_{i4} e^{\theta_{i4} x_2-} = 0.
\end{aligned}\right.
\end{equation*}
Multiply the first inequality in above by $\theta_{i3}$ and $\theta_{i4}$ respectively, and then subtract the second equality:
\begin{equation*}
\left\{\begin{aligned}
& A_{i2} (\theta_{i4} - \theta_{i3}) e^{\theta_{i3} x_2-} < 0,\\
& B_{i2} (\theta_{i3} - \theta_{i4}) e^{\theta_{i4} x_2-} > 0,
\end{aligned}\right.
\end{equation*}
from which one obtains that $A_{i2} > 0$ and $B_{i2} > 0$. Therefore, for $x \in [x_1, x_2)$, $V^{\prime\prime}_i(x) =  A_{i2} \theta_{i3}^2 e^{\theta_{i3} x} + B_{i2} \theta_{i4}^2 e^{\theta_{i4} x} > 0$ and thus $V^{\prime}_i(x_1) < V^{\prime}_i(x_2-) = 0$.

Recall that $A_{i1} > 0$ as shown before and $V^{\prime}_i(x_1-) = A_{i1} \theta_{i1} e^{\theta_{i1} x_1-} + B_{i1} \theta_{i2} e^{\theta_{i2} x_1-} = V^{\prime}_i(x_1) < 0$, $B_{i1}$ can only be strictly positive. Therefore, using the same argument we obtain that $V^{\prime\prime}_i(x) > 0$ and $V^{\prime}_i(x) < V^{\prime}_i(x_1) < 0$ for $x \in [0, x_1)$, it then follows that $V_i(0) = 0 > V_i(x_1) = A_{i2} e^{\theta_{i3} x_1} + B_{i2} e^{\theta_{i4} x_1} > 0$, which leads to the contradiction. Then $B_{i3} < 0$.
The proof of the case of $0 < x_1 = x_2$ is similar.
\qed


Because $B_{i3} < 0$, $V_i$ is concave on interval $[x_2, \infty)$. The concavity of $V_i$ on the whole domain is proved with the help of Lemma \ref{lemma:concave} inspired by \citet[Lemma 4.1]{shreve1984optimal} and \citet[Proposition 3.2]{bai2023reinforcement}.



\begin{lemma}\label{lemma:concave}
Suppose that $v_i(x)$, $i = 1, 2$, are solutions to the linear ordinary differential equations:
\begin{equation}\label{eq:ode_concave}
\frac{1}{2} \sigma^2 v_i^{\prime\prime}(x) + (\mu + \alpha) v_i^{\prime}(x) - \rho_i v_i(x) - \phi \alpha = 0, \quad x \in [a,b),
\end{equation}
where $\mu, \alpha > 0$, $0 < \rho_1 \le \rho_2$, and $\phi \geq 1$ are constants. Then $v(x) = \omega v_1(x) + (1-\omega)v_2(x)$ is a concave function if $v^{\prime\prime}(b-) < 0$ and $v_i(x)$, $i=1, 2$, satisfy either of the following conditions:
\begin{enumerate}
\item[(i)] $v_i^{\prime}(x) > 0$, $\forall x \in [a,b)$;
\item[(ii)] $v^{\prime}(b-) = \phi$, $v_i^{\prime}(b-) > 0$, and $v_i(a) = 0$.
\end{enumerate}
\end{lemma}

\proof
First, differentiate \eqref{eq:ode_concave} and let $m(x) := v^\prime(x)$ and $m_i(x) := v_i^\prime(x)$, then it can be obtained that
$$
m_i^{\prime\prime}(x) = \frac{2 \rho_i}{\sigma^2} m_i(x) - \frac{2 (\mu + \alpha)}{\sigma^2} m_i^{\prime}(x), \quad x \in [a,b).
$$
Then we introduce a change of variable $\varphi(x) := \int_a^x \exp\left(-2 (\mu + \alpha) u/\sigma^2\right) du$, $x \in [a, b)$,
and define $l(y) := \omega l_1(y) + (1-\omega)l_2(y)$ with $l_i(y) := m_i(\varphi^{-1}(y))$, $y\in[0,\bar y)$, where $\bar y = \int_a^b \exp\left(-2 (\mu + \alpha) u/\sigma^2\right) du$. Note that
$$
l_i^{\prime}(y) = \frac{1}{\varphi^\prime(\varphi^{-1}(y))} m^{\prime}_i(\varphi^{-1}(y)) = \frac{m^{\prime}_i(\varphi^{-1}(y))}{\exp\left(-2 (\mu + \alpha) \varphi^{-1}(y)/\sigma^2\right)},
$$
then
$$
l^{\prime}(y) = \frac{\omega m^{\prime}_1(\varphi^{-1}(y)) + (1-\omega) m^{\prime}_2(\varphi^{-1}(y))}{\exp\left(-2 (\mu + \alpha) \varphi^{-1}(y)/\sigma^2\right)} = \frac{m^{\prime}(\varphi^{-1}(y))}{\exp\left(-2 (\mu + \alpha) \varphi^{-1}(y)/\sigma^2\right)},
$$
which implies that $v^{\prime\prime}(\varphi^{-1}(y)) = m^{\prime}(\varphi^{-1}(y))$ has same sign as $l^{\prime}(y)$, specifically, $l^{\prime}(\bar y-) < 0$ because $v^{\prime\prime}(b-) < 0$. Differentiating $l_i^{\prime}$, we obtain the following second-order linear ODEs for $l_i$:
\begin{align*}
l_i^{\prime\prime}(y) &= \left[\varphi^\prime(\varphi^{-1}(y))\right]^{-2} \left(m^{\prime\prime}_i(\varphi^{-1}(y)) - \frac{\varphi^{\prime\prime}(\varphi^{-1}(y))}{\varphi^\prime(\varphi^{-1}(y))} m^\prime_i(\varphi^{-1}(y))\right) \\
&= \left[\varphi^\prime(\varphi^{-1}(y))\right]^{-2} \left(\frac{2 \rho_i}{\sigma^2} m_i(\varphi^{-1}(y)) - \frac{2 (\mu + \alpha)}{\sigma^2} m_i^{\prime}(\varphi^{-1}(y)) + \frac{2(\mu + \alpha)}{\sigma^2} m^\prime_i(\varphi^{-1}(y))\right) \\
& = \left[\varphi^\prime(\varphi^{-1}(y))\right]^{-2} \frac{2 \rho_i}{\sigma^2} l_i(y).
\end{align*}
Hence,
\begin{align}\label{eq:l_ode}
l^{\prime\prime}(y) &= \omega l_1^{\prime\prime}(y) + (1-\omega) l_2^{\prime\prime}(y)\notag\\
&= \left[\varphi^\prime(\varphi^{-1}(y))\right]^{-2} \frac{2}{\sigma^2} \left(\omega \rho_1 l_1(y) + (1-\omega) \rho_2 l_2(y) \right).
\end{align}

On one hand, if $m_i(x) = v_i^{\prime}(x) > 0$, $\forall x \in [a,b)$, then for any $y \in [0,\bar y)$, $l_i(y) = m_i(\varphi^{-1}(y)) > 0$ and $l^{\prime\prime}(y) > 0$ by \eqref{eq:l_ode}, which implies that $l^{\prime}(y)$ is increasing on interval $[0,\bar y)$, and thus $l^{\prime}(y) < l^{\prime}(\bar y-) < 0$ for any $y \in [0,\bar y)$. As $v^{\prime\prime}(x)$ has same sign as $l^{\prime}(\varphi(x))$, we prove that $v^{\prime\prime}(x)< 0$, $\forall x \in [a, b)$.

On the other hand, assume that condition $(ii)$ holds. Suppose there exists $y^* \in [0, \bar y)$ such that $l^\prime(y^*) = 0$ and $l^\prime(y) < 0$ for $y \in (y^*, \bar y)$. Then $l^{\prime\prime}(y^*) < 0$ and by \eqref{eq:l_ode},
\begin{equation}\label{ineq1:l}
\omega \rho_1 l_1(y^*) + (1-\omega) \rho_2 l_2(y^*) < 0.
\end{equation}
Since $l^\prime(y) < 0$ for $y \in (y^*, \bar y)$, we have $l(y^*) > l(\bar y-) = m(b-) = v^\prime(b-) > 0$, that is,
\begin{equation}\label{ineq2:l}
\omega l_1(y^*) + (1-\omega) l_2(y^*) > 0.
\end{equation}
Let inequality \eqref{ineq2:l} multiply $-\rho_1$ on both sides and then add up with \eqref{ineq1:l}, we obtain $(1-\omega) (\rho_2 - \rho_1) l_2(y^*) < 0$, which implies that $l_1(y^*) > 0$ and $l_2(y^*) < 0$. Combining with the fact that $l_2(\bar y-) = v_2^\prime(b-) > 0$ and $l^\prime_2$ has no zero in $[0, \bar y)$ (thanks to \citet[Lemma 4.1]{shreve1984optimal}), it indicates that $l^\prime_2(y) > 0$, $\forall y \in [0, \bar y)$. Therefore,
\begin{equation}\label{ineq:lprime}
\omega \rho_1 l_1^{\prime}(y) + (1-\omega) \rho_2 l_2^{\prime}(y) > \omega \rho_1 l_1^{\prime}(y) + (1-\omega) \rho_1 l_2^{\prime}(y) = \rho_1 l^{\prime}(y).
\end{equation}
We then claim that $\omega \rho_1 l_1(y) + (1-\omega) \rho_2 l_2(y) < 0$ (i.e., $l^{\prime\prime}(y) < 0$) for all $y\in[0, y^*]$. Otherwise, if there exists $y_1$ such that $y_1 := \sup\{y\in[0, y^*]: l^{\prime\prime}(y_1) = 0$\}, since $l^{\prime\prime}(y^*) < 0$, we have $l^{\prime\prime}(y) < 0$ for any $y\in(y_1, y^*]$. Consequently, $l^{\prime}(y_1) > l^{\prime}(y^*) = 0$, and inequality \eqref{ineq:lprime} tells that $\omega \rho_1 l_1^{\prime}(y_1) + (1-\omega) \rho_2 l_2^{\prime}(y_1) > \rho_1 l^\prime(y_1) > 0$. Then according to \eqref{eq:l_ode}, $l^{\prime\prime}(y_1) = 0$ and $l^{\prime\prime}(y_1+) < 0$ lead to $\omega \rho_1 l_1(y_1) + (1-\omega) \rho_2 l_2(y_1) = 0$ and $\omega \rho_1 l_1(y_1+) + (1-\omega) \rho_2 l_2(y_1+) < 0$, that is, $\omega \rho_1 l_1^{\prime}(y_1) + (1-\omega) \rho_2 l_2^{\prime}(y_1) < 0$, which is a contradiction.

Since $v^{\prime\prime}(x^*)$ has same sign as $l^{\prime}(y^*) = 0$ and $v^{\prime}(x^*) = l(y^*) > l(\bar y -) = v^{\prime}(b-) = \phi$, where $x^* = \varphi^{-1}(y^*)$, combining with \eqref{eq:ode_concave} leads to
\begin{equation}\label{ineq:v_x*}
\omega \rho_1 v_1(x^*) + (1-\omega)\rho_2 v_2(x^*) = \frac{1}{2} \sigma^2 v^{\prime\prime}(x^*) + (\mu + \alpha) v^{\prime}(x^*) - \phi \alpha > 0.
\end{equation}
However, $\omega \rho_1 v^{\prime}_1(x) + (1-\omega) \rho_2 v^{\prime}_2(x) = \omega \rho_1 l_1(\phi(x)) + (1-\omega) \rho_2 l_2(\phi(x)) < 0$ for all $x \in [a, x^*]$, resulting in $\omega \rho_1 v_1(x^*) + (1-\omega) \rho_2 v_2(x^*) < \omega \rho_1 v_1(a) + (1-\omega) \rho_2 v_2(a) = 0$, which contradicts with \eqref{ineq:v_x*}, therefore, there cannot exist $y^* \in [0, \bar y)$ such that $l^\prime(y^*) = 0$, that is, $v^{\prime\prime}(x) < 0$ for all $x \in [a, b)$.
\qed




\pfof{Theorem \ref{thm:V_concave}}
First, consider $V_i(x)$ for $x \in [x_2, \infty)$. It is straightforward that $V^\prime_i(x) = B_{i3} \theta_{i5} e^{\theta_{i5} x} > 0$ and $V^{\prime\prime}_i(x) = B_{i3} \theta_{i5}^2 e^{\theta_{i5} x} < 0$ from Proposition \ref{prop:parameter_sign}.

Second, for $x \in [x_1, x_2)$, since $V^\prime_i(x_2-) = V^\prime_i(x_2) > 0$, using expression \eqref{eq:Vi_solution}, it is equivalent to $A_{i2} \theta_{i3} e^{\theta_{i3} x_2-} + B_{i2} \theta_{i4} e^{\theta_{i4} x_2-} > 0$. We claim that $V^\prime_i(x) > 0$ for all $x \in [x_1, x_2)$ by considering different signs of $A_{i2}$ and $B_{i2}$. If $A_{i2} < 0$, then in order to make $V^\prime_i(x_2-) > 0$, we can only have $B_{i2} < 0$, hence $V^{\prime\prime}_i(x) = A_{i2} \theta_{i3}^2 e^{\theta_{i3} x} + B_{i2} \theta_{i4}^2 e^{\theta_{i4} x} < 0$, indicating $V^\prime_i(x) > V^\prime_i(x_2-) > 0$, $\forall x \in [x_1, x_2)$. If $A_{i2} > 0$ and $B_{i2} < 0$, then $V^\prime_i(x) = A_{i2} \theta_{i3} e^{\theta_{i3} x} + B_{i2} \theta_{i4} e^{\theta_{i4} x} > 0$. If $A_{i2} > 0$ and $B_{i2} > 0$, suppose $V_i^\prime(x_1) < 0$. According to the smooth principle, $V_i^\prime(x_1-) = A_{i1} \theta_{i1} e^{\theta_{i1} x_1-} + B_{i1} \theta_{i2} e^{\theta_{i2} x_1-} = V_i^\prime(x_1) < 0$. As $A_{i1} > 0$ by Proposition \ref{prop:parameter_sign}, $B_{i1}$ can only be positive, resulting in $V_i^{\prime\prime}(x) = A_{i1} \theta_{i1}^2 e^{\theta_{i1} x} + B_{i1} \theta_{i2}^2 e^{\theta_{i2} x} > 0$. Thus, $V_i^\prime(x) < V_i^\prime(x_1-) < 0$ for all $x \in [0, x_1)$, leading to $V_i(0) > V_i(x_1-) = V_i(x_1) = A_{i2} e^{\theta_{i3} x_1} + B_{i2} e^{\theta_{i4} x_1} > 0$, which contradicts with the boundary condition $V_i(0) = 0$. Therefore, $V_i^\prime(x_1)$ is positive and $V^{\prime\prime}_i(x) = A_{i2} \theta_{i3}^2 e^{\theta_{i3} x} + B_{i2} \theta_{i4}^2 e^{\theta_{i4} x} > 0$, which confirms that $V_i^\prime(x) > V_i^\prime(x_1) > 0$, $\forall x \in [x_1, x_2)$.

Next, we show $V^{\prime\prime}(x) = \omega V^{\prime\prime}_1(x) + (1-\omega) V_2^{\prime\prime}(x) < 0$, $\forall x \in [x_1, x_2)$. Since $V^\prime(x_2-) = V^\prime(x_2) = 1$ and $V^{\prime\prime}(x_2) < 0$, according to ODEs \eqref{eq:Vi_ODE},
\begin{align*}
V^{\prime\prime}(x_2-) &= \omega V^{\prime\prime}_1(x_2-) + (1-\omega) V_2^{\prime\prime}(x_2-)\\
&= \frac{2}{\sigma^2} \left[-\mu V^\prime(x_2-) + \left(\omega \rho_1 V_1(x_2-) + (1-\omega) \rho_2 V_2(x_2-)\right)\right]\\
&= \frac{2}{\sigma^2} \left[-(\mu-\bar l) V^\prime(x_2) - \bar l + \left(\omega \rho_1 V_1(x_2) + (1-\omega) \rho_2 V_2(x_2)\right)\right]\\
&= \omega V^{\prime\prime}_1(x_2) + (1-\omega) V_2^{\prime\prime}(x_2) = V^{\prime\prime}(x_2) < 0.
\end{align*}
Then by Lemma \ref{lemma:concave} $(i)$ with $\alpha$ being $0$, $V^{\prime\prime}(x)$ should always be negative on interval $[x_1, x_2)$.

Finally, for $x \in [0, x_1)$, it is already known that $V_i(0) = 0$, $V^\prime_i(x_1-) = V^\prime_i(x_1) > 0$, and $V^\prime(x_1-) = V^\prime(x_1) = \phi$. Using the same argument as above,
\begin{align*}
V^{\prime\prime}(x_1-) &= \frac{2}{\sigma^2} \left[-(\mu+\bar r) V^\prime(x_1-) + \phi \bar r + \left(\omega \rho_1 V_1(x_1-) + (1-\omega) \rho_2 V_2(x_1-)\right)\right]\\
&= \frac{2}{\sigma^2} \left[-\mu V^\prime(x_1) + \left(\omega \rho_1 V_1(x_1) + (1-\omega) \rho_2 V_2(x_1)\right)\right]\\
&= \omega V^{\prime\prime}_1(x_1) + (1-\omega) V_2^{\prime\prime}(x_1) = V^{\prime\prime}(x_1) < 0.
\end{align*}
By Lemma \ref{lemma:concave} $(ii)$ with $\alpha = \bar r$, $V^{\prime\prime}(x) < 0$, which shows $V^{\prime}(x) > V^{\prime}(x_1-) > 0$ for all $x \in [0, x_1)$.
\qed




\pfof{Theorem \ref{thm:V_classification}}
It remains to prove {\it (ii)} and {\it (iii)}. For Case {\it (ii)}, since there doesn't exist such $0 < x_1 \le x_2 < \infty$ that satisfy $V^\prime(x_1) = \phi \ge 1$ and $V^\prime(x_2) = 1$, we assume that there exists $x_2 > 0$ such that $V^\prime(x_2) = 1$. Then the equilibrium strategy becomes
\begin{equation*}
\hat u_s = (\hat l(x), \hat r(x)) = \left\{\begin{aligned}
& (0, 0), \qquad & 0 \leq x < x_2,\\
& (\bar l, 0), & x \geq x_2.
\end{aligned}\right.
\end{equation*}
Following a similar argument as in Case {\it (i)} with boundary condition $V_i(0) = 0$, we obtain that
$$
V_i(x) = \begin{cases}
A_{i2} \left(e^{\theta_{i3} x} - e^{\theta_{i4} x}\right), & x \in [0, x_2),\\
\frac{\bar l}{\rho_i} + B_{i3} e^{\theta_{i5} x}, & x \in [x_2, \infty),
\end{cases}
$$
where, by letting $x_1$ = 0 in \eqref{eq:CDEs},
$$
A_{i2} = -\frac{\theta_{i5}}{(\theta_{i5} - \theta_{i4}) e^{\theta_{i4} x_2}  + (\theta_{i3} - \theta_{i5}) e^{\theta_{i3} x_2}} \cdot \frac{\bar l}{\rho_i} > 0,
$$
and
$$
B_{i3} = - \frac{\theta_{i3} e^{\theta_{i3} x_2} - \theta_{i4} e^{\theta_{i4} x_2}}{(\theta_{i5} - \theta_{i4}) e^{(\theta_{i4} + \theta_{i5}) x_2}  + (\theta_{i3} - \theta_{i5}) e^{(\theta_{i3} + \theta_{i5}) x_2}} \cdot \frac{\bar l}{\rho_i} < 0.
$$
The concavity of $V = \omega V_1 + (1-\omega) V_2$ can be obtained using a similar argument as in the proof of Theorem \ref{thm:V_concave} with $A_{i2} > 0$ and $B_{i3} < 0$. Moreover, the existence of $x_2 > 0$ is guaranteed by the condition that there exists $x_2 > 0$ that solves \eqref{eq:x2} given $x_1 = 0$.

For Case {\it (iii)}, since we cannot find a positive $x_1$ such that $V^\prime(x_1) = \phi$ nor a positive $x_2$ such that $V^\prime(x_2) = 1$, which means $V^\prime(x) \le 1$ for $x \in [0, \infty)$. Thus the equilibrium strategy becomes
$$
\hat u_s = (\hat l(x), \hat r(x)) = (\bar l, 0),  \qquad x \geq 0,
$$
and the boundary condition leads to
$$
V_i(x) =  \frac{\bar l}{\rho_i} \left(1 - e^{\theta_{i5} x}\right), \qquad x \in [0, \infty),
$$
with $\theta_{i5} < 0$, which also shows the concavity of $V$.
\qed








