\section{Appendix}
\subsection{Proof of Theorem \ref{thm:post_conv_cdf}}
\begin{proof}
    Let $X_{(r)}$ denote the $r$-th smallest value among $X_1, \ldots, X_n$.
    To obtain sign invariance, the following condition must be satisfied:    
    $$
    \bbE_w[\tilde{F}(X_{(r)})] = 1 - \bbE_w[\tilde{F}(X_{(n-r+1)})], \quad \text{for } r = 1, \ldots, n.
    $$

    Since $(w_1, \ldots, w_n) \sim \mathrm{Dir}(1, \ldots, 1)$, we have
    \begin{align*}
        \bbE_w[\tilde{F}(X_{(r)})] &= \bbE_w\left[a \sum_{i=1}^r w_i + b \right] \\
        &= a \cdot \frac{r}{n} + b, \\
        \bbE_w[\tilde{F}(X_{(n-r+1)})] &= \bbE_w\left[a \sum_{i=1}^{n-r+1} w_i + b \right] \\
        &= a \cdot \frac{n - r + 1}{n} + b.
    \end{align*}

    Therefore, the following equation must hold:
    $$
    a \cdot \frac{r}{n} + b = 1 - \left(a \cdot \frac{n - r + 1}{n} + b \right).
    $$

    Simplifying, we obtain the condition:
    $$
    \frac{n + 1}{n}a + 2b = 1.
    $$
\end{proof}

\subsection{Proof of Lemma \ref{lem:posterior_mar}}
\begin{proof}
We begin by incorporating the missingness mechanism into the posterior. Let $\mathcal{M} = \mathcal{M}_c\cup \mathcal{M}_o$ denote the missingness indicator matrix, and let $F = (F_1, \ldots, F_p)$ denote the collection of marginal CDFs. Suppose that we are interested in the posterior distribution over $(R, F)$ given the observed data $\bfX_{\mathcal{O}}$ and the missingness pattern $\mathcal{M}$.

The full posterior, including the missingness mechanism, is given by:
\begin{align}
\pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}, \mathcal{M})
&\propto P(\mathcal{M} \vert \bfX_{\mathcal{O}}, \bfX_{\mathcal{M}}) \cdot \pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}).
\label{eq:full_joint_missing}
\end{align}

The first term, $P(\mathcal{M} \vert \bfX_{\mathcal{O}}, \bfX_{\mathcal{M}})$, specifies the missing data mechanism—that is, the probability of the missingness pattern $\mathcal{M}$ given the full data $\bfX = (\bfX_{\mathcal{O}}, \bfX_{\mathcal{M}})$. 

Now, under the assumption that the missingness is MAR, we have:
\begin{align}
P(\mathcal{M} \vert \bfX_{\mathcal{O}}, \bfX_{\mathcal{M}}) = P(\mathcal{M} \vert \bfX_{\mathcal{O}}).
\label{eq:mar}
\end{align}

That is, the missingness mechanism depends only on the observed values, and not on the values that are themselves missing. Substituting \eqref{eq:mar} into \eqref{eq:full_joint_missing}, we obtain:
\begin{align*}
\pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}, \mathcal{M})
&\propto P(\mathcal{M} \vert \bfX_{\mathcal{O}}) \cdot \pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}).
\end{align*}

Since $P(\mathcal{M} \vert \bfX_{\mathcal{O}})$ is constant with respect to $(R, F, \bfX_{\mathcal{M}})$, it can be dropped from the posterior. Thus, under the MAR assumption, the missingness mechanism is said to be ignorable, meaning that inference for $(R, F)$ can proceed based on the observed data alone:
\begin{align}
\pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}, \mathcal{M})
= \pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}).
\label{eq:ignore_M}
\end{align}

It follows that the posterior over $R$ can be obtained by marginalizing over $F$ and the missing values $\bfX_{\mathcal{M}}$:
\begin{align*}
\pi(R \vert \bfX_{\mathcal{O}}, \mathcal{M})
&= \int \int \pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}, \mathcal{M}) \, d\bfX_{\mathcal{M}} \, dF \\
&= \int \int \pi(R, F, \bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}) \, d\bfX_{\mathcal{M}} \, dF.
\end{align*}

To further simplify this expression, we assume that the posterior of $R$ given the full data depends on the observed and missing values only through their transformations into latent Gaussian variables via $F$. Formally, we assume:
\begin{align}
\pi(R \vert \bfX_{\mathcal{O}}, \bfX_{\mathcal{M}}, F) = \pi(R \vert \bfX_{\mathcal{O}}, F).
\label{eq:cond_indep}
\end{align}

This conditional independence is justified by the model structure, where the latent Gaussian variables $Z$ are deterministically related to $\bfX$ through the transformation $F$, and $R$ controls only their dependence.

Substituting \eqref{eq:cond_indep} into the marginal posterior, we obtain:
\begin{align*}
\pi(R \vert \bfX_{\mathcal{O}}) 
&\propto \int [ \int \pi(R \vert \bfX_{\mathcal{O}}, F) \cdot \pi(\bfX_{\mathcal{M}} \vert \bfX_{\mathcal{O}}, F) \, d\bfX_{\mathcal{M}} ] \cdot \pi(F \vert \bfX_{\mathcal{O}}) \, dF \\
&= \int \pi(R \vert \bfX_{\mathcal{O}}, F) \cdot \pi(F \vert \bfX_{\mathcal{O}}) \, dF.
\end{align*}
\end{proof}

\subsection{Proof of Theorem \ref{thm:post_conv_cdf}}
\begin{proof}
    Let $D_n = \sup_{t \in \mathbb{R}} \abs{F_n(t) - F(t)}$ and  
    $C_n = \sup_{t \in \mathbb{R}} \abs{F^{BB}(t) - F(t)}$,  
    where $F_n$ is the empirical cumulative distribution function (ECDF) and $F^{BB}$ is the Bayesian bootstrap CDF.

    Given that $U_i = F(X_i) \overset{iid}{\sim} U(0,1)$ for $i = 1, \ldots, n$, we can rewrite $C_n$ as follows:
    $$
    \begin{aligned}
    C_n &= \sup_{t \in \mathbb{R}} \abs{F^{BB}(t) - F(t)} \\
    &= \sup_{t \in \mathbb{R}} \abs{\sum_{i=1}^n w_i \mathbf{1}(X_i \leq t) - F(t)} \\
    &= \sup_{t \in \mathbb{R}} \abs{\sum_{i=1}^n w_i \mathbf{1}(F(X_i) \leq F(t)) - F(t)} \\
    &= \sup_{F(t) \in [0,1]} \abs{\sum_{i=1}^n w_i \mathbf{1}(U_i \leq F(t)) - F(t)} \\
    &= \sup_{s \in [0,1]} \abs{\sum_{i=1}^n w_i \mathbf{1}(U_i \leq s) - s}.
    \end{aligned}
    $$

    The supremum over $s \in [0,1]$ can be computed via order statistics of the uniform variables. Let $U_{(k)}$ denote the $k$-th order statistic of $\{U_1, \ldots, U_n\}$. Then,
    $$
    C_n = \max_{1 \leq k \leq n} [ \max ( | \sum_{i=1}^k w_i - U_{(k)} |, | \sum_{i=1}^{k-1} w_i - U_{(k)} | ) ].
    $$

    Similarly, we can express $D_n$ as:
    $$
    D_n = \max_{1 \leq k \leq n} [ \max ( | \frac{k}{n} - U_{(k)} |, | \frac{k-1}{n} - U_{(k)} | ) ].
    $$

    Since $(w_1, \ldots, w_n) \sim \mathrm{Dirichlet}(1,\ldots,1)$, the partial sums of weights follow the distribution of sorted uniform random variables:
    $$
    (w_1, \sum_{i=1}^2 w_i, \ldots, \sum_{i=1}^{n-1} w_i ) \overset{d}{=} (V_{(1)}, \ldots, V_{(n-1)}),
    $$
    where $V_i \overset{iid}{\sim} U(0,1)$ and $V_{(k)}$ is the $k$-th order statistic.

    By the Dvoretzky-Kiefer-Wolfowitz (DKW) inequality with Massart’s sharp constant (\cite{massart1990tight}), we have:
    $$
    \mathbb{P}(D_n > \epsilon) \leq 2 \exp(-2n \epsilon^2), \quad \text{for all } \epsilon > 0.
    $$

    Applying the same logic to the Dirichlet weights, define
    $$
    E_{n-1} = \max_{1 \leq k \leq n-1} [ \max ( | \frac{k}{n-1} - V_{(k)} |, | \frac{k-1}{n-1} - V_{(k)} | ) ],
    $$
    and again by the DKW inequality,
    $$
    \mathbb{P}(E_{n-1} > \epsilon) \leq 2 \exp(-2(n-1)\epsilon^2).
    $$

    Now consider the difference between $U_{(k)}$ and $V_{(k)}$. For each $k$,
    $$
    \begin{aligned}
    | V_{(k)} - U_{(k)} | 
    &\leq | V_{(k)} - \frac{k}{n-1} | + | \frac{k}{n} - U_{(k)} | + \frac{k}{n(n-1)}, \\
    | U_{(k)} - V_{(k-1)} | 
    &\leq | U_{(k)} - \frac{k-1}{n} | + | \frac{k-1}{n-1} - V_{(k-1)} | + \frac{k-1}{n(n-1)}.
    \end{aligned}
    $$

    Hence,
    $$
    C_n \leq D_n + E_{n-1} + \frac{1}{n-1}.
    $$

    Therefore, for any $\delta > \dfrac{1}{n-1}$,
    $$
    \begin{aligned}
    \pi( \sup_{t \in \mathbb{R}} \abs{F^{BB}(t) - F(t)} > \delta \vert \bfX )
    &= \pi(C_n > \delta \vert \bfX) \\
    &\leq \mathbb{P}( D_n + E_{n-1} + \frac{1}{n-1} > \delta ) \\
    &\leq \mathbb{P}( D_n > \frac{1}{2}(\delta - \frac{1}{n-1} ) ) + \mathbb{P}( E_{n-1} > \frac{1}{2}(\delta - \frac{1}{n-1} ) ) \\
    &\leq 2 \exp( -2n ( \frac{1}{2}(\delta - \frac{1}{n-1} ) )^2 ) \\
    &\quad + 2 \exp( -2(n-1) ( \frac{1}{2}(\delta - \frac{1}{n-1} ) )^2 ) \\
    &\leq 4 \exp( -\frac{1}{2}(n-1) ( \delta - \frac{1}{n-1}  )^2 ).
    \end{aligned}
    $$

    Finally, since $\tilde{F}^{BB}(t) = \dfrac{n}{n+1}F^{BB}(t)$, the inequality holds
    $$\sup_{t\in\bbR}\abs{\tilde{F}^{BB}(t)-F^{BB}(t)}\leq \dfrac{1}{n+1}.$$

    Therefore, for any $\delta>\dfrac{2n}{n^2-1}$,
    \begin{align*}
        \pi( \sup_{t \in \mathbb{R}} \abs{\tilde{F}^{BB}(t) - F(t)} > \delta \vert \bfX ) &\leq \pi( \sup_{t \in \mathbb{R}} \abs{F^{BB}(t) - F(t)} + \sup_{t \in \mathbb{R}} \abs{\tilde{F}^{BB}(t) - F^{BB}(t)} > \delta \vert \bfX )\\
        &\leq  \pi( \sup_{t \in \mathbb{R}} \abs{F^{BB}(t) - F(t)}  > \delta  - \dfrac{1}{n+1}\vert \bfX ) \\
        &\leq 4 \exp( -\dfrac{1}{2}(n-1) ( \delta - \frac{2n}{n^2-1}  )^2 ).
    \end{align*}

\end{proof}

