Let us start proving the next lemma.

\begin{lemma}\label{lem1}
Suppose that $\theta\in\left[ 0,\pi\right)$ and $E\in\R$. If $y\in \left( Ker(T_{\theta}-EI)\setminus\left\lbrace 0\right\rbrace\right) \cap\M$,
then $\langle y,u_{+}\rangle\neq 0$.
\end{lemma}
\begin{proof}
Suppose there exists $y\in \left( Ker(T_{\theta}-EI)\setminus\left\lbrace 0\right\rbrace\right) \cap\M$ such that $\langle y,u_{+}\rangle =0$. Given $z\in\C\setminus\R$
\begin{equation*}
(T_{\theta}-\overline{z}I)^{-1}y=(E-\overline{z})^{-1}y.
\end{equation*}
Then
\begin{equation*}
\langle y,(T_{\theta}-zI)^{-1}u_{+}\rangle =
\langle (T_{\theta}-\overline{z}I)^{-1}y,u_{+}\rangle =\langle (E-\overline{z})^{-1}y,u_{+}\rangle =0.
\end{equation*}
Since $u_{+}$ is cyclic for $T_{\theta}\upharpoonright_{\M}$ when $\theta$ is fixed, one concludes $y=0$.
\end{proof}

\begin{definition}
Let $X$ be a Banach space and $X^{*}$ be its dual space. The weak topology is the weakest topology in $X$ such that each functional in $X^{*}$ is continuous. The weak*-topology is the weakest topology in $X^{*}$ such that each functional in $X^{**}$ is continuous.
\end{definition}

\begin{remark}
If $X$ is a Hilbert space the weak topology and weak*-topology coincide. Therefore by Banach-Alaoglu-Bourbaki Theorem
the closed balls in a Hilbert space are compact with respect to the weak topology. 
\end{remark}

Let $\tau :=\left[ 0,\pi \right] \times\R\times\M$ where the Hilbert space $\M$ will be endowed with the weak topology. By the last lemma, we can define the following sets:

\begin{itemize}
\item $\tau_{M}:=\left[ 0,\pi \right]\times\R\times B_{M}\cap\M$ where $B_{M}$ is the closed ball in $\H$ with
center at $0$ and radius $M$
\item $Q_{M}:=\left\lbrace \left(\theta,E,y\right)\in\tau_{M}:y\in Ker(T_{\theta}-EI)\;such\;that\;\langle y,u_{+}\rangle =1 \right\rbrace $.
\end{itemize}

\begin{remark}
The topological space $\tau_{M}$ is metrizable because $B_{M}\cap\M$ is too. It is due to the separability of $\M$. Further $B_{M}\cap\M$ is a convex set in $\M$ so that is strongly, weakly and weakly sequentially
closed in $\M$. Therefore $\tau_{M}$ is a closed subspace of $\tau$.
\end{remark}

We propose the next definition.

\begin{definition}
Let $A:\H\longrightarrow\H$ be an operator. It is said to be weakly closed in $\H$ if given
$\left( x_{n}\right)_{n\in\N}\subseteq D(A)$ such that
\begin{center}
$x_{n}\longrightarrow^{w}x\in\H$ and $Ax_{n}\longrightarrow^{w}y\in\H$
\end{center}
then $x\in D(A)$ and $Ax=y$.
\end{definition}

The proof of the following proposition is like the classical case. Only the fact that the inner product is continuous with respect to weak limits is required .

\begin{prop}\label{debilcerrado}
Let $A:\H\longrightarrow\H$ be a densely defined operator. Then $A^{*}$ is weakly closed on $\H$.
\end{prop}

We prove the following lemma.

\begin{lemma}\label{lem2}
The set $Q_{M}$ is closed in $\tau_{M}$.
\end{lemma}
\begin{proof}
%Since $B_{M}\cap\M$ is a closed subspace of $\M$, in particular it is a closed convex set and then it is weakly closed. Therefore, it is weakly closed sequentially.
%Thus, $y\in B_{M}\cap\M$
Let $(\theta_{n},E_{n},y_{n})\in Q_{M}$ be a sequence such that it converges to $(\theta ,E, y)\in\tau_{M}$. We are going to show $(\theta ,E, y)\in Q_{M}$. By definition for every $n\in\N$, $y_{n}\in  Ker(T_{\theta_{n}}-E_{n}I)\cap\M$
such that $\langle y_{n},u_{+}\rangle =1$. Since $y_{n}\longrightarrow^{w} y$
one has $\langle y,u_{+}\rangle =1$ and hence $y\neq 0$. Moreover, 
\begin{equation*}
B^{*}y_{n}=T_{\theta_{n}}y_{n}=E_{n}y_{n}\longrightarrow^{w}Ey.
\end{equation*}
By Proposition \ref{debilcerrado}, $y\in D(B^{*})$ and $B^{*}y=Ey$. That is, there exist $x\in D(B)$ and
$a,b\in\C$ such that
$y=x+au_{+}+bu_{-}$. Then, for each $n\in\N$ there exist $x_{n}\in D(B)$ and $c_{n}\in\C$  such that
\begin{equation*}
y_{n}=x_{n}+c_{n}u_{+}+c_{n}e^{-2i\theta_{n}}u_{-}\longrightarrow^{w}y=x+au_{+}+bu_{-}.
\end{equation*}
On the other hand, by using the inner product of the graph of $B^{*}$
\begin{align*}
\langle y_{n},u_{+}\rangle_{B^{*}} :=\langle y_{n},u_{+}\rangle +\langle B^{*}y_{n},B^{*}u_{+}\rangle
									&=\langle y_{n},u_{+}\rangle +\langle E_{n}y_{n},iu_{+}\rangle \\
									&=\langle y_{n},u_{+}\rangle -iE_{n}\langle y_{n},u_{+}\rangle \\
									&\longrightarrow^{w}\langle y,u_{+}\rangle -iE\langle y,u_{+}\rangle\\
									&=\langle y,u_{+}\rangle_{B^{*}}.
\end{align*}
Moreover,
\begin{equation*}
\langle y_{n},u_{+}\rangle_{B^{*}}=\langle x_{n},u_{+}\rangle_{B^{*}}+\langle c_{n}u_{+},u_{+}\rangle_{B^{*}}
					+\langle c_{n}e^{-2i\theta_{n}}u_{-},u_{+}\rangle_{B^{*}}
					=2c_{n}
\end{equation*}
\begin{equation*}
\langle y,u_{+}\rangle_{B^{*}}=\langle x,u_{+}\rangle_{B^{*}}+\langle au_{+},u_{+}\rangle_{B^{*}}
					+\langle bu_{-},u_{+}\rangle_{B^{*}}
					=2a.
\end{equation*}
Therefore $c_{n}\longrightarrow a$. Then 
%\end{equation*}c_{n}u_{+}+c_{n}e^{-2i\theta_{n}}u_{-}\longrightarrow^{w} au_{+}+ae^{-2i\theta}u_{-}.\end{equation*}
%Furthermore $x_{n}\longrightarrow^{w} \widehat{x}\in\H$. So
\begin{equation*}
x_{n}+c_{n}u_{+}+c_{n}e^{-2i\theta_{n}}u_{-}\longrightarrow^{w}x+au_{+}+ae^{-2i\theta}u_{-}.
\end{equation*}
By uniqueness of limits $y=x+au_{+}+ae^{-2i\theta}u_{-}$. Hence
$y\in Ker(T_{\theta}-EI)\setminus\left\lbrace 0\right\rbrace$. Finally, $Q_{M}$ is closed.
\end{proof}

Let us mention the next identity.


\begin{lemma}\label{lem3}
Let $y_{j}=x_{j}+c_{j}e^{i\theta_{j}}u_{+}+c_{j}e^{-i\theta_{j}}u_{-}\in Ker(T_{\theta_{j}}-E_{j}I)$ with $j=1,2$.
Then
\begin{equation*}
-4c_{1}\overline{c_{2}}sen(\theta_{1}-\theta_{2})=(E_{1}-E_{2})\langle y_{1},y_{2}\rangle.
\end{equation*}
\end{lemma}

The following result is formulated like in \cite{Gordon}.

\begin{lemma}\label{funcionW}
Let $F\subseteq Q_{M}$ be a compact set. The function $W_{F}:F\times F\longrightarrow\C$ such that
\begin{equation*}
W_{F}\left((\theta_{1},E_{1},y_{1}),(\theta_{2},E_{2},y_{2})\right) :=\langle y_{1},y_{2}\rangle
\end{equation*}
is continuous at least at a pair $(\varepsilon_{0},\varepsilon_{0})\in F\times F$.
\end{lemma}
\begin{proof}
Let $\left\lbrace e_{n}\right\rbrace_{n\in\N} $ be a orthonormal basis of $\M$. We define
$J_{m},J_{F}:F\longrightarrow\R$  with $m\in\N$ and $\varepsilon=(\theta,E,y)$ by
\begin{equation*}
J_{m}(\varepsilon):=\sum_{n=1}^{m}\vert\langle y, e_{n}\rangle\vert^{2}
\end{equation*}
and
\begin{equation*}
J_{F}(\varepsilon):=\Vert y\Vert^{2}.
\end{equation*}
Due to Parseval's identity, it turns out that for each $\varepsilon\in F$
\begin{equation*}
J_{F}(\varepsilon)=\sum_{n=1}^{\infty}\vert\langle y,e_{n}\rangle\vert^{2}
=\lim_{m\rightarrow\infty}J_{m}(\varepsilon).
\end{equation*}
Let $\varepsilon_{k}=(\theta_{k},E_{k},y_{k})\in F$ be a sequence that converges to $\varepsilon\in F$. Then,
$y_{k}\longrightarrow^{w}y$. Hence,
\begin{equation*}
\lim_{k\rightarrow\infty}J_{m}(\varepsilon_{k})
=\sum_{n=1}^{m}\vert\langle y,e_{n}\rangle\vert^{2}=J_{m}(\varepsilon).
\end{equation*}
Therefore, $J_{F}$ is pointwise limit of continuous functions. By \cite[Theorem 7.3]{Oxtoby}, there is some
$\varepsilon_{0}\in F$ such that $J_{F}$ is continuous at $\varepsilon_{0}=(\theta_{c},E_{c},y_{0})$.\\

We assert that $W_{F}$ is
continuous at $(\varepsilon_{0},\varepsilon_{0})$. If $\varepsilon_{n}=(\theta_{n},E_{n},y_{n})\longrightarrow\varepsilon_{0}$
and $\varepsilon'_{n}=(\theta'_{n},E'_{n},y'_{n})\longrightarrow\varepsilon_{0}$, then
\begin{equation*}
y_{n},y'_{n}\longrightarrow^{w}y_{0}
\end{equation*}
and by continuity of $J_{F}$ at $\varepsilon_{0}$,
\begin{equation*}
\Vert y_{n}\Vert,\Vert y'_{n}\Vert\longrightarrow \Vert y_{0}\Vert.
\end{equation*}
So, $y_{n},y'_{n}\longrightarrow y_{0}$.
Thus, 
\begin{equation*}
W_{F}(\varepsilon_{n},\varepsilon'_{n})=\langle y_{n},y'_{n}\rangle
\longrightarrow\langle y_{0}, y_{0}\rangle=W_{F}(\varepsilon_{0},\varepsilon_{0}).
\end{equation*}
Finally, $W_{F}$ is continuous at $(\varepsilon_{0},\varepsilon_{0})$.
\end{proof}


Let $\P:\tau\longrightarrow\R$, $\Pi:\tau\longrightarrow\left[ 0,\pi\right]$, $\RR:\tau\longrightarrow\left[ 0,\pi\right]\times\R$, $p:\left[ 0,\pi\right]\times\R\longrightarrow\R$ and $q:\left[ 0,\pi\right]\times\R\longrightarrow\left[ 0,\pi\right]$ be projections. We follow the same procedure that is used in the proof of \cite[Proposition 2*]{Gordon}.

\begin{prop}\label{prop2*}
If $F\subseteq Q_{M}$ is compact and $\P(F)$ is nowhere dense if and only if $\Pi(F)$ is nowhere dense.
\end{prop}
\begin{proof}
Suppose that there is a compact subset $F\subseteq Q_{M}$ such that $\P(F)$ is nowhere dense and $\Pi(F)$ contains a non-empty open set of $\left[ 0,\pi \right]$ which one denotes as $I$. Consider the partially ordered set given by the collection
\begin{equation*}
X:=\left\lbrace F'\subseteq F: F' \;is\;compact\;set\;in\;Q_{M}\;and\;\Pi(F')\supset I\right\rbrace.
\end{equation*}
We assert that $X$ has a minimal element. Let $\left\lbrace F_{\alpha}\right\rbrace_{\alpha\in\Delta} $ be
a chain in $X$ where $\Delta$ is an arbitrary set of indices. It turns out that
$\bigcap_{\alpha\in\Delta}F_{\alpha}$ is a compact subset of $F$ in $Q_{M}$. We assert that
$\Pi\left( \bigcap_{\alpha\in\Delta}F_{\alpha}\right)\supset I $. For all $\alpha\in\Delta$, there exists
$G_{\alpha}\subseteq\R\times\M$ such that $F_{\alpha}=\Pi(F_{\alpha})\times G_{\alpha}$. The inclusion follows
from the following fact
\begin{equation*}
\bigcap_{\alpha\in\Delta}F_{\alpha}\supseteq\bigcap_{\alpha\in\Delta}\Pi(F_{\alpha})\times\bigcap_{\alpha\in\Delta}G_{\alpha}.
\end{equation*}
Therefore, $\bigcap_{\alpha\in\Delta}F_{\alpha}$ is a lower bound of
$\left\lbrace F_{\alpha}\right\rbrace_{\alpha\in\Delta} $. We conclude by Zorn's lemma. Denote the minimal set by $\FF$.\\

Now we want to prove that there is some subset of $\FF$ such that its projections with respect to $\P$ and $\Pi$ are homeomorphic.
By Lemma \ref{funcionW}, there exists $\delta >0$ such that for all $\varepsilon,\varepsilon'\in \FF$
\begin{equation}\label{qqq}
d_{\FF\times \FF}\left( (\varepsilon,\varepsilon'),(\varepsilon_{0},\varepsilon_{0})\right)<\delta
\Rightarrow\left\vert W_{\FF}(\varepsilon,\varepsilon')-W_{\FF}(\varepsilon_{0},\varepsilon_{0})\right\vert <
\dfrac{\Vert y_{0}\Vert^{2}}{2}
\end{equation}
where $d_{\FF\times \FF}$ is the metric of $\FF\times \FF$.\\

Let $U$ be the ball in $\tau_{M}$ defined as
\begin{equation*}
U:=\left\lbrace\varepsilon\in \tau_{M} :d_{M}\left( \varepsilon,\varepsilon_{0}\right)<\frac{\delta}{3}\right\rbrace 
\end{equation*}
%with center $\varepsilon_{0}$ and radius $\frac{\delta}{3}$.
where $d_{M}$ denotes the metric on $\tau_{M}$. We are going to show that $p\vert_{\RR(\FF\cap\overline{U})}$ and $q\vert_{\RR(\FF\cap\overline{U})}$ are injective. That is,
for all $\varepsilon_{1}=(\theta_{1},E_{1},y_{1}),\varepsilon_{2}=(\theta_{2},E_{2},y_{2})\in \FF\cap\overline{U}$, it is sufficient to prove that $\theta_{1}=\theta_{2}$ if and only if $E_{1}=E_{2}$.
\begin{itemize}
\item $(\Rightarrow)$ Suppose that $\theta_{1}=\theta_{2}$. By Lemma \ref{lem3}
\begin{equation}\label{0}
(E_{1}-E_{2})\langle y_{1},y_{2}\rangle=0.
\end{equation}
Since $\varepsilon_{1},\varepsilon_{2}\in \overline{U}$,
\begin{equation*}
d_{\FF\times \FF}\left( (\varepsilon_{1},\varepsilon_{2}),(\varepsilon_{0},\varepsilon_{0})\right)=
d_{M}\left( \varepsilon_{1},\varepsilon_{0}\right)+d_{M}\left( \varepsilon_{2},\varepsilon_{0}\right)<\delta .
\end{equation*}
By (\ref{qqq}), 
\begin{equation*}
\left\vert\langle y_{1},y_{2}\rangle-\Vert y_{0}\Vert^{2}\right\vert
=\left\vert W_{\FF}(\varepsilon_{1},\varepsilon_{2})-W_{\FF}(\varepsilon_{0},\varepsilon_{0})\right\vert
<\dfrac{\Vert y_{0}\Vert^{2}}{2}.
\end{equation*}
Thus, $\langle y_{1},y_{2}\rangle\neq 0$ implies $E_{1}=E_{2}$.

\item $(\Leftarrow)$ Suppose that $E_{1}=E_{2}$. If $\theta_{1}\neq\theta_{2}$, then the operators
$T_{\theta_{1}}\upharpoonright_{\M}$ and $T_{\theta_{2}}\upharpoonright_{\M}$ have
an eigenvalue in common, but that contradicts to Theorem \ref{teo1.1}.
\end{itemize}
Next, $p\vert_{\RR(\FF\cap\overline{U})}$ and $q\vert_{\RR(\FF\cap\overline{U})}$ are injective and therefore
homeomorphisms. Then 
\begin{center}
$\P(\FF\cap\overline{U})=p\left[ \RR(\FF\cap\overline{U})\right]$ and $\Pi(\FF\cap\overline{U})=q\left[ \RR(\FF\cap\overline{U})\right] $
\end{center}
are homeomorphic to $\RR(\FF\cap\overline{U})$ and therefore between them.\\

On the other hand, $\Pi(\FF)= \Pi(\FF\cap U)\cup \Pi(\FF\setminus U)$ where $\Pi(\FF)$ contains to $I$. Since
$\P(\FF\cap\overline{U})\subseteq \P(\FF)$, by hypothesis it is nowhere dense in $\R$. But
$\Pi(\FF\cap\overline{U})$ is nowhere dense in $\left[ 0,\pi \right]$ and $\Pi(\FF\cap U)$ inherits that property. Then $I$ is not
contained in $\Pi(\FF\cap U)$. Hence $I\subseteq \Pi(\FF\setminus U)$. Moreover, $\FF\setminus U$ is properly contained in $\FF$ and is compact in $Q_{M}$. But this contradicts the minimality of $\FF$. Consequently,
$\Pi(F)$ is nowhere dense in $\left[ 0,\pi \right]$. The other direction is analogous.
\end{proof}

Finally we arrive at the following proposition.

\begin{prop}\label{prop2}
Let $Y$ be a countable union of closed nowhere dense subsets in $\R$. Then
\begin{equation*}
\left\lbrace \theta\in\left[ 0,\pi\right)\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap Y\neq\varnothing\right\rbrace 
\end{equation*}
is a countable union of closed nowhere dense subsets in $\left[ 0,\pi\right]$.
\end{prop}
\begin{proof}
It turns out that
\begin{equation*}
\left\lbrace \theta\in\left[ 0,\pi\right)\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap Y\neq\varnothing\right\rbrace
=\Pi(Q\cap \P^{-1}(Y))
\end{equation*}
where $Q:=\left\lbrace (\theta,E,y)\in\tau:y\in Ker(T_{\theta}-EI)\;and\;\langle y,u_{+}\rangle=1\right\rbrace$.\\

By hypothesis, there is a sequence $\left\lbrace Y_{n}\right\rbrace _{n\in\N} $ of closed nowhere dense subsets
in $\R$ such that $Y= \bigcup_{n\in\N}Y_{n}$. For all $M\in\N$ we define
\begin{center}
$Q^{(M)}:=Q_{M}\cap  \left( \left[ -M,M\right]\times\left[-M,M\right]\times B_{M}\cap\M\right)  $ 
\end{center}
which is closed in $\tau_{M}$ by Lemma \ref{lem2}. Further, due to Tychonoff Theorem and Banach-Alaoglu-Bourbaki Theorem,
$Q^{(M)}$ is compact in $\tau_{M}$. It is true that $Q=\bigcup_{M\in\N}Q^{(M)}$. Then,
\begin{equation}\label{proyecciones}
\Pi(Q\cap \P^{-1}(Y))=\bigcup_{M,n\in\N}\Pi\left( Q^{(M)}\bigcap \P^{-1}\left( Y_{n}\right) \right).
\end{equation}
Since $Q^{(M)}\bigcap \P^{-1}\left( Y_{n}\right)$ is closed and contained in a compact, it inherits compactness. Furthermore, $\P\left( Q^{(M)}\bigcap \P^{-1}\left( Y_{n}\right)\right)=\P\left( Q^{(M)} \right) \bigcap Y_{n} $ is contained in a nowhere dense set, thus, it inherits that property. According to the last proposition, $\Pi\left( Q^{(M)}\bigcap \P^{-1}\left( Y_{n}\right) \right)$ is nowhere dense. In addition, it is compact by continuity of $\Pi$. But compact implies closed in $\R^{2}$.
\end{proof}

With the above we can prove our theorem on \textbf{forbidden extension parameters}.

\begin{theorem}\label{TEO3}
Let $\theta_{0}$ fixed. Then
\begin{equation}\label{setprincipal}
\left\lbrace \theta\in\left[ 0,\pi\right]\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap\sigma(T_{\theta_{0}}\upharpoonright_{\M})=\varnothing\right\rbrace 
\end{equation}

is dense $\textit{G}_{\delta}$ in $\left[ 0,\pi\right]$.
\end{theorem}
\begin{proof}
Consider the set
\begin{equation*}
Y:=\sigma(T_{\theta_{0}}\upharpoonright_{\M})\cap\bigcup_{\theta\in\left[ 0,\pi\right)\setminus\lbrace \theta_{0}\rbrace} \sigma_{p}(T_{\theta}\upharpoonright_{\M}).
\end{equation*}
By Proposition \ref{prop2} and Corollary \ref{prop1} one has that
\begin{equation*}
\left\lbrace \theta\in\left[ 0,\pi\right]\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap Y\neq\varnothing\right\rbrace
\end{equation*}
is a countable union of closed nowhere dense subsets in $\left[ 0,\pi\right]$. Thus,
\begin{equation*}
N:=\left\lbrace \theta\in\left[ 0,\pi\right]\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap Y=\varnothing\right\rbrace
\end{equation*}
is dense $\textit{G}_{\delta}$ in $\left[ 0,\pi\right]$. Furthermore

\begin{equation*}\sigma_{p}(T_{\theta}\upharpoonright_{\M})\bigcap Y=\left\{ \begin{array}{lcc}
                				\sigma_{p}(T_{\theta}\upharpoonright_{\M})\bigcap\sigma(T_{\theta_{0}}\upharpoonright_{\M})	&   if  & \theta\neq\theta_{0} \\

             					\\ \varnothing &  if  &\theta =\theta_{0}
             			\end{array}
             			 \right.\end{equation*}
Therefore, $\theta_{0}\in N$. However, 
\begin{center}
$\theta_{0}$ belongs to the set (\ref{setprincipal}) if and only if
$\sigma_{p}(T_{\theta_{0}}\upharpoonright_{\M})=\varnothing$.
\end{center}
 Then

\begin{equation*}
N =\left\lbrace \theta\in\left[ 0,\pi\right]\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap\sigma(T_{\theta_{0}}\upharpoonright_{\M})=\varnothing\right\rbrace\cup\left\lbrace \theta_{0}\right\rbrace.
\end{equation*}
\begin{itemize}
\item Case 1. If $\sigma_{p}(T_{\theta_{0}}\upharpoonright_{\M})=\varnothing$, then $N$ is equal to the set
(\ref{setprincipal}).
\item Case 2. Suppose $\sigma_{p}(T_{\theta_{0}}\upharpoonright_{\M})\neq\varnothing$. Thus,
\begin{equation*}
N\setminus\left\lbrace \theta_{0}\right\rbrace =\left\lbrace \theta\in\left[ 0,\pi\right]\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap\sigma(T_{\theta_{0}}\upharpoonright_{\M})=\varnothing\right\rbrace.
\end{equation*}
Since $N$ is dense in $\left[ 0,\pi\right]$, $N\setminus\left\lbrace \theta_{0}\right\rbrace$ is too.
Moreover, if $\left\lbrace F_{n}\right\rbrace _{n\in\N} $ is the sequence of open subsets in $\left[ 0,\pi\right]$ such that $N=\bigcap_{n\in\N}F_{n}$, then
$N\setminus\left\lbrace \theta_{0}\right\rbrace=\bigcap_{n\in\N}\left( F_{n}\setminus\left\lbrace \theta_{0}\right\rbrace\right) $ and each $F_{n}\setminus\left\lbrace \theta_{0}\right\rbrace$ is open in $\left[ 0,\pi\right]$.
\end{itemize}
In conclusion,
\begin{equation*}
\left\lbrace \theta\in\left[ 0,\pi\right]\mid\sigma_{p}(T_{\theta}\upharpoonright_{\M})\cap\sigma(T_{\theta_{0}}\upharpoonright_{\M})=\varnothing\right\rbrace
\end{equation*}
is dense $\textit{G}_{\delta}$ in $\left[ 0,\pi\right]$.
\end{proof}

%Due to the invariance of both  and essential spectrum we conclude the following results.
Denote by $\sigma _{ac}$ and $\sigma _{sc}$ the absolutely continuous and singular continuous spectrum respectively. We mean by $int$ to interior of a set. Remind that $\sigma _{p}$ denotes the set of eigenvalues. We get the following corollaries. 
%\footnote{Denote by $\sigma _{ac}(A)$ and $\sigma _{sc}(A)$ the absolutely continuous and singular continuous spectrum respectively of an operator $A=A^{*}$. } .

\begin{corollary}\label{cor4.1}
Let $\theta_{0}$ fixed and suppose $\sigma_{ac}(T_{\theta_{0}}\upharpoonright_{\M})=\varnothing$.
Then 
\begin{equation*}
\left\lbrace \theta\in\left[ 0,\pi\right]\mid\sigma(T_{\theta}\upharpoonright_{\M})\cap int\;\sigma(T_{\theta_{0}}\upharpoonright_{\M})\subseteq  \sigma_{sc}(T_{\theta}\upharpoonright_{\M}) \right\rbrace 
\end{equation*}
is dense $\textit{G}_{\delta}$ in $\left[ 0,\pi\right]$.
\end{corollary}
\begin{proof}
Follows by the invariance of absolutely continuous spectrum for self-adjoint extensions and Theorem \ref{TEO3}.
\end{proof}
