In order to prove the second main theorem we note the following fact.

\begin{lemma}
Let $\theta':=\frac{1}{2}arg\left( -\frac{c-i}{c+i}\right)$  with $c\in\R\setminus\left\lbrace 0\right\rbrace$. The functions
\begin{equation*}
\Psi_{c}:\R\setminus\left\lbrace -\frac{1}{c}\right\rbrace \longrightarrow\left( 0,\pi\right)\setminus\left\lbrace \theta'\right\rbrace\;and\;
\Psi:\R\longrightarrow\left( 0,\pi\right)
\end{equation*}
where
\begin{equation*}
\Psi_{c}(\alpha):=\frac{1}{2}arg\left[ -\frac{1+\alpha(c-i)}{1+\alpha(c+i)}\right]\;and\;
\Psi(\alpha):=\Psi_{c=0}(\alpha)
\end{equation*}
%\frac{1}{2}arg\left( \frac{-1+\alpha i}{1+\alpha i}\right)
are homeomorphisms.
\end{lemma}
\begin{proof}
It is enough to note that 
\begin{equation*}
\Psi_{c}^{-1}: \left( 0,\pi\right)\setminus\left\lbrace \theta'\right\rbrace\longrightarrow\R\setminus\left\lbrace -\frac{1}{c}\right\rbrace\;and\;\Psi^{-1}: \left( 0,\pi\right)\longrightarrow\R
\end{equation*}
where
\begin{equation*}
\Psi_{c}^{-1}(\theta):=-\frac{1+e^{2\theta i}}{c-i+(c+i)e^{2\theta i}}\;and\;\Psi^{-1}(\theta):=\Psi_{c=0}^{-1}(\theta)
\end{equation*}
is the inverse function of $\Psi_{c}$ and $\Psi$ respectively. In addition, both $\Psi_{c}$ and $\Psi$ are composition of continuous functions. Analogously for $\Psi_{c}^{-1}$ and $\Psi^{-1}$.
\end{proof}

Finally we can prove the second main theorem.

\begin{proof}[Proof of Theorem \ref{maintheorem2}]
Suppose $c\neq 0$. By Theorem \ref{ultimate},
\begin{equation*}
-\frac{1}{c}\in\Gamma_{c}\Longleftrightarrow 0\in M
\end{equation*}
where $M$ denotes to the set (\ref{setprincipal}) with $\theta_{0}=\frac{\pi}{2}$. If $-\frac{1}{c}\not\in\Gamma_{c}$, then $\Gamma_{c}$ can be mapped by $\Psi_{c}$. Again by Theorem \ref{ultimate} and putting $\theta=\Psi_{c}(\alpha)$,

\begin{align*}
\Psi_{c}(\Gamma_{c})&=\left\lbrace \Psi_{c}(\alpha):\sigma_{p}(A_{\alpha,c}\upharpoonright_{\M})\cap\sigma(A\upharpoonright_{\M})=\varnothing\right\rbrace \\
			  &=\left\lbrace \theta\in\left( 0,\pi\right)\setminus\left\lbrace \theta'\right\rbrace :\sigma_{p}\left( T_{\theta}\upharpoonright_{\M}\right) \cap\sigma\left( T_{\frac{\pi}{2}}\upharpoonright_{\M}\right) =\varnothing\right\rbrace.
\end{align*}
It is obtained that $\Gamma_{c}=\Psi_{c}^{-1}\left( M\setminus\left\lbrace\theta'\right\rbrace\right) $. We realize of the following:
\begin{itemize}
\item[a)] If $\theta'\not\in M$, one concludes by Theorem \ref{TEO3}.
\item[b)] If $\theta'\in M$, the idea of Case 2 in Proof of Theorem \ref{TEO3} is followed for the set
$\Gamma_{c}$.
\end{itemize}
For the case in which $-\frac{1}{c}\in\Gamma_{c}$, we have that
$\Gamma_{c}\setminus\left\lbrace -\frac{1}{c}\right\rbrace =\Psi_{c}^{-1}\left( M\setminus\left\lbrace 0,\theta'\right\rbrace\right) $. Therefore, $\Gamma_{c}$ contains a dense $G_{\delta}$ subset in $\R$.\\

If $c=0$, according to (\ref{tetace}) the corresponding coupling $\alpha$ with $\theta =0=\theta'$ is $\alpha=\infty$ which
is not considered. Therefore $\Gamma=\Psi^{-1}\left( M\setminus\left\lbrace 0\right\rbrace\right)$ and one repeats the procedure in a) and b).
\end{proof}

\begin{remark}
If $\varphi\in\H_{-1}\setminus\H$, then there is a unique set
\begin{equation*}
\left\lbrace x\in\sigma(A\upharpoonright_{\M}):x\not\in\sigma_{p}(A_{\alpha}\upharpoonright_{\M}),\forall\;\alpha\in\R\setminus\left\lbrace 0\right\rbrace \right\rbrace .
\end{equation*}
In the same way there is a unique set
\begin{equation*}
\left\lbrace \alpha\in\R\mid\sigma_{p}(A_{\alpha}\upharpoonright_{\M})\cap\sigma(A\upharpoonright_{\M})=\varnothing\right\rbrace.
\end{equation*}
Even if $\varphi\in\H_{-2}\setminus\H_{-1}$ is homogeneous to $A$ (see \cite[Subsection 1.3.3]{ALBKUR}), the set is unique.
\end{remark}


%------------------------------
We conclude the following corollaries.

\begin{corollary}
Suppose the hypothesis of Theorem \ref{maintheorem1} and $(A+iI)^{-1}\varphi$ is cyclic for $A$. The sets
\begin{equation*}
\left\lbrace x\in\sigma(A):x\not\in\sigma_{p}(A_{\alpha,c}),\forall\;\alpha\in\R\setminus\left\lbrace 0\right\rbrace \right\rbrace 
\end{equation*}
and
\begin{equation*}
\left\lbrace \alpha\in\R\mid\sigma_{p}(A_{\alpha,c})\cap\sigma(A)=\varnothing\right\rbrace
\end{equation*}
contain a dense $\textit{G}_{\delta}$ subset in $\sigma(A)$ and $\R$ respectively.
\end{corollary}

Denote by $\sigma_{dis}$ the discrete spectrum.

\begin{corollary}
Suppose the hypothesis of Theorem \ref{maintheorem1}. Then 
\begin{equation*}
\Theta_{c}:=\left\lbrace \alpha\in\R\mid\sigma_{p}(A_{\alpha,c}\upharpoonright_{\M})=\sigma_{dis}(A_{\alpha,c}\upharpoonright_{\M})\right\rbrace
\end{equation*}
contains a dense $\textit{G}_{\delta}$ in $\R$. Also, if $\sigma_{ac}(A\upharpoonright_{\M})=\varnothing$
\begin{equation*}
\Delta_{c}:=\left\lbrace \alpha\in\R\mid\sigma(A_{\alpha,c}\upharpoonright_{\M})\cap int\;\sigma(A\upharpoonright_{\M})\subseteq  \sigma_{sc}(A_{\alpha,c}\upharpoonright_{\M}) \right\rbrace 
\end{equation*}
contains a dense $\textit{G}_{\delta}$ in $\R$.
\end{corollary}
\begin{proof}
The proof follows similar lines to Corollary \ref{cor4.1} and \ref{discreteeigen}.
\end{proof}

\begin{corollary}
If the hypothesis of Theorem \ref{maintheorem1} holds and $\varphi\in\H_{-2}\setminus\H_{-1}$, then 
\begin{equation}\label{thetaset}
\left\lbrace \left( \alpha,c\right) \in\R^{2}\mid\sigma_{p}(A_{\alpha,c}\upharpoonright_{\M})=
\sigma_{dis}(A_{\alpha,c}\upharpoonright_{\M})\right\rbrace 
\end{equation}
%\left\lbrace \left( \alpha,c\right) \in\R^{2}\mid\sigma_{p}(A_{\alpha,c}\upharpoonright_{\M})%\cap\sigma(A\upharpoonright_{\M})=\varnothing \right\rbrace
is a dense set in $\R^{2}$. In addition if $\sigma_{ac}(A\upharpoonright_{\M})=\varnothing$, 
\begin{equation}\label{deltaset}
\left\lbrace \left( \alpha,c\right) \in\R^{2}\mid\sigma(A_{\alpha,c}\upharpoonright_{\M})\cap int\;\sigma(A\upharpoonright_{\M})\subseteq  \sigma_{sc}(A_{\alpha,c}\upharpoonright_{\M}) \right\rbrace 
\end{equation}
is a dense set in $\R^{2}$
\end{corollary}
\begin{proof}
It suffices to see that (\ref{thetaset}) and (\ref{deltaset}) are equal to $\cup_{c\in\R}\left( \Theta_{c}\times\left\lbrace c\right\rbrace \right) $ and $\cup_{c\in\R}\left( \Delta_{c}\times\left\lbrace c\right\rbrace \right) $ respectively.
\end{proof}

