\begin{nobreaks}
\vspace{2mm}
\begin{mdframed}
\textbf{\underline{seMCD-algorithm for multiple overlapping seMCD-buckets  as in \eqref{eq_ordering_buckets}}}\\[2mm]
Define $U_N^{(h_0)}=-\infty$ and $L_N^{(h_{k+1})}=\infty$  
for all $N$.\\[1mm]
Continue taking samples until, for the first time $\tau$, it holds $\mathfrak{r}_\tau-\mathfrak{l}_\tau\le 2$, where, for arbitrary $N$,
\begin{align*}
&\mathfrak{l}_N := \max\{0\le j\le k: S_N\ge U_N^{(h_j)}\},\qquad \mathfrak{r}_N := \min\{\mathfrak{l}_N< j \le k+1: S_N\le L_N^{(h_j)}\}.
\end{align*}
Output the seMCD-bucket $(h_{\mathfrak{l}_{\tau}},h_{\mathfrak{r}_{\tau}})$.
\end{mdframed}
\end{nobreaks}

\begin{Remark}
By construction the number of samples  until the algorithm stops is smaller for the overlapping than the non-overlapping case if the same split points are used. In this case, for equal-width seMCD-buckets, the output bucket will usually be wider for the overlapping case. Alternatively, one can use the same buckets as in the non-overlapping case and add overlapping ones. Then, the seMCD-algorithm for the overlapping buckets is still guaranteed to stop before the corresponding non-overlapping one. For equal-width seMCD-buckets, the output bucket will then typically have the same widths in both cases. 
\end{Remark}

    \subsubsection{Statistical properties of the seMCD-algorithm}\label{sec_stat_guar}

    We are now ready to explain why the statistical guarantees carry over to the situation with more than two buckets both for the non-overlapping and overlapping case:

\begin{Lemma}\label{lemma_new_FWER}
Let the monotonicity condition \ref{ass_Monotonnicity_boundary_sequences} hold.
Consider a set of split points $h_1, \ldots, h_k$ for the overlapping or non-overlapping seMCD-algorithm, and denote the true (unknown) value by $h$.  Denote by $\sB=\sB(\bm{\xi}_1,\bm{\xi}_2,\ldots)$ the seMCD-bucket that the algorithm outputs. Then,	      
\begin{align*}
&\P_h(h\in \sB)\ge \P_h\left( L_N^{(h)}<S_N<U_N^{(h)} \text { for all }N \in\mathbb{N}\right).
\end{align*}
\end{Lemma}


\begin{proof}[Proof of Lemma \ref{lemma_new_FWER}]
	By the monotonicity condition \ref{ass_Monotonnicity_boundary_sequences} it holds, with the notation $[k]=\{1,\ldots,k\}$,
\begin{align*}
    &\P_h(h \in \sB) = 1-\P_h(h \notin \sB)\\ 
    &\geq 1-\P_h\left(\left( \bigcup_{\{\ell \in [k]: h_\ell\geq h\}} \left\{\exists N \in \mathbb N: S_{N}\geq U_{N}^{(h_\ell)} \right\} \right) \cup \left( \bigcup_{\{\ell \in [k]: h_\ell\leq h\}} \left\{\exists N \in \mathbb N: S_{N}\leq L_{N}^{(h_\ell)}  \right\} \right) \right)\\
    &\geq 1-\P_h\left( \left\{\exists N \in \mathbb N:S_{N}\geq U_{N}^{(h)}\right\}  \cup  \left\{\exists N \in \mathbb N: S_{N}\leq L_{N}^{(h)} \right\} \right)\\
    &= \P_h\left( L_{N}^{(h)} < S_{N}< U_{N}^{(h)} \text{ for all } N \in \mathbb N \right). 
\end{align*}
\end{proof}

Lemma \ref{lemma_new_FWER} shows, in particular, that probabilistic statements as in \eqref{I}  with respect to the split points $h_j$, $j=1,\ldots,k$, carry over to the desired statistical guarantees of the seMCD-algorithm as long as the monotonicity condition \ref{ass_Monotonnicity_boundary_sequences} is satisfied. This is the case for the non-parametric boundary sequences discussed in Section~\ref{sec_sequential_construction}.

The following result gives a lower bound for the probability that the algorithm stops in finite time, which we will show to be equal to one for the boundary sequences in Section~\ref{sec_sequential_construction}. 



\begin{Lemma}\label{lem_new_stop}
Denote by $\tau=\tau(\bm{\xi}_1,\bm{\xi}_2,\ldots)$ the stopping time of the seMCD-algorithm, i.e.\ the number of steps until the algorithm terminates and outputs a seMCD-bucket.
Let $\wideunderbar{h}\le h\le \widebar{h}$ and $(\wideunderbar{h},\widebar{h})$ be one of the seMCD-buckets,  then
\begin{align*}
	\P_h(\tau<\infty)&\ge \P_h\left(\liminf_{N\to\infty}(S_N-U_N^{(\wideunderbar{h})})>0\right)+\P_h\left(\liminf_{N\to\infty}(L_N^{(\widebar{h})}-S_N)>0\right)-1.
\end{align*}
\end{Lemma}
In particular, if the two probabilities on the right-hand side are equal to one, then the stopping time is almost surely finite.

\begin{proof}
By construction, the algorithm will be guaranteed to stop if the seMCD-process is above $U_N^{(\wideunderbar{h})}$ and at the same time below $L_N^{(\widebar{h})}$. If $\liminf_{N\to\infty}(S_N-U_N^{(\wideunderbar{h})})>0$, then $S_N $ will be above $U_N^{(\wideunderbar{h})}$ for all $N$ large enough. Similarly, if $\liminf_{N\to\infty}(L_N^{(\widebar{h})}-S_N)>0$, the seMCD process $S_N$ will  be below $L_N^{(\widebar{h})}$ for all $N$ large enough. Consequently,
    \begin{align*}
	\P_h(\tau<\infty)&\ge \P_h\left(\liminf_{N\to\infty}(S_N-U_N^{(\wideunderbar{h})})>0,\;\liminf_{N\to\infty}(L_N^{(\widebar{h})}-S_N)>0\right).
\end{align*}
By $P(A\cap B)= P(A)+P(B)-P(A\cup B)\ge P(A)+P(B)-1$, the assertion follows.
\end{proof}

\begin{Remark}\label{rem_simplicial}
   Despite this stopping guarantee   
   the methodology does not overcome the curse of dimensionality associated with some depth functions, such as the simplicial depth. Indeed, the simplicial depth, computed with respect to absolutely continuous distributions, that are angularly symmetric about the origin, contracts to 0 with rate $O(1/2^d)$, when the dimension $d$ grows \citep[Theorem 4]{LiuSimplicial}. In particular, for $d\ge 5$, all simplicial depth values are included in a (hypothetical) seMCD-depth bucket covering $[0,0.1]$. So, while such a bucket is still meaningful for $d=1$, this is no longer the case for $d\ge 1$. \\ 
   To guarantee a similar precision for each dimension $d$, the split points need to be scaled by the factor $1/2^{d-1}$. However, with such rescaled buckets more seMCD-samples are required in higher dimensions. In fact, some preliminary simulations 
   with $d=5$ and overlapping buckets with non-rescaled split points of $0.05,0.1,0.15,\ldots, 0.6$ revealed that the samples required until the algorithm stops were of the order of magnitude of $10^3/2$ larger for the rescaled buckets than for the non-rescaled ones.
\end{Remark}


\subsubsection{Greedy seMCD-algorithm}\label{sec_another_look_algorithm}
In this section, we introduce an alternative algorithm, that has both advantages and disadvantages over the previously described approach.
 Here, we keep track of the  feasible output seMCD-buckets by tracking the largest feasible lower index $\mathfrak{l}$ as well as the smallest feasible upper index $\mathfrak{r}$, with the meaning that all buckets contained in $(h_{\mathfrak{l}},h_{\mathfrak{r}})$ are still feasible output buckets. The algorithm terminates as soon as only one bucket, or the non-empty intersection of two buckets, is contained in this interval and outputs this interval. 
We call the algorithm greedy as, due to this tracking, the number of checks necessary to update $\mathfrak{r}$ and $\mathfrak{l}$ after an additional sample is taken is smaller than in the previous algorithms. Indeed, the maximum/minimum are only taken over still feasible indices $\mathfrak{l}<j<\mathfrak{r}$ in the greedy algorithm, while they are taken over all $j$ in the previous algorithms.

\vspace{2mm}
\begin{mdframed}
\textbf{\underline{Greedy seMCD-algorithm}}

\renewcommand{\theenumi}{\arabic{enumi}}
\renewcommand{\labelenumi}{\textbf{Step} \textbf{\theenumi}:}
\begin{enumerate}[align=left,leftmargin=*,widest=10]
	\item Set the lower feasible index $\mathfrak{l}=0$ and the upper feasible index to $\mathfrak{r}=k+1$.
	\item Take an additional sample and check in the following order
		\begin{itemize}
			\item[1.] if, for some $\mathfrak{l}< j <\mathfrak{r}$, it holds $S_N\ge U_N^{(h_j)}$:\\[2mm] Update $\mathfrak{l} := \max\{\mathfrak{l}< j <\mathfrak{r}: S_N\ge U_N^{(h_j)}\}$. \\[2mm]
            If $\mathfrak{r}-\mathfrak{l}=1$ in the non-overlapping case, resp.\ $\mathfrak{r}-\mathfrak{l}\le 2$ in the overlapping case,\\ go to Step~3.\\[1mm]
			\item[2.] if, for some $\mathfrak{l}< j <\mathfrak{r}$, it holds $S_N\le L_N^{(h_j)}$:\\[2mm] Update $\mathfrak{r} := \min\{\mathfrak{l}< j <\mathfrak{r}: S_N\le L_N^{(h_j)}\}$.\\[2mm] If $\mathfrak{r}-\mathfrak{l}=1$ in the non-overlapping case, resp.\ $\mathfrak{r}-\mathfrak{l}\le 2$ in the overlapping case,\\ go to Step~3.
            \end{itemize}
			\item Output the seMCD-bucket $(h_{\mathfrak{l}},h_{\mathfrak{r}})$.
		\end{enumerate}
\end{mdframed}

The greedy algorithm produces a nested sequence of intervals $(h_{\mathfrak{l}},h_{\mathfrak{r}})$ which contain the true value uniformly with a probability of at least $1-\alpha$.   It stops as soon as this interval equals one of the prespecified seMCD-buckets or their non-empty intersection. 

The greedy algorithm stops earlier than the previous algorithm: Indeed, it can already stop within the gray area as in Figure~\ref{fig_nonstopping_regions}, for example, if the seMCD-process in (a) first crosses above the upper dash-dotted orange line and then -- without leaving the gray area -- below the lower dashed blue line.  In fact, if $\wideunderbar{h}< h<\widebar{h}$ for the true value $h$ and $(\wideunderbar{h},\widebar{h})$ is one of the seMCD-buckets, then the greedy algorithm stops as soon as the seMCD-algorithm has at least once been above the upper boundary sequence associated with $\wideunderbar{h}$ and below the lower boundary sequence associated with $\widebar{h}$. Consequently, the lower bound in Lemma~\ref{lem_new_stop} can be replaced by:
\begin{align*}
	\P_h(\tau_{\operatorname{greedy}}<\infty)&\ge 
	 \P_h\left(S_{\wideunderbar{N}}\ge U_{\wideunderbar{N}}^{(\wideunderbar{h})}\text{ for some }\wideunderbar{N}\ge 1\right)+\P_h\left(S_{\widebar{N}}\le L_{\widebar{N}}^{(\widebar{h})}\text{ for some }\widebar{N}\ge 1\right)-1.
\end{align*}
This comes at the cost of a higher probability of outputting the wrong bucket: For example, in Figure~\ref{fig_nonstopping_regions} the seMCD-process with true value in $(0.1,0.25)$ could first falsely cross the upper dashed-dotted blue while remaining between the green lines, then fall below the lower dashed green line to falsely output the bucket $(0.25,0.4)$ before entering the white area between the blue and orange lines, where the original algorithm would correctly output the bucket $(0.1,0.25)$. While this happens with low probability and does not affect the algorithms statistical guarantees, it is most likely to occur at the beginning, where each new sample has a larger impact on the seMCD-process  and the curves are still close together, forming a larger gray area. In other words, the original algorithm is more conservative, especially at the beginning of the sampling. This is a desirable property -- in particular in combination with the non-parametric asymptotic boundary sequences as discussed in Section~\ref{sec_sequential_construction}. However, the assertion and proof of Lemma~\ref{lemma_new_FWER} and thus the corresponding statistical guarantee also hold for the greedy algorithm.

\subsection{SeMCD-buckets for monotonic E-depths}\label{sec_transformation}
In Section~\ref{type_b} monotonic E-depths were introduced which are of the form
\begin{align*}
   g:= F(h):=F(\E(H(\bm{\xi})))
\end{align*}
for a strictly monotonic function $F$. In the following, we will consider $F$ to be strictly increasing. The less common strictly decreasing case is analogous. The seMCD-methodology based on such monotonic E-depths is applicable for the calculation of depth buckets as in Section~\ref{section_depth_level_sets} or anomaly detection as in Section~\ref{section_outlier} by choosing non-overlapping depth buckets 
\begin{align*}
(-\infty,g_1),(g_1,g_2),\ldots,(g_l,\infty), \qquad  \text{with } \quad g_1<g_2<\ldots<g_l\quad \text{ and }\quad g_j=F(h_j).
\end{align*}
For the overlapping case, one can similarly use $   (-\infty,g_2), (g_1,g_3), \ldots, (g_{l-2},g_l), (g_{l-1},\infty).$
This is because, for $F$ strictly increasing and any $\ell<u$,
\begin{align*}
   h_{\ell} < \E (H(\bm{\xi})) < h_{u}\quad \iff \quad g_{\ell} <F(\E (H(\bm{\xi})))<g_u.
\end{align*}
Consequently, one can run the usually seMCD-algorithm with the seMCD-buckets based on $h_j$, $j=1,\ldots,l$,  for $\E (H(\bm{\xi}))$ and then  output the corresponding bucket based on $g_j=F(h_j)$, $j=1,\ldots,l$, for $F(\E (H(\bm{\xi})))$ without losing the statistical guarantees.

For binary maximum depth classification in combination with E-depths we have proposed to use the seMCD-algorithm directly on the difference of the two empirical depths as in \eqref{eq_classification_difference}. For the monotonic E-depths, this difference reads with the same notation as in Section~\ref{subsec_classification}
\begin{align}\label{eq_diff_modified_E_class}
    F(\E[ H_{\bx_1,\ldots,\bx_{r_x}}(\bm \zeta)])-F(\E[H_{\by_1,\ldots,\by_{r_y}}(\bm \zeta)]).
\end{align}
In combination with the non-overlapping seMCD-buckets $(-\infty,0),(0,\infty)$, the methodology is applicable by using the same seMCD-buckets on $\E[ H_{\bx_1,\ldots,\bx_{r_x}}(\bm \zeta)-H_{\by_1,\ldots,\by_{r_y}}(\bm \zeta)]$ because this expected value is negative (positive) iff the value in \eqref{eq_diff_modified_E_class} is negative (positive). Thus, the statistical guarantee remains. However, because of the non-linearity of $F$, using an additional overlapping block $(-\epsilon_F,\epsilon_F)$ for the quantity in \eqref{eq_diff_modified_E_class} requires of an additional assumption. Let us assume that $F$ is  Lipschitz-continuous with Lipschitz constant $L_F>0$. Then, using the seMCD-algorithm with the third bucket of $(-\epsilon_F/L_F,\epsilon_F/L_F)$ on $\E[ H_{\bx_1,\ldots,\bx_{r_x}}(\bm \zeta)-H_{\by_1,\ldots,\by_{r_y}}(\bm \zeta)]$ gives the desired statistical guarantee for the quantity \eqref{eq_diff_modified_E_class} with the buckets $(-\infty,0),(-\epsilon_F,\epsilon_F),(0,\infty)$. This is because
\begin{align*}
  \left|\E[ H_{\bx_1,\ldots,\bx_{r_x}}(\bm \zeta)-H_{\by_1,\ldots,\by_{r_y}}(\bm \zeta)]\right|\le \frac{\epsilon_F}{L_F}\
     \implies  
  \left |F( \E[ H_{\bx_1,\ldots,\bx_{r_x}}(\bm \zeta)])-F(\E[H_{\by_1,\ldots,\by_{r_y}}(\bm \zeta)])\right|\le \epsilon_F.
\end{align*}
Note that, depending on the true underlying depth values (not only the difference), this might be a very conservative procedure in terms of the true coverage for the $(-\epsilon_F,\epsilon_F)$-bucket.

\section{Construction of the boundary sequences}\label{sec_boundary}
By Lemma~\ref{lemma_new_FWER} the algorithms described in the previous section require lower and upper boundary sequences that fulfil \eqref{I}, in order to keep their statistical guarantees. In constructing such boundary sequences, we will make use of the following connection to sequential testing: In the latter, the sample size is not fixed in advance. Instead, data collection continues until a stopping criterion is reached. As with classical testing, the probability of a type-I-error is controlled at a fixed level $\alpha$, that is, if the null hypothesis is true, the procedure will stop with a probability of at most $\alpha$. Typically, for a sequence of iid\ random variables $Y_1,Y_2,\ldots$, with $h=\E (Y_1)$ and a null hypothesis of $h=h_1$, the test decision is based on the partial sum process $S_N=\sum_{i=1}^NY_i$ in addition to the appropriate boundary sequences $L_N^{(h_1)}$ and $U_N^{(h_1)}$. The sampling stops as soon as $S_N \not\in (L_N^{(h_1)},U_N^{(h_1)})$. Clearly, the outlined sequential test with $Y_i=H(\bm{\xi}_i)$ controls the type-I-error at level $\alpha$ iff \eqref{I} holds.

If the distribution of the seMCD process $\{S_N\}$ depends only on the unknown quantity of interest $h=\E (H(\bm{\xi}))$, but is otherwise known, then the probabilities in \eqref{I} are in principle known, permitting the construction of such boundary sequences. However, other scenarios are possible: It might happen that the distribution of the seMCD-process is known but not analytically accessible, that it depends additionally on other unknown quantities, or that it is indeed not known at all. To elaborate, in the context of depth calculation as discussed in this paper, we encounter the following cases:
\renewcommand{\theenumi}{\arabic{enumi}}
\renewcommand{\labelenumi}{\textbf{Case} \textbf{\theenumi}:}
\begin{enumerate}[wide]
	\item \label{Case1}The distribution of $H(\bm{\xi})$ is fully known up to the unknown expectation $h$, with all the probabilities in \eqref{I} being easily computable. In the context of sequential testing, this corresponds to a two-sided simple hypothesis in a fully parametric situation.  As an example, consider Type A depths with indicator kernels such as the simplicial depth, see Appendix~\ref{subsec_multivariate_depths_A}, where $H(\bm{\xi})\sim \textrm{Bernoulli}(h)$ with unknown success probability $h$.  In Section~\ref{sec_gandy_approach} we describe how to obtain boundary sequences in this Bernoulli case that fulfil \eqref{I} -- \eqref{III}.
	\item \label{Case2} Similarly to Case~\ref{Case1}, the  distribution of $H(\bm{\xi})$ is theoretically known, but an exact analytical evaluation is difficult or impossible. Examples are given by the integrated depths, see \eqref{DI}, where the expectation is with respect to a distribution that is not related to the one with respect to which the depth is computed. Without access to this distribution it is practically impossible to construct exact boundary sequences fulfilling \eqref{I}, see Remark~\ref{rem_generalization}. However, the asymptotic approach as outlined in Section~\ref{sec_sequential_construction} is applicable.
	\item \label{Case3} The distribution of $H(\bm{\xi})$ is known, but depends not only on the unknown parameter $h$ but also on other unknown quantities. As an example, consider binary maximum depth classification in combination with a Type A depth with indicator kernel as in \eqref{eq_classification_difference}. The distribution of the corresponding $H(\bm{\xi})$ is a three-point distribution on $\{-1,0,1\}$ depending on the two unknown empirical depths $d_{\bx_1,\ldots,\bx_{r_{\bx}}}$ and $ d_{\by_1,\ldots,\by_{r_{\by}}}$ with respect to each of the two samples and not only on $h=d_{\bx_1,\ldots,\bx_{r_{\bx}}}-d_{\by_1,\ldots,\by_{r_{\by}}}$. In sequential testing, this corresponds to a test situation with a composite rather than a simple hypothesis $d_{\bx_1,\ldots,\bx_{r_{\bx}}}=d_{\by_1,\ldots,\by_{r_{\by}}}$. As for Case~\ref{Case2} this makes constructing exact boundary sequences challenging, see Remark~\ref{rem_generalization}. However, the asymptotic approach of Section~\ref{sec_sequential_construction} is applicable.
	\item\label{Case4} The distribution of $H(\bm{\xi})$ is not known, and there is no reasonable choice of a parametric statistical model for it, e.g.\ because the distribution depends on the entire unknown distribution of the observations and not only on the unknown parameter $h$. An example is  the modified band depth, see Appendix~\ref{subsec_functional_depth_A}. This corresponds to a non-parametric testing situation with no knowledge of the underlying distributional family. Without access to the probabilities in \eqref{I}, it is impossible to obtain exact boundary sequences based on $S_N$.  However, as is often the case in non-parametric statistics, the asymptotic approach described in Section \ref{sec_sequential_construction} is applicable. 
\end{enumerate}

\subsection{Boundary sequences for Type A depth functions with  indicator kernel}\label{sec_gandy_approach}
In this section, we first discuss the construction of boundary sequences if $H(\bm{\xi})\sim \mbox{Bernoulli}(h)$, with $0<h<1$, followed by the statistical properties of the corresponding seMCD-algorithm. Several sequential tests have been developed in this context dating from the 1970s \citep{Robbins1970,Lai1976} to today \cite{Fischer2024B}. In this article we follow the approach suggested by \cite{Gandy2009}. The latter paper was the basis for the introduction of $p$-value buckets discussed in \cite{Gandy2020b}, which inspired this paper.

\subsubsection{Recursive computation of the boundary sequences}\label{rec_comp_seq}
The boundary sequences in this section are based on an error spending sequence $(\alpha_N)_{N \in \mathbb N}$, where the construction guarantees that $\alpha_N$ is an upper bound for the probability of making a wrong decision within the first $N$ sampling steps. Thus, $(\alpha_N)_{N \in \mathbb N}$ has to be nondecreasing with values in $[0,\alpha]$ and $\alpha_N \to \alpha$ as $N \to \infty$, see e.g.\ \cite{LanDeMets1983} for details.  The spending sequence determines the shape of the boundary sequences. As an example, consider the class of spending sequences $\alpha_N = \alpha \cdot N/(\kappa+N)$, where the parameter $\kappa \in \mathbb N$ denotes the number of iterations, after which half of the error is spent, i.e.\ $\alpha_{\kappa} = \alpha/2$.  

For the Bernoulli case, clearly $S_N$ only takes integer values, and it holds $0\le S_{N+1}-S_N\le 1$ for all $N$. Similarly, our boundary sequences will be constructed to take only integer values and such that $0\le L_{N+1}-L_N\le 1$ as well as $0\le U_{N+1}-U_N\le 1$ for all $N$, where we suppress the upper index $(h)$ of the boundary sequences for notational ease in the description of the algorithm. Thus, at the time of stopping, the seMCD-process will be equal to one of the boundary sequences. Consequently, for the Bernoulli case the inequalities in the conditions for the calculation of $\mathfrak{l}_N, \mathfrak{r}_N$ in the seMCD-algorithm can be replaced by equalities.

We will now explain how to recursively compute boundary sequences for a given error spending sequence and split point $h$:
With an initialisation of $S_0=0, L_0=-1, U_0=1$, define 
\begin{align*}
	&\mathfrak p_{N}(k) := \P_h(S_{N}=k, L_j < S_j < U_j \text{ for all }j< N),
\end{align*}
i.e.\ the probability of $S_N=k$, $k\in \mathbb{N}$, and not having previously hit a boundary sequence.  For $N=0$, clearly,  $\mathfrak p_0(0)=1$ and the following recursions hold:
\begin{align*}
&\mathfrak p_{N+1}(U_N)=\mathfrak p_{N}(U_N-1)\cdot h,\qquad
\mathfrak p_{N+1}(L_N+1)=\mathfrak p_{N}(L_N+1)\cdot (1- h),
\\
&\mathfrak p_{N+1}(k)=\mathfrak p_{N}(k)\cdot (1-h)+\mathfrak p_{N}(k-1)\cdot h \quad \text{for }L_N+1< k < U_N.
\end{align*}
In addition, define the probability of making a wrong decision within the first $N$ sampling steps by first hitting the \textbf{upper} boundary sequence, i.e.\
 \[ 
\beta_U{(N)} := \P_h(\text{For some } \ell \le N: S_\ell = U_\ell \text{ and }  L_j<S_j<U_j \text{ for all }j< \ell),
\]
as well as the corresponding probability for first hitting the \textbf{lower} boundary sequence by 
\[ 
\beta_L{(N)} := \P_h(\text{For some } \ell \le N: S_\ell = L_\ell \text{ and } L_j< S_j< U_j \text{ for all }j< \ell).
\]
Clearly, the following recursions hold:
\begin{align}\label{eq_rec_betas}
    \beta_U{(N+1)} = \beta_U{(N)} + \mathfrak p_{N+1}(U_{N+1}), \qquad \beta_L{(N+1)} = \beta_L{(N)} + \mathfrak p_{N+1}(L_{N+1}).
\end{align}

The below algorithm constructs the boundary sequences in such a way that they fulfil 
\begin{align}\label{eq_guar_betas}
\beta_U{(\ell)} \leq \frac{\alpha_{\ell}}{2} \quad \text{and}\quad \beta_L{(\ell)} \leq \frac{\alpha_{\ell}}{2} 
\end{align}
for all $\ell\in\mathbb{N}$. The three quantities $\mathfrak p_{N+1}(k)$, $\beta_U(N)$ as well as $\beta_L(N)$ are only based on the boundary sequences for $j\le N$. If $\beta_U(N)$ and $\beta_L(N)$ fulfil \eqref{eq_guar_betas} for $\ell=N$ (induction hypothesis), then, based only on these three quantities, the algorithm chooses the boundary sequences at the next point $N+1$ in such a way, that   \eqref{eq_guar_betas} also holds for $\ell=N+1$ (induction step). Consequently, \eqref{eq_guar_betas} holds for all $\ell\in\mathbb{N}$ by induction, as clearly, for $N=0$,  $\beta_U{(0)}=0\le \alpha_0/2$ and $\beta_L{(0)}=0\le \alpha_0/2$.

Let us explain the construction of $U_{N+1}$ in detail: Because the error spending sequence is nondecreasing and as \eqref{eq_guar_betas} is guaranteed for $\ell=N$, by induction hypothesis, it holds $\alpha_{N+1}/2 \ge \beta_U{(N)}$. If $\mathfrak p_{N+1}(U_N) \le \alpha_{N+1}/2 - \beta_U{(N)}$,  then for $U_{N+1}:=U_N$  it indeed holds by \eqref{eq_rec_betas}
\begin{align*}
    \beta_U{(N+1)} = \beta_U{(N)} + \mathfrak p_{N+1}(U_{N})\le \alpha_{N+1}/2.
\end{align*}
Otherwise, choosing $U_{N+1}:=U_N+1$ yields $\beta_U{(N+1)}=\beta_U{(N)}$, such that the first assertion in \eqref{eq_guar_betas} holds by monotonicity  of the error spending sequence. 
%
The construction of $L_{N+1}$ is similar, see the below algorithm for details,  and analogously yield the second assertion in \eqref{eq_guar_betas}. 

We summarize the above findings in the following algorithm:

\vspace{2mm}
\begin{mdframed}
\textbf{\underline{Algorithm to compute the boundary sequences}}
\vspace{2mm}

\textbf{Initialise:} $L_0=-1$, $U_0=1$, $p_0(0)=1$, $\beta_U(0)=0=\beta_L(0)$.\\[2mm]
\textbf{Recursively, compute} the values for $N+1$ from those of $N$ as follows:
\begin{itemize}
\item Compute $\mathfrak p_{N+1}(U_N)=\mathfrak p_{N}(U_N-1)\cdot h$.
\begin{align*}
            &\textbf{If }\mathfrak p_{N+1}(U_N)\leq \frac{\alpha_{N+1}}2 - \beta_U(N): \qquad \text{Set } U_{N+1} = U_N.\\[1mm]             &\textbf{Otherwise:}\qquad \text{Set }U_{N+1} = U_N+1.
        \end{align*}
\item Compute $\mathfrak p_{N+1}(L_N+1)=\mathfrak p_{N}(L_N+1)\cdot (1-h)$.
\begin{align*}
            &\textbf{If }\mathfrak p_{N+1}(L_N+1)\leq \frac{\alpha_{N+1}}2 - \beta_L(N): \qquad \text{Set } L_{N+1} = L_N+1.\\[1mm]             &\textbf{Otherwise:}\qquad \text{Set }L_{N+1} = L_N.
        \end{align*}
\item Compute $\mathfrak p_{N+1}(k) = \mathfrak p_{N}(k) \cdot (1-h) + \mathfrak p_{N}(k-1) \cdot h$ for $L_N+1< k< U_N$.
\end{itemize}
\end{mdframed}



\begin{Remark}\label{rem_generalization}
When $H(\bm{\xi})$ does not follow a Bernoulli-distribution several obstacles arise for a generalisation of the above algorithm, even if the distribution class is known as in Case~\ref{Case1}: If $H(\bm{\xi})$ is no longer a.s.\ non-negative, $S_N$ no longer increases a.s., greatly complicating things. As soon as the underlying probability distribution is continuous, keeping track of meaningful alternatives of $\mathfrak p_N(\cdot)$ becomes difficult. If the probabilities $\mathfrak p_N(\cdot)$ cannot be calculated analytically as in Case \ref{Case2}, the difficulties are obvious. When there exist multiple parameters leading to the same $h=\E (H(\bm{\xi}))$, as in Case \ref{Case3}, $\mathfrak p_N(\cdot)$ will typically depend on those underlying parameters and needs to be tracked for all of these usually infinitely many parameters,  which can be challenging. Finally, in Case \ref{Case4} there is no possibility of calculating $\mathfrak p_N(\cdot)$ (nor a suitable alternative in the continuous case) rendering such an approach impossible.
\end{Remark}

\subsubsection{Statistical Guarantees}
By the construction detailed in the previous Section \ref{rec_comp_seq}, inductively, \eqref{eq_guar_betas} holds for all $\ell\in\mathbb{N}$, such that for the true value $h$, the probability of $\{S_j\}$ having hit one of the boundary sequences up to sample $N$ is given by $\beta_U{(N)}+ \beta_L{(N)} \leq \alpha_{N}$ for all $N \in \mathbb N$. Furthermore, reintroducing the dependence on  $h$ again, by monotonicity of the probabilities with respect to $h$, it holds for any $h_-\le h_+$ and all $N$, that 
\begin{align*}
    \beta_U^{(h_-)}(N)\le \beta_U^{(h_+)}(N)\quad \text{and}\quad \beta_L^{(h_-)}(N)\ge \beta_L^{(h_+)}(N).
\end{align*}
In summary, we have proven the following lemma using again the upper indices in the boundary sequences for clarity:

\begin{Lemma}\label{lem_bernoulli-guarantee}
In the above situation with boundary sequences  constructed with the above algorithm, \eqref{I} holds as well as
\[
    \P_h \left(U^{(h)}_{\ell} < S_{\ell}< L^{(h)}_{\ell}\text{ for all }\ell\in \{1,\ldots, N\}\right) \geq 1-\alpha_{N}\quad \text{for all }N \in \mathbb N. %\geq 1-\alpha.
\] 
Defining the stopping time $\tau^{(h)} = \inf\{N \in \mathbb N: S_N \geq U_N^{(h)} \text{ or } S_N \leq L_N^{(h)} \}$ it holds for any $h_-\le h\le h_+$
\begin{align}\label{eq_stopping_probability}
	&\P_{h_-}\left(\tau^{(h)} < \infty,S_{\tau^{(h)}}\geq U_{\tau^{(h)}}^{(h)}  \right)  \leq \frac{\alpha}{2} \quad\text{and}\quad \P_{h_+}\left(\tau^{(h)} < \infty,S_{\tau^{(h)}}\leq L_{\tau ^{(h)} }^{(h)}\right)\leq  \frac{\alpha}{2}.
\end{align}
\end{Lemma}

If \eqref{I} as well as the monotonicity condition \ref{ass_Monotonnicity_boundary_sequences} hold, then Lemma~\ref{lemma_new_FWER} delivers the desired statistical guarantee of making a wrong decision with a probability less than the chosen tolerance parameter $\alpha$. While Lemma~\ref{lem_bernoulli-guarantee} shows that \eqref{I} holds, the monotonicity condition \eqref{eq_Monotonnicity_boundary_sequences} is not necessarily fulfilled. Therefore, here, for completeness, we will repeat arguments of \citet[Theorem 3]{Gandy2020b},  making use of \eqref{eq_stopping_probability}. 

\begin{Corollary}
In the Bernoulli-case with boundary sequences constructed by the above algorithm, which fulfil
\begin{align}\label{MonStrong}        U_N^{(h_1)} \leq U_N^{(h_2)} \leq ... \leq U_N^{(h_{l})} \quad\text{as well as}\quad L_N^{(h_1)} \leq L_N^{(h_2)} \leq ... \leq L_N^{(h_{l})} \tag{\textbf{Mon}$\bm{(h_1, \ldots,h_k)}$}
\end{align}
for all split points $h_1, \ldots,h_k$, with the notation of Lemma~\ref{lemma_new_FWER}, it holds
\begin{align*}
    \P_h(h\in \sB)\ge 1-\alpha.
\end{align*}
\end{Corollary}

The monotonicity condition \eqref{MonStrong} is weaker than \ref{ass_Monotonnicity_boundary_sequences} and
can be easily checked when computing the boundary sequences using the recursive algorithm above. 
Indeed, \citet[Lemma 2]{Gandy2020b} entails that, if $\alpha \leq 1/4$, there exists a constant $n_0 \in \mathbb N$ such that \eqref{MonStrong} holds for all $N \geq n_0$. If the condition does not hold for lower values, the sequences can be adjusted so that the monotonicity is also guaranteed for $N < n_0$.

\begin{proof}
First, consider the case, where both $\mathfrak U = \min \{h_j: h_j \geq h\}$ and $\mathfrak L = \max \{h_j: h_j \leq h\}$ exist, then by \eqref{MonStrong} and \eqref{eq_stopping_probability} for all $0< h< 1$
\begin{align}\label{eq_FWER_1}
    & \P_{h}\left( \bigcup_{h_j\geq h} \left\{\tau^{(h_j)} < \infty,S_{\tau^{(h_j)}}\geq U_{\tau^{(h_j)}}^{(h_j)}\right\}  \right)= \P_{h}\left( \tau^{( \mathfrak U)} < \infty,S_{\tau^{(\mathfrak U)}}\geq U_{\tau^{(\mathfrak U)}}^{( \mathfrak U)}\right) \leq \frac{\alpha}{2},\\
    & \P_{h}\left( \bigcup_{h_j\leq h} \left\{\tau^{(h_j)} < \infty,S_{\tau^{(h_j)}}\leq L_{\tau^{(h_j)}}^{(h_j)}\right\}  \right)= \P_{h}\left( \tau^{( \mathfrak L)} < \infty,S_{\tau^{(\mathfrak L)}}\leq L_{\tau^{(\mathfrak L)}}^{( \mathfrak L)}\right) \leq \frac{\alpha}{2}.\label{eq_FWER_2}
    \end{align}
    This yields the assertion. In the case, where $\mathfrak U$ or $\mathfrak L$ do not exist, the unions on the left-hand side of \eqref{eq_FWER_1} and \eqref{eq_FWER_2} are empty, such that the corresponding probabilities are zero, and the assertion follows.
 \end{proof}

Finally, the algorithm will stop with probability one in finite time, if
the true value is inside one of the buckets.  In fact, \citet[Theorem 1]{Gandy2009} not only shows that the stopping time is finite in this case, but also  that it has finite expectation.

\subsection{General boundary sequences without parametric assumptions}\label{sec_sequential_construction}\label{subsec_sequential_asymptotic_boundaries}
The algorithm in the previous section only works for $H(\bm{\xi})$ Bernoulli distributed, which is the situation in very specific instances of Case \ref{Case1} such as simplicial depth, spherical depth or lens depth. As pointed out in Remark~\ref{rem_generalization}, obtaining similar algorithms may be difficult, or even impossible as in the non-parametric setting of Case \ref{Case4}. To solve this, we discuss  a different non-parametric 
construction method for the boundary sequences, where the statistical guarantees are  obtained in a suitable asymptotic sense. For that we make use of a non-parametric sequential testing approach recently introduced by~\cite{gnettner2025newflexibleclasssharp}. This approach has its origins in the sequential change point analysis of time series and was initially introduced by \cite{Chu1996} and  later extended by \cite{Horvath2004}. A detailed review on the progress in this field is provided by \cite{ClaudiaAlex2023}.

Recall, that the summands $H(\bm{\xi}_j)$ of the seMCD-process in \eqref{eq_SM} are iid with unknown mean $h=\E(\bm{\xi}_j)$, which is the quantity of interest. In this subsection, we will not make any assumptions on the distribution of $H(\bm{\xi}_1)$, but we do require second moments and non-degeneracy, i.e.\  $0<\sigma^2:=\V(H(\bm{\xi}_1))<\infty$ with typically unknown variance $\V(H(\bm{\xi}_1))$. The latter condition is typically fulfilled in a depth context. Thus, the methodology derived in this section is applicable in all situations discussed in Section~\ref{section_2_depth} as long as second moments exist. This comes at the cost of replacing the finite-sample guarantee with respect to the tolerance in Section~\ref{sec_gandy_approach} by asymptotic guarantees.

To explain the motivation behind the asymptotics,  we first replace the finite-sample guarantee in \eqref{I} by
\begin{align*}
    \lim_{m\to\infty}\P_{h}\left( L_{N,m}^{(h)}(\sigma^2)<S_N<U_{N,m}^{(h)}(\sigma^2) \text { for all }N\ge m\right)= 1-\alpha.
\end{align*}
The parameter $m$ plays a similar  role here as the sample size in classical statistics and can be considered as a burn-in period for the asymptotic approximations to work well. The boundary sequences depend on $m$ in a similar way as the normalization of the mean in a $t$-test depends on the sample size. The burn-in parameter $m$ has to be chosen in advance but will typically be much smaller than standard choices for Monte Carlo repetitions. In our simulation study, we choose $m=500$.

By a careful mathematical analysis it is possible to construct boundary sequences for $N<m$ without violating the above asymptotic guarantee. Thus,  it is possible to stop before $m$ samples have been taken, as long as the evidence is strong enough. Furthermore, in practice, we need to replace the usually unknown variance $\sigma^2$ with a suitable estimator $\tilde{\sigma}_N^2$ based only on the samples $H(\bm{\xi}_1),\ldots, H(\bm{\xi}_N)$ taken so far. In summary, we  construct boundary sequences, such that  the following asymptotic statement holds 
\begin{align}
    \lim_{m\to\infty}\P_{h}\left( L_{N,m}^{(h)}(\tilde{\sigma}_N^2)<S_N<U_{N,m}^{(h)} (\tilde{\sigma}_N^2)\text { for all }N\ge 1\right)= 1-\alpha. \tag{I$^*$}\label{Iasym}
\end{align}
This statement will replace \eqref{I} in the non-parametric situation.

Indeed, \citet[Theorem~3.1]{gnettner2025newflexibleclasssharp} yields after some elementary algebra:
\begin{Theorem}\label{theorem_boundary_nonparam}
Let $\{\bm{\xi}_j\}$ be iid with $h=\E (H(\bm{\xi}_1))$ and $0<\V(H(\bm{\xi}_1))<\infty$. Then,  \eqref{Iasym} holds  for the following class of boundary sequences: 
\begin{align}\label{eq_bound_np}
   & L_{N,m}^{(h)}(\tilde{\sigma}_N^2)=N\cdot h-\tilde{\sigma}_N\cdot w_{(\gamma_1,\gamma_2)}(N,m),\quad U_{N,m}^{(h)}(\tilde{\sigma}_N^2)=N\cdot h+\tilde{\sigma}_N\cdot w_{(\gamma_1,\gamma_2)}(N,m),\\
   & \text{where }w_{(\gamma_1,\gamma_2)}(N,m)=c_{\alpha}(\gamma_1,\gamma_2)\cdot m^{\gamma_2-\frac 1 2} \cdot N^{\gamma_1}\cdot (m+N)^{1-\gamma_1-\gamma_2}\notag
\end{align}
for $0\le \gamma_1,\gamma_2<1/2$, 
 \begin{align*}
     \tilde{\sigma}_N^2=\hat{\sigma}_N^2+\mathds 1_{\{\hat{\sigma}_N^2=0\}}\cdot \infty,\quad \hat{\sigma}^2_N=\frac{1}{N-1}\sum_{j=1}^N\left(H(\bm{\xi}_j)-\frac{1}{N}\sum_{i=1}^NH(\bm{\xi}_i)\right)^2,
 \end{align*}
 with the convention that $0\cdot\infty=0$,
 and $c_{\alpha}(\gamma_1,\gamma_2)$ is the $(1-\alpha)$-quantile of $\sup_{0\le t\le 1}\frac{|B(t)|}{t^{\gamma_1}\, (1-t)^{\gamma_2}}$ for a standard Brownian bridge $\{B(\cdot)\}$.
\end{Theorem}
\citet[Theorem~3.1]{gnettner2025newflexibleclasssharp} allow for more general shape functions $w(N,m)$. We have selected the above shape functions because the critical values $c_{\alpha}$ are obtained as the quantiles of a supremum over  a weighted Brownian bridge, i.e.\ the supremum is only taken over the unit interval. Other shape functions typically require the calculation of quantiles of a supremum over the full positive line of a weighted Gaussian process, which is numerically problematic. For $\gamma_1=\gamma_2=0$ the quantiles of the limit are theoretically known, otherwise they can be approximated e.g.\ by the methodology introduced in \cite{franke2022adaptive}.

\begin{Remark}\label{rem_offset}
    In order to avoid small-sample instabilities due to the estimation of the variance, it can be beneficial to take more than a minimal number $\mathfrak l_m$ of samples or equivalently set $\tilde{\sigma}_j=\infty$ for $j\le \mathfrak l_m$, where $\mathfrak l_m$ is chosen much smaller than $m$. Mathematically, if $\mathfrak l_m/m\to 0$, the assertion of Theorem~\ref{theorem_boundary_nonparam} remains true.
\end{Remark}

The choices $\gamma_1=\gamma_2=1/2$ are excluded from Theorem \ref{theorem_boundary_nonparam}. These choices lead to $w(N,m)$ being proportional to $\sqrt{N}$ as in standard a-posteriori testing.  However, by the law of iterated logarithm, \eqref{Iasym} does not hold for these choices. The parameter $\gamma_1$ regulates the boundary sequence at the beginning, while $\gamma_2$ regulates it at infinity. Generally, a smaller $\gamma_j$, $j=1,2$, leads to more conservative boundaries at the respective end. As a compromise between being close to the a-posteriori rate at infinity but not too liberal at the beginning, we choose $\gamma_1=0.1$ and $\gamma_2=0.4$ in the simulations. In fact, for the split point $h=0.25$ this choice of $\gamma_1,\gamma_2$ with $\alpha=0.05$, $m=500$ and variance $h(1-h)$ (the latter corresponds to the Bernoulli case) is very close to the exact boundary sequences from Section~\ref{sec_gandy_approach} with $\kappa=1000$. These asymptotic boundaries are slightly more conservative for small $N$ compared to the exact ones and slightly less conservative for large $N$.

The boundary sequences in \eqref{eq_bound_np} clearly fulfil Condition~\ref{ass_Monotonnicity_boundary_sequences}. Thus, combining Lemma~\ref{lemma_new_FWER} with Theorem~\ref{theorem_boundary_nonparam} yields:

\begin{Corollary}\label{cor_fbr}
Under the assumptions of Theorem~\ref{theorem_boundary_nonparam}, it holds 
\begin{align*}
    \liminf_{m\to\infty}\P_h(h\in \sB_m)\ge 1-\alpha,
\end{align*}
where $\sB_m$ is the output seMCD-bucket of the algorithm based on the boundary sequences \eqref{eq_bound_np}.
\end{Corollary}

Similarly, the proof of \citet[Theorem~3.2]{gnettner2025newflexibleclasssharp} shows that, with the notation of Lemma~\ref{lem_new_stop}, the seMCD-process will eventually be above the upper boundary sequence associated with  $\wideunderbar{h}$ as well as below the lower boundary sequence associated with $\widebar{h}$. Consequently, in combination with Lemma~\ref{lem_new_stop}, we obtain the following stopping guarantee of the algorithm for all values $h$ that are contained in interior of one of the seMCD-buckets.

\begin{Corollary}\label{cor_47}
Under the assumptions of Theorem~\ref{theorem_boundary_nonparam}, it holds for the stopping time $\tau_m(\gamma_1,\gamma_2)$ of the seMCD-algorithm with the boundary sequences from \eqref{eq_bound_np} for $\gamma_2>0$
\begin{align*}
P_h(\tau_m(\gamma_1,\gamma_2)<\infty)=1\text{ for each $m$ and }\gamma_2>0, \qquad \lim_{m\to\infty}P_h(\tau_m(\gamma_1,0)<\infty)=1,
\end{align*}
where the true value $h$ is contained in the interior of one of the seMCD-buckets.
\end{Corollary}

In view of this result, a choice of $\gamma_2>0$ is clearly preferable.

\section{Simulation and real data analyses}\label{sec_buckets_simulations}
In this section, we present the results of an  empirical study for illustrative purposes. The calculations in this section have all been conducted with MATLAB  (R2019b, or newer) with our own implementation of depth functions. The greedy seMCD-algorithm is as in Section~\ref{sec_another_look_algorithm}, with the boundary sequences as in Theorem~\ref{theorem_boundary_nonparam} with $\gamma_1=0.1$, $\gamma_2=0.4$ and $m=500$, $\mathfrak l_m=10$  is as in Remark~\ref{rem_offset}. All empirical results are based on $1000$ repetitions.

In Section \ref{fs} we focus on a comparison of the stopping and run time for various combinations of the tuning parameters for the seMCD-algorithm.  In Section \ref{ss}, we discuss maximum depth classification with seMCD-buckets, before Section~\ref{subsec_binary_classification} illustrates the seMCD-methodology in binary classification. The source code for this section is available in the ancillary files of this arXiv preprint.

\subsection{Empirical performance of the seMCD-algorithm for overlapping buckets}\label{fs}

In this section, we compare the performance of the seMCD-algorithm with different tolerance parameters:
\[\textbf{T1 } \alpha=1\ \%,\qquad \textbf{T2 } \alpha=2.5\ \%\]
and overlapping bucket configurations: 
\begin{align*}
    &\textbf{W1 } [0,0.05), (0.025,0.075),(0.05,0.1),(0.075, 0.125),\ldots, (0.6,0.65],\\
    &\textbf{W2 } [0,0.1),(0.05,0.15),(0.1,0.2),(0.15,0.25),\ldots,  (0.55,0.65].
\end{align*}
The buckets in \textbf{W1} have a  width of $0.05$, while the ones in \textbf{W2} have a width of $0.1$. We use the modified band depth (see Appendix~\ref{subsec_functional_depth_A}) as an instance of  functional depth and the IRW depth (see Appendix~\ref{subsec_IRW_depth}) as an instance of  multivariate depth. The selection is based on the fact that the exact depth value can be computed for the first and that the literature contains  a recommended number of plain-vanilla Monte Carlo samples for the second, as we comment below.

\subsubsection{Modified band depth based on 2 curves-bands}\label{subsec_sim_mod_band_depth}
The functional modified band depth 
allows for the calculation of the exact depth value. Thus, not only will we evaluate computational properties of the seMCD-algorithm, but also calculate the empirical false-bucket-rate (\textbf{FBR}), i.e.\ the percentage of cases in which the output seMCD-bucket does not contain the true value.

To elaborate, the aim is to compute the empirical depth with respect to 
an initial fixed sample of 100 iid standard Brownian motions on the time domain $[0,1]$, which have been simulated on an equidistant grid of length 0.001. We investigate the properties of the seMCD-algorithm where the target values are the empirical depths (with respect to the above fixed sample) in three different cases, with $t\in[0,1]$. (a) $x(t)=2$,  with true empirical depth value $0.0163$ for the initial sample, (b) $x(t)=\sin(2\pi t)$,  with  true empirical depth value $0.2864$ and (c) $x(t)=B_t$, a fixed Brownian motion simulated as above, with  true empirical depth value  $0.452$.
We then run the seMCD-algorithms $1000$ times and compare the number of samples taken until stopping as well as the false-bucket-rates (\textbf{FBR}).

Table~\ref{table_new_sim1} reports the average number of samples at the time of stopping as well as the false-bucket-rate, in the four cases resulting from the combination of the two studied tolerances and the two overlapping bucket configurations. The false-bucket-rate clearly stays very well below the tolerance in all cases. This is not surprising as Corollary~\ref{cor_fbr} in combination with Lemma~\ref{lemma_new_FWER} shows that the tolerance is conservative, in particular if the true value is not close to the split points. Indeed, while still conservative, the \textbf{FBR} is highest for (c) where the true value is closer to a split point than in the other cases. In each case where a decision was made for a false bucket, the false bucket was a direct neighbour of a correct bucket.

Furthermore, we illustrate the obtained results by providing  the boxplots of the stopping times in Figure~\ref{fig_boxplot_ModifiedBandDepth}.  Clearly, more samples are required to make a decision for narrower buckets, i.e.\ scenarios \textbf{W1} as well as a smaller tolerance \textbf{T1}, where the widths of the buckets has a stronger influence than the tolerance. For the different values in (a) to (c) the stopping time depends mainly on the signal-to-noise-ratio, where the signal is given by the distance to the bucket boundary (in case of overlapping ones the maximum of all buckets that contain the true value) and the noise is given by $\V (H(\bm{\xi}))$. In the above example, the empirical variance of all summands for exactly computing the empirical depth can be thought of as a surrogate and is given by 
$ 0.0040$ for (a), $0.0374$ for (b) and by $0.0665$ for (c).

