\section{Examples of E-depth functions}\label{appendix_depths}
\subsection{Multivariate Type A depths with indicator kernel}\label{subsec_multivariate_depths_A}
Let $\mathbb{S}:=\mathbb{R}^d$. For the simplicial depth \citep{LiuSimplicial}, in \eqref{DA} $r:=d+1$ and
\begin{align}\label{hs}
G^{S}(\bz,[\bm{\eta}_1,\ldots,\bm{\eta}_{d+1}])=\mathds 1_{\left\{\bz \in \mathrm{conv}\left\{\bm{\eta}_{1}, \ldots,\bm{\eta}_{d+1}\right\}\right\}},
\end{align}
where $\mathrm{conv}$ stands for the convex hull. The condition $\bz$ lies in $\mathrm{conv}\{\bm{\eta}_{1}, \ldots,\bm{\eta}_{{d+1}}\}$ is equivalent to checking whether a vector $\bm{\theta} \in \mathbb R^{d+1}$ with entries $\theta_j\geq 0$ for $j=1,\ldots, d+1$ and $ \sum_{j=1}^{d+1} \theta_j = 1$ exists such that $ \sum_{j=1}^{d+1} \theta_j \cdot \bm{\eta}_{j} = \bz$, which is implemented in standard software by checking if the following linear program has a feasible solution: 
\begin{align*}
	&\min_{\bm{\theta} \in \mathbb R^{d+1}} \quad  \langle \bm{1}, \bm \theta \rangle, \quad\text{with } \bm{1}=(1, \ldots,1)^T,\\
    &\text{s.t.} \quad  \sum_{j=1}^{d+1} \theta_j \cdot \bm{\eta}_{j} = \bz, \quad \sum_{j=1}^{d+1} \theta_j = 1,\quad \theta_j \geq 0 \text{ for each } j =1,\ldots,d+1.
\end{align*}
The  empirical simplicial depth given $\mathbb{R}^d$-valued random vectors $\bZ_1,\ldots,\bZ_n$, i.e.\ the standard estimator as in \eqref{typeAdepth}  of the theoretical simplicial depth, is given by
\begin{align}
    D_A(\bz;\bZ_1, \ldots,\bZ_n) = {n \choose d+1}^{-1} \sum_{1 \leq i_1<...<i_{d+1} \leq n} 
    \mathds 1_{\left\{\bz \in \mathrm{conv}\left\{\bZ_{i_1}, \ldots,\bZ_{i_{d+1}}\right\}\right\}}.
\end{align} 

Other well-known examples take in in \eqref{DA} $r:=2$, independently of $d$. They are: spherical depth \citep{elmore2006},  with 
\begin{align}\label{he}
    G^{E}(\bz;[\bm{\eta}_1,\bm{\eta}_2])= \mathds 1_{\left\{ (\bm{\eta}_1-\bz)^T \cdot (\bm{\eta}_2-\bz) \leq 0 \right\}},
\end{align}
lens depth \citep{LiuModarres2011}, with 
\begin{align}\label{hl}
    G^{L}(\bz;[\bm{\eta}_1,\bm{\eta}_2])= \mathds 1_{\left\{ \|\bm{\eta}_1 - \bm{\eta}_2\| \geq \max(\|\bz - \bm{\eta}_1\|,\|\bz - \bm{\eta}_2\|)\right\}}
\end{align}
and $\beta$-skeleton depth \citep{yang2018beta}, with 
\begin{align}\label{hb}
    G^{\beta}(\bz;[\bm{\eta}_1,\bm{\eta}_2])= \mathds 1_{\left\{ \|\bm{\eta}_1 - \bm{\eta}_2\| \geq \max\{\|\bm{\eta}_i+(\frac{2}{\beta}-1)\bm{\eta}_j-\frac{2}{\beta}\bz\|: \; i,j=1,2, i\neq j\}\right\}}.
\end{align}
Unlike  \eqref{hs}, conditions  \eqref{he}-\eqref{hb} are computationally easy to check.



\subsection{Functional Type A depths}\label{subsec_functional_depth_A}

Let $I \subseteq \mathbb R$ be a compact interval. Let $\mathbb{S}$ be an infinite dimensional Hilbert space on $\mathcal V$, with $\bz(t)\in \mathbb R$ for each $\bz\in\mathbb{S}$ and $t\in \mathcal V$. Let $\| \cdot\|_{L^2}$ be the $L^2$ norm and $r:=1$. For the h-depth \citep{Cuevas2007Projection}, we have
\begin{align}G^{\mbox{h}}(\bz;\bm{\eta}) =\frac{1}{\mbox{h}}\,K \left(\frac{\| \bz-\bm{\eta}\|_{L^2}}{\mbox{h}}\right),
\end{align}
with $K$ the Gaussian kernel. The bandwidth parameter $h$ can be a prefixed constant or data-driven  \citep{AliciaHeatherConstruction}.

Let $\mathbb{S}$ be the space of continuous functions on $\mathcal V$, with $\bz(t)\in \mathbb R$ for each $\bz\in\mathbb{S}$ and $t\in \mathcal V$. Let $r:=2$.
Making use of 2 curves-bands, for the band depth  \citep{LR2009}, we have
\begin{align}\label{band}
    G^{B}(\bz;[\bm{\eta}_1,\bm{\eta}_2]) =\mathds 1_{\left\{ \min( {\bm{\eta}}_1(t),{\bm{\eta}}_2(t)) \leq {\bz}(t)  \leq \max( {\bm{\eta}}_1(t),{\bm{\eta}}_2(t)) \mbox{ for all } t \in \mathcal V \right\}}
\end{align}
and for the modified band depth \citep{LR2009}
\begin{align}
    G^{M}(\bz;[\bm{\eta}_1,\bm{\eta}_2]) =\frac{ \lambda\left(  \left\{t \in \mathcal V: \min( {\bm{\eta}}_1(t),{\bm{\eta}}_2(t)) \leq {\bz}(t)  \leq \max( {\bm{\eta}}_1(t),{\bm{\eta}}_2(t)) \right\}\right)}{ \lambda(\mathcal V)},\label{eq_kern_mod_band}
\end{align}
where  $\lambda(\cdot)$ denotes the Lebesgue measure. The 2 curves-bands case is the most commonly used special case of a more general class based on $J$ curves-bands.  The seMCD-methodology discussed in this paper only  works for $J=2$. 

These depth functions can also be applied to multivariate data.

\subsection{Integrated depths}\label{subsec_IRW_depth}
Let $\mathbb{S}$ be a Banach space with a separable dual $\mathbb{S}^*$ and $\bm \eta$ a random element with probability measure on $\mathbb{S}^*$, for instance a non-degenerate Gaussian measure if $\mathbb{S}$ is infinite-dimensional or the uniform distribution on the unit sphere if it is finite-dimensional. Let $\bz\in \mathbb{S}$.  For the  integrated dual depth \citep{CuevasFraimanIntegrated2009} with respect to a distribution $P$, we have in \eqref{DI}
\begin{align}\label{dual}
    I^D(\bz; \bm{\eta}) = D_u( u(  \bm{\eta},\bz), u(\bm{\eta},\bZ)),
\end{align}
where $\bZ\sim P$, the quantity $D_u$ is a univariate depth function  and $u$ is a function related to it such that, conditioned on $\bm \eta$, it holds $u(  \bm{\eta},\bz)\in\mathbb{R}$ and $u(\bm{\eta},\bZ)$ is a random variable. 

In the particular case that $\mathbb{S}=R^d$, $\bm \eta$ is a random element with the uniform distribution on the unit sphere in $\mathbb R^d$  and $D_u$ is the univariate Tukey depth \citep{Tukey}, we have the integrated rank-weighted (IRW) depth \citep{Ramsay2019}. Thus, \eqref{dual} results in
\begin{align}\label{T}
        I^R(\bz; \bm{\eta}) = \min\left\{
        \P(  \bm{\eta}^T \cdot \bZ \leq  \bm{\eta}^T \cdot \bz | \bm{\eta}), \P(  \bm{\eta}^T \cdot \bZ \geq  \bm{\eta}^T \cdot \bz | \bm{\eta})  \right\}.
\end{align} 
Using $\bZ_1,\ldots,\bZ_n\overset{\textrm{iid}}{\sim} P$, we can write an empirical version of $\P( \bm{\eta}^T \cdot \bZ \leq  \bm{\eta}^T \cdot \bz|\bm{\eta})$ as
\begin{align*} 
   \frac{1}{n}\sum_{j=1}^n\mathds 1_{\{
   \bm{\eta}^T \cdot \bZ_j \leq  \bm{\eta}^T \cdot \bz \}}
\end{align*} 
and analogously for the other probability in \eqref{T}. Thus, approximating an empirical version of the IRW depth simply requires to also do a numerical approximation of the expectation.  Additionally, $\bm{\eta} \deq \bm W/\|\bm W\|$ holds with $\bm W$ being a standard normal distribution on $\mathbb R^d$ \citep{Marsaglia1972}. Then, because of the inequalities in \eqref{T}, it is equivalent to take $\bm{\eta}$ distributed as a  standard normal on $\mathbb R^d$. Thus, the empirical IRW depth can easily be approximated by Monte Carlo methods, fitting the seMCD-framework.
