\title{Drawdowns, Drawups, and Occupation Times under General Markov Models}

\author{Pingping Zeng\thanks{Department of Mathematics, Southern University of Science and Technology, Shenzhen, China. Email: zengpp@sustech.edu.cn.} \and Gongqiu Zhang\thanks{Corresponding author. School of Science and Engineering, The Chinese University of Hong Kong (Shenzhen), China. Email: zhanggongqiu@cuhk.edu.cn.} \and Weinan Zhang\thanks{Department of Data Science, City University of Hong Kong, Hong Kong SAR. Email: zhang.weinan@foxmail.com.}}

