\section{Drawdowns, Drawups, and Occupation Times}
\label{sec:drawdown_drawup_occupation}

In this section, we derive linear systems for five drawdown quantities
% the Laplace transforms of five quantities 
under the CTMC and then propose efficient algorithms for solving these linear systems.

\subsection{The Drawdown Time Preceding the Drawup Time}
\label{subsec:drawdown_preceding_drawup}

Write $\underline{Y}_{t} = \inf_{0 \le u \le t} Y_u$ and denote by $\widehat{\tau}_b=\mathrm{inf}\{t\geq 0: Y_t-\underline{Y}_t\geq b\}$ the first passage time of the drawup process of the CTMC $Y$ to the level $b>0$. $\widehat{\tau}_b$ is called the drawup time. We consider the drawdown time $\tau_a$ and the drawup time $\widehat{\tau}_b$, especially when the former precedes the latter, and define the following quantity:
\begin{align}
    \label{eq:drawdown_preceding_drawup}
    A(q, x, y) := \mathbb{E}_{x, y}\big[ e^{-q\tau_a} \mathbf{1}_{\{\tau_a < \widehat{\tau}_b\}} f(Y_{\tau_a})  \big].
\end{align}
Here, $q \in \mathbb{C}$ with $\Re(q) > 0$, $f:\mathbb{S} \to \mathbb{R}$, and $\mathbb{E}_{x, y}[\cdot] = \mathbb{E}[\cdot \,|\, Y_0 = x, \,\overline{Y}_0 = x, \,\underline{Y}_0 = y]$.

\begin{proposition}
    \label{prop:drawdown_preceding_drawup}
    Suppose $b \ge a$. For any $q \in \mathbb{C}$ with $\Re(q) > 0$,  $x \in \mathbb{S}$, and 
    $y \in \mathbb{S} \cap (x-a, x]$, the quantity $A(q, x, y)$ satisfies the following linear system: 
    % $y \in \mathbb{S} \cap (x-b, x]$,
\begin{equation}\label{eq:linear_system_drawdown_preceding_drawup}
\begin{aligned}
    A(q, x, y) 
    % &= P_{(x-a, x]}(q, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) 
    % + R_{(x-a, x]}(q, x, y; A(q, \cdot, \tilde{\cdot}) \mathbf{1}_{\{ \cdot - \tilde{\cdot} < b, %\cdot \in (x, y+b), \tilde{\cdot} \in (x-a,y] \}})\\
    =&~P_{(x-a, x]}(q, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) \\
    &~
    + \sum_{z \in\mathbb{S}\cap (x, y+b),\, w \in\mathbb{S}\cap ((x-a)\vee(z-b), y]}R_{(x-a, x]}(q, x, y;  \mathbf{1}_{\{\cdot =z, \,\tilde{\cdot}=w\}})A(q,z,w),
\end{aligned}
\end{equation}
where
\begin{align}
    R_{(\ell, r]}(q, x, y; g) := \mathbb{E} \big[ e^{-qT_r^+} \mathbf{1}_{\{ T_\ell^->T_r^+\}} g(Y_{T_r^+}, \underline{Y}_{T_r^+})\, \big| \, Y_0 = x,\, \underline{Y}_0 = y \big],
\end{align}
which satisfies the following linear system: for $x, y \in \mathbb{S}$ with $x \ge y$,
\begin{align}\label{eq:liner-system-min}
    \begin{cases}
        q R_{(\ell, r]}(q, x, y; g) - \sum\limits_{z \in \mathbb{S}} G(x, z) R_{(\ell, r]}(q, z, y \wedge z; g) = 0, \qquad & x \in (\ell, r], \\
        R_{(\ell, r]}(q, x, y; g) = g(x, y) \mathbf{1}_{\{x > r \}}, \qquad & x \notin (\ell, r].
    \end{cases}
\end{align}
Here, $\ell<r$, $T_r^+ := T_{(-\infty, r]}$, and $T_{\ell}^- := T_{(\ell, \infty)}$.
\end{proposition}
\begin{proof}
The proof of Proposition \ref{prop:drawdown_preceding_drawup} is given in Appendix \ref{proof:drawdown_preceding_drawup}.
\end{proof}


Next, we develop an efficient algorithm to solve the linear systems \eqref{eq:linear_system_drawdown_preceding_drawup} and \eqref{eq:liner-system-min} recursively; see Algorithm \ref{alg:quantity-1}. 
