\begin{algorithm}[htbp]
    \caption{Calculate $A(q,x,y)$}\label{alg:quantity-1}
    \begin{algorithmic}
         \State \textbf{Assumptions} $\eta_x:=\{i:y_i=x\}$ and $\eta_y:=\{i:y_i=y\}$. 
         \State \textbf{Notations} $i_a:=\min\{j:y_j>y_i-a\},~i_b:=\min\{j:y_j>y_i-b\}$, $\bm{G}:=\{G(y_m,y_{l})\}_{m,{l}=0}^{N}$, $\bm{I}_{m}$ denotes an ${m\times m}$ identity matrix, and $\text{Diag}(\bm{c})$ denotes the diagonal matrix with diagonal elements being $\bm{c}$.
        \State \textbf{Input} $\mathbb{S},~\bm{G},~f,~\eta_x,~\eta_y,$ and $q$.
        \State \textbf{Initialize} $A(q,y_N,\cdot)\gets 0$
        \For{$i=N-1$ to $\eta_{x}$}
        \State $\bm{G}_i\gets\{G(y_m,y_{l})\}_{m,{l}=i_a}^{i}$,~~~~$\bm{e}_{i}\gets\text{Diag}(\{\mathbf{1}_{\{y_m=y_i\}}\}_{m=i_a}^{i})$,
        \State $\bm{G}_i^-\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=0}^{i_a-1}$,~~~~$\bm{G}_i^+\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{l=i+1}^{N}$,
        \State $\bm{A}_i^+\gets\{\{A(q,y_m,y_{l})\}_{m=i+1}^{N}\}_{{l}=i_b}^{i_a}$,~~~~$\bm{f}_{i}\gets\{f(y_m)\}_{m=0}^{i_a-1}$,
        \State $\{g_{i,n}(\cdot,\tilde{\cdot})\}_{n=i_a}^{i-1}\gets\bigg\{\sum\limits_{y_i<y_m<y_n+b,\,y_{i_a}\vee y_{m_b}<y_l\leq y_n}\mathbf{1}_{\{\cdot=y_m,\,\tilde{\cdot}=y_l\}}A(q,y_m,y_l)\bigg\}_{n=i_a}^i$,
        \State $P_{(y_i-a,y_i]}(q,y_i;f)\gets -\bm{e}_i(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^-\bm{f}_i)$,
        % \State $\{R_{(y_i-a,y_i]}(q,y_i,y_n;g_{i,n})\}_{n=i_b}^{i_b}\gets -\bm{e}_i(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^+\bm{A}_i^+)$
        % \State $\{P_{(y_i-a,y_i]}(q,y_j;f) \}_{j=i_a}^{i}\gets -(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^-\bm{f}_i)$
        % \State $\{\{R_{(y_i-a,y_i]}(q,y_m,y_n;g_{i,n})\}_{m=i_a}^{i}\}_{n=i_b}^{i_a}\gets -(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^+\bm{A}_i^+)$
        \State $\{A(q,y_i,y_{l})\}_{{l}=i_b}^{i_a}\gets P_{(y_i-a,y_i]}(q,y_i;f) -\bm{e}_i(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^+\bm{A}_i^+)$,
        \For{$j=i_a+1$ to $i$}
        \State $\bm{G}_{i,j}\gets\{G(y_m,y_{l})\}_{m,{l}=j}^{i}$,~~~~$\bm{e}_{i,j}=\text{Diag}(\{\mathbf{1}_{\{y_m=y_i\}}\}_{m=j}^{i})$,
        \State $\bm{G}_{i,j}^-\gets\{\{G(y_m,y_{l})\}_{m=j}^{i}\}_{{l}=i_a}^{j-1}$,~~~~$\bm{G}_{i,j}^+\gets\{\{G(y_m,y_{l})\}_{m=j}^{i}\}_{{l}=i+1}^{N}$,
        \State $\bm{R}_{i,j}^-\gets\{R_{(y_i-a,y_i]}(q,y_m,y_m;g_{i,m})\}_{m=i_a}^{j-1}$,~~~~$\bm{A}_{i,j}^+\gets\{A(q,y_m,y_j)\}_{m=i+1}^{N}$,
        % \State $\{R_{(y_i-a,y_i]}(q,y_m,y_j;g_{i,j})\}_{m=j}^{i}\gets -(\bm{G}_{i,j}-q\bm{I}_{i-j+1})^{-1}(\bm{G}_{i,j}^-\widetilde{\bm{R}}_{i,j}^-+\bm{G}_{i,j}^+\bm{A}_{i,j}^+)$
        \State $A(q,y_i,y_j)\gets P_{(y_i-a,y_i]}(q,y_i;f)-\bm{e}_{i,j}(\bm{G}_{i,j}-q\bm{I}_{i-j+1})^{-1}(\bm{G}_{i,j}^-\bm{R}_{i,j}^-+\bm{G}_{i,j}^+\bm{A}_{i,j}^+)$.
        \EndFor
        \EndFor
        \State \Return $A(q,y_{\eta_x},y_{\eta_y})$
    \end{algorithmic}
\end{algorithm}

