\subsection{The Generalized Occupation Time of the CTMC until the Drawdown Time}
\label{subsec:occupation_below_level}


Next, we consider the generalized occupation time of the CTMC $Y$ until the drawdown time $\tau_a$ and introduce the following quantity:
\begin{align}
    \label{eq:occupation_below_level}
    B(k, x) = \mathbb{E}_x\big[ e^{-\int_0^{\tau_a} k(Y_s) \diff s}  \mathbf{1}_{\{\tau_a<\infty\}}f(Y_{\tau_a}) \big].
\end{align}
When $k(x) =q\mathbf{1}_{\{x < \xi\}}$ and $f(x)\equiv 1$, $B(k, x)$ is reduced to the Laplace transform of the occupation time of the CTMC $Y$ below the level $\xi$ until the drawdown time $\tau_a$.

\begin{proposition}
    \label{prop:occupation_below_level}
    For $x \in \mathbb{S}$ and any $k: \mathbb{S} \to \mathbb{C}$ such that $\Re(k(x)) \ge 0$ for all $x \in \mathbb{S}$, the quantity $B(k, x)$ satisfies the following linear system: 
\begin{equation}
    \label{eq:linear_system_occupation_below_level}
    \begin{aligned}
    B(k, x) 
    % &= P_{(x-a, x]}(k, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) + P_{(x-a, x]}(k, x; B(k, \cdot) \mathbf{1}_{\{ \cdot > x \}})\\
    &=P_{(x-a, x]}(k, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) +\sum_{y\in\mathbb{S},\,y>x}P_{(x-a, x]}(k, x;  \mathbf{1}_{\{ \cdot =y \}})B(k, y).
    \end{aligned}
\end{equation}
\end{proposition}
\begin{proof}
The proof of Proposition \ref{prop:occupation_below_level} is deferred to Appendix \ref{proof:occupation_below_level}.
\end{proof}



We construct an efficient algorithm to solve the linear system \eqref{eq:linear_system_occupation_below_level}, formally described and analyzed in Algorithm \ref{alg:quantity-2}. 
% We first introduce some notations. Let $\mathbb{S},~\bm{G},~\eta_x,~i_a$ are identical to those in Algorithm \ref{alg:quantity-1}. 
% For brevity, we abbreviate $P_{(y_i-a,y_i]}(k,x;f(\cdot)\mathbf{1}_{\{\cdot\leq y_i-a\}})$ and $P_{(y_i-a,y_i]}(k,x;B(k,\cdot)\mathbf{1}_{\{\cdot> y_i\}})$ as $P_i^-(x)$ and $P_i^+(x)$, respectively. Here and subsequently, we use $\text{diag}\{\bm{I}\}$ to represent the diagonal matrix with diagonal elements being vector $\bm{I}$. 
\begin{algorithm}[htbp]
    \caption{Calculate $B(k,x)$}\label{alg:quantity-2}
    \begin{algorithmic}
        \State \textbf{Assumption} $\eta_x:=\{i:y_i=x\}$.
        \State \textbf{Notations} $i_a:=\min\{j:y_j>y_i-a\}$, $\bm{G}:=\{G(y_m,y_{l})\}_{m,{l}=0}^{N}$, 
        % $P_i(x):=P_{(y_i-a,y_i]}(k,x;f(\cdot)\mathbf{1}_{\{\cdot\leq y_i-a\}})+\sum_{j=i+1}^{n}P_{(y_i-a,y_i]}(k,x;\mathbf{1}_{\{\cdot=y_j\}})B(k,y_j)$, 
        and $\text{Diag}(\bm{c})$ denotes the diagonal matrix with diagonal elements being $\bm{c}$.
        \State \textbf{Input} $\mathbb{S},~\bm{G},~f,~k,$ and $\eta_x$.
        \State \textbf{Initialize} $B(k,y_N)\gets 0$
        \For{$i=N-1$ to $\eta_{x}$}
        \State $\bm{G}_i\gets\{G(y_m,y_{l})\}_{m,{l}=i_a}^{i}$,~~~~$\bm{k}_i\gets\text{Diag}(\{k(y_m)\}_{m=i_a}^i)$,~~~~$\bm{e}_{i}=\text{Diag}(\{\mathbf{1}_{\{y_m=y_i\}}\}_{m=i_a}^{i})$,
        \State $\bm{G}_i^-\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=0}^{i_a-1}$,~~~~$\bm{G}_i^+\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=i+1}^{N}$,
        \State $\bm{f}_{i}\gets\{f(y_m)\}_{m=0}^{i_a-1}$,~~~~$\bm{B}_i^+\gets\{B(k,y_m)\}_{m=i+1}^N$,
        % \State $\{P_{i}(y_j)\}_{j=i_a}^{i}\gets -(\bm{G}_i-\bm{k}_i)^{-1}(\bm{G}_i^-\bm{f}_i+\bm{G}_i^+\bm{B}_i^+)$,
        \State $B(k,y_i)\gets -\bm{e}_i(\bm{G}_i-\bm{k}_i)^{-1}(\bm{G}_i^-\bm{f}_i+\bm{G}_i^+\bm{B}_i^+)$.
        \EndFor
        \State \Return $B(k,y_{\eta_x})$
    \end{algorithmic}
\end{algorithm}

\begin{remark}\label{rmk:complexity-quantity-2}
      The complexity analysis of Algorithm \ref{alg:quantity-2} is analogous to that of Algorithm \ref{alg:quantity-1}. The only difference is that the former does not involve the running minimum $\underline{Y}$ and one dimension is reduced. Therefore, the complexity of Algorithm \ref{alg:quantity-2} is reduced to $\mathcal{O}(N^3)$ for general Markov processes and $\mathcal{O}(N)$ for diffusion processes.
\end{remark}

