% \end{remark}



\subsection{The Generalized Occupation Time of the Drawdown Process until the Drawdown Time}
\label{subsec:occupation_drawdown_above_level}

In this subsection, we consider the generalized occupation time of the drawdown process until the drawdown time, which is reflected in the following quantity:
\begin{align}
    \label{eq:generalized_occupation_drawdown}
    C(k, x) = \mathbb{E}_x\big[ e^{-\int_0^{\tau_a} k(Y_s, \overline{Y}_s) \diff s} \mathbf{1}_{\{\tau_a<\infty\}} f(Y_{\tau_a}) \big].
\end{align}
% Here, $\mathbb{E}_x[\cdot]=\mathbb{E}_x[\cdot | Y_0=x, \overline{Y}_0=x]$.
When $k(x, y) = q \mathbf{1}_{\{y-x > \xi\}}$ and $f(x)\equiv 1$, $C(k,x)$ is reduced to the Laplace transform of the occupation time of the drawdown process above the level $\xi$ until the drawdown time $\tau_a$.

\begin{proposition}
    \label{prop:generalized_occupation_drawdown}
    For $x\in \mathbb{S}$ and any $k: \mathbb{S}^2 \to \mathbb{C}$ such that $\Re(k(x,y)) \ge 0$ for all $x, y\in\mathbb{S}$, the quantity $C(k, x)$ satisfies the following linear system:
\begin{equation}\label{eq:linear_system_generalized_occupation_drawdown}
    \begin{aligned}
    C(k, x) 
    % &= P_{(x-a, x]}(k(\cdot,x), x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) + S_{(x-a, x]}(k, x, x; C(k, \cdot) \mathbf{1}_{\{ \cdot > x \}})\\
    &=P_{(x-a, x]}(k(\cdot,x), x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) +\sum_{z\in\mathbb{S},\,z>x} S_{(x-a, x]}(k, x, x;  \mathbf{1}_{\{ \cdot = z \}})C(k, z),
    \end{aligned}
\end{equation}
where
\begin{align}
    S_{(\ell, r]}(k, x, y; g) := \mathbb{E} \big[ e^{-\int_0^{T_r^+} k(Y_s, \overline{Y}_s) \diff s} \mathbf{1}_{\{ T_\ell^->T_r^+ \}} g(Y_{T_r^+})\, \big|\,  Y_0 = x, \overline{Y}_0 = y \big],
\end{align}
which satisfies the following linear system: for $x, y \in \mathbb{S}$ with $x \le y$,
\begin{align}
    \label{eq:linear_system_generalized_occupation_drawdown_r}
    \begin{cases}
        k(x, y) S_{(\ell, r]}(k, x, y; g) - \sum_{z \in \mathbb{S}} G(x, z) S_{(\ell, r]}(k, z, y \vee z; g) = 0, &\qquad x \in (\ell, r], \\
        S_{(\ell, r]}(k, x, y; g) = g(x) \mathbf{1}_{\{x > r \}}, &\qquad x \notin (\ell, r].
    \end{cases}
\end{align}
\end{proposition}
\begin{proof}
The proof of Proposition \ref{prop:generalized_occupation_drawdown} is provided in Appendix \ref{proof:generalized_occupation_drawdown}.
\end{proof}

% The linear systems \eqref{eq:linear_system_generalized_occupation_drawdown} and \eqref{eq:linear_system_generalized_occupation_drawdown_r} can be solved recursively from $x = y_N$ to $x = y_0$.



Next, we develop an efficient algorithm to solve the linear systems \eqref{eq:linear_system_generalized_occupation_drawdown} and \eqref{eq:linear_system_generalized_occupation_drawdown_r} recursively;
see Algorithm \ref{alg:quantity-3}. 
% Let $\mathbb{S},~\bm{G},~\eta_x,~i_a$ are identical to those in Algorithm \ref{alg:quantity-1}. For simplicity, we abbreviate $P_{(y_i-a,y_i]}(k(\cdot,x),x;f(\cdot)\mathbf{1}_{\{\cdot\leq y_i-a\}})$ and $S_{(y_i-a,y_i]}(k,x,y;C(k,\cdot)\mathbf{1}_{\{\cdot> y_i\}})$ as $P_i(x)$ and $S_i(x,y)$. 
% Denote $\bm{k}_{i}=\text{diag}\{\{k(y_m,y_i)\}_{m=i_a}^{i}\}$, $\bm{P}_i=\{P_i(x_m)+S_i(y_m,y_i)\}_{m=i_a}^i$, $\bm{P}_{ii}=P_i(y_i)+S_i(y_i,y_i)$, $\bm{C}_i=C(k,y_i)$, $\bm{C}_i^+=\{C(k,y_m)\}_{m=i+1}^{N}$.

\begin{algorithm}[htbp]
    \caption{Calculate $C(k,x)$}\label{alg:quantity-3}
    \begin{algorithmic}
        \State \textbf{Assumption} $\eta_x:=\{i:y_i=x\}$.
        \State \textbf{Notations} $i_a:=\min\{j:y_j>y_i-a\}$, $\bm{G}:=\{G(y_m,y_{l})\}_{m,{l}=0}^{N}$, 
        % $P_i(x,y):=P_{(y_i-a,y_i]}(k(\cdot,x),x;f(\cdot)\mathbf{1}_{\{\cdot\leq y_i-a\}})+\sum_{j=i+1}^{n}S_{(y_i-a,y_i]}(k,x,y;\mathbf{1}_{\{\cdot=y_j\}})C(k,y_j)$, 
        and $\text{Diag}(\bm{c})$ denotes the diagonal matrix with diagonal elements being $\bm{c}$.
        \State \textbf{Input} $\mathbb{S},~\bm{G},~f,~k,$ and $\eta_x$.
        \State \textbf{Initialize} $C(k,y_N)\gets 0$
        \For{$i=N-1$ to $\eta_{x}$}
        \State $\bm{G}_i\gets\{G(y_m,y_{l})\}_{m,{l}=i_a}^{i}$,~~~~$\bm{k}_i\gets\text{Diag}(\{k(y_m,y_i)\}_{m=i_a}^i)$,~~~~$\bm{e}_i=\text{Diag}(\{\mathbf{1}_{\{y_m=y_i\}}\}_{m=i_a}^{i})$,
        \State $\bm{G}_i^-\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=0}^{i_a-1}$,~~~~$\bm{G}_i^+\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=i+1}^{N}$,
        \State $\bm{f}_{i}\gets\{f(y_m)\}_{m=0}^{i_a-1}$,~~~~$\bm{C}_i^+\gets\{C(k,y_m)\}_{m=i+1}^N$,
        % \State $\{P_i(y_m,y_i)\}_{m=i_a}^i\gets -(\bm{G}_i-\bm{k}_i)^{-1}(\bm{G}_i^-\bm{f}_i+\bm{G}_i^+\bm{C}_i^+)$
        \State $C(k,y_i)\gets -\bm{e}_i(\bm{G}_i-\bm{k}_i)^{-1}(\bm{G}_i^-\bm{f}_i+\bm{G}_i^+\bm{C}_i^+)$.
        \EndFor
        \State \Return $C(k,y_{\eta_x})$
    \end{algorithmic}
\end{algorithm}

\begin{remark}\label{rmk:complexity-quantity-3}
    The complexity of Algorithm \ref{alg:quantity-3} for general Markov processes is $\mathcal{O}(N^3)$, which is the same as that of Algorithm \ref{alg:quantity-2}. However, the complexity can only be reduced to $\mathcal{O}(N^2)$ instead of $\mathcal{O}(N)$ for diffusion processes. This distinction arises because, unlike the formula \eqref{eq:linear-combination}, the coefficient $S_{(x-a,x]}(k,x,x;\mathbf{1}_{\{\cdot=x^+\}})$
    % $\{P_{(y_i-a,y_i]}(q,y_j;f) \}_{j=i_a}^{i}$, $\{\{R_{(y_i-a,y_i]}(q,y_m,y_n;g_{i,n})\}_{m=i_a}^{i}\}_{n=i_b}^{i_a}$, and $\{R_{(y_i-a,y_i]}(q,y_m,y_j;g_{i,j})\}_{m=j}^{i}$ 
    cannot be represented in terms of the functions $\psi^\pm(q, x)$ but needs to be calculated by solving a linear system involving both states $x$ and $y$ that incurs complexity $O(N^2)$. Once the coefficients $P_{(x-a, x]}(k(\cdot,x), x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}})$ and $S_{(x-a, x]}(k, x, x;  \mathbf{1}_{\{ \cdot = x^+ \}})$ in the linear system of $C(k, x)$ have been computed, we can solve $C(k, x)$ recursively. The overall complexity of  the resulting Algorithm \ref{alg:quantity-3} for diffusion processes is $\mathcal{O}(N^2)$.

    % The main reason is that the matrix $\bm{G}_i-\bm{k}_i$ is no longer the submatrix of some larger tridiagonal matrix, such as $\bm{G}-\text{diag}\{\{k(y_m,y_N)\}_{m=0}^{N}\}$, resulting in the linear combination of solutions of larger linear systems does not hold in the small linear system. 
    % Although we cannot achieve $O(N)$ complexity by linear combination formula, solving this tridiagonal linear system still requires only $O(N)$ complexity. Since we need to solve a series  of tridiagonal linear system during the recursion procedure, hence the overall complexity is $O(N^2)$.
\end{remark}

% \begin{remark}
%    {\color{red}We can also allow $f$ to be dependent on $\overline{Y}_{\tau_a}$.}
% \end{remark}

\begin{remark}\label{complexity_Levy}
     When $k(x, y) = q \mathbf{1}_{\{y-x > \xi\}}$, $f(x)\equiv 1$, and the Markov process $X$ is a L\'evy process, we have $C(k,x)\equiv C(k,0)$, which leads to the following simple solution to the linear system \eqref{eq:linear_system_generalized_occupation_drawdown}:
    \begin{equation}\label{eq:quantity-3-Levy}
        C(k,x)=\frac{P_{(-a, 0]}(k(\cdot,0), 0; \mathbf{1}_{\{\cdot \le  -a\}})}{1-S_{(-a, 0]}(k, 0, 0; \mathbf{1}_{\{ \cdot > 0 \}})}.
    \end{equation}
    In this case, one avoids solving the linear systems \eqref{eq:linear_system_generalized_occupation_drawdown} recursively and hence the computational time can be reduced significantly. Denote by $n_a$ the number of grid points within the interval $(-a,0]$. Since the calculations of the quantities $P_{(-a, 0]}(k(\cdot,0), 0; \mathbf{1}_{\{\cdot \le  -a\}})$ and $S_{(-a, 0]}(k, 0, 0; \mathbf{1}_{\{ \cdot > 0 \}})$ both require $\mathcal{O}(n_a^3)$ operations, the complexity in the computation of $C(k,x)$ is $\mathcal{O}(n_a^3)$.
\end{remark}

