\subsection{The $n$-th Drawdown Time without Recovery}
\label{subsec:nth_drawdown_without_recovery}

Write $\overline{Y}_{s, t} = \sup_{s \le u \le t} Y_u$. The $n$-th drawdown time without recovery $\tilde{\tau}_{a,n}$ is defined as $\tilde{\tau}_{a,n} = \inf \{ t > \tilde{\tau}_{a,n-1}: \overline{Y}_{\tilde{\tau}_{a,n-1}, t} - Y_t \ge a \}$ for $n \ge 1$ with $\tilde{\tau}_{a,0} = 0$. Consider the quantity as follows:
\begin{align}
    \label{eq:nth_drawdown_without_recovery}
    H_n(q, x) = \mathbb{E}_x\big[ e^{-q\tilde{\tau}_{a,n}} f(Y_{\tilde{\tau}_{a,n}}) \big].
\end{align}

\begin{proposition}
    \label{prop:nth_drawdown_without_recovery}
    For $n \ge 1$, any $q \in \mathbb{C}$ with $\Re(q) > 0$, and $x\in \mathbb{S}$, the quantity $H_n(q, x)$ satisfies the following linear system:
\begin{equation}\label{eq:linear_system_nth_drawdown_without_recovery}
    H_n(q, x) =P_{(x-a, x]}(q, x; H_{n-1}(q,\cdot)\mathbf{1}_{\{\cdot \le x -a\}}) +\sum_{y\in\mathbb{S},\, y>x} P_{(x-a, x]}\big(q, x; \mathbf{1}_{\{\cdot = y \}} \big)H_n(q, y)
\end{equation}
with $H_0(q, x) = f(x)$.
\end{proposition}
\begin{proof}
See Appendix \ref{proof:nth_drawdown_without_recovery}.
\end{proof}


% Once $H_{n-1}(q,x)$ is known for $n\geq 1$, we can evaluate $H_{n}(q,x)$ by following the key steps depicted in Section \ref{subsec:first_passage_time_drawdown}. Therefore, the linear system \eqref{eq:linear_system_nth_drawdown_without_recovery} can be solved recursively from $n = 1$ and our algorithm is summarized in Algorithm \ref{alg:quantity-4}. 
Next, we develop an efficient algorithm to solve the linear system \eqref{eq:linear_system_nth_drawdown_without_recovery} recursively from $n = 1$, formally described and analyzed in Algorithm \ref{alg:quantity-4}. 
% Let $\mathbb{S},~\bm{G},~\bm{I}_n,~\eta_x,~i_a$ are identical to those in Algorithm \ref{alg:quantity-1}. For simplicity, we abbreviate $P_{(y_i-a,y_i]}(q,x;H_{n-1}(q,\cdot)\mathbf{1}_{\{\cdot\leq y_i-a\}})$ and $P_{(y_i-a,y_i]}(q,x;H_n(q,\cdot)\mathbf{1}_{\{\cdot> y_i\}})$ as $P_{n,i}^-(x)$ and $P_{n,i}^+(x)$, respectively. 
% Denote $\bm{P}_{n,i}=\{P_{n,i}^-(y_m)+P_{n,i}^+(y_m)\}_{m=i_a}^i$, $\bm{P}_{n,ii}=P_{n,i}^-(y_i)+P_{n,i}^+(y_i)$, $\bm{H}_{n,i}=H_n(q,y_i)$, $\bm{H}_{n,i}^-=\{H_n(q,y_m)\}_{m=0}^{i_a-1}$, $\bm{H}_{n,i}^+=\{H_n(q,y_m)\}_{m=i_a+1}^{N}$.
\begin{algorithm}[htbp]
    \caption{Calculate $H_n(q,x)$}\label{alg:quantity-4}
    \begin{algorithmic}
        \State \textbf{Assumption} $\eta_x:=\{i:y_i=x\}$.
        \State \textbf{Notations} 
        % $n_a:=\min \{i: y_i>y_0+a\}$, 
        $i_a:=\min\{j:y_j>y_i-a\}$, 
        $\bm{G}:=\{G(y_m,y_{l})\}_{m,{l}=0}^{N}$, $\bm{I}_m$ denotes an $m\times m$ identity matrix, 
        % $P_{n,i}^-(x):=P_{(y_i-a,y_i]}(q,x;H_{n-1}(q,\cdot)\mathbf{1}_{\{\cdot\leq y_i-a\}})$, $P_{n,i}^+(x):=\sum_{j=i+1}^{n}P_{(y_i-a,y_i]}(q,x;\mathbf{1}_{\{\cdot=y_j\}})H_n(q,y_j)$.
        and $\text{Diag}(\bm{c})$ denotes the diagonal matrix with diagonal elements being $\bm{c}$.
        \State \textbf{Input} $\mathbb{S},~\bm{G},~f,~\eta_x,~n,$ and $q$.
        \State \textbf{Initialize} $H_0(q,\cdot)\gets f(\cdot)$
        \For{$k=1$ to $n$}
        \State $H_k(q,y_N)\gets 0$
        \For{$i=N-1$ to $0$}
        \State $\bm{G}_i\gets\{G(y_m,y_{l})\}_{m,{l}=i_a}^{i}$,~~~~$\bm{e}_i=\text{Diag}(\{\mathbf{1}_{\{y_m=y_i\}}\}_{m=i_a}^{i})$,
        \State $\bm{G}_i^-\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=0}^{i_a-1}$,~~~~ $\bm{G}_i^+\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=i+1}^{N}$,
        \State $\bm{H}_{k-1,i}^-=\{H_{k-1}(q,y_m)\}_{m=0}^{i_a-1}$,~~~~ $\bm{H}_{k,i}^+=\{H_k(q,y_m)\}_{m=i_a+1}^{N}$,
        % \State $\{P_{k,i}^-(y_m)+P_{n,i}^+(y_m)\}_{m=i_a}^i\gets -(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^-\bm{H}_{k-1,i}^-+\bm{G}_i^+\bm{H}_{k,i}^+)$
        \State $H_k(q,y_i)\gets -\bm{e}_i(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^-\bm{H}_{k-1,i}^-+\bm{G}_i^+\bm{H}_{k,i}^+)$.
        \EndFor
        \EndFor
        \State \Return $H_n(q,y_{\eta_x})$
    \end{algorithmic}
\end{algorithm}

\begin{remark}\label{rmk:complexity-quantity-4}
   As revealed from Algorithm \ref{alg:quantity-4}, the complexity analysis for calculating $H_n(q,x)$ is analogous to that of $Q_a(q,x;f)$ except that the former involves an additional recursion with respect to (w.r.t.) $k$. The computations in inverse matrices are still of order $\mathcal{O}(N^3)$ since the inverse matrix $(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}$ is independent of the recursion w.r.t. $k$, whereas the matrix multiplications cost $\mathcal{O}(nN^2)$ operations when $k$ increases from $1$ to $n$. Therefore, the overall complexity of Algorithm \ref{alg:quantity-4} for general Markov processes is $\mathcal{O}(\mathrm{max}(n,N)N^2)$. The complexity can be reduced to $\mathcal{O}(nN)$ for diffusion processes.
    % , while $X$ is a L\'evy process, the complexity is $O(N^3)+O(nN^2)$.
\end{remark}


    Consider an insurance policy that offers a protection against relative drawdowns. Assume the seller pays the buyer 1 at each relative drawdown time without recovery as long as it occurs before the maturity $T$; see \citet[Section 5]{landriault2015frequency-drawdown}. The price of the insurance policy can be defined as $\sum_{k=1}^{\infty}\mathbb{E}_x\big[e^{-r_f\tilde{\tau}_{a,k}}\mathbf{1}_{\{\tilde{\tau}_{a,k}<T\}}\big]$, whose Laplace transform w.r.t. $T$ is given by
    \begin{align}\label{LaplaceH}
    \int_{0}^{\infty}\sum_{k=1}^{\infty} e^{-qT}\mathbb{E}_x\big[e^{-r_f\tilde{\tau}_{a,k}}\mathbf{1}_{\{\tilde{\tau}_{a,k}<T\}}\big]\,\diff T=\frac{1}{q}\sum_{k=1}^{\infty}\mathbb{E}_x\big[ e^{-(q+r_f)\tilde{\tau}_{a,k}}\big]=\frac{H(q+r_f,x)}{q}.
    \end{align}
    Here, $r_f$ is the risk-free rate and $H(q,x):=\sum_{k=1}^{\infty}\mathbb{E}_x\big[ e^{-q\tilde{\tau}_{a,k}}\big]$.
    The pricing of the insurance product reduces to evaluating $H(q,x)$ as follows.

    % The price can be calculated by performing the Laplace inversion on the following quantity:
    % \[H(q,x):=\sum_{k=1}^{\infty}\mathbb{E}_x\big[ e^{-q\tilde{\tau}_{a,k}}\big].\]
    \begin{corollary}\label{cor:nth_drawdown_without_recovery}
         For any $q \in \mathbb{C}$ with $\Re(q) > 0$ and $x\in \mathbb{S}$, the quantity $H(q, x)$ satisfies the following linear system:
\begin{align}\label{eq:linear_system_drawdown_without_recovery_insurance}
        % H(q,x)=Q_a(q, x; 1+H(q, \cdot)).
        &H(q,x)\\
       &=~\sum_{y\in\mathbb{S}, \,y\leq x-a}P_{(x-a,x]}(q,x;\mathbf{1}_{\{\cdot=y\}})(1+H(q,y))
        +\sum_{y\in\mathbb{S}, \,y>x}P_{(x-a,x]}(q,x;\mathbf{1}_{\{\cdot=y\}})H(q,y).
    \end{align}
    % \[H(q,x)=\mathbb{E}_x\big[ e^{-q\tau_a}\big]+\sum_{z\in\mathbb{S}}\mathbb{E}_x\big[ e^{-q\tau_a}\mathbf{1}_{\{Y_{\tau_a}=z\}}\big]H(q,z).\]
    \end{corollary}

