\subsection{The $n$-th Drawdown Time with Recovery}
\label{subsec:nth_drawdown_with_recovery}

The $n$-th drawdown time with recovery $\tau_{a,n}$ is defined as $\tau_{a,n} = \inf \{ t > \tau_{a,n-1}: \overline{Y}_t - Y_t \ge a,\, \overline{Y}_t \geq \overline{Y}_{\tau_{a,n-1}} \}$ for $n \ge 1$ with $\tau_{a,0} = 0$. Consider the following quantity:
\begin{align}
    \label{eq:nth_drawdown_with_recovery}
    J_n(q, x, y) = \mathbb{E}\big[ e^{-q\tau_{a,n}} f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}}) \,\big|\, Y_0 = x, \overline{Y}_0 = y \big].
\end{align}

\begin{proposition}
    \label{prop:nth_drawdown_with_recovery}
    For $n \ge 1$, any $q \in \mathbb{C}$ with $\Re(q) > 0$, and $x, y \in \mathbb{S}$ with $x \le y$, $J_n(q, x, y)$ satisfies the following linear system: 
    \begin{equation}\label{eq:linear_system_nth_drawdown_with_recovery}
        \begin{aligned}
            J_n(q, x, y) &= \sum_{z\in\mathbb{S}, \,z\geq y}P_{(-\infty, y)}(q, x; \mathbf{1}_{\{\cdot =z \}})J_n(q, z, z),\\
            J_n(q, y, y) 
            % &= P_{(y-a, y]}(q, y; J_n(q, \cdot, \cdot; f) \mathbf{1}_{\{\cdot > y \}}) +  P_{(y-a, y]}(q, y; J_{n-1}(q, \cdot, y; f) \mathbf{1}_{\{\cdot \le y-a \}})\\
            &=  P_{(y-a, y]}(q, y; J_{n-1}(q, \cdot, y) \mathbf{1}_{\{\cdot \le y-a \}})+  \sum_{z\in\mathbb{S},\,z>y}P_{(y-a, y]}(q, y;  \mathbf{1}_{\{\cdot =z \}})J_n(q, z, z).
        \end{aligned}
    \end{equation}
    The initial condition is $J_0(q, x, y) = f(x, y)$.
\end{proposition}
\begin{proof}
The proof of Proposition \ref{prop:nth_drawdown_with_recovery} is given in Appendix \ref{proof:nth_drawdown_with_recovery}.
\end{proof}


