\begin{algorithm}[htbp]
    \caption{Calculate $J_n(q,x,y)$}\label{alg:quantity-5}
    \begin{algorithmic}
    \State \textbf{Assumptions} $\eta_x:=\{i:y_i=x\}$ and $\eta_y=\{i: y_i=y\}$.
        \State \textbf{Notations} 
        % $n_a:=\min\{i: y_i> y_0+a\}$, 
        $i_a:=\min\{j:y_j>y_i-a\}$, $\bm{G}:=\{G(y_m,y_{l})\}_{m,{l}=0}^{N}$, $\bm{I}_m$ denotes an $m\times m$ identity matrix,
