        % $\widetilde{P}_{n,i}^+(x):= \sum_{j=i}^{n} P_{(-\infty,y_i)}(q,x;\mathbf{1}_{\{\cdot=y_j\}}) J_n(q,y_j,y_j)$.
        and $\text{Diag}(\bm{c})$ denotes the diagonal matrix with diagonal elements being $\bm{c}$.
        \State \textbf{Input} $\mathbb{S},~\bm{G},~f,~\eta_x,~\eta_y,~n,$ and $q$.
        \State \textbf{Initialize} $J_0(q,\cdot,\tilde{\cdot})\gets f(\cdot,\tilde{\cdot})$
        \For{$k=1$ to $n$}
        \State $J_k(q,\cdot,y_N;f)\gets 0$
        \For{$i=N-1$ to $0$}
        \State $\bm{G}_i\gets\{G(y_m,y_{l})\}_{m,{l}=i_a}^{i}$,~~~~$\bm{e}_i=\text{Diag}(\{\mathbf{1}_{\{y_m=y_i\}}\}_{m=i_a}^{i})$,
        \State $\bm{G}_i^-\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=0}^{i_a-1}$,~~~~ $\bm{G}_i^+\gets\{\{G(y_m,y_{l})\}_{m=i_a}^{i}\}_{{l}=i+1}^{N}$,
        \State $\widetilde{\bm{G}}_i\gets\{G(y_m,y_{l})\}_{m,{l}=0}^{i-1}$,~~~~ $\widetilde{\bm{G}}_i^+\gets\{\{G(y_m,y_{l})\}_{m=0}^{i-1}\}_{{l}=i}^{N}$,
        \State $\bm{J}_{k-1,i}^-\gets\{J_{k-1}(q,y_m,y_i)\}_{m=0}^{i_a-1}$,~~~~ $\bm{J}_{k,i}^+\gets\{J_k(q,y_m,y_m)\}_{m=i+1}^{N}$,
        % \State $\{P_{k,i}^-(y_m)+P_{k,i}^+(y_m)\}_{m=i_a}^i\gets -(\bm{G}_i-q\bm{I}_{i-i_a+1})^{-1}(\bm{G}_i^-\bm{J}_{k-1,i}^-+\bm{G}^+\bm{J}_{k,i}^+)$
