            J(q,x,y)=&~\sum_{z\in\mathbb{S},\, z\geq y}P_{(-\infty,y)}(q,x;\mathbf{1}_{\{\cdot =z\}})J(q,z,z),\\
            J(q,y,y)=&~\sum_{z\in\mathbb{S},\, z\leq y-a}P_{(y-a,y]}(q,y;\mathbf{1}_{\{\cdot=z\}})(1+J(q,z,y))\\
            &~+\sum_{z\in\mathbb{S},\, z>y}P_{(y-a,y]}(q,y;\mathbf{1}_{\{\cdot=z\}})J(q,z,z).
        \end{aligned}
    \end{equation}
