\begin{remark}\label{rmk:complexity-quantity-5-insurance}
    Similar to Remark \ref{rmk:complexity-quantity-4-insurance}, the complexity of solving the linear system \eqref{eq:linear_system_drawdown_with_recovery_insurance} for general Markov processes is $\mathcal{O}(N^3)$.
   If the Markov process $X$ is a L\'evy process, we have $J(q,x,y)\equiv J(q,0,y-x)$,  which leads to the following simplified solution to the linear system \eqref{eq:linear_system_drawdown_with_recovery_insurance}:
    \begin{equation}\label{eq:linear_system_drawdown_with_recovery_insurance_Levy}
        \begin{aligned}
            J(q,x,y)&=P_{(-\infty,y-x)}(q,0;\mathbf{1}_{\{\cdot\geq y-x\}})J(q,0,0),\\
            J(q,0,0)&=\frac{P_{(-a,0]}(q,0;\mathbf{1}_{\{\cdot\leq -a\}})}{1-P_{(-a,0]}(q,0;\mathbf{1}_{\{\cdot>0\}})-P_{(-a,0]}(q,0;P_{(-\infty,0)}(q,\cdot;\mathbf{1}_{\{\tilde{\cdot}\geq 0\}})\mathbf{1}_{\{\cdot\leq -a\}})}.
        \end{aligned}
    \end{equation}
   Since a CTMC $Y$ with the state space $\mathbb{S} = h \mathbb{Z}$ is chosen to approximate the L\'evy process $X$, the quantity $P_{(-\infty,y-x)}(q,0;\mathbf{1}_{\{\cdot\geq y-x\}})$ satisfies an infinitely large linear system. %the truncation is needed to make this quantity solvable. So 
   To resolve this difficulty, we select a large $A>a>0$ to approximate $P_{(-\infty,y-x)}(q,0;\mathbf{1}_{\{\cdot\geq y-x\}})$ by $P_{(-A,y-x)}(q,0;\mathbf{1}_{\{\cdot\geq y-x\}})$.  Similarly, let $n_A$ denote the number of grid points within the interval $(-A,0]$, then the complexity in the computation of the quantity $P_{(-A,y-x)}(q,0;\mathbf{1}_{\{\cdot\geq y-x\}})$ is $\mathcal{O}(n_A^3)$,
   %The complexity of calculating $J(q,0,0)$ is of the same order. 
   which results in $\mathcal{O}(n_A^3)$ order for the overall complexity of solving the linear system \eqref{eq:linear_system_drawdown_with_recovery_insurance_Levy}.

If the Markov process $X$ is a diffusion process, the linear system \eqref{eq:linear_system_drawdown_with_recovery_insurance} can be simplified as follows:
    \begin{equation}\label{eq:quantity-5-diffusion-simplified}
        \begin{aligned}
            J(q,x,y)=&~P_{(-\infty,y)}(q,x;\mathbf{1}_{\{\cdot=y\}})J(q,y,y),\\
            J(q,y,y)=&~\frac{P_{(y-a,y]}(q,y;\mathbf{1}_{\{\cdot=y^+\}})J(q,y^+,y^+)+P_{(y-a,y]}(q,y;\mathbf{1}_{\{\cdot= (y-a)^\ominus\}})}{1-P_{(y-a,y]}(q,y;\mathbf{1}_{\{\cdot= (y-a)^\ominus\}})P_{(-\infty,y)}(q,(y-a)^\ominus;\mathbf{1}_{\{\cdot=y\}})}.
        \end{aligned}
    \end{equation}
   In this case, $P_{(-\infty,y)}(q,x;\mathbf{1}_{\{\cdot=y\}})$ can be approximated by $P_{[y_0,y)}(q,x;\mathbf{1}_{\{\cdot=y\}})$, where $y_0$ is a boundary point. Thus, by taking advantage of \eqref{eq:linear-combination}, the linear system \eqref{eq:quantity-5-diffusion-simplified} can be solved recursively with $\mathcal{O}(N)$ computational complexity. 
\end{remark}


\section{Convergence Analysis}
\label{sec:convergence_rate}
In this section, we establish the convergence of the CTMC approximation for five quantities analyzed in Section \ref{sec:drawdown_drawup_occupation}.
Let $\{Y_t^{(n)}\}_{n \in \mathbb{Z}^+}$ be a sequence of CTMCs to approximate $X_t$, where the superscript $(n)$ denotes the number of grid points and $\delta_n$ represents the corresponding mesh size. We assume $\delta_n\to 0$ as $n\to \infty$. Sufficient conditions for $Y^{(n)}\Rightarrow X$ in $D(\mathbb{R})$ are laid out in \cite{Mijatovic2013barrier}, where $\Rightarrow$ stands for the weak convergence of stochastic processes and $D(\mathbb{R})$ is the space of real-valued C$\grave{\text{a}}$dl$\grave{\text{a}}$g functions endowed with the Skorokhod topology. 

% \subsection{Convergence Analysis}
Denote by $\omega$ a path of the Markov process $X$ and introduce the following subsets of $D(\mathbb{R})$:
\begin{align*}
    U&:=\{\omega\in D(\mathbb{R}):\inf\{t\geq u:\overline{\omega}_{u,t}-\omega_t\geq a\}=\inf\{t\geq u:\overline{\omega}_{u,t}-\omega_t> a\} ~\text{for all}~u\geq 0\},\\
    V&:=\{\omega\in D(\mathbb{R}):\inf\{t\geq u:\overline{\omega}_{u,t}\geq  L\}=\inf\{t\geq u:\overline{\omega}_{u,t}>L\} ~\text{for all}~u\geq 0\},\\
    \widetilde{\mathcal{W}}&:=\{\omega\in D(\mathbb{R}): \text{for all}~t>s> 0,~\text{if}~\sup_{s\leq u\leq t}(\overline{\omega}_{s,u}-\omega_u)<a,~\text{there exists a}~\delta\in (0, s)~\text{such that} \\
    &\qquad \sup_{s-\delta\leq u\leq t}(\overline{\omega}_{s-\delta,u}-\omega_u)<a\},\\
    \mathcal {W}&:=\{\omega\in D(\mathbb{R}): \text{for all} ~t>u>s\geq 0,~\text{if}~s~\text{and}~u~\text{are consecutive drawdown times with }\\
    & \qquad \text{recovery and}~\overline{\omega}_{s,u}>\overline{\omega}_{u,t},~\text{there exists a}~\delta\in (0,u-s)~\text{such that}~u-\delta\in\mathbb{R}^+\setminus J(\omega)~\text{and}\\
    &\qquad \overline{\omega}_{s,u-\delta}>\overline{\omega}_{u-\delta,t}\}.
    % \widetilde{V}&:=\{\omega\in D(\mathbb{R}):\tilde{\tau}_{a,k}(\omega)\in \mathbb{R}^+\setminus J(\omega)~\text{for}~k=1,2,\dots.\},\\
    % V&:=\{\omega\in D(\mathbb{R}):\tau_{a,k}(\omega)\in \mathbb{R}^+\setminus J(\omega)~\text{for}~k=1,2,\dots.\}.
\end{align*}
Here, $a>0,~L\in\mathbb{R},~J(\omega):=\{t\geq 0: \omega_t\neq\omega_{t-}\},$ and $\overline{\omega}_{s,t}:=\sup_{s\leq u\leq t}\omega_u$.

We first impose the following assumptions on the paths of $X_t$.
\begin{assumption}[\cite{zhang2023drawdown}]\label{assump:path-x}
    (1) $X_t$ does not have monotone sample paths. (2) $X_t$ is quasi-left continuous, i.e., there exists a sequence of totally inaccessible stopping times that exhausts the jumps of $X_t$. (3) For all $x$, the L\'evy measure $\nu(x,\cdot)$ is either absolutely continuous or if it is discrete, $X_t$ must have a diffusion component, i.e., $\sigma(x)>0$ for all $x$ attainable in the state space. Furthermore, if the L\'evy measure $\nu(x, \cdot)$ has finite activity for any $x$, $X_t$ must have a diffusion component. 
    % (4) $X\in U\cap V\cap \widetilde{W}\cap W$ and $P(X\in U\cap V\cap \widetilde{W}\cap W)=1$.
\end{assumption}
Assumption \ref{assump:path-x} ensures that $\tau_a^{(n)}$ converges in distribution to $\tau_a$ as $n\to\infty$; see \citet[Section 4.1]{zhang2023drawdown} for more details. In the following analysis, the quantities bearing the superscript $(n)$ are defined under the CTMC $Y^{(n)}$. 

\begin{theorem}\label{thm:convergence}
    Suppose Assumption \ref{assump:path-x} holds and $Y^{(n)}\Rightarrow X$. 
    \begin{enumerate}[label={(\arabic*)}]
        \item $\Big(\tau_a^{(n)},\widehat{\tau}_b^{(n)},Y_{\tau_a^{(n)}}^{(n)}\Big)$ converges in distribution to $(\tau_a,\widehat{\tau}_b,X_{\tau_a})$ as $n\to \infty$.
        \item Suppose $k(\cdot)$ is a bounded and piecewise continuous univariate function, and there exists a subset $I\subseteq D(\mathbb{R})$ satisfying $P(X\in I)=1$ and for any $\omega\in I$, there exists a finite set $\textbf{T}_{dis}:=\{t_{i}\}_{i=1}^{m}$ such that $k(\omega_s)$ is continuous in $s\in(0,\tau_a)\setminus\textbf{T}_{dis}\subset\mathbb{R}^+\setminus J(\omega)$. Then $\Big(\tau_a^{(n)},\int_{0}^{\tau_a^{(n)}}k(Y_s^{(n)})\diff s,Y_{\tau_a^{(n)}}^{(n)}\Big)$ converges in distribution to $(\tau_a,\int_{0}^{\tau_a}k(X_s)\diff s,X_{\tau_a})$ as $n\to \infty$.
        \item Suppose $k(\cdot,\tilde{\cdot})$ is a bounded and piecewise continuous bivariate function,  and there exists a subset $I\subseteq D(\mathbb{R})$ satisfying $P(X\in I)=1$ and for any $\omega\in I$, there exists a finite set $\textbf{T}_{dis}:=\{t_{i}\}_{i=1}^{m}$ such that $k(\omega_s,\overline{\omega}_s)$ is continuous in $s\in(0,\tau_a)\setminus\textbf{T}_{dis}\subset\mathbb{R}^+\setminus J(\omega)$. Then $\Big(\tau_a^{(n)},\int_{0}^{\tau_a^{(n)}}k(Y_s^{(n)},\overline{Y}_s^{(n)})\diff s,Y_{\tau_a^{(n)}}^{(n)}\Big)$ converges in distribution to $(\tau_a,\int_{0}^{\tau_a}k(X_s,\overline{X}_s)\diff s,X_{\tau_a})$ as $n\to \infty$.
        \item  Suppose $\tilde{\tau}_{a,k}<\tilde{\tau}_{a,k+1}$ almost surely for $k=1,2,\dots$ and $P(X\in U\cap \widetilde{\mathcal W})=1$, then $\Big(\tilde{\tau}_{a,k}^{(n)},Y_{\tilde{\tau}_{a,k}^{(n)}}^{(n)}\Big)$ converges in distribution to $(\tilde{\tau}_{a,k},X_{\tilde{\tau}_{a,k}})$ as $n\to \infty$.
        \item Suppose $\tau_{a,k}<\tau_{a,k+1}$ almost surely for $k=1,2,\dots$ and $P(X\in U\cap V\cap {\mathcal W})=1$, then $\Big(\tau_{a,k}^{(n)},Y_{\tau_{a,k}^{(n)}}^{(n)}\Big)$ converges in distribution to $(\tau_{a,k},X_{\tau_{a,k}})$ as $n\to \infty$.
    \end{enumerate}
\end{theorem}
\begin{proof}
The proof of Theorem \ref{thm:convergence} is deferred to Appendix \ref{proof_convergence}.
\end{proof}

