\section{Construction of the CTMC Approximation}
\label{sec:ctmc_approximation}
 This section is devoted to constructing a CTMC $Y$ with the state space $\mathbb{S}$ to approximate a Markov process $X$ whose inﬁnitesimal generator $\mathcal L$ is depicted in \eqref{eq:infinitesimal_generatorX}. It suffices to specify the transition rate matrix $\bm{G}$ with elements $G(x, y)$ for $x, y \in \mathbb{S}$, such that the infinitesimal generator $\mathcal{G}$ of $Y$ is an approximation of $\mathcal{L}$ in the sense that:
\begin{align}
    \label{eq:infinitesimal_generator_approximation}
    \mathcal{G}g(x) \approx \mathcal{L}g(x)
\end{align}
for any function $g\in C^2_c (I): I \to \mathbb{R}$ and any $x \in \mathbb{S}$. 

To this end, the derivative terms and the integral term  in \eqref{eq:infinitesimal_generatorX} are approximated by the central difference method and a summation over the discrete state space $\mathbb{S}$, respectively. 
More specifically, the derivative terms are approximated as follows:
\begin{align}
    \label{eq:central_difference_approximation}
    g''(x) &\approx \Delta g(x) := \frac{\nabla^+ g(x) - \nabla^- g(x)}{\delta x},\\
    g'(x) &\approx \nabla g(x) := \frac{\delta^-x}{2\delta x} \nabla^+ g(x) + \frac{\delta^+x}{2\delta x} \nabla^- g(x),
\end{align}
where
\begin{align}
    &x^+ = \inf \{ y \in \mathbb{S}: y > x \}, ~ \delta^+ x = x^+ - x, \qquad &x \in \mathbb{S} \backslash \{y_N\},\\
    &x^- = \sup \{ y \in \mathbb{S}: y < x \}, ~ \delta^- x = x - x^-, \qquad &x \in \mathbb{S} \backslash \{y_0\},\\
    &\delta x=\frac{\delta^+ x +\delta^- x }{2}, \qquad &x \in \mathbb{S} \backslash \{y_0, y_N\},\\
    &\nabla^\pm g(x) = \pm \frac{g(x^\pm) - g(x)}{\delta^\pm x}, \qquad &x \in \mathbb{S} \backslash \{y_0, y_N\}.
\end{align}
On the other hand, the integral term is approximated as follows:
\begin{align}
    \label{eq:jump_approximation}
    &\int_\mathbb{R} \big(g(x+y) - g(x) - yg'(x) \mathbf{1}_{\{|y| \le 1 \}} \big) \nu(x, \diff y) \\
    &\approx~ \frac{1}{2} g''(x)  \int_{ - \delta^-x/2}^{\delta^+x/2} y^2 \nu(x, \diff y) - g'(x) \int_{\mathbb{R} \backslash [-\delta^-x/2, \delta^+x/2]} y\mathbf{1}_{\{|y| \le 1 \}}\nu(x, \diff y)  \\
    &~~~~ + \sum_{z \in \mathbb{S} \backslash \{x\}} \big(g(z) - g(x) \big) \int^{z + \delta^+ z/2 - x + \infty \mathbf{1}_{\{ z= y_N \}}}_{z - \delta^- z/2 - x - \infty \mathbf{1}_{\{ z= y_0 \}}} \nu(x, \diff y),
\end{align}
where the first term approximates the integral for small jumps and the resulting $g''(x)$ is then discretized by the central difference approximation as before. 

For brevity, we introduce
\begin{equation}\label{eq:ctmc-jump-diffusion-notation}
    \begin{aligned}
        &\overline{b}(x)= \int_{\mathbb{R} \backslash [-\delta^-x/2, \delta^+x/2]} y\mathbf{1}_{\{|y| \le 1 \}} \nu(x, \diff y),  \\
        &\overline{\sigma}^2(x) = \frac{1}{2} \int_{ - \delta^-x/2}^{\delta^+x/2} y^2 \nu(x, \diff y), \\
        &\overline{\nu}(x, z)= \int^{z + \delta^+ z/2 - x + \infty 1_{\{ z= y_N \}}}_{z - \delta^- z/2 - x - \infty 1_{\{ z= y_0 \}}} \nu(x, \diff y).
    \end{aligned}
\end{equation}
Thus, the infinitesimal generator $\mathcal{G}$ of $Y$ can be chosen as follows: for $x \in \mathbb{S} \backslash \{y_0, y_N\}$,
\begin{align}
    \mathcal{G} g(x)  = \frac{1}{2} \big( \sigma^2(x) +\overline{\sigma}^2(x) \big) \Delta g(x) + \big(b(x) - \overline{b}(x)\big) \nabla g(x) + \sum_{z \in \mathbb{S} \backslash \{x\}} \overline{\nu}(x, z) \big(g(z) - g(x) \big),
\end{align}
otherwise, $\mathcal{G} g(x) = 0.$
The generator $\mathcal{G}$ implies that the transition rate matrix $G$ satisfies the following conditions:
\begin{align}
& G(x, x^+) = (b(x) - \overline{b}(x)) \frac{\delta^- x}{2\delta^+ x\delta x} + \frac{1}{2} \big( \sigma^2(x) +\overline{\sigma}^2(x) \big) \frac{1}{\delta^+ x\delta x} + \overline{\nu}(x, x^+), ~~~~~~ x \in \mathbb{S} \backslash \{y_0, y_N\},\\
& G(x, x^-) = -(b(x) - \overline{b}(x)) \frac{\delta^+ x}{2\delta^- x \delta x} + \frac{1}{2} \big( \sigma^2(x) +\overline{\sigma}^2(x) \big) \frac{1}{\delta^- x\delta x} + \overline{\nu}(x, x^-), ~~~~ x \in \mathbb{S} \backslash \{y_0, y_N\},\\
& G(x, z) = \overline{\nu}(x, z),~~~~~~~~~~~~~~~~~~~ x \in \mathbb{S}\backslash\{y_0, y_N\},~z \in \mathbb{S} \backslash \{x, x^+, x^-\},\\
& G(x, x) = - \sum_{y \in \mathbb{S} \backslash \{x\}} G(x, y), \qquad x \in \mathbb{S},
\end{align}
and all other elements of $G$ are zeros.

\begin{remark}
    For L\'evy processes, it is desirable to construct a CTMC that preserves the property of independent and stationary increments. To this end, 
    %we choose a CTMC with the infinite state space $\mathbb{S} = h \mathbb{Z}$ for some $h > 0$ {\color{red}with $\mathbb{Z}$ being the set of integers.}
 a CTMC $Y$ with the state space $\mathbb{S} = h \mathbb{Z}$ is chosen to approximate the L\'evy process $X$ so that $Y$ itself is also a L\'evy process. Here, $h > 0$ and $\mathbb{Z}$ denotes the set of integers. 
   In this case, for any $x\in\mathbb{S}$, we have
    $x^\pm=x\pm h$ and $\delta^\pm x=\delta x=h.$
    Moreover, $b(x),~\sigma^2(x),$ and $\nu(x,\diff y)$ in \eqref{eq:infinitesimal_generatorX}
    % and $\overline{\sigma}^2(x),~\overline{b}(x),~\overline{\nu}(x, z)$ in \eqref{eq:ctmc-jump-diffusion-notation} 
    are independent of $x$, 
   which enables us to write $b=b(x),$ $\sigma^2=\sigma^2(x),$ and $\nu(\diff y)=\nu(x,\diff y)$.
Therefore, we introduce
$\overline{b}= \int_{\mathbb{R} \backslash [-h/2, h/2]} y\mathbf{1}_{\{|y| \le 1 \}} \nu(\diff y),$ $\overline{\sigma}^2= \frac{1}{2} \int_{ - h/2}^{h/2} y^2 \nu( \diff y),$  and $\overline{\nu}(z-x)= \int^{z -x + h/2}_{z - x - h/2} \nu( \diff y)$.
It follows that the transition rate matrix $G$ is characterized by
     \begin{align}
         & G(x, x+h) = \frac{b - \overline{b}}{2 h} + \frac{\sigma^2 +\overline{\sigma}^2}{2 h^2} + \overline{\nu}(h), \\
        & G(x, x-h) = -\frac{b - \overline{b}}{2 h} + \frac{\sigma^2 +\overline{\sigma}^2}{2 h^2} + \overline{\nu}(-h),\\
        & G(x, z) = \overline{\nu}(z-x),~~~~ z\in\mathbb{S}\backslash\{x,~x\pm h\},\\
        & G(x, x) = - \sum_{y \in \mathbb{S} \backslash \{x\}} G(x, y).
     \end{align}
\end{remark}

\begin{remark}
    For diffusion processes, we have  $\overline{b}(x) = 0$, $\overline{\sigma}^2(x) = 0$, and $\overline{\nu}(x, z) = 0$ for all $x, z \in \mathbb{S}$. The resulting CTMC is a birth-death process.
\end{remark}


