\subsection{Proof of Proposition \ref{prop:drawdown_preceding_drawup}}\label{proof:drawdown_preceding_drawup}
\begin{proof}
Similar to the proof of Theorem 3.1 in \cite{zhang2023drawdown}, by the introduction of $T_x^+$, $A(q, x, y)$ can be decomposed as follows:
\begin{align}
    A(q, x, y) = \mathbb{E}_{x, y}\big[ e^{-q\tau_a} \mathbf{1}_{\{\tau_a < \widehat{\tau}_b,\, \tau_a < T_x^+ \}} f(Y_{\tau_a})  \big] + \mathbb{E}_{x, y}\big[ e^{-q\tau_a} \mathbf{1}_{\{\tau_a < \widehat{\tau}_b, \,\tau_a > T_x^+ \}} f(Y_{\tau_a})  \big].
\end{align}
On the event $\{\tau_a < T_x^+\}$, we have $\tau_a = T_{x-a}^-$ and the drawup up to $\tau_a$ is less than $b$, leading to $\tau_a < \widehat{\tau}_b$. On the other hand, notice that $\{\tau_a > T_x^+\} = \{T_{x-a}^- > T_x^+\}$. Therefore, for $x \in \mathbb{S}$ and $y \in \mathbb{S} \cap (x-a, x]$, we have
\begin{align}
    &A(q, x, y) \\
    &=\mathbb{E}_{x, y}\big[ e^{-qT_{x-a}^-} \mathbf{1}_{\{T_{x-a}^- < T_x^+ \}} f(Y_{T_{x-a}^-})  \big]\\
    &~~~~+\mathbb{E}_{x, y}\big[ e^{-qT_x^+} \mathbf{1}_{\{T_{x-a}^- > T_x^+ \}}\mathbb{E}[e^{-q(\tau_a-T_x^+)}\mathbf{1}_{\{\tau_a<\widehat{\tau}_b\}}f(Y_{\tau_a})\,|\,Y_{T_x^+}, \overline{Y}_{T_x^+}=Y_{T_x^+}, \underline{Y}_{T_x^+}]\big]\\
    &=  P_{(x-a, x]}(q, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) +\mathbb{E}_{x, y}\big[ e^{-qT_x^+} \mathbf{1}_{\{ T_{x-a}^- > T_x^+ \}}A(q, Y_{T_x^+}, \underline{Y}_{T_x^+})  \big]\\
    &=  P_{(x-a, x]}(q, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) \\
    &~~~~ +\sum_{z \in \mathbb{S} \cap (x, y + b),\,{w \in\mathbb{S}\cap ((x-a)\vee(z-b), y]}} \mathbb{E}_{x, y}\big[ e^{-qT_x^+} \mathbf{1}_{\{ T_{x-a}^- > T_x^+, \,Y_{T_x^+} = z, \,\underline{Y}_{Y_x^+}=w \}}A(q, Y_{T_x^+}, \underline{Y}_{T_x^+})  \big]\\
    &=P_{(x-a, x]}(q, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}})\\
    &~~~~+\sum_{z \in \mathbb{S} \cap (x, y + b),\,{w \in\mathbb{S}\cap ((x-a)\vee(z-b), y]}} \mathbb{E}_{x, y}\big[ e^{-qT_x^+} \mathbf{1}_{\{ T_{x-a}^- > T_x^+, \,Y_{T_x^+} = z, \,\underline{Y}_{Y_x^+}=w \}}  \big]A(q, z, w),
    % &=P_{(x-a, x]}(q, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) \\
    % &\quad \quad \quad+ \sum_{z \in\mathbb{S}\cap (x, y+b),\,w>z-b}R_{(x-a, x]}(q, x, y;  \mathbf{1}_{\{\cdot =z, \,\tilde{\cdot}=w\}})A(q,z,w).
\end{align}
which in conjunction with the definition of the quantity $R_{(\ell, r]}(q, x, y; g)$ yields (\ref{eq:linear_system_drawdown_preceding_drawup}).

  It remains to derive the linear system for the quantity $R_{(\ell,r]}(q,x,y;g)$. For $x\leq\ell$, we have $\{T_r^+<T_\ell^-\}=\emptyset$, leading to $R_{(\ell, r]}(q,x,y;g)=0$, while for $x>r$, we have $T_r^+=0$, resulting in $R_{(\ell, r]}(q,x,y;g)=g(x,y)$. Consider $x\in(\ell,r]$, inspired by the proof of Proposition 3.1 in \cite{zhang2023drawdown}, we introduce $\mathbb{T}_t=\{kt: k=0,1,\dots\}$ and define
  $\mathbb T_{(\ell,r]}=\inf\{s\in\mathbb{T}_t: Y_s\notin (\ell,r]\},~
  \mathbb T_r^{+}=\mathbb T_{(-\infty,r]},$ and $\mathbb T_\ell^{-}=\mathbb T_{(\ell,\infty)}$. The Markov property of $Y$ yields
\begin{align*}
    &\mathbb{E} \big[ e^{-q\mathbb T_r^{+}} \mathbf{1}_{\{ \mathbb T_\ell^{-}>\mathbb T_r^{+} \}} g(Y_{\mathbb T_r^{+}}, \underline{Y}_{\mathbb T_r^{+}}) \,\big|\,  Y_0 = x, \underline{Y}_0 = y \big]\\
    &=e^{-qt}\sum_{z\in\mathbb{S}}\mathbb{E}\big[ e^{-q\mathbb T_r^{+}} \mathbf{1}_{\{ \mathbb T_\ell^{-}>\mathbb T_r^{+} \}} g(Y_{\mathbb T_r^{+}}, \underline{Y}_{\mathbb T_r^{+}}) \,\big| \, Y_0 = z, \underline{Y}_0 = y \wedge z \big]p(t,x,z)\\
    &=(1-qt)t\sum_{z\in\mathbb{S},\,z\neq x}\mathbb{E}\big[ e^{-q\mathbb T_r^{+}} \mathbf{1}_{\{ \mathbb T_\ell^{-}>\mathbb T_r^{+} \}} g(Y_{\mathbb T_r^{+}}, \underline{Y}_{\mathbb T_r^{+}}) \,\big|\,  Y_0 = z, \underline{Y}_0 = y \wedge z \big]G(x,z)\\
    &~~~~+(1-qt)\mathbb{E}\big[ e^{-q\mathbb T_r^{+}} \mathbf{1}_{\{ \mathbb T_\ell^{-}>\mathbb T_r^{+} \}} g(Y_{\mathbb T_r^{+}}, \underline{Y}_{\mathbb T_r^{+}})\, \big|\,  Y_0 = x, \underline{Y}_0 = y  \big](1+G(x,x)t)+o(t),
\end{align*}
where $p(t,x,z):=P(Y_t=z\,|\,Y_0=x)$. The second equality holds since $p(t,x,z)=\mathbf{1}_{\{x=z\}}+G(x,z)t+o(t)$ and $e^{-qt}=1-qt+o(t)$ when $t\to 0$. 
Dividing both sides by $t$ gives
\begin{align*}
    &\sum_{z\in\mathbb{S}}G(x,z)\mathbb{E}\big[ e^{-q\mathbb T_r^{+}} \mathbf{1}_{\{\mathbb T_r^{+} < \mathbb T_\ell^{-}\}} g(Y_{\mathbb T_r^{+}}, \underline{Y}_{\mathbb T_r^{+}})\, \big|\,  Y_0 = z, \underline{Y}_0 = y \wedge z \big]\\
    &-q\mathbb{E}\big[ e^{-q\mathbb T_r^{+}} \mathbf{1}_{\{\mathbb T_r^{+} < \mathbb T_\ell^{-}\}} g(Y_{\mathbb T_r^{+}}, \underline{Y}_{\mathbb T_r^{+}})\, \big|\,  Y_0 = x, \underline{Y}_0 = y\big]+o(1)=0.
\end{align*}
By similar arguments in the proof of Proposition 3.1 in \cite{zhang2023drawdown}, we finally arrive at \eqref{eq:liner-system-min}.
\end{proof}

\subsection{Proof of Proposition \ref{prop:occupation_below_level}}\label{proof:occupation_below_level}
\begin{proof}
   Recall that on the event $\{\tau_a < T_x^+\}$, we have $\tau_a = T_{x-a}^-$. Moreover, $\{\tau_a > T_x^+\} = \{T_{x-a}^- > T_x^+\}$. Thus,
\begin{align}
   B(k, x)= ~&\mathbb{E}_x\Big[ e^{-\int_0^{\tau_a} k(Y_s) \diff s} \mathbf{1}_{\{\tau_a < T_x^+ \}} f(Y_{\tau_a})  \Big] + \mathbb{E}_x\Big[ e^{-\int_0^{\tau_a} k(Y_s) \diff s} \mathbf{1}_{\{\tau_a > T_x^+ \}} f(Y_{\tau_a})  \Big] \\
   = ~&\mathbb{E}_x\Big[ e^{-\int_0^{T_{x-a}^-} k(Y_s) \diff s} \mathbf{1}_{\{T_{x-a}^- < T_x^+ \}} f(Y_{T_{x-a}^-})  \Big]\\
   ~&+\sum_{z \in \mathbb{S},\, z > x} \mathbb{E}_x\Big[ e^{-\int_0^{T_x^+} k(Y_s) \diff s} \mathbf{1}_{\{T_{x-a}^- > T_x^+, \,Y_{T_x^+}=z\}} B(k, Y_{T_x^+}) \Big]\\
   =~&P_{(x-a, x]}(k, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}})+\sum_{z \in \mathbb{S},\, z > x}\mathbb{E}_x\Big[ e^{-\int_0^{T_x^+} k(Y_s) \diff s} \mathbf{1}_{\{T_{x-a}^- > T_x^+,\, Y_{T_x^+}=z\}} \Big]B(k, z)\\
   =~&P_{(x-a, x]}(k, x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}})+\sum_{z \in \mathbb{S},\, z > x}P_{(x-a, x]}(k, x; \mathbf{1}_{\{\cdot =z\}})B(k,z).
\end{align}
\end{proof}

\subsection{Proof of Proposition \ref{prop:generalized_occupation_drawdown}}\label{proof:generalized_occupation_drawdown}
\begin{proof}
    Using similar arguments in the proof of Proposition \ref{prop:occupation_below_level}, we have
    \begin{align}
        C(k, x)=~& \mathbb{E}_x\Big[ e^{-\int_0^{\tau_a} k(Y_s, \overline{Y}_s) \diff s} \mathbf{1}_{\{\tau_a < T_x^+ \}} f(Y_{\tau_a})  \Big] 
         + \mathbb{E}_x\Big[ e^{-\int_0^{\tau_a} k(Y_s, \overline{Y}_s) \diff s} \mathbf{1}_{\{\tau_a > T_x^+ \}} f(Y_{\tau_a})  \Big] \\
        =~& \mathbb{E}_x\Big[ e^{-\int_0^{T_{x-a}^-} k(Y_s, \overline{Y}_s) \diff s} \mathbf{1}_{\{T_{x-a}^- < T_x^+ \}} f(Y_{T_{x-a}^-})  \Big]\\ 
        &+ \sum_{z \in \mathbb{S}, \,z > x} \mathbb{E}_x\Big[ e^{-\int_0^{T_x^+} k(Y_s, \overline{Y}_s) \diff s} \mathbf{1}_{\{T_{x-a}^- > T_x^+, \,Y_{T_x^+}=z \}}C(k, Y_{T_x^+})  \Big]\\
        =~&P_{(x-a, x]}(k(\cdot,x), x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}})\\
        &+\sum_{z \in \mathbb{S},\, z > x} \mathbb{E}_x\Big[ e^{-\int_0^{T_x^+} k(Y_s, \overline{Y}_s) \diff s} \mathbf{1}_{\{T_{x-a}^- > T_x^+,\, Y_{T_x^+}=z \}}  \Big]C(k, z)\\
        =~&P_{(x-a, x]}(k(\cdot,x), x; f(\cdot) \mathbf{1}_{\{\cdot \le x -a\}}) + \sum_{z \in \mathbb{S}, \,z > x}S_{(x-a, x]}(k, x, x;  \mathbf{1}_{\{ \cdot =z \}})C(k, z).
    \end{align}
    The linear system for the quantity $S_{(\ell, r]}(k,x,y;g)$ can be derived in a similar way as the quantity $R_{(\ell, r]}(q,x,y;g)$ (see the proof of Proposition \ref{prop:drawdown_preceding_drawup}) and hence is omitted here.
\end{proof}

\subsection{Proof of Proposition \ref{prop:nth_drawdown_without_recovery}}\label{proof:nth_drawdown_without_recovery}
\begin{proof}
   Applying the law of iterated expectations and Lemma \ref{passage_duration} yields
    \begin{align*}
        H_{n}(q,x)=&~\mathbb{E}_x\Big[ e^{-q\tilde{\tau}_{a,n}} f(Y_{\tilde{\tau}_{a,n}}) \Big]\\
        =&~\mathbb{E}_x\Big[ e^{-q\tilde{\tau}_{a,1}}\mathbb{E}\big[e^{-q(\tilde{\tau}_{a,n}-\tilde{\tau}_{a,1})}f(Y_{\tilde{\tau}_{a,n}})\,|\, Y_{\tilde{\tau}_{a,1}},\overline{Y}_{\tilde{\tau}_{a,1}, \tilde{\tau}_{a,1}}\big]  \Big]\\
        =&~\mathbb{E}_x\Big[ e^{-q\tilde{\tau}_{a,1}}H_{n-1}(q,Y_{\tilde{\tau}_{a,1}})  \Big]\\
        =&~Q_a(q,x;H_{n-1}(q,\cdot))\\
        =&~P_{(x-a, x]}(q, x; H_{n-1}(q,\cdot)\mathbf{1}_{\{\cdot \le x -a\}}) +\sum_{y\in\mathbb{S},\, y>x} P_{(x-a, x]}\big(q, x; \mathbf{1}_{\{\cdot = y \}} \big)H_n(q, y).
    \end{align*}
\end{proof}

\subsection{Proof of Proposition \ref{prop:nth_drawdown_with_recovery}}\label{proof:nth_drawdown_with_recovery}
\begin{proof}
    Since $\tau_{a,n}>T_{(-\infty,y)}$ and $\overline{Y}_{T_{(-\infty,y)}}=Y_{T_{(-\infty,y)}}\geq y$, applying the law of iterated expectations yields
    \begin{align*}
        J_n(q,x,y)
        % &=\mathbb{E}\big[ e^{-q\tau_{a,n}} f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}}) \,\big|\, Y_0 = x, \overline{Y}_0 = y \big]\\
        &=\mathbb{E}\Big[ e^{-q T_{(-\infty,y)}}\mathbb{E}\big[e^{-q(\tau_{a,n}-T_{(-\infty,y)})}f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}})\,\big|\,Y_{T_{(-\infty,y)}}, \overline{Y}_{T_{(-\infty,y)}}\big]  \,\Big|\, Y_0 = x, \overline{Y}_0 = y \Big]\\
        &=\mathbb{E}\Big[ e^{-q T_{(-\infty,y)}}J_n(q,Y_{T_{(-\infty,y)}},Y_{T_{(-\infty,y)}}) \,\big|\, Y_0 = x, \overline{Y}_0 = y \Big]\\
        &= \sum_{z\in\mathbb{S}, \,z\geq y}P_{(-\infty, y)}(q, x; \mathbf{1}_{\{\cdot =z \}})J_n(q, z, z).
    \end{align*}
    On the other hand, $J_n(q,y,y)$ can be decomposed as follows
    \begin{align*}
        J_n(q,y,y)=&~\mathbb{E}\big[ e^{-q\tau_{a,n}} f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}}) \,\big|\, Y_0 = y, \overline{Y}_0 = y \big]\\
        =&~\mathbb{E}\big[ e^{-q\tau_{a,n}} \mathbf{1}_{\{\tau_{a,1}<T_y^+\}}f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}}) \,\big|\, Y_0 = y, \overline{Y}_0 = y \big]\\
        &~+\mathbb{E}\big[ e^{-q\tau_{a,n}} \mathbf{1}_{\{\tau_{a,1}>T_y^+\}}f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}}) \,\big|\, Y_0 = y, \overline{Y}_0 = y \big]\\
        =&~\mathbb{E}\Big[ e^{-q \tau_{a,1}}\mathbf{1}_{\{\tau_{a,1}<T_y^+\}}\mathbb{E}\big[e^{-q(\tau_{a,n}-\tau_{a,1})}f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}})\,\big|\, Y_{\tau_{a,1}}, \overline{Y}_{\tau_{a,1}}\big]  \,\Big|\, Y_0 = y, \overline{Y}_0 = y \Big]\\
        &~+\mathbb{E}\Big[ e^{-q T_y^+}\mathbf{1}_{\{\tau_{a,1}>T_y^+\}}\mathbb{E}\big[e^{-q(\tau_{a,n}-T_y^+)}f(Y_{\tau_{a,n}}, \overline{Y}_{\tau_{a,n}})\,\big|\, Y_{T_y^+}, \overline{Y}_{T_y^+}\big]  \,\Big|\, Y_0 = y, \overline{Y}_0 = y \Big]\\
        =&~\mathbb{E}\Big[ e^{-q T_{y-a}^-}\mathbf{1}_{\{T_{y-a}^-<T_y^+\}}J_{n-1}(q,Y_{T_{y-a}^-},y)  \,\Big|\, Y_0 = y, \overline{Y}_0 = y \Big]\\
        &~+\sum_{z\in\mathbb{S},\, z>y}\mathbb{E}\Big[ e^{-q T_y^+}\mathbf{1}_{\{T_{y-a}^->T_y^+,Y_{T_y^+}=z\}}J_{n}(q,Y_{T_y^+},Y_{T_y^+})  \,\Big|\, Y_0 = y, \overline{Y}_0 = y \Big]\\
        =&~P_{(y-a, y]}(q, y; J_{n-1}(q, \cdot, y) \mathbf{1}_{\{\cdot \le y-a \}})+\sum_{z\in\mathbb{S},\, z>y}P_{(y-a, y]}(q, y; \mathbf{1}_{\{\cdot =z \}})J_n(q,z,z).
    \end{align*}
    Here, the sixth line is attributed to the fact that on the event $\{\tau_{a,1}<T_y^+\}$, we have $\tau_{a,1}=T_{y-a}^-$ and $\overline{Y}_{\tau_{a,1}}=\overline{Y}_0=y$, and the seventh line holds since the condition $Y_0=\overline{Y}_0=y$ implies that $Y_{T_y^+}=\overline{Y}_{T_y^+}>y$.
    % For the first term, on the event $\{\tau_{a,1}<T_y^+\}$, we have $\tau_{a,1}=T_{y-a}^-$, and $\overline{Y}_{\tau_{a,1}}=\overline{Y}_0=y$. Thus, the second term equals to
