    % \end{align*}
    % For the second term, the condition $Y_0=\overline{Y}_0=y$ indicates that $Y_{T_y^+}=\overline{Y}_{T_y^+}>y$. Besides, $\{\tau_{a,1} > T_y^+\} = \{T_{y-a}^- > T_y^+\}$, then it equals to
    % \begin{align*}
    %     &\sum_{z\in\mathbb{S}, z>y}\mathbb{E}\Big[ e^{-q T_y^+}\mathbf{1}_{\{T_{y-a}^->T_y^+,Y_{T_y^+}=z\}}J_{n}(q,Y_{T_y^+},Y_{T_y^+})  \,\Big|\, Y_0 = y, \overline{Y}_0 = y \Big]\\
    %     &=\sum_{z\in\mathbb{S}, z>y}\mathbb{E}\Big[ e^{-q T_y^+}\mathbf{1}_{\{T_{y-a}^->T_y^+,Y_{T_y^+}=z\}}  \,\Big|\, Y_0 = y, \overline{Y}_0 = y \Big]J_n(q,z,z)\\
