\subsection{Proof of Theorem \ref{thm:convergence}}\label{proof_convergence}
\begin{proof}
    For brevity, we write $s'=\tau_a(\omega)$, $s'^{(n)}=\tau_{a}(\omega^{(n)})$, $\overline{\omega}_{s,t}^{(n)}=\sup_{u\in[s,t]}\omega_u^{(n)}$, $MD_{s,t}=\sup_{u\in[s,t]} (\overline{\omega}_{s,u}-\omega_u)$, $MD_{s,t}^{(n)}=\sup_{u\in[s,t]} (\overline{\omega}_{s,u}^{(n)}-\omega_u^{(n)})$, $M_k=\sup_{u\in[\tau_{a,k-1}(\omega),\tau_{a,k}(\omega)]}\omega_{u}$, $M_{k}^{(n)}=\sup_{u\in[\tau_{a,k-1}(\omega^{(n)}), \tau_{a,k}(\omega^{(n)})]}\omega_u^{(n)}$, $T_{M_k}=\inf\{t>\tau_{a,k}(\omega):\omega_t\geq M_k\}$, and $T_{M_k}^{(n)}=\inf\{t>\tau_{a,k}(\omega^{(n)}):\omega_t^{(n)}\geq M_k^{(n)}\},$ where $0\leq s <t$ and $k=1,2,\dots$. Define $\tau_{a,0}(\omega)=\tau_{a,0}(\omega^{(n)})=0$. 
    In the subsequent analysis, we focus on establishing the continuity of the mappings w.r.t. the sample path $\omega$. Combined with the weak convergence $Y^{(n)}\Rightarrow X$, this continuity property ensures 
    % the distributional convergence of associated functionals: specifically,
    the quantities defined under the CTMC $Y^{(n)}$ converge in distribution to their counterparts defined under the Markov process $X$.
    \begin{enumerate}[label={(\arabic*)}]
        \item It suffices to show that $\omega\mapsto(\tau_a(\omega),\widehat{\tau}_b(\omega),\omega_{\tau_a(\omega)})$ is a continuous mapping almost surely. Since the continuity of the mapping $\omega\mapsto(\tau_a(\omega),\omega_{\tau_a(\omega)})$ has been verified by \cite{zhang2023drawdown}, it remains to prove the mapping $\omega\mapsto\widehat{\tau}_b(\omega)$ is continuous. Observe that the running minimum satisfies the identity $\inf_{0\leq s\leq t}X_s=-\sup_{0\leq s\leq t}(-X_s)$. Following the methodology of \citet[Theorem 4.1]{zhang2023drawdown}, we directly verify the continuity of the mapping  $\omega\mapsto\widehat{\tau}_b(\omega)$.


        \item As discussed above, it suffices to show the continuity of the mapping $\omega\mapsto\int_{0}^{\tau_a(\omega)}k(\omega_s)\diff s$. Suppose $\omega^{(n)}\to\omega$ under the Skorokhod topology. For any $\epsilon>0$, denote by $\bm{T}_{\epsilon}=\cup_{1\leq i\leq m}(t_{i}-\epsilon,t_{i}+\epsilon)$ the neighbourhood of $\bm{T}_{dis}$. By \citet[Chapter VI, Section 2, 2.3]{jacod2013limit}, for $s\in(0,\tau_a)\setminus\bm{T}_{\epsilon}$, the convergence $\omega_s^{(n)}\to\omega_s$ holds as $n\to\infty$, ensuring the convergence $k(\omega_s^{(n)})\to k(\omega_s)$. Denote by $U_k$ the upper bound of the function $k(\cdot)$. Notice that $\tau_{a}(\omega^{(n)})\to\tau_a(\omega)$ as $n\to\infty$, then it follows that \[\left|\int_{0}^{\tau_a(\omega)}k(\omega_s^{(n)})\diff s-\int_{0}^{\tau_a(\omega^{(n)})}k(\omega_s^{(n)})\diff s\right|\leq U_k\left|\tau_{a}(\omega)- \tau_{a}(\omega^{(n)})\right|\to 0.\]
        On the other hands,
        \begin{align*}
            &\left|\int_{0}^{\tau_a(\omega)}k(\omega_s)\diff s-\int_{0}^{\tau_a(\omega)}k(\omega_s^{(n)})\diff s\right|\\
            &\leq\int_{\bm{T}_{\epsilon}}\left|k(\omega_s)-k(\omega_s^{(n)})\right|\diff s+\int_{(0,\tau_a(\omega))\setminus\bm{T}_{\epsilon}}\left|k(\omega_s)-k(\omega_s^{(n)})\right|\diff s\\
            &\leq 4mU_k\epsilon+\int_{(0,\tau_a(\omega))\setminus\bm{T}_{\epsilon}}\left|k(\omega_s)-k(\omega_s^{(n)})\right|\diff s\\
            &\to 4mU_k\epsilon.
        \end{align*}
        The second inequality is established by the boundedness of the function $k(\cdot)$ and the last line follows from an application of the dominated convergence theorem.
        Since $\epsilon$ can be arbitrarily small, combining the above two results  yields that $\int_{0}^{\tau_a(\omega^{(n)})}k(\omega_s^{(n)})\diff s\to\int_{0}^{\tau_a(\omega)}k(\omega_s)\diff s$ as $n\to\infty$.
        \item The proof of the continuity of the mapping $\omega\mapsto\int_{0}^{\tau_a(\omega)}k(\omega_s,\overline{\omega}_s)\diff s$ is analogous to that of the mapping $\omega\mapsto\int_{0}^{\tau_a(\omega)}k(\omega_s)\diff s$ and hence is omitted.
        \item According to \citet[Theorem 4.1]{zhang2023drawdown}, $\tilde{\tau}_{a,1}(\omega^{(n)})=\tau_a(\omega^{(n)})\to\tau_a(\omega)=\tilde{\tau}_{a,1}(\omega)$ as $n\to\infty$. 
        % Since stopping times $\tilde{\tau}_{a,k}$ are defined recursively, 
        Therefore, it suffices to show the continuity of the mapping $\omega\mapsto\tilde{\tau}_{a,2}(\omega)$, and the continuity of the mappings $\omega\mapsto\tilde{\tau}_{a,k}$ for $k=3,\dots$ can be proved by mathematical induction. 

        ~~~~Assume $s'<\tilde{\tau}_{a,2}(\omega)<s,~\omega\in U$, and $s\in\mathbb{R}^+\setminus J(\omega)$, then $MD_{s',s}>a$. 
        % Since the path $\omega$ is continuous {\color{red}on the right at $s'$}, we can easily conclude that {\color{red}the maximum drawdown process $MD_{s',s}$} is also continuous on the right at $s'$. 
        By the right-continuity of the path $\omega$ at $s'$, $MD_{s',s}$ inherits this property and is also right-continuous at $s'$. Consequently, there exists a $\delta\in(0,s-s')$ such that $s'+\delta\in\mathbb{R}^+\setminus J(\omega)$ and $MD_{s'+\delta,s}>a$. \citet[Theorem 4.1]{zhang2023drawdown} implies that $MD_{s'+\delta,s}^{(n)}\to MD_{s'+\delta,s}$ as $n\to\infty$, in conjunction with the previous result yields $MD_{s'+\delta,s}^{(n)}>a$ for a sufficiently large $n$. Since $s'^{(n)}\to s'$, for a sufficiently large $n$, it follows that $s'^{(n)}\leq s'+\delta$ and hence $MD_{s'^{(n)},s}^{(n)}\geq MD_{s'+\delta,s}^{(n)}>a$,  equivalently, $\tilde{\tau}_{a,2}(\omega^{(n)})<s$. The arbitrariness of $s$ and dense property of the set $\mathbb{R}^+\setminus J(\omega)$ finally result in $\lim\sup_{n\to\infty}\tilde{\tau}_{a,2}(\omega^{(n)})\leq \tilde{\tau}_{a,2}(\omega)$.

        ~~~~Suppose $s'<s<\tilde{\tau}_{a,2}(\omega)$, $\omega\in \widetilde{\mathcal W}$, and $s\in\mathbb{R}^+\setminus J(\omega)$, then $MD_{s',s}<a$. Moreover, there exists a $\delta\in(0,s')$ such that $MD_{s'-\delta,s}<a$. The convergence $s'^{(n)}\to s'$ implies that $s'^{(n)}>s'-\delta$ holds for a sufficiently large $n$. Furthermore, applying \citet[Theorem 4.1]{zhang2023drawdown} yields $\lim_{n\to\infty}MD_{s'^{(n)},s}^{(n)}\leq\lim_{n\to\infty}MD_{s'-\delta,s}^{(n)}=MD_{s'-\delta,s}<a$, equivalently, $\tilde{\tau}_{a,2}(\omega^{(n)})>s$. As $s$ is arbitrary and $\mathbb{R}^+\setminus J(\omega)$ is dense, it follows that $\lim\inf_{n\to\infty}\tilde{\tau}_{a,2}(\omega^{(n)})\geq \tilde{\tau}_{a,2}(\omega)$.

        ~~~~Combining the above two results concludes the proof.
        \item Following the above proof of conclusion (4) in Theorem \ref{thm:convergence}, it suffices to prove the continuity of the mapping of $\omega\mapsto\tau_{a,2}(\omega)$.
        % in analogous to (4). 
        Observe that $\tau_{a,2}(\omega)=T_{M_1}+\inf\{t>T_{M_1}:\overline{\omega}_{T_{M_1},t}-X_t\geq a\}$ and $\tau_{a,2}(\omega^{(n)})=T_{M_1}^{(n)}+\inf\{t>T_{M_1}^{(n)}:\overline{\omega}_{T_{M_1}^{(n)},t}^{(n)}-Y_t^{(n)}\geq a\}$. It remains to show the convergence of $T_{M_1}^{(n)}$ as the convergence of the second term involved in $\tau_{a,2}(\omega^{(n)})$ can be proved in a similar way as that of $\tilde{\tau}_{a,2}(\omega^{(n)})$.

        ~~~~Suppose $s'<T_{M_1}<s,~\omega\in {V}$, and $s\in\mathbb{R}^+\setminus J(\omega)$. Thus, $\overline{\omega}_{0,s'}<\overline{\omega}_{s',s}$.
        % and $\omega_{s'}< \overline{\omega}_{0,s'}-a$. 
        By the
        right-continuity of the path $\omega$ at $s'$, there exists a $\delta\in(0,s-s')$ such that $s'+\delta\in\mathbb{R}^+\setminus J(\omega)$ and $\overline{\omega}_{s',s'+\delta}<\overline{\omega}_{s'+\delta,s}$. On the other hand, applications of \citet[Lemma 6]{Song2013weakconvergence} and \citet[Chapter VI, Section 2, 2.3]{jacod2013limit} yield $\overline{\omega}_{0,s'+\delta}^{(n)}\to \overline{\omega}_{0,s'+\delta}$ and $\overline{\omega}_{s'+\delta,s}^{(n)}\to \overline{\omega}_{s'+\delta,s}$ as $n\to\infty$. Besides, since $s'^{(n)}\to s'$, for a sufficiently large $n$, it follows that $s'^{(n)}<s'+\delta$. As a result, $\lim_{n\to\infty}\overline{\omega}_{0,s'^{(n)}}^{(n)}\leq \lim_{n\to\infty}\overline{\omega}_{0,s'+\delta}^{(n)}= \overline{\omega}_{0,s'+\delta}<\overline{\omega}_{s'+\delta,s}=\lim_{n\to\infty} \overline{\omega}_{s'+\delta,s}^{(n)}\leq\lim_{n\to\infty}\overline{\omega}_{s'^{(n)},s}^{(n)}$, equivalently, $s'^{(n)}<T_{M_1}^{(n)}<s$. Finally, by the arbitrariness of $s$ and dense
        property of the set $\mathbb{R}^+\setminus J(\omega)$, the inequality $\lim\sup_{n\to\infty}T_{M_1}^{(n)}\leq T_{M_1}$ holds.

        ~~~~Suppose $s'<s<T_{M_1}$, $\omega\in \mathcal W$, and $s\in\mathbb{R}^+\setminus J(\omega)$, then $\overline{\omega}_{0,s'}>\overline{\omega}_{s',s}$. Moreover, there exists a $\delta>0$ such that $s'-\delta\in\mathbb{R}^+\setminus J(\omega)$ and $\overline{\omega}_{0,s'-\delta}>\overline{\omega}_{s'-\delta,s}$. On the other hand, applying \citet[Lemma 6]{Song2013weakconvergence} and \citet[Chapter VI, Section 2, 2.3]{jacod2013limit} yield $\lim_{n\to\infty}\overline{\omega}_{0,s'-\delta}^{(n)}=\overline{\omega}_{0,s'-\delta}$ and $\lim_{n\to\infty}\overline{\omega}_{s'-\delta,s}^{(n)}=\overline{\omega}_{s'-\delta,s}$. Besides, the convergence $s'^{(n)}\to s'$ implies that $s'^{(n)}>s'-\delta$ for a sufficiently large $n$. As a result, $\lim_{n\to\infty}\overline{\omega}_{0,s'^{(n)}}^{(n)}\geq\lim_{n\to\infty}\overline{\omega}_{0,s'-\delta}^{(n)}=\overline{\omega}_{0,s'-\delta}>\overline{\omega}_{s'-\delta,s}=\lim_{n\to\infty}\overline{\omega}_{s'-\delta,s}^{(n)}\geq\lim_{n\to\infty}\overline{\omega}_{s'^{(n)},s}^{(n)}$, equivalently, $T_{M_1}^{(n)}>s$. The arbitrariness of $s$ and dense property of the set $\mathbb{R}^+\setminus J(\omega)$ finally lead to $\lim\inf_{n\to\infty}T_{M_1}^{(n)}\geq T_{M_1}$.

        ~~~~Combining the above two results completes the proof.
    \end{enumerate}
\end{proof}

