\section{Preliminaries}\label{sec.pre}
%-------------------------------------------------------------------------
Along the paper, we will denote by $\mathbb{F}$ a field, a priori without any restriction about its characteristic.

%------------------------------------------------------------------------
\subsection{Leibniz algebras}
%-------------------------------------------------------------------------
\begin{definition}\label{def.Leibniz}
A \textbf{Leibniz algebra} is a pair $(\mathfrak{l},[-,-])$, where $\mathfrak{l}$ is an $\mathbb{F}$-vector space and $[-,-]\colon \mathfrak{l}\times \mathfrak{l}\rightarrow \mathfrak{l}$ is a bilinear map, such that the following condition holds:
\begin{equation}\label{LeibRule}
[[a,b],c]=[[a,c],b]+[a,[b,c]]\quad\textnormal{(Leibniz rule)}
\end{equation}
for all $a,b,c\in\mathfrak{l}$. The map $[-,-]$ is referred to as the \textbf{Leibniz bracket} of $\mathfrak{l}$.

Let $(\mathfrak{l},[-,-]_{\mathfrak{l}})$ and $(\mathfrak{m},[-,-]_{\mathfrak{m}})$ be Leibniz algebras. A linear map $f\colon \mathfrak{l}\rightarrow \mathfrak{m}$ is a \textbf{Leibniz algebra morphism} if $f$ preserves the bracket, i.e., $f([a,b]_{\mathfrak{l}})=[f(a),f(b)]_{\mathfrak{m}}$ for all $a,b\in\mathfrak{l}$. The category of Leibniz algebras will be denoted by {\sf Leib}.
\end{definition}
\begin{remark}\label{Lie_algebra_is_Leibniz_algebra}
It is straightforward to prove that every Lie algebra $(\g,[-,-])$ satisfies the Leibniz rule \eqref{LeibRule}. This yields an inclusion functor $\iota\colon {\sf Lie}\longrightarrow{\sf Leib},$ where ${\sf Lie}$ denotes the category of Lie algebras.

Note that every Leibniz algebra $\mathfrak{l}$ always has the following non-trivial ideal
\[\textnormal{Leib}(\mathfrak{l})\coloneqq \operatorname{span}_{\mathbb{F}}\{[x,x]\colon x\in\mathfrak{l}\}.\]
The quotient $\mathfrak{l}/\textnormal{Leib}(\mathfrak{l})$ is always a Lie algebra, so $\mathfrak{l}$ is a Lie algebra if and only if $\textnormal{Leib}(\mathfrak{l})=0$. In other words, $\textnormal{Leib}(\mathfrak{l})$ allows to measure how far a Leibniz algebra is from being a Lie algebra. 
\end{remark}
\begin{definition} 
Let $(\mathfrak{l},[-,-])$ be a Leibniz algebra. 
\begin{enumerate}
\item[(i)] The \textbf{left center} of $\mathfrak{l}$ is the subset of $\mathfrak{l}$
\[\mathcal{LZ}(\mathfrak{l})\coloneqq\{x\in\mathfrak{l}\colon [x,\mathfrak{l}]=0\}.\]
\item[(ii)] The \textbf{right center} of $\mathfrak{l}$ is the subset of $\mathfrak{l}$
\[\mathcal{RZ}(\mathfrak{l})\coloneqq\{x\in\mathfrak{l}\colon [\mathfrak{l},x]=0\}.\]
\end{enumerate}
\end{definition}
\begin{remark}\label{rem.condLeibR}
In every Leibniz algebra $(\mathfrak{l},[-,-])$, \begin{equation}\label{condLeibR}[a,[b,b]]=0,\end{equation} 
for all $a,b\in\mathfrak{l},$ i.e., $\textnormal{Leib}(\mathfrak{l})\subseteq\mathcal{RZ}(\mathfrak{l})$. Indeed, by the Leibniz rule \eqref{LeibRule}, 
\[[[a,b],b]-[[a,b],b]-[a,[b,b]]=0\implies[a,[b,b]]=0.\]
\end{remark}
\begin{definition}
    A Leibniz algebra $(\mathfrak{l},[-,-])$ is \textbf{abelian} if $[\mathfrak{l},\mathfrak{l}]=0$.
\end{definition}
As a consequence of \eqref{condLeibR}, if $(\mathfrak{l},[-,-])$ is a Leibniz algebra with idempotent bracket, i.e., $[a,a]=a$ for all $a\in\mathfrak{l}$, then $\mathfrak{l}$ is automatically abelian.


The notion of derivation of a Leibniz algebra is defined analogously to that in general algebraic structures.
\begin{definition}
    Let $(\mathfrak{l},[-,-])$ be a Leibniz algebra. A \textbf{derivation} of $\mathfrak{l}$ is a linear endomorphism $L\colon \mathfrak{l}\rightarrow \mathfrak{l}$ satisfying the Leibniz rule with respect to the Leibniz bracket:
\begin{equation*}\label{der_def}
[L(a),b]+[a,L(b)]=L([a,b])
\end{equation*}
for all $a,b\in\mathfrak{l}$. We will denote the collection of all derivations of $\mathfrak{l}$ by $\operatorname{Der}(\mathfrak{l})$.
\end{definition}

Thus, equation \eqref{LeibRule} is equivalent to the fact that $\operatorname{ad}_{a}\coloneqq[-,a]\in\operatorname{Der}(\mathfrak{l})$ for all $a\in\mathfrak{l}$.

