\subsection{Heaps and affine spaces}
%------------------------------------------------------------------------
\begin{definition}
A \textbf{heap} is a set $X$ together with a ternary operation $\langle-,-,-\rangle\colon X\times X\times X\rightarrow X$ which satisfies the following conditions:
\begin{subequations}\label{heapcond}
\begin{align}\label{h_asoc}
\langle\langle a,b,c\rangle,d,e\rangle=\langle a,b,\langle c,d,e\rangle\rangle\quad&\textnormal{(associativity),}\\
\label{h_Malcev1}\langle a,b,b\rangle=a \quad&\textnormal{(Mal'cev identity 1),}\\
\label{h_Malcev2}\langle a,a,b\rangle=b \quad &\textnormal{(Mal'cev identity 2),}
\end{align}
\end{subequations}
for all $a,b,c,d,e\in X$. A heap $(X,\langle -,-,-\rangle)$ is said to be \textbf{abelian} if the equality
\begin{equation}\label{h_ab}
\langle a,b,c\rangle=\langle c,b,a\rangle
\end{equation}
also holds. 

Let $(X,\langle -,-,-\rangle_{X})$ and $(Y,\langle -,-,-\rangle_{Y})$ be heaps. A map $f\colon X\rightarrow Y$ is a \textbf{heap morphism} if $f$ preserves the heap ternary operation, i.e., $f(\langle a,b,c\rangle_{X})=\langle f(a),f(b),f(c)\rangle_{Y}$ for all $a,b,c\in X$.
%With this morphisms, heaps constitute a category that we will denote by {\sf Heap}. Abelian heaps constitute a full subcategory of {\sf Heap} denoted by {\sf AbHeap}.
\end{definition}

Due to \eqref{h_asoc}, we simply write $\langle a,b,c,d,e\rangle$ for $\langle\langle a,b,c\rangle,d,e\rangle=\langle a,b,\langle c,d,e\rangle\rangle$ because the distribution of brackets does not matter. Note that if $X$ is an abelian heap, then \eqref{h_Malcev1} is equivalent to \eqref{h_Malcev2}.


There exists a strong relationship between abelian heaps and abelian groups. On the one hand, if $(G,+)$ is an abelian group, then $G$ with the ternary operation defined by
\[\langle x,y,z\rangle_{G}\coloneqq x-y+z,\]
for all $x,y,z\in G$, is an abelian heap. On the other hand, if $(X,\langle -,-,-\rangle)$ is an abelian heap and $o\in X$, then the binary operation
\[a+b\coloneqq\langle a,o,b\rangle,\]
for all $a,b\in X$, induces an abelian group structure on $X$. The unit is the fixed element $o$, and the inverse of $a\in X$ with respect to $+$ is $-a\coloneqq \langle o,a,o\rangle$. This group structure is called \textbf{the retract of $X$ at $o$}, denoted by $X_{o}$. All retracts of a given heap are mutually isomorphic (as groups) (see \cite[Lemma 2.1]{BRZ1}). 


\begin{definition}\label{affspace}
An \textbf{$\mathbb{F}$-affine space} (or simply, \textbf{affine space}) is a triple $(\mathfrak{a},\langle -,-,-\rangle, -\triangleright_{-}-)$, where $(\mathfrak{a},\langle -,-,-\rangle)$ is a non-empty abelian heap and $-\triangleright_{-}-$ is a ternary map:
\begin{align*}
-\triangleright_{-}-\colon \mathbb{F}\times\mathfrak{a}\times\mathfrak{a}&\rightarrow\mathfrak{a}\\(\alpha,a,b)&\mapsto \alpha\triangleright_{a}b,
\end{align*}
satisfying the following conditions:
\begin{enumerate}
\item[(i)] For all $\alpha\in\mathbb{F}$ and $a\in \mathfrak{a}$, the map $\alpha\triangleright_{a}-\colon\mathfrak{a}\rightarrow \mathfrak{a}$ is a heap morphism.
\item[(ii)] For all $a,b\in\mathfrak{a}$, the map $-\triangleright_{a}b\colon\mathbb{F}\rightarrow\mathfrak{a}$ is a heap morphism considering that the heap ternary operation in $\mathbb{F}$ is given by $\langle\alpha,\beta,\gamma\rangle_{\mathbb{F}}\coloneqq \alpha-\beta+\gamma$ for all $\alpha,\beta,\gamma\in\mathbb{F}$.
\item[(iii)] For all $a\in\mathfrak{a}$, the map $-\triangleright_{a}-\colon\mathbb{F}\times\mathfrak{a}\rightarrow \mathfrak{a}$ is a left action, i.e., $1_{\mathbb{F}}\triangleright_{a}b=b$ and $\alpha\triangleright_{a}(\beta\triangleright_{a}b)=(\alpha\beta)\triangleright_{a}b$, for all $\alpha,\beta\in\mathbb{F}$ and for all $b\in\mathfrak{a}$.
\item[(iv)] For all $a,b\in\mathfrak{a}$, $0_{\mathbb{F}}\triangleright_{a}b=a$.
\item[(v)] (\textbf{Base change property})
\[\alpha\triangleright_{a}b=\langle \alpha\triangleright_{c}b,\alpha\triangleright_{c}a,a\rangle\]
for all $\alpha\in\mathbb{F}$ and for all $a,b,c\in \mathfrak{a}$.
\end{enumerate}

Let $(\mathfrak{a},\langle -,-,-\rangle_{\mathfrak{a}}, -\triangleright^{\mathfrak{a}}_{-}-)$ and $(\mathfrak{b},\langle -,-,-\rangle_{\mathfrak{b}}, -\triangleright^{\mathfrak{b}}_{-}-)$ be affine spaces. A map $f\colon \mathfrak{a}\rightarrow\mathfrak{b}$ is an \textbf{affine morphism} if $f$ is a heap morphism and also the equality
\begin{equation}\label{affmap_cond}
f(\alpha\triangleright^{\mathfrak{a}}_{a}b)=\alpha\triangleright^{\mathfrak{b}}_{f(a)}f(b)
\end{equation}
holds, for all $a,b\in\mathfrak{a}$ and for all $\alpha\in\mathbb{F}$.
\end{definition}

The following two properties are deduced from the axioms of an affine space (see \cite[Lemma 3.5]{BreBrz:hea} for detailed proofs):
\begin{enumerate}
\item[(i)] The map $\alpha\triangleright_{-}b\colon \mathfrak{a}\rightarrow\mathfrak{a}$ is a heap morphism for all $\alpha\in\mathbb{F}$ and $b\in\mathfrak{a}$.
\item[(ii)] For all $\alpha\in \mathbb{F}$ and $a\in\mathfrak{a}$, the equality 
\begin{equation}\label{prop_affspace}\alpha\triangleright_{a}a=a\end{equation}
holds.
\end{enumerate}
\begin{remark}\label{morph_aff_lin}
Let $(\mathfrak{a},\langle -,-,-\rangle, -\triangleright_{-}-)$ be an affine space and fix $o\in\mathfrak{a}$. The retract of $\mathfrak{a}$ at $o$, $\mathfrak{a}_{o}$, is an $\mathbb{F}$-vector space with the external operation
\[\alpha a\coloneqq\alpha\triangleright_{o}a,\]
for all $\alpha\in\mathbb{F}$ and for all $a\in\mathfrak{a}.$ This vector space is called \textbf{the tangent space to $\mathfrak{a}$ at $o$} (or simply, the \textbf{fibre of $\mathfrak{a}$ at $o$}), and  denoted by $T_{o}\mathfrak{a}$.
In terms of the external operation in $T_{o}\mathfrak{a}$,
\begin{equation}\label{relation_external_triangle}
\alpha\triangleright_{a}b=(1-\alpha)a+\alpha b.
\end{equation}
Moreover, $T_{o}\mathfrak{a}$ acts freely and transitively over $\mathfrak{a}$ via the following action
\begin{align*}
\psi\colon \mathfrak{a}\times T_{o}\mathfrak{a}\rightarrow\mathfrak{a}\qquad (a,b)\mapsto \psi(a,b)\coloneqq \langle a,o,b\rangle.
\end{align*}
Note also that fibres of $\mathfrak{a}$ are mutually isomorphic (as vector spaces) (see \cite[Remark 2.5]{BRZ2}).

In addition, if $f\colon \mathfrak{a}\rightarrow \mathfrak{b}$ is an affine morphism, then it induces an unique linear map $\overrightarrow{f}$ between $T_{o}\mathfrak{a}$ and $T_{u}\mathfrak{b}$ defined by $\overrightarrow{f}(a)\coloneqq f(a)-f(o)$ for all $a\in\mathfrak{a}$. 
Conversely, if $\widehat{f}\colon T_{o}\mathfrak{a}\rightarrow T_{u}\mathfrak{b}$ is a linear map and we fix an element $b\in\mathfrak{b}$, then the map 
    \begin{align*}%\label{affine.map}
f\colon \mathfrak{a}\rightarrow\mathfrak{b}\qquad a\mapsto f(a)\coloneqq \widehat{f}(a)+b=\langle \widehat{f}(a),u,b\rangle
\end{align*}
is an affine map, and also all affine maps from $\mathfrak{a}$ to $\mathfrak{b}$ arise in this way. Note that $b = f(o)$.

To make a connection with a more traditional definition of an affine space as a set $\mathfrak{a}$ with a free and transitive action of a vector space $\overrightarrow{\mathfrak{a}}$, we can set explicitly $\overrightarrow{\mathfrak{a}}= T_o\mathfrak{a}$ (or any other vector space isomorphic to a vector fibre of $\mathfrak{a}$). The action is then given by $a+v \coloneqq \langle a,o,v\rangle$, for all $a\in \mathfrak{a}$ and $v\in T_o\mathfrak{a}$. The vector from $a$ to $b$ in $\mathfrak{a}$ is then $\overrightarrow{ab}\coloneqq\langle o,a,b\rangle$.
\end{remark}

\begin{definition}\label{def.Lie}
An $\mathbb{F}$\textbf{-affgebra} (or simply, an \textbf{affgebra}) is an affine space $\mathfrak{a}$ together with a bi-affine morphism $\mu_{\mathfrak{a}}\colon\mathfrak{a}\times\mathfrak{a}\rightarrow\mathfrak{a},$
which is called the \textbf{affine product} of the affgebra. If $\mu_{\mathfrak{a}}$ is associative, then we say that $\mathfrak{a}$ is an \textbf{associative affgebra}.

If $(\mathfrak{a},\mu_{\mathfrak{a}})$ and $(\mathfrak{b},\mu_{\mathfrak{b}})$ are affgebras, then an affine morphism $f\colon \mathfrak{a}\rightarrow\mathfrak{b}$ is said to be an \textbf{affgebra morphism} if $f(\mu_{\mathfrak{a}}(a,b))=\mu_{\mathfrak{b}}(f(a),f(b))$, for all $a,b\in\mathfrak{a}$.
\end{definition}
\begin{remark}
Let $(\mathfrak{a},\mu_{\mathfrak{a}})$ be an affgebra. In view of the fact that $\mu_{\mathfrak{a}}$ is a bi-affine morphism,  the equalities
\begin{gather*}
\mu_{\mathfrak{a}}(a,\langle b,c,d\rangle)=\langle\mu_{\mathfrak{a}}(a,b),\mu_{\mathfrak{a}}(a,c),\mu_{\mathfrak{a}}(a,d)\rangle,\\
\mu_{\mathfrak{a}}(\langle a,b,c\rangle,d)=\langle\mu_{\mathfrak{a}}(a,d),\mu_{\mathfrak{a}}(b,d),\mu_{\mathfrak{a}}(c,d)\rangle
\end{gather*}
hold for all $a,b,c,d\in\mathfrak{a}$. This means that $(\mathfrak{a},\langle -,-,-\rangle,\mu_{\mathfrak{a}})$ is a \textbf{truss} \cite[Definition 3.1]{BRZ1}. 
\end{remark}
