\begin{abstract}
The primary aim of this paper is to construct harmonic mapping associated with four parameter Wright functions. Further sufficient conditions have been established so that this harmonic mapping satisfies geometric properties such as harmonic starlikeness and convexity. Moreover, we examine relation between several subclasses of family of harmonic close-to-convexity mappings. The results obtained in this paper are novel and their significance is illustrated by several consequences.
\end{abstract}
\maketitle

\section{Introduction and Motivation}
Harmonic functions play a vital role in several problems in applied mathematics and are also important because of their use in the minimal surface. Many different geometers, such as Lewy and Rado \cite{lewy}, Choquest \cite{choquet} and  Kneser\cite{kneser} studied the harmonic functions. A continuous complex value mapping $f = u +iv$ is said to be harmonic in a domain $D$ connected simply in the complex plane if it holds $f_{z\Bar{z}}=0$ in $D$, that is, $u$ and $v$ are real harmonic functions in $D$. This type of harmonic function $f$ can be represented as $f = h + \Bar{g}$, where $h$ and $g$ are analytic in $D$ with $h(0)=0$, $h^{\prime}(0)=1$, $g(0)=0$ and have Taylor series representations of the form 
\begin{align}\label{eqharmonic}
h(z)=z+\sum_{n=2}^{\infty}a_{n}z^{n}, \quad g(z)=\sum_{n=1}^{\infty}b_{n}z^{n}, \quad |b_{1}|<1.
\end{align}
We often say $h$ and $g$ the analytic and co-analytic parts of $f$ respectively. This above class of harmonic mapping is denoted as $\mathaccent"705E{H}$. A necessary and sufficient condition for $f$ in the class $\mathaccent"705E{H}$ to be sense preserving and locally univalent is $|h'(z)|>|g'(z)|$ in $D$. The subclass of $\mathaccent"705E{H}$ consisting of functions that are sense-preserving and univalent in $D$ are denoted by $HS$. For $0\leq \alpha <1$,\\
$$HS^{*}(\alpha)=\left\{f\in \mathaccent"705E{H}: \frac{\partial}{\partial \theta}(\arg(f(re^{\i\theta})))>\alpha \right\}$$.
$$HK(\alpha)=\left\{f\in \mathaccent"705E{H}: \frac{\partial}{\partial \theta}(\arg(\frac{\partial}{ \partial\theta}(f(re^{i\theta}))))>\alpha \right\},$$
for $z=re^{i\theta}$, $0\leq \theta \leq 2\pi$ and $0\leq r <1$. It can be noted that $HS^{*}=HS^{*}(0)$ is the class of harmonic starlike functions with respect to origin in $D$. Similarly $HK=HK(0)$ is the class of harmonic convex function in $D$. For $0\leq \alpha <1$ harmonic starlike of order $\alpha$ and harmonic convex of order $\alpha$ denoted by $HS^{*}(\alpha)$ and $HK(\alpha)$, respectively.

The subclass of $\mathaccent"705E{H}$ denoted by $S\mathaccent"705E{H}$ that is sense-preserving and univalent in $D$. It can be seen that $\frac{f-\Bar{B_{1}f}}{1-|B_{1}|^{2}}  \in S\mathaccent"705E{H}$, whenever $f\in S\mathaccent"705E{H}$. There is a subclass $S\mathaccent"705E{H^{o}}$ taken into account by $S\mathaccent"705E{H}$ given by \\
$$S\mathaccent"705E{H^{o}}=\left\{f= h + \Bar g \in S\mathaccent"705E{H}: g'(0)=B_{1}=0 \right\}.$$
The subclass $S\mathaccent"705E{H^{o}}$ and $S\mathaccent"705E{H}$ were studied in \cite{clunie}. It can be noted that $HS(0)=S\mathaccent"705E{H}$. The class $C$ of all close-to-convex analytic functions in $D$, assume that $C\mathaccent"705E{H^{o}}$ and $C\mathaccent"705E{H}$ are the subclass respectively of $S\mathaccent"705E{H^{o}}$ and $S\mathaccent"705E{H}$ such that for any $f \in C\mathaccent"705E{H^{o}}$ and $f \in C\mathaccent"705E{H}$, $f(D)$ is close to convex in $D$. It can be recall that a domain $D$ is close to convex if the complement of $D$ can be written as a union of nonincreasing half lines. 

A complex valued harmonic function $f$ in $D$ is called typically real given that $f(z)$ is real iff $z$ is real. All sense preserving typically real harmonic function $f \in \mathaccent"705E{H}$ are denoted by the class $T\mathaccent"705E{H}$ and with $g(0)=0$ is denoted by $T\mathaccent"705E{H^{o}}$. Suppose that $SRH(\alpha)$ and $KRH(\alpha)$ denote the subclass of $HS^{*}(\alpha)$ and $HK(\alpha)$ respectively containing the function $f=h+\Bar g$, where  
\begin{equation}\label{eq1}
  h(z)=z-\sum_{n=2}^{\infty}|A_{n}|z^{n}, \quad g(z)=\sum_{n=1}^{\infty}|B_{n}|z^{n}, \quad |B_{1}|<1.  
\end{equation}
Assume that $SRH=SRH(0),$ $KRH=KRH(0).$ 

The Wright function
$$\mathcal{W}_{\alpha, \beta}(z)=\sum_{n=0}^{\infty}\frac{z^{n}}{\Gamma(\alpha n +\beta)n!},\quad \beta,z \in C, \alpha >-1,$$ was firstly introduced by E. M. Wright \cite{wright} in connection with the theory of partitions. It plays important role in fractional calculus \cite{luchko,podlubny}, integral equation of Hankel type, Mikusiski operational calculus and  stochastic process. For a history regarding Wright function and applications, one can refer \cite{mainardi}. It is noted that Wright functions is an entire function of order $\frac{1}{1+\alpha}$, which is also generalized Bessel functions \cite{podlubny,baricz}. These functions generalized hypergeometric functions \cite{stegun, Andrews}.\\
The four parameter Wright functions \cite{luchko}\\
$$\mathcal{W}_{{(\alpha, \beta),(\gamma, \delta)}}(z)=\sum_{n=0}^{\infty}\frac{z^{n}}{\Gamma(\alpha  +n\beta)\Gamma(\gamma  +n \delta)},\quad \alpha,\gamma,z \in C, \beta,\delta \in R,$$ was studied by E. M. Wright for $\beta,\delta>0$ \cite{Wright}. In addition he derived many properties of $\mathcal{W}_{(\alpha, \beta),(\gamma, \delta)}(z)$ for $\gamma=\delta=1$ and $-1<\beta<0$ \cite{right}.  It can be justified \cite{mehrez} that if $\beta + \delta>0$, then the infinite series expansion of $\mathcal{W}_{{(\alpha, \beta)},({\gamma, \delta})}(z)$ converges absolutely for all $z\in C$. It is well known that \cite{luchko} $\mathcal{W}_{{(\alpha, \beta)},({\gamma, \delta})}(z)$ is an entire function for $\alpha, \gamma \in C$ and $0<\beta < \delta.$\\
It can be noted that 
$$W_{{(\alpha, \beta)},({\gamma, \delta})}(z)\\=z\Gamma(\alpha)\Gamma(\gamma)\mathcal{W}_{{(\alpha, \beta)},({\gamma, \delta})}(z)=z+\sum_{n=2}^{\infty}\frac{z^{n}}{\Gamma(\alpha  +(n-1)\beta)\Gamma(\gamma  +(n-1) \delta)},$$ where $ \alpha, \gamma \in C, \quad \forall \quad \beta, \delta>-1$ belongs to normalized class for all $z \in D$. Some geometric properties of four-parameter Wright functions $W_{{(\alpha, \beta)},({\gamma, \delta})}(z)$ have beed studied in \cite{das}.\\
In this paper, we shall study for the real valued $\beta, \delta$ and $z\in D$ and now define a linear operator by convolution as follwos for the functions:\\
$$W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(z)=z+\sum_{n=2}^{\infty}\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}z^{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}$$ and \\ $$W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(z)=z+\sum_{n=2}^{\infty}\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}z^{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}.$$
Now define a linear convolution operator corresponding to $f=h+\bar{g}$\\
$L:\hat{H} \rightarrow \hat{H}$ as: \\
\begin{align*}
    L(f)&=f \ast(W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(z)+\bar {\sigma W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(z)})\nonumber\\
    &=H(z) + \bar{\sigma G(z)}=h \ast{W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(z)}+\bar {\sigma   g * W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(z)}, \quad |\sigma|<1,
\end{align*}
where 
\begin{align}\label{eqHarmonic}
H(z)=z+\sum_{n=2}^{\infty}\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}z^{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})},\nonumber\\
G(z)=\sum_{n=1}^{\infty}\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}z^{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}.  
\end{align}
Since four-parameter Wright function $\mathcal{W}_{{(\alpha, \beta),(\gamma, \delta)}}(z)$ is a generalization of Wright function $\mathbb{W}_{(\alpha, \beta)}(z)=\mathcal{W}_{{(\alpha, \beta),(1,1)}}(z)$, similar to above linear operator we can define :

$L:\hat{H} \rightarrow \hat{H}$ as: \\
\begin{align}\label{eqwright}
    L(f)&=f \ast(W_{{(\alpha_{1}, \beta_{1})},(1,1)}(z)+\bar {\sigma W_{{(\alpha_{2}, \beta_{2})},(1,1)}(z)})\nonumber\\
    &=H(z) + \bar{\sigma G(z)}=h \ast{W_{{(\alpha_{1}, \beta_{1})},(1,1)}(z)}+\bar {\sigma   g * W_{{(\alpha_{2}, \beta_{2})},(1,1)}(z)}, \quad |\sigma|<1,
\end{align}
where 
\begin{align}
H'z)=z+\sum_{n=2}^{\infty}\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}z^{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})},\nonumber\\
G'(z)=\sum_{n=1}^{\infty}\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}z^{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})}.  
\end{align}

In \cite{op, sarkar, aghalary}, researchers derived several require conditions for harmonic mapping asscoiated with special functions hypergeometric function, Bessel function, Mittag-leffler functon, Wright-functions lies on geometric characteristics such as Harmonic convexity and starlikeness. Ahuja at.al \cite{ahuja} studied harmonic close -to-convexity for harmonic mapping involving hypergeometric function. In \cite{sahu}, connections between various subclasses of hamonic mapping have been discussed related to Wright function.
Motivated by above mentioned result, we have decided to study geometric properties such as harmonic convexity , starlikeness, close-to-convexity for harmonic mapping involving four-parameter Wright function in this paper.

The paper is systemized like this. In Section \ref{sec2}, we have mentioned some crucial lemmas, which will turn out to be useful to derive our iportant results. Section \ref{sec3} discusses some sufficient conditions in such a way that the harmonic mapping involving four-parameter Wright function satisfies like harmonic starlikeness. In Section \ref{sec4}, we have considered normalized harmonic mapping involving four-parameter Wright function and harmonic. Harmonic close-to-convexity has been established for the above function in section \ref{sec5}. In the section \ref{sec6}, several consequences and conclusion of main results have been investigated

In order to prove the main findings, we require following lemmas:


\section{Lemma}\label{sec2}
\begin{lemma}\cite{jahangiri}\label{lem1}
    Let $f= h + \bar g \in \hat{H}$ with $h$ and $g$ of the form \eqref{eq1}. If for some $\alpha(0\leq \alpha <1),$ the inequality $$\sum_{n=2}^{\infty}(n-\alpha)|A_{n}|+\sum_{n=1}^{\infty}(n+\alpha)|B_{n}|\leq 1-\alpha$$ is satisfied, then f is harmonic, sense preserving, univalent in $D$ and $f\in HS^{*}(\alpha)$.
\end{lemma}
\begin{lemma}\cite{karlsson}\label{lem2}
  Let $f= h + \bar g \in \hat{H}$ where $h$ and $g$ are given by \eqref{eq1}. If for $\alpha(0\leq \alpha <1),$ the inequality $$\sum_{n=2}^{\infty}(n(n-\alpha))|A_{n}|+\sum_{n=1}^{\infty}(n(n+\alpha))|B_{n}|\leq 1-\alpha$$ is satisfied, then f is harmonic, sense preserving, univalent in $D$ and $f\in HK(\alpha)$.  
\end{lemma}
\begin{lemma}\label{lem3}
    Suppose $h$ and $g$ are analytic function in $D$ with $|g^{\prime}(0)|<|h^{\prime}(0)|$ and that $h+\epsilon g \in C$ for each $\epsilon(|\epsilon|=1$. Then $h + \bar g \in C_{\hat{H}}.$
\end{lemma}

\begin{lemma}\label{lem5}
    If $q(z)=z+\sum_{n=2}^{\infty}t_{n}z^{n}$ is analytic in $D$, then q maps onto a starlike domain if $\sum_{n=2}^{\infty}n|t_{n}|\leq 1.$
\end{lemma}

\begin{lemma}\label{lem4}
    If $f=h + \bar g \in K_{\hat{H}^{o}}$ is given by \eqref{eq1}, then $|A_{n}|\leq (n+1)/2$, $|B_{n}|\leq (n-1)/2$, $n=1,2,3,\cdots$.
\end{lemma}

The results in the next two lemmas found in \cite{wang} and \cite{small}, respectively.
\begin{lemma}\label{lem7}
    If $f=h + \bar g \in C_{\hat{H}^{o}}(S_{\hat{H}^{o}} or T_{\hat{H}^{o}})$ is given by \eqref{eq1}, then 
    \begin{align*}
    |A_{n}|\leq \frac{(2n+1)(n+1)}{6}, |B_{n}|\leq \frac{(2n-1)(n-1)}{6}, n=1,2,3,\cdots.
     \end{align*}
\end{lemma}

\begin{lemma}\label{lemclosetoconvex}
    If $f=h + \bar g \in C_{\hat{H} }$ is given by \eqref{eq1}, then 
    \begin{align*}
    |A_{n}|\leq \frac{(2n+1)(n+1)}{6}+ \frac{(2n-1)(n-1)}{6}|B_{1}|, \quad n=1,2,3,\cdots\\
     |B_{n}|\leq \frac{(2n-1)(n-1)}{6}+ \frac{(2n+1)(n+1)}{6}|B_{1}| \quad n=1,2,3,\cdots.
     \end{align*}
\end{lemma}

 The result in next lemma from \cite{jahangiri, jmj} provide necessary and sufficient conditions in terms of coefficient for the functions in $SRH(\alpha)$ and $KRH(\alpha)$.
\begin{lemma}\label{lem6}
    Let $f= h + \bar g \in \hat{H}$ where $h$ and $g$ are given by \eqref{eq1}.  Then   $$f \in SRH(\alpha) \Leftrightarrow \sum_{n=2}^{\infty}((n-\alpha))|A_{n}|+\sum_{n=1}^{\infty}((n+\alpha))|B_{n}|\leq 1-\alpha,$$
 $$f \in KRH(\alpha) \Leftrightarrow
   \sum_{n=2}^{\infty}(n(n-\alpha))|A_{n}|+\sum_{n=1}^{\infty}(n(n+\alpha))|A_{n}|\leq 1-\alpha.$$
\end{lemma}

