\section{Harmonic Starlikeness}\label{sec3}
\begin{theorem}
    Suppose that $\beta_{1},\beta_{2}, \delta_{1}, \delta_{2}\geq 0$, $\alpha_{1},\alpha_{2}, \gamma_{1}, \gamma_{2}> 0$ and $|\sigma|<1$. Also assume $f= h + \bar g \in \hat{H}$ if the inequality $|A_{n}|\leq 1, |B_{n}|\leq 1$ and \\$$ (W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime}(1)-1) -\alpha(W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(1)-1)+|\sigma|(W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_2})}^{\prime}(1) + \alpha W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(1))\leq (1-\alpha)$$ are satisfied then $L(f)$ is harmonic starlike function, i.e $L(f)\in HS^{*}(\alpha)$.
\end{theorem}

\begin{proof}
Let $f= h + \bar g \in \hat{H}$, where $h$ and $g$ given by the equation \eqref{eqharmonic}. We have to prove $L(f)\in HS^{*}(\alpha)$, where $$L(f)=z+\sum_{n=2}^{\infty}\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}z^{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}+\sum_{n=1}^{\infty}\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}z^{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}.$$
    In view of lemma \ref{lem1},
it suffices to show that \begin{align*}
        S_{2}=&\sum_{n=2}^{\infty}(n-\alpha)\left|\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}\right||A_{n}|\\
        &+|\sigma|\sum_{n=1}^{\infty}(n+\alpha)\left|\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}\right||B_{n}|\leq (1-\alpha).
        \end{align*}
        Now, we have
        \begin{align*}
        S_{2} &  \leq \sum_{n=1}^{\infty}(n+1-\alpha)\left|\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n \beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}\right|\\
        & + |\sigma|\sum_{n=0}^{\infty}(n+1+\alpha)\left|\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}\right|=\\
        &  (W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime}(1)-1) -\alpha(W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(1)-1)+|\sigma|(W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_2})}^{\prime}(1) + \alpha W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(1)).
    \end{align*}
    As a result, by the given conditions,  the desired outcome has been obtained.
\end{proof}

