        & P_{1}\leq  \sum_{n=2}^{\infty}\left|\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}\right|+|\sigma|\sum_{n=1}^{\infty}\left|\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}\right|\\
        & = \sum_{n=1}^{\infty}\left|\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}\right|+|\sigma|\sum_{n=0}^{\infty}\left|\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}\right|\\
        &=W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(1)+|\sigma|W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(1).   \end{align*}
 Using the stated condition of theorem established, readily to follow the required result. 
 \end{proof}


In the below section, we obtain some sufficient conditions in such a way that the harmonic mapping involving four-parameter Wright function satisfies harmonic close-to-convex domain.

In this we determine adequate condition which guarantee that a harmonic mapping map unit disk to $D$ into harmonic close-to-convex domain.
\section{Harmonic Close-to-convexity}\label{sec5}
\begin{theorem}
Suppose that $\beta_{1},\beta_{2}, \delta_{1}, \delta_{2}\geq 0$, $\alpha_{1},\alpha_{2}, \gamma_{1}, \gamma_{2}> 0$ and $|\sigma|<1$. Also let us assume $f= h + \bar g \in \hat{H}$ if the following conditions
\begin{enumerate}\label{eq1}

\rm(i) $\sum_{n=2}^{\infty}n|A_{n}|+\sum_{n=1}^{\infty}n|B_{n}|\leq1, \quad |B_{1}|<1$,\\

\rm(ii)$[W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(1)+W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(1)-2] \leq (1-|B_{1}|)$
\end{enumerate}
satisfied, then   $L(f) \in H + \bar G \in C_{\hat{H}}.$  \end{theorem}
\begin{proof}
    Let $f =h + \bar g$ and $L(f)=H +\bar G, B_{1} \neq 0,$. $h,g$ and $H,G$ given by equation \eqref{eqharmonic} and \eqref{eqHarmonic} respectively.  We have to prove that $L(f) = H + \bar{G} \in C_{\hat{H}}$.   Since $H$ and $G$ are analytic function, it can be noted that $H^{\prime}(0)=1 >|B_{1}|=|G^{\prime}(0)|.$\\ 
    Suppose that $\frac{H+\epsilon G}{1+\epsilon B_{1}} =z + \sum_{n=2}^{\infty} nt_{n},$
where
$$t_{n}=\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})(1+\epsilon B_{1})}+\epsilon\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})(1+\epsilon B_{1})},$$ for all $|\epsilon|=1.$ By taking lemma \ref{lem5} into the account, it is sufficient to show that $\sum_{n=2}^{\infty} nt_{n}\leq 1$ to get the required result.
Using condition $(i), |A_{n}|\leq \frac{1}{n}, |B_{n}|\leq \frac{1}{n}$  for all $n\geq 2$, we have
\begin{align*}
&\sum_{n=2}^{\infty} n t_{n}\leq\\
&  \left[\sum_{n=2}^{\infty}\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})(1-| B_{1}|)}+\epsilon\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})(1- |B_{1}|)}\right]\\
&\left[\sum_{n=1}^{\infty}\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n\delta_{1})(1-| B_{1}|)}+\epsilon\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})(1- |B_{1}|)}\right]\\
&=\frac{1}{(1-|B_{1}|)}[W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}(1)+W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}(1)-2]. 
\end{align*}
Follow by lemma \ref{lem3}, we obtain the desired outcome that $L(f)\in  C_{\hat{H}}. $
\end{proof}

In the next we investigate adequate condition which assure that a harmonic convex function map unit disk to $D$ into harmonic close-to-convex region.

\begin{theorem}
Let us consider $\beta_{1},\beta_{2}, \delta_{1}, \delta_{2}\geq 0$, $\alpha_{1},\alpha_{2}, \gamma_{1}, \gamma_{2}> 0$ and $|\sigma|<1$. Also suppose $f= h + \bar g \in  K_{\hat{H}^{o}}$ if the inequality
\begin{equation}\label{eq2}
[W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)+2W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime}(1)+ W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1)]\leq 4
\end{equation}
satisfied, then   $L(f) \in H + \bar G \in C_{\hat{H}}.$    \end{theorem}
\begin{proof}
By given assumption $f =h + \bar g \in K_{\hat{H}^{o}}$ and $L(f)=H +\bar G, B_{1} = 0,$ where $h,g$ and $H,G$ given by equation \eqref{eqharmonic} and \eqref{eqHarmonic} respectively.  Since $H$ and $G$ are analytic function, it can be noted that $H^{\prime}(0)=1 >|B_{1}|=|G^{\prime}(0)|.$ 
    In view of lemma \ref{lem3}, it suffices to prove that  $H+\epsilon G =z + \sum_{n=2}^{\infty} nt_{n} \in C_{\hat{H}},$
where
$$t_{n}=\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})(1+\epsilon B_{1})}+\epsilon\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})(1+\epsilon B_{1})},$$ for all $|\epsilon|=1.$ With the help of  lemma \ref{lem5}, it is adequate to prove that $\sum_{n=2}^{\infty} nt_{n}\leq 1$ to get the required outcome.
Employing lemma \ref{lem4}, \begin{align*}
    |A_{n}|\leq \frac{n+1}{2}, |B_{n}|\leq \frac{n-1}{2} \quad \forall \quad n\geq 2,
    \end{align*}we have
\begin{align*}
&\sum_{n=2}^{\infty} n t_{n}\leq\\
&  \frac{1}{2}\left[\sum_{n=1}^{\infty}\frac{(n+1)(n+2)\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}+\epsilon\frac{n(n+1) \Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}\right]\\
&\leq \frac{1}{2}\left[\sum_{n=1}^{\infty}\frac{n(n+1)\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}+\frac{2(n+1)\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}+\epsilon\frac{n(n+1) \Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}\right]\\
&=\frac{1}{2}[W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)+2W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime}(1)-2+\epsilon W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1)]. 
\end{align*}
Follow by asserted condition of theorem, we establish the result that $L(f)\in  C_{\hat{H}}. $
\end{proof}



\begin{theorem}\label{thm9}
Suppose that $\beta_{1},\beta_{2}, \delta_{1}, \delta_{2}\geq 0$, $\alpha_{1},\alpha_{2}, \gamma_{1}, \gamma_{2}> 0$ and $|\sigma|<1$. Also assume $f=h + \bar g \in C_{\hat{H}^{o}}(S_{\hat{H}^{o}} or T_{\hat{H}^{o}})$ if the inequality
\begin{align*}\label{eq2}
&2W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime\prime}(1)+9W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)+6(W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime}(1)-1)+ W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime\prime}(1)\\
&+3 W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1)\leq 6
\end{align*}
satisfied, then   $L(f) = H + \bar G \in C_{\hat{H}^{o}}.$    \end{theorem}

\begin{proof}
    Consider $f=h + \bar g \in C_{\hat{H}^{o}}(S_{\hat{H}^{o}} or T_{\hat{H}^{o}})$, $L(f) = H + \bar G$, where $h,g$ and $H,G$ given by equation \eqref{eqharmonic} and \eqref{eqHarmonic} respectively. We have to show $L(f) \in C_{\hat{H}^{o}}.$ In view of lemma \ref{lem3}, it is enough to prove that  $H+\epsilon G =z + \sum_{n=2}^{\infty} nt_{n} \in C_{\hat{H}},$
where
$$t_{n}=\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}+\epsilon\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})},$$ for all $|\epsilon|=1.$ By taking lemma \ref{lem5} into the account, it is sufficient to show that $\sum_{n=2}^{\infty} nt_{n}\leq 1$ to get the required result.
Using lemma \ref{lem7}, 
\begin{align*}  
|A_{n}|\leq \frac{(2n+1)(n+1)}{6}, |B_{n}|\leq \frac{(2n-1)(n-1)}{6}  \quad \forall \quad n\geq 2,
\end{align*} we have
\begin{align*}
&\sum_{n=2}^{\infty} n t_{n}\leq\\
&\frac{1}{6}\sum_{n=2}^{\infty}  \left[\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})n(2n+1)(n+1)}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}+\epsilon\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})n(2n-1)(n-1)}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}\right]\\
& = \frac{1}{6}\left[\sum_{n=1}^{\infty}\frac{(n+1)(2n+3)(n+2)\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}+\epsilon\frac{n(n+1)(2n+1) \Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}\right]\\
&\leq \frac{1}{6}\left[\sum_{n=1}^{\infty}\frac{2n(n+1)(n-1)\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}+\frac{9n(n+1)\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}+\frac{6(n+1)\Gamma(\alpha_{1})\Gamma(\gamma_{1})}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}\right]\\
&+\frac{1}{6}\left[\left(\sum_{n=1}^{\infty}\frac{2n(n+1)(n-1) \Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}+\frac{3n(n+1) \Gamma(\alpha_{2})\Gamma(\gamma_{2})}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}\right)\right]\\
&=\frac{1}{6}[2W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime\prime}(1)+9W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)+6(W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime}(1)-1)+2 W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime\prime}(1)]\\
&+\frac{1}{2} W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1),
\end{align*}
Taking identities $(n+1)(2n+3)(n+2)=2n(n+1)(n-1)+9n(n+1)+6(n+1)$\\
$n(n+1)(2n+1)=2n(n+1)(n-1)+3n(n+1).$\\
Hence, proof is readily to follow by hypothesis of theorem statement.
\end{proof}

In the next result we investigate sufficient condition which enough that harmonic close-to-convex map the unit disk $D$ to harmonic close-to-convex region.

\begin{theorem}
Assume that $\beta_{1},\beta_{2}, \delta_{1}, \delta_{2}\geq 0$, $\alpha_{1},\alpha_{2}, \gamma_{1}, \gamma_{2}> 0$ and $|\sigma|<1$. Also let $f=h + \bar g \in C_{\hat{H}}$ if the following inequality hold
\begin{align*}
&=2W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime\prime}(1)+9W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)+6(W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime}(1)-1)\\
&+|B_{1|}|\left(2 W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime\prime}(1)]+ 3W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)\right)\\
&+2 W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime\prime}(1)+3 W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1)\\
&+|B_{1}|\left(2W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime\prime}(1)+9W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1)+6(W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime}(1)-1)\right)\leq 6(1-|B_{1}|),
\end{align*}
 then   $L(f) = H + \bar G \in C_{\hat{H}}.$    \end{theorem}

\begin{proof}
    Let $f=h + \bar g \in C_{\hat{H}}$, $L(f) = H + \bar G$, where $h,g$ and $H,G$ given by equation \eqref{eqharmonic} and \eqref{eqHarmonic} respectively. We have to prove $L(f) \in C_{\hat{H}}$, where G and H are analytic function in $D$ and $H^{\prime}(0)=1>|B_{1}|=|G^{\prime}(0)|$. In view of lemma \ref{lem3}, it is enough to prove that  $\frac{H+\epsilon G}{1+\epsilon B_{1}} =z + \sum_{n=2}^{\infty} nt_{n} \in C,$
where
$$t_{n}=\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})A_{n}}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})(1+\epsilon B_{1})}+\epsilon\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})B_{n}}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})(1+\epsilon B_{1})},$$ for all $|\epsilon|=1.$ By taking lemma \ref{lem5} into the account, it is enough to prove that $\sum_{n=2}^{\infty} nt_{n}\leq 1$ to get the stated outcome.
Using lemma \ref{lemclosetoconvex}, 
we get
\begin{align*}
&\sum_{n=2}^{\infty} n t_{n}\leq\\
&\frac{1}{6(1-|B_{1}|)}\sum_{n=2}^{\infty}  \left[\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})n(2n+1)(n+1)}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}+\frac{ \Gamma(\alpha_{1})\Gamma(\gamma_{1})n(2n-1)(n-1)|B_{1}|}{\Gamma(\alpha_{1}  +(n-1)\beta_{1})\Gamma(\gamma_{1}  +(n-1) \delta_{1})}\right]\\
&+\frac{1}{6(1-|B_{1}|)}\sum_{n=2}^{\infty}  \left[\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})n(2n-1)(n-1)}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}+\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})n(2n+1)(n+1)|B_{1}|}{\Gamma(\alpha_{2}  +(n-1)\beta_{2})\Gamma(\gamma_{2}  +(n-1) \delta_{2})}\right]\\
&=\frac{1}{6(1-|B_{1}|)}\sum_{n=1}^{\infty}  \left[\frac{\Gamma(\alpha_{1})\Gamma(\gamma_{1})(n+1)(2n+3)(n+2)}{\Gamma(\alpha_{1}  +n\beta_{1})\Gamma(\gamma_{1}  +n\delta_{1})}+\frac{ \Gamma(\alpha_{1})\Gamma(\gamma_{1})(n+1)(2n+1)n|B_{1}|}{\Gamma(\alpha_{1}  +n1\beta_{1})\Gamma(\gamma_{1}  +n \delta_{1})}\right]\\
&+\frac{1}{6(1-|B_{1}|)}\sum_{n=2}^{\infty}  \left[\frac{\Gamma(\alpha_{2})\Gamma(\gamma_{2})(n+1)(2n+1)n}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}+\frac{ \Gamma(\alpha_{2})\Gamma(\gamma_{2})(n+1)(2n+3)(n+2)|B_{1}|}{\Gamma(\alpha_{2}  +n\beta_{2})\Gamma(\gamma_{2}  +n \delta_{2})}\right].
\end{align*}
In the similar manner of proof of theorem \ref{thm9}, we obtain
\begin{align*}
&=\frac{1}{6(1-|B_{1}|}[2W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime\prime}(1)+9W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)+6(W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime}(1)-1)\\
&+\frac{|B_{1|}}{6(1-|B_{1}|}\left(2 W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime\prime}(1)]+ 3W_{{(\alpha_{1}, \beta_{1})},({\gamma_{1}, \delta_{1}})}^{\prime\prime}(1)\right)\\
&+\frac{1}{6(1-|B_{1}|}(2 W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime\prime}(1)+3 W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1))\\
&+\frac{|B_{1}|}{6(1-|B_{1}|)}\left(2W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime\prime}(1)+9W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime\prime}(1)+6(W_{{(\alpha_{2}, \beta_{2})},({\gamma_{2}, \delta_{2}})}^{\prime}(1)-1)\right).
\end{align*}
Thus, by the asserted conditions of the theorem, desires result has been established.
\end{proof}


 \section{conclusion}\label{sec6}
 In this investigation, we have constructed a class of harmonic mappings involving with the four-parameter Wright functions and derived sufficient conditions under which these mappings exhibit significant geometric properties such as harmonic starlikeness and convexity. Additionally, we have explored the interrelation among various subclasses of harmonic close-to-convex mappings. The novel results presented herein not only extend existing work in the field but also offer a basics for further study and vital role in geometric function theory.
It is very well-known that Wright function $\mathbb{W}_{\alpha, \beta}(z)$ can be derived from $\mathcal{W}_{(\alpha, \beta), (\gamma,\delta)}(z)$ after substituting $\gamma=\delta=1$. Therefore, all the results derived such as harmonic starlikeness, convexity and harmonic close-to-convexity can be established for harmonic mapping associated with Wright function \eqref{eqwright}. Subsequently, it can be noted that,  consequences for all theorems can be obtained similar as corollary \ref{cor1} and remark \ref{reamrk1}.

