\coordinate [label={[font=\normalsize]left:3}] (3) at ({-.5*sqrt(3)-0.1},0,-.5);

\draw[fill=bblue,fill opacity=.5] (2)--(1)--(0)--cycle;
\draw[fill=mediumpurple,fill opacity=.5] (3)--(2)--(0)--cycle;
