We are now prepared to prove Theorem \ref{disc}.  With the lemmas from the previous section in hand, the proof is relatively straightforward.

\begin{proof}
Suppose that $u$ is a solution; we first verify that no two indifference segments intersect in $X$.  If two indifference curves \emph{do} intersect, Lemma \ref{triangle} yields a region $X_i$ sharing a boundary with only two adjacent regions, both of which intersect the lower right part of the boundary, and by Theorem \ref{between} and Lemma \ref{partition}, it must be adjacent to $X_{i-1}$ and $X_{i+1}$.  Lemmas \ref{case1}, \ref{case2} and \ref{case3} then yield a contradiction, and so we conclude that, indeed, we cannot have two indifference segments intersecting in $X$.  

It remains to show that this no intersection property implies nestedness.  We show this now. For this proof alone, closure is taken in $X$, rather than in $\mathbb{R}^m.$




    Let $i_0=\min\{p:\,\mu(X_p)>0\}.$ We have $X_{i_0}$ has only one adjacent region which is $X_{i_0+1}.$  Hence, $X_=^N(z_{i_0},k_{i_0})$ is the indifference segment between $X_{i_0}$ and $X_{i_0+1}$  for some $k_{i_0}.$ By construction, we have $\nu=Du_{\#}\mu,$ meaning  $\nu(z_{i_0})=\mu(X_{i_0}).$ As $X_{i_0}$ is adjacent to $X_{i_0+1},$ there exists $\beta\in[0,1]$ such that $\frac{\partial}{\partial x_1}u(x_1,\beta)$ increases from $y_{i_0}$ to $y_{i_0+1}$ which means $X_{i_0}=X^N_\le(z_{i_0},k_{i_0})$ and hence $k_{i_0}=k^N(z_{i_0}).$ Also, for some $k_{i_0+1}$ the set $X^N_=(z_{i_0+1},k_{i_0+1})$ is the boundary between $X_{i_0+1}$ and $X_{i_0+2}$ and it does not intersect with $X^N_=(z_{i_0},k^N(z_{i_0}))$ in $X.$ Then, $\overline{X_{i_0}\cup X_{i_0+1}}=X^N_\le(z_{i_0+1},k_{i_0+1})$ and $\mu(X_{i_0}\cup X_{i_0+1})=\mu(X^N_\le(z_{i_0+1},k_{i_0+1}))$  and by construction we get 
    \[\nu(\{z_{i_0},z_{i_0+1}\})=\mu(X_{i_0})+\mu(X_{i_0+1})=\mu(X^N_\le(z_{i_0+1},k_{i_0+1}))\] and we get $k_{i_0+1}=k^N(z_{i_0+1}).$

    Proceeding inductively, we get $\overline{\cup_{k=0}^iX_k}= \overline{X^N_\le(z_{i-1},k^N(z_{i-1}))\cup X_{i}}=X^N_\le(z_i,k_i)$ where $X^N_=(z_i,k_i)$ is the boundary between $X_i$ and $X_{i+1}.$ Then 
\[\nu_N(\{z_p:\,0\le p\le i\})=\sum_{k=0}^{i}\mu(X_k)=\mu(X^N_\le(z_{i-1},k^N(z_{i-1})))+\mu(X_{i})=\mu(X^N_\le(z_{i},k_i))\]
and so $k_i=k^N(z_i).$

 Therefore, \[X^N_\le(z_{i},k^N(z_{i}))\subset \overline{\cup_{k=0}^{j-1}X_k}\cup X_j\subseteq X_<(z_{j},k^N(z_{j}))\] for all $i<j$ such that $\mu(X_i),\mu(X_j)>0,$ which implies discrete nestedness of the solution.   
\end{proof}


Next is the proof of Lemma \ref{conv}.
\begin{proof}
As the sequence of measures $(\nu_N) :=((Du_N)_\#\mu)$ corresponding to the solutions $u_N$ of the monopolist's problem with data $(\mu, Y_N,c),$ all have support within the compact set $Y$, there exists a weak-convergent subsequence $\nu_N\to\nu$ for some probability measure $\nu$ on $Y$.
%{\color{red}BP: Do we have a reference for these assertions?}
From the stability of the optimal transport problem  $(\mu,\nu_N)$ with surplus $b(x,y)=x\cdot y$ \cite{Santambrogio}, we get that the corresponding payoff $u_N$ and pricing functions $v_N$ converges uniformly to $u$ and $v$ respectively, the corresponding payoff and pricing functions of the optimal transport problem with marginals $(\mu, \nu)$ (that is, solution to the dual problem \eqref{eqn: OT dual}). Also, we conclude that
\[\mathcal{W}_b(\mu,\nu_N):=\int_X b(x,Du_N(x))d\mu(x)\to \mathcal{W}_b(\mu,\nu)=\int_X b(x,Du(x))d\mu(x).\]

And from the uniform convergence of $(u_N)$ we get that
\[\int_X u_Nd\mu\to\int_X u d\mu.\]

Also, from the weak convergence of $\nu_N,$ we deduce that
\[\int_X c(Du_N)d\mu=\int_Yc(y)d\nu_N\to \int_Y c(y)d\nu=\int_X c(Du)d\mu.\]
Hence,
\[\mathcal{P}(u_N)\to\mathcal{P}(u).\]

Let $\overline{\nu}=D\overline u_\#\mu$ be the corresponding measure of the solution $\overline{u}$ of the monopolist's problem \eqref{PA} with data $(\mu,Y,c).$ There exists a sequence of discrete measures $\overline{\nu}_N$ such that for all $N$ the atoms belongs to $Y_N,$ and $\overline{\nu}_N\to\overline{\nu}.$ Similar to the previous argument we get that $\mathcal{P}(\overline{u}_N)\to\mathcal{P}(\overline{u}),$ where $\overline{u}_N$ are the corresponding payoffs for the optimal transport problem $(\mu,\overline{\nu}_N).$ Hence, \[\mathcal{P}(\overline{u})=\lim_{N\to\infty}\mathcal{P}(\overline{u}_N)\le\lim_{N\to\infty}\mathcal{P}(u_N)=\mathcal{P}(u)\le\mathcal{P}(\overline{u}).\]
Therefore, $u$ is a solution for the monopolist's problem \eqref{PA} with data $(\mu,Y,c).$
\end{proof}
We now prove Lemma \ref{noatoms}.
\begin{proof}
    Let $\underline{z}=(\underline{y},F(\underline{y})),\overline{z}=(\overline{y },F(\overline{y}))\in Y$ such that $\underline{y}<
\overline{y},$ and $\underline{z}$ and $\overline{z}$ are not  atoms with respect to $\nu.$ We denote by $[(r,F(r)),(s,F(s))]=\{(y,F(y))\in Y:\, r\le y\le s\}$ and similarly $[(r,F(r)),(s,F(s)))=\{(y,F(y))\in Y:\, r\le y< s\}.$ Hence,\[\begin{array}{ll}\limsup_{N\to\infty}\nu_N([0,\underline{z}])\le\nu([0,\underline{z}])&=\nu([0,\underline{z}))\\
&\le\liminf_{N\to \infty}\nu_N([0,\underline{z}))\\
&\le \limsup_{N\to \infty}\nu_N([0,\underline{z}))\le\limsup_{N\to\infty}\nu_N([0,\underline{z}]),
\end{array}\]
    where the first and second inequalities comes from the definition of weak-convergence as $[0,\underline{z}]$ and $[0,\underline{z})$ are relatively closed and open in $Y$ respectively, and the equality comes from the fact that $\underline{z}$ is not an atom. Similarly for $\overline{z}$ we get 
%    \[\begin{array}{ll}\limsup_{N\to\infty}\nu_N([0,\overline{z}])=\nu([0,\overline{z}])=\nu([0,\overline{z}))=\liminf_{N\to \infty}\nu_N([0,\overline{z}))= \limsup_{N\to \infty}\nu_N([0,\overline{z}))=\limsup_{N\to\infty}\nu_N([0,\overline{z}]).\end{array}\]
\[\lim_{N\to\infty}\nu_N([0,\overline{z}])=\nu([0,\overline{z}])=\nu([0,\overline{z})).\]
    Let  $z_i^N=(y_i^N,F(y_i^N))\in Y_N\,$ and $z_j^N=(y_j^N,F(y_j^N))\in Y_N$  where for each $N,\,  i=\min\{k\,:\,y_k^N\in[\underline{y},\overline{y}) \}$ and $\,j=\max\{k\,:\,y_k^N\in[\underline{y},\overline{y}) \}$ and $y^N_p<y^N_{p+1}.$     

Note that $z_i^N\to \underline{z},$  $z_j^N \to \overline{z},$  $\frac{F(y_{i}^N)-F(y_{i-1}^N)}{y_{i}^N-y_{i-1}^N}\to F'(\underline{y})$ and $\frac{F(y_{j+1}^N)-F(y_j^N)}{y_{j+1}^N-y_j^N}\to F'(\overline{y})$. 

\hspace{-6pt}Consider the upper points of intersection 
\[d_N\in \overline{X_=^N(z_{i-1}^N,k^N(z_{i-1}^N))}\cap \big(\{0\} \times [0,1] \cup[0,1] \times \{1\}\big).\] There exists a convergent subsequence of $(d_N)$ that converges to $d\in\partial X.$ We consider the set $D=X_<(\underline{z},d\cdot(1,F'(\underline{y})))=\Big\{x\in X:\, (x-d)\cdot(1,F'(\underline{y}))<0\Big\}.$ We  claim that $\mu(D)=\nu([0,\underline{z}]).$ 

Suppose that $\mu(D)<\nu([0,\underline{z}])=\mu(X_\le(\underline{z},k(\underline{z}))),$ then $X_=(\underline{z},d\cdot(1,F'(\underline{y})))\subset X_<(\underline{z},k(\underline{z})).$ Let $d_{\underline{z}}$ be the upper intersection in $\overline{X_=(\underline{z},k(\underline{z}))}\cap \partial X,$ so $d\neq d_{\underline{z}}.$ We claim that there exists $\varepsilon>0$ such that $X^N_\le(z_{i-1}^N,k^N(z_{i-1}^N))\subset X_<(\underline{z},k(\underline{z})-\varepsilon)$ for all $N$ large enough. As $d\in \overline{X_<(\underline{z},k(\underline{z}))}\setminus X_=(\underline{z},k(\underline{z}))$ we get $(d_{\underline{z}}-d)\cdot(1,F'(\underline{y}))>0$ and we  take $0<\varepsilon<(d_{\underline{z}}-d)\cdot(1,F'(\underline{y})),$ then for $x\in X^N_\le(z_{i-1}^N,k^N(z_{i-1}^N)),$ we have 
\[(x-d_N)\cdot\Big(1,\frac{F(y_{i}^N)-F(y_{i-1}^N)}{y_{i}^N-y_{i-1}^N}\Big)\le0.\]
Knowing that $k(\underline{z})=d_{\underline{z}}\cdot(1,F'(\underline{y}))$ we get
\[\begin{array}{ll}\hspace{-0.2cm}
&x\cdot(1,F'(\underline{y}))-k(\underline{z})+\varepsilon\vspace{3pt}\\
&=(x-d_{\underline{z}})\cdot (1,F'(\underline{y}))+\varepsilon \vspace{3pt}\\
&=(x-d_N)\cdot(1,F'(\underline{y}))+(d_N-d_{\underline{z}})\cdot(1,F'(\underline{y}))+\varepsilon\vspace{3pt}\\
