&\le (x-d_N)\cdot\Big(1,\frac{F(y_{i}^N)-F(y_{i-1}^N)}{y_{i}^N-y_{i-1}^N}\Big)+(1,1)\cdot\Big((1,F'(\underline{y}))
-\Big(1,\frac{F(y_{i}^N)-F(y_{i-1}^N)}{y_{i}^N-y_{i-1}^N}\Big)\Big)\vspace{3pt}\\
&\quad+(d_N-d)\cdot(1,F'(\underline{y}))+(d-d_{\underline{z}})\cdot(1,F'(\underline{y}))+\varepsilon<0
\end{array}\]

where the second and third terms go to zero and the first is non-positive and the fourth term $(d-d_{\underline{z}})\cdot(1,F'(\underline{y}))+\varepsilon$ is negative by the choice of $\varepsilon.$ Therefore, for large enough $N,$ 
we have $x\cdot(1,F'(\underline{y}))-k(\underline{z})+\varepsilon<0$ and then $x\in X_<(\underline{z},k(\underline{z})-\varepsilon) $ which proves our claim. As $f\ge\alpha>0,$ we have 
\[\begin{array}{ll}
\mu(X_\le(\underline{z},k(\underline{z})))-\mu(X^N_\le(z_{i-1}^N,k^N(z_{i-1}^N)))&=\mu(X_\le(\underline{z},k(\underline{z}))\setminus X^N_\le(z_{i-1}^N,k^N(z_{i-1}^N)))\\
&\ge\mu(X_\le(\underline{z},k(\underline{z}))\setminus X_<(\underline{z},k(\underline{z})-\varepsilon))>0\end{array}\] as $X^N_\le(z_{i-1}^N,k^N(z_{i-1}^N))\subset X_<(\underline{z},k(\underline{z})-\varepsilon)\subset X_\le(\underline{z},k(\underline{z})).$ Hence, \[\lim_{N\to\infty}\mu(X_\le(\underline{z},k(\underline{z})))-\mu(X^N_\le(z_{i-1}^N,k^N(z_{i-1}^N)))>0.\] But, 
\[\lim_{N\to\infty}\mu(X_\le(\underline{z},k(\underline{z})))-\mu(X^N_\le(z_{i-1}^N,k^N(z_{i-1}^N)))=\lim_{N\to\infty}\nu([0,\underline{z}])-\nu_N([0,\underline{z}])=0\] which is a contradiction. Using a similar argument we can prove that $\mu(D)$ cannot be bigger than $\nu([0,\underline{z}]),$ which implies $\mu(D)=\nu([0,\underline{z}]).$  This establishes the claim.









Since $\mu(D)=\lim_{N\to\infty}\nu_N([0,{\underline{z}}])=\nu([0,{\underline{z}}]),$ we get $D=X_<({\underline{z}},k({\underline{z}}))$ and then $\partial D\cap X=X_=(\underline{z},k(\underline{z})).$ Similarly, we can prove that  $E=X_<(\overline{z},k(\overline{z}))$ where $E=\{x\in X:\, (x-e)\cdot(1,F'(\overline{y}))<0\}$ such that $e$ is the limit of a subsequence $(e_N)$ and $e_N\in \overline{X_=^N(z_j^N,k^N(z_j^N))}\cap(\{0\}\times [0,1]\cup [0,1]\times\{1\}).$

Since $(\mu,\nu_N)$ is discretely nested, each point $ x_N \in \mathbb{R}^2 \setminus X $ is the unique intersection of the lines $ X_=^N(z_i^N, k^N(z_i^N)) $ and $ X_=^N(z_j^N, k^N(z_j^N)) $, and hence satisfies the linear system
\begin{equation}\label{eq3}
