&\quad-\int_{r_i}^1 f_{x_1x_1}\Big(t_i+(1-x_2)\frac{F(y_{i+1})-F(y_{i})}{y_{i+1}-y_{i}},x_2\Big)dx_2\Bigg)>0\vspace{3pt}\\




