\title{New properties of weighted generalized core-EP inverse in Banach algebras}

\author{Huanyin Chen}
\author{Marjan Sheibani}
\address{School of Big Data, Fuzhou University of International Studies and Trade, Fuzhou 350202, China}
\email{<huanyinchenfz@163.com>}
