=&\overline{\bigg(\frac{\int D\phi\,O_1 e^{-\mathcal{S}[\{h(x)\}]}}{\int D\phi\,e^{-\mathcal{S}[\{h(x)\}]}}\bigg)^N \bigg(\frac{\int D\phi\,O_2e^{-\mathcal{S}[\{h(x)\}]}}{\int D\phi\,e^{-\mathcal{S}[\{h(x)\}]}}\bigg)^M}\\
    =&\frac{1}{Z_*}\int Dh \int D\phi e^{-\int_x \frac{h^2}{4\Delta}-\mathcal{S}[\{h(x)\}]}\bigg[\bigg(\frac{\int D\phi\,O_1 e^{-\mathcal{S}[\{h(x)\}]}}{\int D\phi\,e^{-\mathcal{S}[\{h(x)\}]}}\bigg)^N\nonumber\\
    &\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\;\times\bigg(\frac{\int D\phi\,O_2 e^{-\mathcal{S}[\{h(x)\}]}}{\int D\phi\,e^{-\mathcal{S}[\{h(x)\}]}}\bigg)^M\bigg].    
\end{align}
Then using the replica trick, which involves essentially tracing back the steps from Eq. \ref{EqReversingToRamdomnessLastStep} to \ref{EqReversingToRamdomnessFirstStep}, one can see that the correlation function in the above equation can be written as
\begin{align}
    &\overline{\langle O_1\rangle_{\{h\}}^N\langle O_2\rangle_{\{h\}}^M}=
    \nonumber
    \\
    =&\frac{1}{Z_*}\int Dh e^{-\int_x \frac{h^2}{4\Delta}}\bigg[\Big(\int D\phi e^{-\mathcal{S}[\{h(x)\}]}\Big)^{1-N-M}\times\nonumber\\
    &\;\;\;\;\;\;\;\times\Big({\int D\phi\,O_1 e^{-\mathcal{S}[\{h(x)\}]}}\Big)^N\Big({\int D\phi\,O_2 e^{-\mathcal{S}[\{h(x)\}]}}\Big)^M\bigg]  \\
   =&\frac{1}{Z_*}\lim_{R\rightarrow1}\int Dh e^{-\int_x \frac{h^2}{4\Delta}}\bigg[\Big(\int D\phi e^{-\mathcal{S}[\{h(x)\}]}\Big)^{R-N-M}\times\nonumber\\
    &\;\;\;\;\;\;\;\times\Big({\int D\phi\,O_1 e^{-\mathcal{S}[\{h(x)\}]}}\Big)^N\Big({\int D\phi\,O_2 e^{-\mathcal{S}[\{h(x)\}]}}\Big)^M\bigg]  \\
    =&\frac{1}{Z_*}\lim_{R\rightarrow1}\int \prod_{a=1}^{R} D\phi^{(a)} O_1^{(1)}\dots O_1^{(N)}O_2^{(1)}\dots O_2^{(M)}e^{-\mathbb{S}}\label{EqCorrelationInReplicaTheory},
\end{align}
where $\mathbb{S}$ is precisely the replica action given in Eq. \ref{EqDisorderReplicaAction}, and 
{the fields $O_{1}^{(a)}$ and $O_2^{(a)}$ denote the copies of fields $O_1$ and $O_2$, respectively, in replica copy $a$.}\par
For the purpose of our discussion, we will write Eq. \ref{EqCorrelationInReplicaTheory} in the following form
\begin{align}
    &\overline{\langle O_1\rangle_{\{h\}}^N\langle O_2\rangle_{\{h\}}^M}=\nonumber\\&\lim_{R\rightarrow1}\frac{Z_{R}}{Z_*}\times \frac{\int \prod_{a=1}^{R} D\phi^{(a)} O_1^{(1)}\dots O_1^{(N)}O_2^{(1)}\dots O_2^{(M)}e^{-\mathbb{S}}}{\int \prod_{a=1}^{R} D\phi^{(a)} e^{-\mathbb{S}}},
\end{align}
where $Z_{R}=\int \prod_{a=1}^{R} D\phi^{(a)} e^{-\mathbb{S}}$ is the partition function of the replica theory
{(Eq.~\ref{EqReversingToRamdomnessFirstStep}, 
where $\mathbb{S}$ is defined in Eq. \ref{EqDisorderReplicaAction})}
and $Z_*=\int D\phi \,e^{-S_{*}}$ is the partition function of the unperturbed CFT $S_{*}$.
