\section{Formulas Used in Preprocessing}
\label{sec:apx:preprocessing_formulas}

The following formulas were used to derive engineered features during preprocessing. These transformations aim to capture temporal trends, volatility, and relative price positioning across product categories.

\begin{table}[H]
\centering
\renewcommand{\arraystretch}{1.6}
\small
\begin{tabular}{|p{3.7cm}|p{4.5cm}|p{8cm}|}
\hline
\textbf{Feature} & \textbf{Formula} & \textbf{Interpretation} \\
\hline

\textbf{Quantity Rolling Mean (QRM)} &
$\displaystyle \text{QRM}_k(t) = \frac{1}{k} \sum_{i=1}^{k} Q_{t - i}$ &
Captures average quantity sold over the previous $k$ weeks, used for lag-based demand modeling. \\

\hline
\textbf{Trend Indicator} &
$\displaystyle \text{Trend}_t = \text{QRM}_4(t) - \text{QRM}_2(t)$ &
Compares medium-term vs short-term average demand to measure directional change. \\

\hline
\textbf{Acceleration} &
$\displaystyle \text{Acceleration}_t = Q_{t-1} - \text{QRM}_2(t)$ &
Measures deviation from short-term average, capturing momentum. \\

\hline
\textbf{Volatility (Rolling Std. Dev.)} &
$\displaystyle \text{Volatility}_t = \sqrt{ \frac{1}{k} \sum_{i=1}^{k} (Q_{t - i} - \bar{Q})^2 }$ &
Estimates fluctuation in recent weekly demand. \\

\hline
\textbf{Price vs Category Average (PVC)} &
$\displaystyle \text{PVC}_{Avg} = \frac{\text{Price}}{\mathbb{E}[\text{Price}_{\text{cluster}}]}$ &
Measures a product's price relative to the average of its semantic cluster (e.g., mugs). \\

\hline
\end{tabular}
\caption{Derived feature formulas used in the preprocessing pipeline.}
\label{tab:preprocessing_formulas}
\end{table}

\noindent
\textbf{Variable Definitions:} $Q_{t-i}$ denotes the quantity sold $i$ weeks before week $t$; $\bar{Q}$ is the mean quantity over the last $k$ weeks; $\mathbb{E}[\text{Price}_{\text{cluster}}]$ refers to the average price of all products within a semantically clustered product group (e.g., mugs, candles); and $\text{Price}$ is the observed price of the product.

\clearpage

\section{Evaluation Metrics Formulas}
\label{sec:apx:evaluation_metrics}

The following table formally defines the evaluation metrics used to assess MARL agent performance in dynamic pricing environments.

\begin{table}[H]
\centering
\renewcommand{\arraystretch}{1.5}
\small
\begin{tabular}{|p{4cm}|p{5cm}|p{8cm}|}
\hline
\textbf{Metric} & \textbf{Formula} & \textbf{Interpretation} \\
\hline

\textbf{Revenue per Agent} &
$\displaystyle R_{agent} = \sum_{t=1}^{T} P_t \cdot Q_t$ &
Total revenue accumulated by an agent over $T$ time steps, where $P_t$ is the price and $Q_t$ is the sold quantity at week $t$. \\

% \hline
% \textbf{Price Stability} &
% $\displaystyle CV_{price} = \frac{\sigma_P}{\mu_P}$ &
% Coefficient of variation of price series, indicating pricing consistency. Lower values signify higher stability. \\

\hline
\textbf{Nash Equilibrium Proximity} &
$\displaystyle \Delta NE = 1 - \min\left(1, \overline{\Delta P} \cdot 10\right)$ &
Measures average absolute price change ratio over recent periods. Closer to 1 implies proximity to equilibrium. \\

\hline
\textbf{Optimality Gap} &
$\displaystyle \text{Gap} = \frac{R_{max} - R_{agent}}{R_{max}}$ &
Relative performance gap between an agent’s revenue and the observed maximum. Lower is better. \\

% \hline
% \textbf{Price-Revenue Elasticity} &
% $\displaystyle \varepsilon = \frac{\Delta R / R}{\Delta P / P}$ &
% Correlation of revenue changes with price changes, reflecting demand responsiveness. \\

\hline
\textbf{Gini Coefficient} &
$\displaystyle Gini = \frac{\sum_{i=1}^{N} \sum_{j=1}^{N} |R_i - R_j|}{2N \sum_{i=1}^{N} R_i}$ &
Measures inequality in revenue distribution across agents. A value of 0 indicates perfect equality; values approaching 1 reflect higher inequality. \\

\hline
\textbf{Social Welfare} &
$\displaystyle SW = \sum_{i=1}^{N} R_i \cdot (1 - Gini)$ &
Aggregate market revenue adjusted by fairness (Gini coefficient), rewarding both efficiency and equity. \\

\hline
\textbf{Jain’s Fairness Index} &
$\displaystyle J = \frac{(\sum_{i=1}^{N} R_i)^2}{N \cdot \sum_{i=1}^{N} R_i^2}$ &
Evaluates fairness of revenue distribution across agents, ranging from $1/N$ (worst) to $1$ (best). \\

\hline
\textbf{Market Share Evolution} &
$\displaystyle MS_{i,t} = \frac{R_{i,t}}{\sum_{j=1}^{N} R_{j,t}}$ &
Agent $i$’s share of total market revenue at time $t$. Tracks competitive dynamics. \\

\hline
\textbf{Price Volatility} &
$\displaystyle \text{MeanAbsChange} = \frac{1}{T} \sum_{t=2}^{T} |\frac{P_t - P_{t-1}}{P_{t-1}}|$ &
Mean absolute price change over time, complemented by standard deviation and max change per agent-product pair. \\

% \hline
% \textbf{Strategic Diversity} &
% $\displaystyle \text{DiversityAgent} = \overline{\sigma(\Delta P_{products})}$ &
% Average standard deviation of week-to-week price changes across products within an agent’s portfolio. Higher values indicate more diverse pricing strategies. \\

\hline
\textbf{Price Convergence} &
$\displaystyle \text{Convergence} = 1 - \frac{\sigma_P}{\max(P)}$ &
Measures how closely agent prices align in the final simulation period. A value close to 1 indicates strong convergence (low price dispersion), while values near 0 indicate significant divergence in pricing strategies. \\

\hline
\textbf{Adjustment Magnitude} &
$\displaystyle \text{AdjMag} = \frac{1}{T{-}1} \sum_{t=2}^{T} \left| \frac{P_t - P_{t-1}}{P_{t-1}} \right|$ &
Mean absolute percentage change in price between consecutive weeks. Captures how intensely agents adjust their prices over time. \\

\hline
\textbf{Adjustment Frequency} &
$\displaystyle \text{AdjFreq} = \frac{1}{T{-}1} \sum_{t=2}^{T} \mathbb{1}\left[ \left| \frac{P_t - P_{t-1}}{P_{t-1}} \right| > \tau \right]$ &
Proportion of weeks with a price change exceeding 1\% ($\tau = 0.01$). Reflects how frequently agents make meaningful pricing updates. \\

\hline
\end{tabular}
\caption{Evaluation metric formulas used for performance assessment of MARL agents.}
\label{tab:evaluation_metrics_formulas}
\end{table}

\noindent
\textbf{Variable Definitions:}
\begin{itemize}
\item $P_t$: Price set by the agent at time step $t$.
\item $Q_t$: Quantity sold by the agent at time step $t$.
\item $R_{i}$: Revenue of agent $i$ over the evaluation period.
\item $R_{i,t}$: Revenue of agent $i$ at time step $t$.
\item $R_{max}$: Maximum observed revenue achieved by any agent in the experiment.
\item $\mu_P$: Mean of the price series over time.
\item $\sigma_P$: Standard deviation of the price series over time.
\item $\overline{\Delta P}$: Average absolute percentage change in price between consecutive time steps.
\item $R_j$: Revenue of agent $j$ over the evaluation period (paired comparison with $R_i$ for Gini calculation).
\item $\Delta R$, $\Delta P$: Changes in revenue and price between consecutive periods or episodes.
\item $N$: Total number of competing agents in the simulation.
% \item $\text{MeanAbsChange}$: Average absolute price change rate between consecutive time steps.
\item $\sigma(\Delta P_{products})$: Standard deviation of price changes across an agent’s product portfolio.
\item $\mathbb{1}[\cdot]$: Indicator function that equals 1 if the condition is true and 0 otherwise.
\item $\tau$: Threshold for detecting significant price changes, set to 0.01 (i.e., 1\%).
\end{itemize}

