\section{Critical driving potential for NESS}

Here we derive an analytical expression for the critical driving potential $\mu_{\text{crit}}$ required for a living circuit to sustain a non-equilibrium steady state (NESS). This threshold marks a first-order phase transition between network collapse and functional self-organization.

\label{critmuappendix}

First, consider a 3-cycle where the per capita dissipation along any edge—for instance, the edge connecting nodes 
$1$ and $2$—must be strictly positive for that edge to persist, i.e., 
% We first consider the limit where all edge conductances $\Lambda_{ij}$ are small but equal ($\Lambda_{ij} = \varepsilon \ll 1$). In this limit, the right-hand side of equation (2) in the main text must be positive for a NESS to exist:
\begin{equation}
\frac{\Lambda_{13}\Lambda_{23}}{B}(e^{\mu} - 1)k_{21}k_{13}k_{32} \log A - \sigma_{\text{maint}} > 0,
\end{equation}
%
where 
$$ A = \frac{k_{12}e^{\mu}(\Lambda_{23}\Lambda_{13} k_{23}W_{31} + \Lambda_{13}\Lambda_{12} k_{13}k_{21} + \Lambda_{23}\Lambda_{12} k_{23}k_{21})}{k_{21}(\Lambda_{13}\Lambda_{12} k_{13}k_{12} + \Lambda_{13}\Lambda_{23} k_{13}k_{32} + \Lambda_{12}\Lambda_{23} k_{12}k_{23})} $$
and 
\begin{eqnarray} B &=&\Lambda_{13}\Lambda_{12} k_{13}k_{12}e^{\mu} + \Lambda_{13}\Lambda_{23} k_{13}k_{32} + \Lambda_{12}\Lambda_{23} k_{12}k_{23}e^{\mu}  \nonumber \\ & & + \Lambda_{23}\Lambda_{13} k_{23}k_{31} + \Lambda_{13}\Lambda_{12} k_{13}k_{21} + \Lambda_{23}\Lambda_{12} k_{23}k_{21} \nonumber \\ & & + \Lambda_{23}\Lambda_{13} k_{32}k_{31}  + \Lambda_{23}\Lambda_{12} k_{32}k_{21} + \Lambda_{12}\Lambda_{13} k_{31}k_{12}e^{\mu}  \, .\nonumber
\end{eqnarray}

Since all terms in the above expression are homogeneous of the same order in the $\Lambda'$s in both the numerator and the denominator, the dynamics on any simplex of edge conductances can be rescaled and mapped onto the unit simplex (see Appendix \ref{Methods}). In particular, approaching the extinction of an edge - e.g., when $\Lambda_{12} = \varepsilon \to 0$ - implies that the conductances of the remaining two edges remain finite and non-zero. Therefore, near extinction, the edge dissipation is 
\begin{equation}
\frac{1}{B_{0}}(e^{\mu} - 1)k_{21}k_{13}k_{32} \log A_{0} - \sigma_{\text{maint}} > 0
\end{equation}
% \begin{equation}
% B = \varepsilon^2 B_0
% \end{equation}
where $B_0$ and $A_{0}$ is independent of $\Lambda's$:
\begin{align}
B_0 &= (k_{13}k_{32} + k_{23}k_{31} +  k_{32}k_{31} )
\end{align}
and 
$$
 A_{0} = e^{\mu}\frac{k_{12} k_{23}k_{31}}{k_{21}k_{13}k_{32}} = e^{\mu} .
$$

% Similarly, the quantity $A$ becomes independent of $\varepsilon$.

% The inequality simplifies to:

% \begin{equation}
% \frac{\varepsilon^2}{\varepsilon^2 B_0}(e^{\mu} - 1)k_{21}k_{13}k_{32} \log A - \sigma > 0
% \end{equation}

As $\mu$ increases, the first term grows, eventually balancing $\sigma_{\text{maint}}$ at the critical point:

\begin{equation}
\frac{1}{B_0}(e^{\mu_{\text{crit}}} - 1)k_{21}k_{13}k_{32} \log A_{0} = \sigma_{\text{maint}}
\end{equation}

This implies:

\begin{equation}
\big(e^{\mu_{\text{crit}}}-1\big)\mu_{\text{crit}} \approx \frac{\sigma_{\text{maint}} B_0}{k_{21}k_{13}k_{32}}
\end{equation}
 This critical value is independent of $\varepsilon$, confirming that the threshold for maintaining a NESS depends only on the network's kinetics and topology, not on the absolute magnitude of the conductances when they are all scaled equally. 
 % Thus, the critical driving potential depends on $\sigma_{\text{maint}}$ and $$

% \begin{equation}
% \mu_{\text{crit}} \approx \log\left(1+\frac{\sigma_{\text{maint}}}{\chi(k )}\right)
% \end{equation}
% where $\chi(k) = \frac{k_{21}k_{13}k_{32}}{B_0} $ represents an effective current that emerges from the network's kinetics and topology.

We can also extend this analysis to $N$-node cycles, where nodes are labeled $0, 1, 2, \ldots, N-1$ and edge $(N-1)-0$ couples to the external energy source. Following similar arguments, the critical driving potential for an N-node cycle is:

\begin{equation}
\big(e^{\mu_{\text{crit}}}-1\big)\mu_{\text{crit}} \approx \frac{\sigma_{\text{maint}}}{\chi_N(k)}
\end{equation}

where $\chi_N(k)$ is the emergent current for the N-node case:

\begin{equation}
\chi_N(k) = \frac{\prod_{i=0}^{N-1} k_{i,i+1}}{B_N}
\end{equation}

Here, $B_N$ is a generalized form of $B_0$ for N nodes:

\begin{equation}
B_N = \sum_{i,j} k_{ij}k_{ji} \cdot C_{ij}(e^{\mu})
\end{equation}

where $C_{ij}(e^{\mu})$ is either 1 or $e^{\mu}$ depending on whether the path from $i$ to $j$ includes the energy-coupled edge.

% Similarly, $A_N$ generalizes to:

% \begin{equation}
% A_N = \frac{k_{01}e^{\mu}\left(\sum_{\text{paths $P$ from 1 to 0}} \prod_{(i,j) \in P} k_{ij}\right)}{k_{10}\left(\sum_{\text{paths $P$ from 0 to 1}} \prod_{(i,j) \in P} k_{ij}\right)}
% \end{equation}

This general expression reveals a common feature: the critical driving potential $\mu_{\text{crit}}$ is inversely proportional to an emergent current $\chi_N$ that depends on both the topology and kinetics of the circuit, but is independent of the absolute magnitude of the edge conductances when they are all scaled equally.


\section{First-order phase transition at non-zero threshold in adaptive living circuits}
\label{1storderappendix}
The dynamics of living circuits, much like those of conventional electrical circuits, can be described as a random walk of electrons across the nodes of a bidirectional network:
\begin{equation}
\frac{dp_i}{dt} = \sum_j W_{ij} p_j \, ,
\end{equation}
where $W_{ij} $ denotes the transition rate from state $j \rightarrow i $. Unlike classical Markov processes, however, living circuits are characterized by adaptive transition rates—meaning $ W_{ij} $ is not fixed but evolves in time in response to the instantaneous probability distribution $ \vec{p} $ over the network:
\begin{equation}
\frac{dW_{ij}}{dt} = f(\vec{p}) \, .
\end{equation}
The function $f(\vec{p})$, which governs the adaptive dynamics, is context-dependent and can vary significantly depending on the underlying biological or physical scenario. One illustrative example is Hebbian learning, where synaptic connections between neurons strengthen in response to simultaneous activity, effectively allowing the network to adapt based on past stimuli.

In ecosystem-inspired circuit models, the transition rate decomposes as
$$
W_{ij} = \Lambda_{ij} k_{ij} \, ,
$$
where $k_{ij}$ is the baseline (static) transition rate between nodes $i$ and $j$, and $\Lambda_{ij}$ represents an adaptive factor—specifically, the abundance of a species that facilitates electron transitions across the $i$-$j$ edge. Since these species enhance conductance, $\Lambda_{ij}$ can be interpreted as the analog of edge conductance in electrical circuits. As these species harness the energy released during electron transitions to both sustain the structural machinery required for facilitation of electron transition and support their growth, the adaptive component or the edge conductance evolves as   

\begin{equation}
\ \frac{d\Lambda_{ij}}{dt} = \sigma_{ij}(\vec{p}, \textbf{W}) - \sigma_{\text{maint}}\Lambda_{ij}
\end{equation}
where:
\begin{equation}
    \sigma_{ij}(\vec{p}, \textbf{W}) = ( W_{ij} p_j - W_{ji} p_i) \log\left(\frac{W_{ij}p_j}{W_{ji}p_i}\right)
\end{equation} represents energy dissipation along the $ij$ edge, and $\sigma_{\text{maint}}$ is the minimum dissipation required to maintain the energy-harvesting structure. The need for a structural machinery and its associated cost imply:
\begin{itemize}
    \item The system requires a threshold amount of energy input to sustain non-equilibrium steady states. 
    \item  Any NESS must dissipate energy at least equal to the cost of maintaining the structural machinery i.e., NESS dissipating arbitrarily small energy cannot exist.
\end{itemize} To investigate these predictions, we consider the simplest possible nontrivial topology: a 3-cycle—three nodes connected in a loop with one species per edge facilitating transitions.

Before specializing to this case, we note that for an n-cycle, the non-equilibrium steady state distribution is given by 
\begin{equation}
p_{k} = \frac{T_{k} S_{n+1} + (1-T_{n+1})S_{k}}{\mathcal{Z}}
\end{equation}
where $$ \mathcal{Z} = \sum_{k=1}^{n}\Big(T_{k} S_{n+1} + (1-T_{n+1})S_{k} \Big)$$ 
and 
$$T_{k} = \prod_{i=1}^{k-1} \frac{W_{i+1,i}}{W_{i,i+1}} \  \ \ \text{k=2,3,..,n+1}\ \ \ \text{and}\ \ \  T_{1}=1 \, ,$$
$$S_{k} = \sum_{m=1}^{k-1}\prod_{i=m+1}^{k-1}\frac{W_{i+1,i}}{W_{i,i+1}}\frac{1}{W_{m,m+1}}
\  \ \ \text{k=2,3,..,n+1} \ \ \ \text{and} \ \ \ S_{1}=0 \, .$$
The total dissipation through edge $i\to (i+1)$ is given by   
\begin{equation}
\sigma_{i,i+1} =(W_{i,i+1}p_{i+1}-W_{i+1,i}p_{i})\log \Big(\frac{W_{i,i+1}p_{i+1}}{W_{i+1,i}p_{i}}\Big) \, .
\end{equation}
For living circuits with dynamical conductances, i.e., substituting $W_{i,i+1}\to \Lambda_{i,i+1}k_{i,i+1}$, this becomes
\begin{eqnarray}
\sigma_{i,i+1}
&=&  \Lambda_{i,i+1}(k_{i,i+1}p_{i+1}-k_{i+1,i}p_{i})\log \Big(\frac{k_{i,i+1}p_{i+1}}{k_{i+1,i}p_{i}}\Big) \, .\hspace{0.5cm}
\end{eqnarray}
Using the steady-state distribution, 
\begin{flushleft}
\begin{align}
\hspace{-0.5cm}\mathcal{\sigma}_{i,i+1} &=& \Lambda_{i,i+1}\Bigg(\frac{(k_{i,i+1}T_{i+1}-k_{i+1,i}T_{i}) S_{n+1}}{\mathcal{Z}} +   \frac{(1-T_{n+1})(k_{i,i+1}S_{i+1}-k_{i+1,i}S_{i})}{\mathcal{Z}}\Bigg)\log \Bigg(\frac{k_{i,i+1}(T_{i+1} S_{n+1} + (1-T_{n+1})S_{i+1})}{k_{i+1,i}(T_{i} S_{n+1} + (1-T_{n+1})S_{i})}\Bigg) \nonumber \\
&= & \frac{(1-T_{n+1})}{\mathcal{Z}}\log \Bigg(\frac{k_{i,i+1}p_{i+1}}{k_{i+1,i}p_{i}}\Bigg) \hspace{12cm}
\end{align}
\end{flushleft}
This implies that 

$$
\sigma_{\text{tot}} = \sum_{i}\sigma_{i,i+1} = \frac{(1-T_{n+1})}{\mathcal{Z}} \log T_{n+1}
$$
and therefore, a non-equilibrium steady state requires breaking the detailed balance condition, 
$$
\log\Bigg(\frac{W_{21}W_{32}... W_{1n}}{W_{12} W_{23}...W_{n1}}\Bigg) = \log\Bigg(\frac{k_{21}k_{32}... k_{1n}}{k_{12} k_{23}...k_{n1}}\Bigg) =  e^{\mu}\neq 1  \, .
$$
We implement this in the ecosystem-inspired circuit by coupling one edge (say 0 - 1 ) to an external source of energy such as light: $k_{01} \to k_{01}e^{\mu} $.

\begin{figure}[h]
\centering\includegraphics[width=0.7\linewidth]{Supplementary_Figure_1.pdf} \vspace{0.1cm}
\caption{\justifying \textsf{\textbf{Critical energy input and first-order phase transition in a 3-node adaptive living circuit.} The blue curve shows the maximum possible dissipation along the weakest edge across all configurations on the conductance simplex. Since the species facilitating transitions require a minimum energy $\sigma_{\text{maint}}$ to sustain their energy-harvesting machinery, the circuit can maintain a non-equilibrium steady state (NESS) only when the blue curve lies above the $\sigma_{\text{maint}}$ threshold. The red curve represents the total per capita dissipation summed over all three edges. At the critical energy input $\mu_{h\nu}^{\text{critical}}$, the red curve lies significantly above the $3\sigma_{\text{maint}}$ line, indicating that the NESS dissipates more energy than the bare minimum required for survival. These curves correspond to a specific realization of the baseline rates $k_{ij}$, and while the precise values may vary across realizations, the qualitative behavior remains unchanged.}}
    \label{fig:enter-label}
\end{figure}

In a 3-node network, a sustainable non-equilibrium steady state (NESS) requires that all three edges dissipate more than $\sigma_{\text{maint}}$, otherwise the corresponding conductance $\Lambda_{ij}$ will decay to zero. To identify the critical energy input $\mu_{\text{crit}}$, we search the conductance simplex for configurations where the minimum edge dissipation exceeds $\sigma_{\text{maint}}$. Such configurations exist only if $\mu > \mu_{\text{crit}} > 0$, below which all living circuits collapse.

Moreover, at $\mu_{\text{crit}}$, we confirm that the total dissipation exceeds the minimum required for survival:
\begin{equation}
\sum_{\text{edges}} \frac{\sigma_{ij}}{\Lambda_{ij}}> 3 \sigma_{\text{maint}} \, ,
\end{equation}
indicating a first-order phase transition. The value of $\mu_{\text{crit}}$, as well as the residual dissipation above the minimum required, are determined by the baseline rates $k_{ij}$.
\subsection{Limit $\Lambda_{i,i+1} \to 0$}
We now consider a network configuration in which one of the edges is about to go extinct, i.e., $\Lambda_{i,i+1} \approx 0$, and is much smaller compared to the conductances of all other edges. In this limit, 
\begin{equation}
    S_{l (\leq i)} << S_{k (\geq i+1)} \approx \frac{T_{k}}{T_{i+1}} \frac{1}{k_{i,i+1} \Lambda_{i,i+1}}
\end{equation}
Similarly, we also find that 
\begin{equation}
\mathcal{Z} \approx \frac{1}{k_{i,i+1}\Lambda_{i,i+1}} \frac{1}{T_{i+1}} \Big[ T_{n+1} \sum_{l=1}^{k}T_{l} + \sum_{l=k+1}^{n}T_{l}\Big]
\end{equation}
Using these expressions, the dissipation through the dying edge is given by 
\begin{eqnarray}
    \sigma_{i,i+1} &=& \frac{(1-T_{n+1})}{ \frac{1}{k_{i,i+1}\Lambda_{i,i+1}} \frac{1}{T_{i+1}} \Big[ T_{n+1} \sum_{l=1}^{k}T_{l} + \sum_{l=k+1}^{n}T_{l}\Big] + O(1)} \log\Bigg(\frac{1/\Lambda_{i,i+1} + O(1)}{T_{n+1}/\Lambda_{i,i+1} + O(1)}\Bigg) \nonumber \\
    &=& \frac{(1-T_{n+1})T_{i+1} k_{i,i+1}\Lambda_{i,i+1}}{  \Big[ T_{n+1} \sum_{l=1}^{k}T_{l} + \sum_{l=k+1}^{n}T_{l}\Big] + O(\Lambda_{i,i+1})} \log\Bigg(\frac{1 + O(\Lambda_{i,i+1})}{T_{n+1} + O(\Lambda_{i,i+1})}\Bigg) \nonumber \\
    &=& \frac{(T_{n+1}-1)T_{i+1} k_{i,i+1}\Lambda_{i,i+1}}{  \Big[ T_{n+1} \sum_{l=1}^{k}T_{l} + \sum_{l=k+1}^{n}T_{l}\Big]} \Big(\log(T_{n+1}) +  O(\Lambda_{i,i+1})  
     + \log(1 + O(\Lambda_{i,i+1}))\Big)
\end{eqnarray}
whereas dissipation through other edges is given by 
\begin{equation}
    \sigma_{k,k+1} = 0 + \Lambda_{i,i+1} O(\Lambda_{i,i+1}) \, .
\end{equation}

\section{Save the weakest: approximate Lyapunov functional near edge extinction}
\label{xlogxappendix}
From the above analysis, we find that the dynamics of edge conductances during approach towards the edges of the conductance simplex, to leading order, is given by  
\begin{equation}
 \dot{\Lambda}_{ij} = -\frac{\delta \mathcal{F}}{\delta \Lambda_{ij}}   
\end{equation}
where 
\begin{equation}
    \mathcal{F} = -\sum_{i=1}^{n-1} \Bigg(\frac{(T_{n+1}-1)T_{i+1} k_{i,i+1}}{ T_{n+1} \sum_{l=1}^{k}T_{l} + \sum_{l=k+1}^{n}T_{l}} \log(T_{n+1})-\sigma_{\text{maint}}\Bigg) \frac{\Lambda_{i,i+1}^{2}}{2}
\end{equation}

\subsection{Limit $\Lambda_{i,i+1} \to \infty$} 
It is easy to see that, in the limit of infinite conductance through the edge $i-(i+1)$, the dissipation through this edge is 0, effectively severing the 
n-cycle. Thus, the Lyapunov functional during approach towards infinitely large conductances is given by 
\begin{equation}
\mathcal{F} = \sum_{i=1}^{n-1} \sigma_{\text{maint}}\frac{\Lambda_{i,i+1}^{2}}{2}    
\end{equation}

